class TATGEngineAdapter:
    _UNAVAILABLE_REFS_RETRY_MARKER = "[Source-Backed Unavailable Reference Retry]"
    """Type-Aware Test Generator — enriched prompting for Java services.

    Compatible with the ``CATEngineAdapter`` interface so it slots directly
    into the existing backend → runner → CLI pipeline.
    """

    # Maximum .java files scanned for the type index.
    # Increase via the ``TATG_MAX_SCAN_FILES`` env var.
    _DEFAULT_MAX_SCAN_FILES = 600
    _RE_METHOD_DECL = re.compile(
        r"(?:(?:public|protected|private)\s+)?(?:static\s+)?"
        r"(?:final\s+)?([\w.<>,? \[\]]+?)\s+(\w+)\s*\([^)]*\)\s*(?:throws[^\{]+)?\{",
        re.MULTILINE,
    )
    # Declaration-only scanner used by prompt assembly.  Keep this anchored
    # and statement-bounded: the older permissive matcher above is useful for
    # legacy source mining, but can catastrophically backtrack when repeatedly
    # asked for one method in a large class.
    _RE_SOURCE_METHOD_SIGNATURE = re.compile(
        r"(?m)^[ \t]*"
        r"(?:@[A-Za-z_$][A-Za-z0-9_$.]*(?:\([^)\r\n]*\))?[ \t\r\n]*)*"
        r"(?:(?:public|protected|private|static|final|synchronized|native|abstract|"
        r"strictfp|default)[ \t]+)*"
        r"(?:<[^;{}()\r\n]+>[ \t]+)?"
        r"(?!return\b|throw\b|new\b|if\b|for\b|while\b|switch\b|catch\b)"
        r"(?P<return>[A-Za-z_$][A-Za-z0-9_$.\[\]?]*"
        r"(?:[ \t]*<[^;{}()]+>)?(?:[ \t]*\[\])?)[ \t]+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)[ \t\r\n]*"
        r"\((?P<params>[^;{}]*)\)[ \t\r\n]*"
        r"(?:throws[ \t\r\n]+[^;{}]+)?[ \t\r\n]*(?:\{|;)"
    )
    _RE_PLACEHOLDER_OUTPUT = re.compile(r"^\s*<\|[^|>]+\|>\s*$")
    _SOURCE_METHOD_CACHE: dict[tuple[str, str], set[str] | None] = {}
    _CLASSPATH_METHOD_CACHE: dict[tuple[str, str, tuple[str, ...]], set[str] | None] = {}
    _CLASSPATH_PUBLIC_TYPE_CACHE: dict[tuple[str, str, tuple[str, ...]], bool | None] = {}
    _SOURCE_CONSTRUCTOR_CACHE: dict[tuple[str, str], set[int] | None] = {}
    _SOURCE_CONSTRUCTOR_DETAIL_CACHE: dict[tuple[str, str], list[dict[str, Any]] | None] = {}
    _SOURCE_BUILDER_RECIPE_CACHE: dict[tuple[str, str], dict[str, Any] | None] = {}
    _SOURCE_RETURN_FACTORY_CACHE: dict[tuple[str, str], list[str]] = {}
    _SOURCE_STATIC_RETURNS_CACHE: dict[tuple[str, str], dict[str, str] | None] = {}
    _SOURCE_RECORD_COMPONENT_CACHE: dict[tuple[str, str], set[str] | None] = {}
    _SOURCE_STATIC_METHOD_ARITY_CACHE: dict[
        tuple[str, str], dict[str, set[int]] | None
    ] = {}
    _SOURCE_FILE_CACHE: dict[tuple[str, str], Path | None] = {}
    _SOURCE_FILE_INDEX_CACHE: OrderedDict[str, dict[str, Path]] = OrderedDict()
    _PROJECT_SOURCE_IMPORT_CACHE: OrderedDict[str, set[str]] = OrderedDict()
    _RE_PACKAGE_DECL = re.compile(r"(?m)^\s*package\s+([A-Za-z_][\w.]*)\s*;")
    _RE_IMPORT_DECL = re.compile(
        r"(?m)^\s*import\s+(static\s+)?([A-Za-z_][\w.]*(?:\.\*)?)\s*;"
    )
    _RE_CLASS_DECL = re.compile(
        r"\b(?:(?:public|protected|private|static|final|abstract)\s+)*"
        r"(?:class|interface|enum|record)\s+([A-Za-z_][A-Za-z0-9_]*)\b"
    )
    _RE_TYPE_TOKEN = re.compile(r"\b[A-Z][A-Za-z0-9_]*\b")
    _RE_VAR_DECL_NEW = re.compile(
        r"\b(?:final\s+)?([A-Z][A-Za-z0-9_.]*(?:<[^>]+>)?)\s+"
        r"([a-zA-Z_][A-Za-z0-9_]*)\s*=\s*new\s+([A-Z][A-Za-z0-9_.]*)\s*\("
    )
    _RE_VAR_DECL_MOCK = re.compile(
        r"\b(?:final\s+)?([A-Z][A-Za-z0-9_$.]*(?:<[^>]+>)?)\s+"
        r"([a-zA-Z_][A-Za-z0-9_]*)\s*=\s*"
        r"(?:(?:org\.mockito\.)?Mockito\.)?mock\s*\(\s*"
        r"([A-Z][A-Za-z0-9_$.]*)\.class\s*\)"
    )

    @staticmethod
    def _mutation_feedback_min_line_coverage() -> float:
        raw = os.getenv("TATG_MUTATION_FEEDBACK_MIN_LINE_COVERAGE", "0.80")
        try:
            return max(0.0, min(1.0, float(raw)))
        except (TypeError, ValueError):
            return 0.80

    @staticmethod
    def _latency_safe_new_tests_budget(
        requested: int,
        *,
        projected_prompt_chars: int,
        minimum_useful_tests: int = 1,
    ) -> int:
        """Cap per-response test count for very large prompts.

        Large prompts plus many complete @Test bodies can hit the hard
        generation timeout before any candidate reaches streaming validation.
        The cap is based only on prompt size and is environment-overridable.

        Prompt size correlates with method complexity, so using it to shrink the
        test budget penalised exactly the methods that needed the most tests: on
        the benchmark, targets with 80+ branches received *fewer* test slots
        than targets with 10-20 branches.  Latency is now handled by round
        batching (several bounded responses) plus prompt compaction, so this cap
        is off by default and retained for explicit opt-in.
        """
        try:
            budget = max(1, int(requested or 1))
        except (TypeError, ValueError):
            budget = 1
        if not TATGEngineAdapter._env_flag("TATG_LATENCY_SAFE_BUDGET", default=False):
            return budget
        try:
            chars = max(0, int(projected_prompt_chars or 0))
        except (TypeError, ValueError):
            chars = 0
        raw_threshold = os.getenv("TATG_LATENCY_SAFE_PROMPT_CHARS", "").strip()
        try:
            threshold = int(raw_threshold) if raw_threshold else 32000
        except ValueError:
            threshold = 32000
        if threshold <= 0 or chars < threshold:
            return budget
        if chars >= threshold + 12000:
            cap = 4
        elif chars >= threshold + 6000:
            cap = 5
        else:
            cap = 6
        raw_cap = os.getenv("TATG_LATENCY_SAFE_MAX_TESTS", "").strip()
        if raw_cap:
            try:
                cap = max(1, int(raw_cap))
            except ValueError:
                pass
        try:
            useful_floor = max(1, int(minimum_useful_tests or 1))
        except (TypeError, ValueError):
            useful_floor = 1
        # Prompt length is only a latency proxy.  It must not erase the test
        # slots needed by a bounded set of independently source-validated
        # semantic rows.  The floor never exceeds the original structural
        # budget, so simple/high-coverage methods are not expanded by it.
        useful_floor = min(budget, useful_floor)
        return max(1, min(budget, max(cap, useful_floor)))

    @staticmethod
    def _executable_path_safe_new_tests_budget(
        requested: int,
        *,
        source_call_state_plan: str = "",
        generation_control_receipt: str = "",
        coverage_feedback: dict | None = None,
    ) -> int:
        """Cap test count when one valid executable path is the bottleneck.

        The signal is generic and source/feedback-derived: callback/terminal
        producer paths, source-required collaborator returns, Mockito misuse,
        or missing terminal initialization.  In these cases many candidates
        often produce long JSON and repeat invalid setup; fewer candidates make
        the required baseline more likely to be complete and salvageable.
        """
        try:
            budget = max(1, int(requested or 1))
        except (TypeError, ValueError):
            budget = 1
        if budget <= 1:
            return budget
        text = "\n".join(
            str(part or "")
            for part in (source_call_state_plan, generation_control_receipt)
        ).lower()
        feedback = coverage_feedback if isinstance(coverage_feedback, dict) else {}
        failure_text = json.dumps(
            feedback.get("validation_failure_feedback")
            or feedback.get("measured_directional_feedback")
            or {},
            ensure_ascii=True,
            default=str,
        ).lower()
        parser_cursor_terms = (
            "input token shape",
            "json token",
            "xml token",
            "token cursor",
            "parser cursor",
            "parser",
            "cursor",
            "token",
            "filterstart",
            "tokenfilter",
            "nexttoken",
            "skipchildren",
        )
        has_parser_cursor_focus = sum(1 for term in parser_cursor_terms if term in text) >= 2
        # Only structured, target-specific evidence may shrink the candidate
        # budget.  Generic prompt prose always mentions roles such as
        # ``callback_partition`` and historically made every complex target
        # look callback-heavy, silently capping it at four tests.
        structured_path_markers = (
            "source_required_terminal_execution_path",
            "terminal_path:",
            "callback_path:",
            "collaborator_calls_seen_in_target:",
            "source_required_collaborator_return_baseline",
            "builder_required_collaborator",
            "source_exact_collaborator_stub_contracts",
            "observable_producer_setup:",
        )
        has_collaborator_or_terminal_focus = any(
            marker in text
            for marker in structured_path_markers
        )
        if (
            TATGEngineAdapter._legacy_name_heuristics_enabled()
            and not feedback
            and has_parser_cursor_focus
            and not has_collaborator_or_terminal_focus
        ):
            cap = TATGEngineAdapter._env_int(
                "TATG_STATEFUL_INITIAL_MAX_NEW_TESTS",
                2,
                minimum=1,
                maximum=4,
            )
            return max(1, min(budget, cap))
        risk_terms = structured_path_markers + (
            "missing-required-terminal-initialization",
            "missingmethodinvocationexception",
            "when() requires an argument",
        )
        if not any(term in text or term in failure_text for term in risk_terms):
            return budget
        cap = TATGEngineAdapter._env_int(
            "TATG_EXECUTABLE_PATH_MAX_NEW_TESTS",
            4,
            minimum=1,
            maximum=8,
        )
        return max(1, min(budget, cap))

    @staticmethod
    def _mutation_feedback_allowed_for_coverage(coverage_feedback: object) -> bool:
        """Return whether this payload explicitly represents mutation work.

        Structural coverage feedback may carry archived PITest fields for
        reporting.  Those fields must not silently turn a regular coverage
        generation round into a mutation round merely because line coverage is
        high.  Mutation prompting is enabled only by an explicit mutation-mode
        flag or by a standalone set of mutation objectives.
        """
        if not isinstance(coverage_feedback, dict):
            return False
        if any(
            bool(coverage_feedback.get(key))
            for key in (
                "mutation_feedback_enabled",
                "mutation_feedback_forced_by_with_mutation",
                "mutation_feedback_only",
                "mutation_objective_retry_only",
            )
        ):
            return True
        objective_rows = [
            item
            for key in ("mutation_objectives", "test_objectives")
            for item in list(coverage_feedback.get(key) or [])
            if isinstance(item, dict)
        ]
        has_mutation_objective = any(
            TATGEngineAdapter._is_mutation_objective(item)
            for item in objective_rows
        )
        has_structural_objective = any(
            not TATGEngineAdapter._is_mutation_objective(item)
            for item in list(coverage_feedback.get("test_objectives") or [])
            if isinstance(item, dict)
        )
        # A standalone M-id set is itself an explicit mutation-oriented round.
        # Mixed O-id/M-id payloads remain structural unless the caller sets one
        # of the explicit mutation flags above; this prevents stale archived
        # mutation rows from contaminating coverage feedback.
        return has_mutation_objective and not has_structural_objective

    @staticmethod
    def _is_mutation_feedback_only(coverage_feedback: object) -> bool:
        return isinstance(coverage_feedback, dict) and bool(
            coverage_feedback.get("mutation_feedback_only")
            or coverage_feedback.get("mutation_objective_retry_only")
        )

    @staticmethod
    def _is_mutation_objective(objective: object) -> bool:
        if not isinstance(objective, dict):
            return False
        oid = str(objective.get("id") or "").strip().upper()
        source = str(objective.get("source") or "").strip().lower()
        kind = str(objective.get("kind") or "").strip().lower()
        facts = objective.get("facts") if isinstance(objective.get("facts"), dict) else {}
        return (
            oid.startswith(("M", "F"))
            or "mutation" in source
            or "pitest" in source
            or "mutation" in kind
            or "fused" in source
            or "mutator" in facts
            or "status" in facts and str(facts.get("status") or "").upper() in {"SURVIVED", "NO_COVERAGE", "TIMED_OUT"}
        )

    @staticmethod
    def _compact_mutation_feedback_for_repair(coverage_feedback: object) -> dict[str, Any]:
        if not isinstance(coverage_feedback, dict):
            return {}
        if not TATGEngineAdapter._mutation_feedback_allowed_for_coverage(coverage_feedback):
            return {}
        out: dict[str, Any] = {"mutation_feedback_enabled": True}
        for key in ("mutation_score_gap",):
            value = coverage_feedback.get(key)
            if isinstance(value, dict) and value:
                out[key] = dict(value)
        mutants = [
            dict(item)
            for item in list(coverage_feedback.get("surviving_mutants") or [])[:6]
            if isinstance(item, dict)
        ]
        if mutants:
            out["surviving_mutants"] = mutants
        # Preserve the minimal objective identity and exact-line miss receipts
        # needed by per-test pre-validation. The previous compact payload
        # dropped ``mutation_objectives`` entirely, so a short retry could see
        # the textual exclusion while the deterministic gate had no rejected
        # setup fingerprint to compare against. Keep this bounded and omit
        # candidate source excerpts; those remain in the audit only.
        compact_objectives: list[dict[str, Any]] = []
        for objective in list(coverage_feedback.get("mutation_objectives") or [])[:4]:
            if not isinstance(objective, dict):
                continue
            objective_id = str(
                objective.get("id")
                or objective.get("objective_id")
                or objective.get("mutation_objective_id")
                or ""
            ).strip()
            if not objective_id.upper().startswith("M"):
                continue
            raw_facts = (
                objective.get("facts")
                if isinstance(objective.get("facts"), dict)
                else {}
            )
            facts = {
                key: raw_facts.get(key)
                for key in (
                    "status",
                    "line",
                    "mutator",
                    "source_line",
                    "mutation_line_reachability_retry",
                    "mutation_line_reachability_original_status",
                )
                if raw_facts.get(key) not in (None, "", [], {})
            }
            ancestor_path = [
                {
                    key: row.get(key)
                    for key in (
                        "line",
                        "kind",
                        "source_predicate",
                        "required_outcome",
                        "switch_expression",
                        "case_value",
                    )
                    if row.get(key) not in (None, "", [], {})
                }
                for row in list(
                    raw_facts.get(
                        "mutation_semantic_exact_ancestor_control_path"
                    )
                    or []
                )[:8]
                if isinstance(row, dict)
                and str(row.get("source_predicate") or "").strip()
            ]
            if ancestor_path:
                facts[
                    "mutation_semantic_exact_ancestor_control_path"
                ] = ancestor_path
            reachability = (
                raw_facts.get("mutation_reachability_source_evidence")
                if isinstance(
                    raw_facts.get("mutation_reachability_source_evidence"),
                    dict,
                )
                else {}
            )
            protocol = (
                reachability.get("qualified_state_protocol")
                if isinstance(
                    reachability.get("qualified_state_protocol"),
                    dict,
                )
                else {}
            )
            transition_rows: list[dict[str, Any]] = []
            for row in list(protocol.get("transition_rows") or [])[:8]:
                if not isinstance(row, dict):
                    continue
                assignment = str(row.get("assignment") or "").strip()
                if not assignment:
                    continue
                compact_control_path = [
                    {
                        key: control.get(key)
                        for key in (
                            "line",
                            "statement",
                            "source_predicate",
                            "required_outcome",
                        )
                        if control.get(key) not in (None, "", [], {})
                    }
                    for control in list(row.get("control_path") or [])[-4:]
                    if isinstance(control, dict)
                ]
                compact_row = {
                    key: row.get(key)
                    for key in (
                        "line",
                        "assignment",
                        "state_root",
                        "state_field",
                        "source_evidence",
                    )
                    if row.get(key) not in (None, "", [], {})
                }
                if compact_control_path:
                    compact_row["control_path"] = compact_control_path
                transition_rows.append(compact_row)
            if transition_rows:
                facts["mutation_reachability_source_evidence"] = {
                    "qualified_state_protocol": {
                        "required_state_accesses": [
                            str(value).strip()
                            for value in list(
                                protocol.get("required_state_accesses") or []
                            )[:8]
                            if str(value).strip()
                        ],
                        "transition_rows": transition_rows,
                    },
                }
            receiver_protocol = reachability.get("receiver_state_protocol")
            if isinstance(receiver_protocol, dict) and list(
                receiver_protocol.get("required_transitions") or []
            ):
                facts.setdefault(
                    "mutation_reachability_source_evidence",
                    {},
                )["receiver_state_protocol"] = {
                    "target_class": str(
                        receiver_protocol.get("target_class") or ""
                    ),
                    "target_method": str(
                        receiver_protocol.get("target_method") or ""
                    ),
                    "required_transitions": [
                        dict(row)
                        for row in list(
                            receiver_protocol.get("required_transitions")
                            or []
                        )[:6]
                        if isinstance(row, dict)
                    ],
                    "proof_status": str(
                        receiver_protocol.get("proof_status") or ""
                    ),
                }
            receipts: list[dict[str, Any]] = []
            for receipt in list(
                raw_facts.get("prior_mutant_line_miss_receipts") or []
            )[-2:]:
                if not isinstance(receipt, dict):
                    continue
                compact_receipt = {
                    key: receipt.get(key)
                    for key in (
                        "test_method",
                        "mutant_line",
                        "rejected_setup_fingerprint",
                        "rejected_setup_reason",
                        "forbid_exact_candidate_repetition",
                    )
                    if receipt.get(key) not in (None, "", [], {})
                }
                if compact_receipt:
                    receipts.append(compact_receipt)
            if receipts:
                facts["prior_mutant_line_miss_receipts"] = receipts
            compact_objectives.append({
                "id": objective_id,
                "kind": str(objective.get("kind") or ""),
                "facts": facts,
            })
        if compact_objectives:
            out["mutation_objectives"] = compact_objectives
        return out

    @staticmethod
    def _mutation_objective_evidence_map(
        coverage_feedback: object,
    ) -> dict[str, dict[str, Any]]:
        if not isinstance(coverage_feedback, dict):
            return {}
        out: dict[str, dict[str, Any]] = {}
        for objective in list(coverage_feedback.get("mutation_objectives") or []):
            if not isinstance(objective, dict):
                continue
            objective_id = str(
                objective.get("id")
                or objective.get("objective_id")
                or objective.get("mutation_objective_id")
                or ""
            ).strip()
            if not objective_id.upper().startswith("M"):
                continue
            facts = objective.get("facts")
            facts = facts if isinstance(facts, dict) else {}
            effective_status = (
                "NO_COVERAGE"
                if bool(facts.get("mutation_line_reachability_retry"))
                else facts.get("status")
            )
            out[objective_id] = {
                key: facts.get(key)
                for key in (
                    "line",
                    "mutator",
                    "source_line",
                    "mutation_fingerprint",
                    "pit_index",
                    "pit_indexes",
                    "pit_block",
                    "pit_blocks",
                    "source_predicate",
                    "source_predicate_ordinal",
                    "source_predicate_binding",
                )
                if facts.get(key) not in (None, "")
            }
            if effective_status not in (None, ""):
                out[objective_id]["status"] = effective_status
            if bool(facts.get("mutation_line_reachability_retry")):
                out[objective_id]["mutation_line_reachability_retry"] = True
                out[objective_id]["original_status"] = facts.get(
                    "mutation_line_reachability_original_status"
                )
        return out
    _RE_SETTER_CALL_LINE = re.compile(
        r"^(\s*)([a-zA-Z_][A-Za-z0-9_]*)\.(set[A-Z][A-Za-z0-9_]*)\(\s*(.+?)\s*\);\s*$"
    )
    _RE_CTOR_ASSIGN_LINE = re.compile(
        r"^(\s*)(?:final\s+)?([A-Z][A-Za-z0-9_.]*(?:<[^>]+>)?)\s+"
        r"([a-zA-Z_][A-Za-z0-9_]*)\s*=\s*new\s+([A-Z][A-Za-z0-9_.]*)\((.*)\);\s*$"
    )
    _RE_WHEN_THENRETURN_LINE = re.compile(
        r"^(\s*)(?:(?:org\.mockito\.)?Mockito\.)?when\(\s*"
        r"([a-zA-Z_][A-Za-z0-9_]*)\.([a-zA-Z_][A-Za-z0-9_]*)"
        r"\(([^)]*)\)\s*\)\.thenReturn\(\s*(.+?)\s*\);\s*$"
    )
    _RE_FIELD_DECL_LINE = re.compile(
        r"^\s*(?:@\w+(?:\([^)]*\))?\s*)*(?:private|protected|public)\s+"
        r"([A-Z][A-Za-z0-9_]*(?:<[^>]+>)?)\s+([a-zA-Z_][A-Za-z0-9_]*)\s*(?:=|;)"
    )
    # LRU symbol index cache (max 10 project roots to prevent memory exhaustion)
    _SYMBOL_INDEX_CACHE: OrderedDict[str, dict[str, list[str]]] = OrderedDict()
    _SYMBOL_INDEX_CACHE_LOCK = threading.RLock()
    _MAX_SYMBOL_CACHE_SIZE = 10
    _MAX_DEPENDENCY_SYMBOLS = 12000
    _IMPORT_LIBRARY_SCHEMA_VERSION = 6

    class PatchExtractionError(ValueError):
        """Raised when JSON patch output is syntactically valid but unusable."""

        def __init__(
            self,
            message: str,
            *,
            skip_counts: dict[str, int] | None = None,
            rejected_entries: list[dict[str, Any]] | None = None,
        ) -> None:
            self.skip_counts = {
                key: int(value)
                for key, value in (skip_counts or {}).items()
                if int(value or 0) > 0
            }
            self.rejected_entries = [
                dict(item)
                for item in list(rejected_entries or [])[:8]
                if isinstance(item, dict)
            ]
            detail = message
            if self.skip_counts:
                counts = ", ".join(f"{key}={value}" for key, value in sorted(self.skip_counts.items()))
                detail = f"{message}; skip_counts: {counts}"
            parts: list[str] = []
            if self.rejected_entries:
                for item in self.rejected_entries[:3]:
                    reason = str(item.get("reason") or "rejected").strip()
                    method = str(item.get("method") or item.get("test_name") or "").strip()
                    calls = ", ".join(str(x) for x in list(item.get("calls") or [])[:6])
                    excerpt = str(item.get("excerpt") or "").strip().replace("\n", " ")
                    chunk = reason
                    if method:
                        chunk += f":{method}"
                    if calls:
                        chunk += f" calls=[{calls}]"
                    if excerpt:
                        chunk += f" excerpt='{excerpt[:180]}'"
                    parts.append(chunk)
            if parts:
                detail += "; rejected_entries: " + " | ".join(parts)
            super().__init__(detail)

    @staticmethod
    def _mutation_patch_rejection_reason(
        *,
        extraction_error: str = "",
        skip_counts: dict[str, Any] | None = None,
        mutation_feedback_active: bool = False,
    ) -> str:
        """Classify mutation-extra patch rejection into stable lifecycle buckets."""
        counts = skip_counts if isinstance(skip_counts, dict) else {}
        lower = str(extraction_error or "").lower()

        def _count(name: str) -> int:
            try:
                return int(counts.get(name) or 0)
            except Exception:
                return 0

        if _count("mutation_candidate_missing_target_call") > 0:
            return "mutation_candidate_missing_target_call"
        if (
            _count("mutation_objective_id_missing") > 0
            or _count("mutation_objective_id_unknown") > 0
            or _count("mutation_objective_id_conflicting") > 0
        ):
            return "mutation_objective_id_missing"
        if _count("weak_mutation_oracle") > 0:
            return "weak_oracle_rejected"
        if mutation_feedback_active and _count("without_observable_check") > 0:
            return "weak_oracle_rejected"
        if _count("without_target_call") > 0:
            return "mutation_candidate_missing_target_call" if mutation_feedback_active else "target_call_missing"
        if any(
            token in lower
            for token in (
                "no executable @test",
                "no executable",
                "produced no executable",
                "new_tests array",
                "must contain non-empty",
                "test_code entries",
            )
        ):
            return "mutation_test_extraction_empty" if mutation_feedback_active else "test_extraction_empty"
        if any(
            token in lower
            for token in (
                "invalid json",
                "unterminated string",
                "expecting value",
                "expecting ',' delimiter",
                "expecting property name",
                "json response",
                "json_patch_rejected",
            )
        ):
            return "mutation_schema_format_error" if mutation_feedback_active else "schema_format_error"
        return "mutation_schema_format_error" if mutation_feedback_active else "generation_failed"

    @staticmethod
    def _target_call_contract_retry_note(
        *,
        error: Exception,
        target_method: str | None,
        required_call_names: list[str] | None,
        required_obligation_ids: set[str] | None = None,
        method_is_private: bool = False,
        entry_method_names: list[str] | None = None,
        reflection_fallback_allowed: bool = False,
        lazy_terminal_markers: list[str] | None = None,
    ) -> str:
        """Return a compact retry note for JSON patches that miss the target call."""
        skip_counts = getattr(error, "skip_counts", {}) if error is not None else {}
        if not isinstance(skip_counts, dict):
            return ""
        missing_target = (
            int(skip_counts.get("without_target_call") or 0) > 0
            or int(skip_counts.get("mutation_candidate_missing_target_call") or 0) > 0
        )
        missing_lazy_terminal = int(skip_counts.get("without_lazy_terminal_execution") or 0) > 0
        if not missing_target and not missing_lazy_terminal:
            return ""
        target = str(target_method or "target").strip() or "target"
        required_calls = [
            str(name).strip()
            for name in list(required_call_names or [])
            if str(name).strip()
        ]
        entry_calls = [
            str(name).strip()
            for name in list(entry_method_names or [])
            if str(name).strip()
        ]
        if method_is_private and entry_calls:
            call_contract = (
                "call exactly one verified source-visible entry method that reaches "
                f"`{target}`: " + ", ".join(sorted(set(entry_calls))[:8])
            )
        elif method_is_private and reflection_fallback_allowed:
            call_contract = (
                f"use reflection fallback for private `{target}` with getDeclaredMethod(...), "
                "setAccessible(true), method.invoke(...), and an observable assertion"
            )
        else:
            call_contract = f"invoke `{target}` directly"
            if required_calls:
                call_contract += " via one of: " + ", ".join(sorted(set(required_calls))[:8])
        obligations = [
            str(oid).strip()
            for oid in sorted(required_obligation_ids or set())
            if str(oid).strip()
        ]
        obligation_rule = ""
        if obligations:
            obligation_rule = (
                " Bind each new_tests item to one required coverage_obligation_id "
                f"({', '.join(obligations[:12])}) and include that O-id in the Java @Test method name."
            )
        lazy_rule = ""
        markers = [
            str(item).strip()
            for item in list(lazy_terminal_markers or [])
            if str(item).strip()
        ]
        if missing_lazy_terminal:
            lazy_rule = (
                " The previous candidate invoked a lazy/async target but only observed the wrapper; "
                "after the target/entry call, assign the returned computation and consume it with a terminal operation"
                + (f" such as {', '.join(markers[:6])}" if markers else "")
                + ". Assert the terminal value, exact exception, completion, or target side effect; do not assert only on the unconsumed lazy object."
            )
        rejected_entries = getattr(error, "rejected_entries", [])
        rejected_rule = ""
        if isinstance(rejected_entries, list) and rejected_entries:
            rows: list[str] = []
            for item in rejected_entries[:3]:
                if not isinstance(item, dict):
                    continue
                reason = str(item.get("reason") or "rejected").strip()
                method = str(item.get("method") or item.get("test_name") or "").strip()
                calls = ", ".join(str(x) for x in list(item.get("calls") or [])[:8])
                excerpt = str(item.get("excerpt") or "").strip().replace("\n", " ")
                row = reason
                if method:
                    row += f" in {method}"
                if calls:
                    row += f"; observed calls=[{calls}]"
                if excerpt:
                    row += f"; excerpt={excerpt[:220]}"
                rows.append(row)
            if rows:
                rejected_rule = (
                    " Previous rejected candidate evidence: "
                    + " | ".join(rows)
                    + ". Fix the missing target/entry call instead of repeating sibling, collaborator-only, or smoke calls."
                )
        return (
            "\n\n[TARGET-CALL CONTRACT CORRECTION]\n"
            f"The previous JSON produced test_code entries, but none accepted by validation executed the requested target path. "
            f"Return ONLY JSON with key new_tests. In every test_code_lines method, {call_contract} after Arrange setup; "
            "do not submit construction-only, getter-only, neighboring-helper, or smoke tests. "
            "Keep Arrange minimal but sufficient, then assert an exact return value, exception, state change, emitted output, or differential observation."
            f"{lazy_rule}"
            f"{rejected_rule}"
            f"{obligation_rule} Use test_code_lines with one Java source line per array element; no markdown, no package declaration, no class declaration."
        )

    _JAVA_LANG_TYPES = {
        "String", "Object", "Boolean", "Byte", "Short", "Integer", "Long",
        "Float", "Double", "Character", "Void", "Exception", "RuntimeException",
        "IllegalArgumentException", "IllegalStateException", "Number", "Math",
        "System", "Class", "Iterable", "Comparable", "Enum", "Thread",
    }
    _COMMON_JAVA_PACKAGE_TYPES: dict[str, set[str]] = {
        "java.util": {
            "List", "Set", "Map", "HashMap", "ArrayList", "LinkedList", "HashSet",
            "Collections", "Optional", "Arrays", "Collection", "Iterator",
        },
        "java.util.concurrent": {
            "Executor", "ExecutorService", "ScheduledExecutorService", "Future",
            "CompletableFuture", "Callable", "TimeUnit", "Executors",
        },
        "java.util.concurrent.atomic": {
            "AtomicBoolean", "AtomicInteger", "AtomicLong", "AtomicReference",
            "AtomicIntegerArray", "AtomicLongArray", "AtomicReferenceArray",
        },
        "java.math": {"BigDecimal", "BigInteger"},
        "java.time": {
            "LocalDate", "LocalDateTime", "LocalTime", "Instant", "Duration", "Period"
        },
        "java.io": {"StringWriter", "StringReader", "ByteArrayOutputStream", "ByteArrayInputStream", "Writer", "Reader"},
        "javax.xml.stream": {"XMLInputFactory", "XMLOutputFactory", "XMLStreamReader", "XMLStreamWriter"},
        "javax.xml.transform.stream": {"StreamResult", "StreamSource"},
    }
    _COMMON_JDK_INSTANCE_METHODS: dict[str, set[str]] = {
        "Iterable": {"iterator", "forEach", "spliterator"},
        "Collection": {
            "add", "addAll", "clear", "contains", "containsAll", "forEach",
            "isEmpty", "iterator", "remove", "removeAll", "retainAll", "size",
            "spliterator", "stream", "parallelStream", "toArray",
        },
        "List": {
            "add", "addAll", "clear", "contains", "containsAll", "forEach",
            "get", "indexOf", "isEmpty", "iterator", "lastIndexOf",
            "listIterator", "remove", "set", "size", "sort", "spliterator",
            "stream", "parallelStream", "subList", "toArray",
        },
        "Set": {
            "add", "addAll", "clear", "contains", "containsAll", "forEach",
            "isEmpty", "iterator", "remove", "size", "spliterator", "stream",
            "parallelStream", "toArray",
        },
        "Map": {
            "clear", "compute", "containsKey", "containsValue", "entrySet",
            "forEach", "get", "getOrDefault", "isEmpty", "keySet", "put",
            "putAll", "remove", "size", "values",
        },
        "Iterator": {"forEachRemaining", "hasNext", "next", "remove"},
        "Optional": {"filter", "flatMap", "get", "ifPresent", "isEmpty", "isPresent", "map", "orElse", "orElseGet", "orElseThrow", "stream"},
        "Stream": {"collect", "count", "filter", "findFirst", "findAny", "flatMap", "forEach", "limit", "map", "noneMatch", "skip", "toArray", "toList"},
    }

    @classmethod
    def _is_common_jdk_simple_type(cls, simple_type: str) -> bool:
        simple = (simple_type or "").strip().replace("[]", "").rsplit(".", 1)[-1]
        if not simple:
            return False
        if simple in cls._JAVA_LANG_TYPES:
            return True
        return any(simple in types for types in cls._COMMON_JAVA_PACKAGE_TYPES.values())

    @classmethod
    def _is_common_jdk_instance_method(cls, simple_type: str, method: str) -> bool:
        simple = (simple_type or "").strip().replace("[]", "").rsplit(".", 1)[-1]
        name = str(method or "").strip()
        if not simple or not name:
            return False
        if name in cls._COMMON_JDK_INSTANCE_METHODS.get(simple, set()):
            return True
        if simple in {"ArrayList", "LinkedList"} and name in cls._COMMON_JDK_INSTANCE_METHODS.get("List", set()):
            return True
        if simple in {"HashSet"} and name in cls._COMMON_JDK_INSTANCE_METHODS.get("Set", set()):
            return True
        if simple in {"HashMap"} and name in cls._COMMON_JDK_INSTANCE_METHODS.get("Map", set()):
            return True
        return False

    @staticmethod
    def _clip_prompt_log_text(text: str, max_chars: int) -> tuple[str, bool]:
        # Preserve full prompt text in logs; rely on log_prompts_limit for size
        # control instead of clipping content.
        return text or "", False

    @classmethod
    def _prompt_demoted_required_objective_conflicts(cls, prompt_text: str) -> list[str]:
        """Return O-ids that are both demoted/forbidden and rendered as current/required.

        This catches the specific failure mode where broad frontier-competing
        obligations are correctly moved to optional hints, but their
        test_objective payloads are later re-rendered as current hard targets.
        """
        text = str(prompt_text or "")
        demoted_section = cls._extract_bracket_section(text, "[Demoted Optional Objective Hints]")
        if not demoted_section:
            return []
        demoted_ids = set(re.findall(r"\b(O\d+)\b", demoted_section))
        if not demoted_ids:
            return []
        current_section = cls._extract_bracket_section(text, "[Current Round Test Objectives]")
        current_ids = {
            match.group(1)
            for match in re.finditer(r"^\s*-\s+(O\d+)\b", current_section, re.MULTILINE)
        }
        required_ids: set[str] = set()
        for line in text.splitlines():
            if "required_coverage_obligation_ids" in line:
                required_ids.update(re.findall(r"\b(O\d+)\b", line))
            if "required_candidate:" in line and "coverage_obligation_id=" in line:
                required_ids.update(re.findall(r"coverage_obligation_id=(O\d+)", line))
        return sorted(demoted_ids & (current_ids | required_ids), key=cls._oid_sort_key)

    @classmethod
    def _record_prompt_log(
        cls,
        request: GenerationRequest,
        *,
        phase: str,
        label: str,
        system_prompt: str,
        user_prompt: str,
        attempt: int | None = None,
    ) -> None:
        if not bool(getattr(request, "log_prompts", False)):
            return
        logs = getattr(request, "prompt_logs", None)
        if not isinstance(logs, list):
            return
        limit = max(0, int(getattr(request, "log_prompts_limit", 20) or 20))
        user_prompt_text = user_prompt or ""
        sys_text, sys_truncated = cls._clip_prompt_log_text(system_prompt, 4000)
        user_text, user_truncated = cls._clip_prompt_log_text(user_prompt, 12000)
        try:
            audit_char_cap = max(
                12000,
                int(os.getenv("TATG_PROMPT_AUDIT_MAX_CHARS", "60000") or "60000"),
            )
        except (TypeError, ValueError):
            audit_char_cap = 60000
        audit_prompt_text = (
            user_prompt_text
            if len(user_prompt_text) <= audit_char_cap
            else user_prompt_text[:audit_char_cap]
        )
        audit_window_truncated = len(audit_prompt_text) < len(user_prompt_text)
        coverage_feedback_present = "[Coverage Feedback For This Generation Round]" in user_prompt_text
        mutation_feedback_present = (
            "[Mutation Objective Context]" in user_prompt_text
            or "[Mutation Feedback" in user_prompt_text
            or "source=mutation_feedback" in user_prompt_text
            or "required_candidate: candidate_role=mutation_reachability" in user_prompt_text
            or "required_candidate: candidate_role=mutation_oracle" in user_prompt_text
            or "MutationReachability" in user_prompt_text
            or "MutationAssertion" in user_prompt_text
        )
        mutation_feedback_marker_present = (
            re.search(
                r"^\[Mutation Feedback For Mutation Extra Round\]\s*$",
                user_prompt_text,
                re.MULTILINE,
            )
            is not None
        )
        mutation_objective_context_present = (
            re.search(
                r"^\[Mutation Objective Context\]\s*$",
                user_prompt_text,
                re.MULTILINE,
            )
            is not None
        )
        mutation_objective_ids_in_prompt = sorted(
            {
                match.group(0)
                for match in re.finditer(
                    # Mutation objective ids are emitted as uppercase M-ids.
                    # Case-insensitive matching made ordinary Maven cache
                    # paths such as ``~/.m2/repository`` look like live M2
                    # objectives in structural prompt audits.
                    r"(?<![A-Za-z0-9_.])M\d+\b",
                    user_prompt_text,
                )
            },
            key=cls._oid_sort_key,
        )
        unified_objective_present = (
            "[Unified Objective Template]" in user_prompt_text
            or "[Current Round Test Objectives]" in user_prompt_text
        )
        section_truncation_markers = user_prompt_text.count("[section truncated:")
        section_truncated = section_truncation_markers > 0
        def _section_positions(marker_pattern: str) -> list[int]:
            return [match.start() for match in re.finditer(marker_pattern, audit_prompt_text, re.MULTILINE)]

        active_positions = _section_positions(r"^\[Active Uncovered Objectives\]\s*$")
        skeleton_positions = _section_positions(r"^\[Source-Backed Baseline Skeleton Obligation\]\s*$")
        executable_baseline_schema_positions = _section_positions(r"^\[Executable Baseline Schema\]\s*$")
        frontier_positions = _section_positions(r"^\[Source-Derived Frontier Candidate Sketches\]\s*$")
        construction_positions = _section_positions(r"^\[Source-Derived Construction Repair Map\]\s*$")
        collaborator_positions = _section_positions(r"^\[Source-Derived Collaborator Callable Map\]\s*$")
        executable_recipe_positions = _section_positions(r"^\[Executable Candidate Recipe\]\s*$")
        source_positions = _section_positions(r"^Source code under test:\s*$")
        callable_positions = _section_positions(r"^\[CALLABLE SURFACE[^\n]*$")
        active_uncovered_section_count = len(active_positions)
        baseline_skeleton_section_count = len(skeleton_positions)
        executable_baseline_schema_section_count = len(executable_baseline_schema_positions)
        frontier_sketch_section_count = len(frontier_positions)
        construction_map_section_count = len(construction_positions)
        collaborator_map_section_count = len(collaborator_positions)
        executable_recipe_section_count = len(executable_recipe_positions)
        source_pos = source_positions[0] if source_positions else -1
        active_pos = active_positions[0] if active_positions else -1
        skeleton_pos = skeleton_positions[0] if skeleton_positions else -1
        executable_baseline_schema_pos = executable_baseline_schema_positions[0] if executable_baseline_schema_positions else -1
        frontier_pos = frontier_positions[0] if frontier_positions else -1
        construction_pos = construction_positions[0] if construction_positions else -1
        collaborator_pos = collaborator_positions[0] if collaborator_positions else -1
        executable_recipe_pos = executable_recipe_positions[0] if executable_recipe_positions else -1
        callable_pos = callable_positions[0] if callable_positions else -1
        demoted_required_conflicts = cls._prompt_demoted_required_objective_conflicts(audit_prompt_text)
        user_budget_match = re.search(
            r"\bnew_tests_count\s*=\s*(\d+)\b",
            user_prompt_text,
            re.IGNORECASE,
        )
        system_budget_match = re.search(
            r"\binclude\s+(?:exactly\s+)?(\d+)\b[^.]*\btest\(s\)",
            str(system_prompt or ""),
            re.IGNORECASE,
        )
        user_test_budget = int(user_budget_match.group(1)) if user_budget_match else None
        system_test_budget = int(system_budget_match.group(1)) if system_budget_match else None
        mutation_only_prompt = mutation_feedback_marker_present
        mutation_structural_section_leaks = []
        if mutation_only_prompt:
            if active_uncovered_section_count:
                mutation_structural_section_leaks.append("[Active Uncovered Objectives]")
            if executable_baseline_schema_section_count:
                mutation_structural_section_leaks.append("[Executable Baseline Schema]")
            if "[Current Round Test Objectives]" in audit_prompt_text:
                mutation_structural_section_leaks.append("[Current Round Test Objectives]")
            if "required_coverage_obligation_ids" in audit_prompt_text:
                mutation_structural_section_leaks.append("required_coverage_obligation_ids")
            if re.search(r'"coverage_obligation_id"\s*:', audit_prompt_text):
                mutation_structural_section_leaks.append("coverage_obligation_id_schema_field")
        prompt_audit = {
            "prompt_audit_window_chars": len(audit_prompt_text),
            "prompt_audit_window_truncated": audit_window_truncated,
            "user_test_budget": user_test_budget,
            "system_test_budget": system_test_budget,
            "system_user_test_budget_mismatch": bool(
                user_test_budget is not None
                and system_test_budget is not None
                and user_test_budget != system_test_budget
            ),
            "active_uncovered_section_count": active_uncovered_section_count,
            "duplicate_active_uncovered_objectives": active_uncovered_section_count > 1,
            "source_before_active_uncovered": bool(
                active_pos >= 0 and source_pos >= 0 and source_pos < active_pos
            ),
            "baseline_skeleton_section_count": baseline_skeleton_section_count,
            "duplicate_baseline_skeleton_obligation": baseline_skeleton_section_count > 1,
            "baseline_skeleton_before_source": bool(
                skeleton_pos >= 0 and source_pos >= 0 and skeleton_pos < source_pos
            ),
            "baseline_skeleton_before_callable_surface": bool(
                skeleton_pos >= 0 and callable_pos >= 0 and skeleton_pos < callable_pos
            ),
            "baseline_skeleton_rendered_complete": cls._baseline_skeleton_rendered_complete(audit_prompt_text),
            "executable_baseline_schema_section_count": executable_baseline_schema_section_count,
            "duplicate_executable_baseline_schema": executable_baseline_schema_section_count > 1,
            "executable_baseline_schema_before_source": bool(
                executable_baseline_schema_pos >= 0 and source_pos >= 0 and executable_baseline_schema_pos < source_pos
            ),
            "executable_baseline_schema_before_callable_surface": bool(
                executable_baseline_schema_pos >= 0 and callable_pos >= 0 and executable_baseline_schema_pos < callable_pos
            ),
            "frontier_sketch_section_count": frontier_sketch_section_count,
            "duplicate_frontier_sketch_section": frontier_sketch_section_count > 1,
            "frontier_sketch_before_source": bool(
                frontier_pos >= 0 and source_pos >= 0 and frontier_pos < source_pos
            ),
            "frontier_sketch_before_callable_surface": bool(
                frontier_pos >= 0 and callable_pos >= 0 and frontier_pos < callable_pos
            ),
            "construction_repair_map_section_count": construction_map_section_count,
            "duplicate_construction_repair_map": construction_map_section_count > 1,
            "construction_repair_map_before_source": bool(
                construction_pos >= 0 and source_pos >= 0 and construction_pos < source_pos
            ),
            "collaborator_callable_map_section_count": collaborator_map_section_count,
            "duplicate_collaborator_callable_map": collaborator_map_section_count > 1,
            "collaborator_callable_map_before_source": bool(
                collaborator_pos >= 0 and source_pos >= 0 and collaborator_pos < source_pos
            ),
            "executable_candidate_recipe_section_count": executable_recipe_section_count,
            "duplicate_executable_candidate_recipe": executable_recipe_section_count > 1,
            "executable_candidate_recipe_before_source": bool(
                executable_recipe_pos >= 0 and source_pos >= 0 and executable_recipe_pos < source_pos
            ),
            "high_priority_mid_field_clip": cls._high_priority_mid_field_clip(audit_prompt_text),
            "high_priority_truncation_warnings": cls._high_priority_truncation_warnings(audit_prompt_text),
            "demoted_required_objective_conflicts": demoted_required_conflicts,
            "demoted_required_objective_conflict_count": len(demoted_required_conflicts),
            "mutation_only_prompt": mutation_only_prompt,
            "mutation_feedback_marker_present": mutation_feedback_marker_present,
            "mutation_objective_context_present": mutation_objective_context_present,
            "mutation_objective_ids_in_prompt": mutation_objective_ids_in_prompt,
            "mutation_only_structural_section_leaks": mutation_structural_section_leaks,
            "mutation_only_structural_section_leak_count": len(mutation_structural_section_leaks),
        }
        priority_prompt = coverage_feedback_present or unified_objective_present or mutation_feedback_present
        if limit and len(logs) >= limit:
            if not priority_prompt:
                return
            replace_index = next(
                (
                    idx
                    for idx, item in enumerate(logs)
                    if isinstance(item, dict)
                    and not bool(item.get("coverage_feedback_present"))
                    and not bool(item.get("unified_objective_present"))
                ),
                None,
            )
            if replace_index is None:
                return
        live_run_id = str(getattr(request, "live_run_id", "") or "")
        generation_iteration = getattr(request, "prompt_iteration", None)
        feedback_snapshot: dict[str, Any] = {}
        feedback_by_label = getattr(request, "generation_coverage_feedback_by_label", None)
        if isinstance(feedback_by_label, dict):
            feedback = feedback_by_label.get(label)
            if not isinstance(feedback, dict) and len(feedback_by_label) == 1:
                only_value = next(iter(feedback_by_label.values()), None)
                if isinstance(only_value, dict):
                    feedback = only_value
            if isinstance(feedback, dict):
                raw_snapshot = feedback.get("feedback_snapshot")
                if isinstance(raw_snapshot, dict):
                    feedback_snapshot = dict(raw_snapshot)
        phase_text = str(phase or "").strip().lower()
        live_feedback_present = coverage_feedback_present or (
            phase_text and phase_text != "generate"
        ) or any(
            marker in user_prompt_text
            for marker in (
                "[Immediate Validation Failure Objectives]",
                "[Recent Validation Failures]",
                "[Mutation Objective Context]",
                "NO_COVERAGE",
                "SURVIVED",
                "MutationReachability",
                "MutationAssertion",
            )
        )
        entry = {
            "phase": phase,
            "label": label,
            "target_label": label,
            "live_run_id": live_run_id,
            "generation_iteration": generation_iteration,
            "feedback_source": "current_live_run" if live_feedback_present else "initial_generation",
            "feedback_snapshot_id": feedback_snapshot.get("feedback_snapshot_id"),
            "feedback_source_phase": feedback_snapshot.get("feedback_source_phase"),
            "feedback_source_iteration": feedback_snapshot.get("feedback_source_iteration"),
            "feedback_snapshot_stale": bool(feedback_snapshot.get("feedback_snapshot_stale")),
            "attempt": attempt,
            "system_prompt": sys_text,
            "user_prompt": user_text,
            "system_prompt_chars": len(system_prompt or ""),
            "user_prompt_chars": len(user_prompt or ""),
            "truncated": bool(sys_truncated or user_truncated or section_truncated),
            "top_level_truncated": bool(sys_truncated or user_truncated),
            "section_truncated": section_truncated,
            "section_truncation_markers": section_truncation_markers,
            "static_entry_path_plan_present": "[Static Entry Path Plan]" in (user_prompt or ""),
            "static_analysis_marker_present": "[Static analysis:" in (user_prompt or ""),
            "private_direct_call_guard_present": "DO_NOT_CALL_DIRECTLY_PRIVATE_OVERLOAD" in (user_prompt or "")
            or "do not call it directly" in (user_prompt or "").lower(),
            "coverage_feedback_present": coverage_feedback_present,
            "mutation_feedback_present": mutation_feedback_present,
            "mutation_feedback_marker_present": mutation_feedback_marker_present,
            "mutation_objective_context_present": mutation_objective_context_present,
            "mutation_objective_ids_in_prompt": mutation_objective_ids_in_prompt,
            "unified_objective_present": unified_objective_present,
            "prompt_audit": prompt_audit,
        }
        if limit and len(logs) >= limit:
            logs[replace_index] = entry
        else:
            logs.append(entry)
        try:
            sidecar_path = getattr(request, "prompt_sidecar_path", None)
            if sidecar_path:
                flushed = max(0, int(getattr(request, "prompt_sidecar_flushed_count", 0) or 0))
                if len(logs) > flushed:
                    path = Path(sidecar_path)
                    path.parent.mkdir(parents=True, exist_ok=True)
                    with path.open("a", encoding="utf-8") as handle:
                        for idx in range(flushed, len(logs)):
                            row = dict(logs[idx]) if isinstance(logs[idx], dict) else {"value": str(logs[idx])}
                            row["index"] = idx
                            handle.write(json.dumps(row, ensure_ascii=True) + "\n")
                    request.prompt_sidecar_flushed_count = len(logs)
        except Exception:
            pass

    @staticmethod
    def _record_generation_stage(
        request: GenerationRequest,
        *,
        label: str,
        stage: str,
        extra: dict[str, Any] | None = None,
    ) -> None:
        """Write a lightweight live stage marker before expensive generation work."""
        try:
            object.__setattr__(request, "tatg_generation_stage", str(stage or ""))
        except Exception:
            pass
        if not bool(getattr(request, "log_prompts", False)):
            return
        sidecar_path = getattr(request, "prompt_sidecar_path", None)
        if not sidecar_path:
            return
        row: dict[str, Any] = {
            "phase": "generation_stage",
            "label": label,
            "target_label": label,
            "stage": str(stage or ""),
            "at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        if isinstance(extra, dict):
            row.update({
                str(key): value
                for key, value in extra.items()
                if value not in (None, "", [], {})
            })
        try:
            path = Path(sidecar_path)
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("a", encoding="utf-8") as handle:
                handle.write(json.dumps(row, ensure_ascii=True) + "\n")
        except Exception:
            pass

    @staticmethod
    def _jvm_descriptor_param_types(descriptor: str | None) -> list[str]:
        descriptor = (descriptor or "").strip()
        if not descriptor.startswith("(") or ")" not in descriptor:
            return []
        inner = descriptor[1:descriptor.index(")")]
        primitives = {
            "I": "int", "J": "long", "D": "double", "F": "float",
            "Z": "boolean", "B": "byte", "S": "short", "C": "char", "V": "void",
        }
        types: list[str] = []
        idx = 0
        while idx < len(inner):
            dims = 0
            while idx < len(inner) and inner[idx] == "[":
                dims += 1
                idx += 1
            if idx >= len(inner):
                break
            ch = inner[idx]
            if ch == "L":
                end = inner.find(";", idx)
                if end == -1:
                    break
                base = inner[idx + 1:end].replace("/", ".").rsplit(".", 1)[-1].rsplit("$", 1)[-1]
                idx = end + 1
            else:
                base = primitives.get(ch, ch)
                idx += 1
            types.append(base + "[]" * dims)
        return types

    @classmethod
    def _signature_matches_jvm_descriptor(cls, signature: str, descriptor: str | None) -> bool:
        descriptor_text = str(descriptor or "").strip()
        if not descriptor_text.startswith("(") or ")" not in descriptor_text:
            return False
        desired = cls._jvm_descriptor_param_types(descriptor)
        actual = []
        for typ in cls._signature_param_types(signature):
            simple = cls._erased_signature_param_type(typ)
            # Class-level Java type variables are not repeated in a method
            # signature, but their unbounded JVM erasure is Object.  Without
            # this normalization descriptor-qualified targets such as
            # ``put(K, V)`` and ``find(K, boolean)`` look unresolved even
            # though the source method is unambiguous.
            if re.fullmatch(r"[A-Z]", simple):
                simple = "Object"
            actual.append(simple)
        return actual == desired

    @staticmethod
    def _erased_signature_param_type(java_type: str) -> str:
        """Return JVM-erased simple source type for descriptor matching.

        JVM descriptors do not retain generic arguments.  Keeping ``<Msg>`` or
        ``<? extends Value>`` in the source-side value makes an exact method
        look unresolved even though its descriptor is unambiguous.  Strip
        nested type arguments while preserving array/varargs dimensions.
        """

        text = TATGEngineAdapter._strip_balanced_java_annotations(java_type)
        text = re.sub(r"\b(?:final|volatile|transient)\b", " ", text)
        text = text.replace("...", "[]")
        erased: list[str] = []
        depth = 0
        for char in text:
            if char == "<":
                depth += 1
                continue
            if char == ">" and depth:
                depth -= 1
                continue
            if depth == 0:
                erased.append(char)
        text = re.sub(r"\s*\[\s*\]", "[]", "".join(erased))
        text = re.sub(r"\s+", "", text)
        dimensions = ""
        while text.endswith("[]"):
            dimensions += "[]"
            text = text[:-2]
        return text.rsplit(".", 1)[-1].rsplit("$", 1)[-1] + dimensions

    def build_preanalysis_context(
        self,
        request: GenerationRequest,
        target: Target,
        source_file: Path,
        source_code: str,
    ) -> dict[str, Any]:
        started = time.perf_counter()
        callgraph_ctx = build_static_analysis_context(
            request=request,
            target=target,
            source_file=source_file,
        )
        if target.method_name and callgraph_ctx:
            callgraph_ctx = self._truncate_prompt_context(
                callgraph_ctx,
                int(os.getenv("TATG_MAX_METHOD_CALLGRAPH_CHARS", "6000")),
            )

        max_scan = int(os.getenv("TATG_MAX_SCAN_FILES", str(self._DEFAULT_MAX_SCAN_FILES)))
        tatg_ctx = build_type_aware_context(
            source_file,
            request.project_root,
            method_name=target.method_name,
            class_name=target.class_name or source_file.stem,
            max_scan_files=max_scan,
        )

        method_is_private = False
        method_is_protected = False
        method_is_package_private = False
        method_is_static = False
        entry_points: list[dict[str, object]] = []
        if target.method_name:
            blocks = self._collect_method_blocks(
                source_code,
                class_name=target.class_name or source_file.stem,
            )
            target_descriptor = str(
                getattr(request, "target_descriptor", "") or ""
            ).strip()
            selected_block: dict[str, object] | None = None
            if target_descriptor:
                for block in blocks:
                    if str(block["name"]) == target.method_name and self._signature_matches_jvm_descriptor(
                        str(block.get("signature") or ""),
                        target_descriptor,
                    ):
                        selected_block = block
                        break
            for block in blocks:
                if selected_block is not None:
                    break
                if str(block["name"]) == target.method_name:
                    selected_block = block
                    break
            if selected_block is not None:
                method_is_private = bool(selected_block.get("is_private"))
                method_is_protected = bool(selected_block.get("is_protected"))
                method_is_package_private = str(selected_block.get("access") or "") == "package-private"
                method_is_static = bool(selected_block.get("is_static"))
            elif target.method_name:
                fallback_access = self._target_method_access_in_source(
                    str(target.method_name),
                    source_code,
                    class_name=target.class_name or source_file.stem,
                )
                method_is_private = fallback_access == "private"
                method_is_protected = fallback_access == "protected"
                method_is_package_private = fallback_access == "package-private"
            if method_is_private:
                entry_points = self._sootup_entry_points(request, target, source_code)
                log.debug(
                    "Private method %s: found %d public entry point(s): %s",
                    target.method_name,
                    len(entry_points),
                    [ep["method"] for ep in entry_points],
                )
            elif method_is_protected:
                entry_points = self._find_public_entry_points(
                    str(target.method_name),
                    source_code,
                    target_descriptor=target_descriptor or None,
                    class_name=target.class_name or source_file.stem,
                )

        api_surface_anchor = ""
        try:
            from tatg.analysis.api_surface import (
                extract_surface,
                render_surface_anchor,
            )
            callable_surface = extract_surface(
                source_file,
                target.class_name or source_file.stem,
            )
            if target.method_name:
                allowed_method_names = {
                    str(target.method_name),
                    *{
                        str(entry.get("method") or "").strip()
                        for entry in entry_points
                        if str(entry.get("method") or "").strip()
                    },
                }
                callable_surface.target_methods = [
                    method
                    for method in callable_surface.target_methods
                    if method.name in allowed_method_names
                ]
            api_surface_anchor = render_surface_anchor(callable_surface)
        except Exception as exc:  # noqa: BLE001
            log.debug("TATG API surface anchor skipped for %s: %s", source_file, exc)

        symbol_grounding = ""
        try:
            symbol_grounding = self._render_symbol_grounding_section(
                project_root=request.project_root or source_file.parent,
                source_code=source_code,
                type_shapes=tatg_ctx.type_shapes,
                target_method=target.method_name,
            )
        except Exception as exc:  # noqa: BLE001
            log.debug("TATG symbol grounding skipped for %s: %s", source_file, exc)

        construction_recipes = ""
        try:
            construction_recipes = self._render_construction_recipes_section(
                source_file=source_file,
                project_root=request.project_root or source_file.parent,
                class_name=target.class_name or source_file.stem,
                method_name=str(target.method_name or "").strip() or None,
                source_code=source_code,
                type_shapes=tatg_ctx.type_shapes,
            )
        except Exception as exc:  # noqa: BLE001
            log.debug("TATG construction recipes skipped for %s: %s", source_file, exc)

        return {
            "status": "ok",
            "callgraph_ctx": callgraph_ctx,
            "tatg_ctx": tatg_ctx,
            "method_is_private": method_is_private,
            "method_is_protected": method_is_protected,
            "method_is_package_private": method_is_package_private,
            "method_is_static": method_is_static,
            "entry_points": entry_points,
            "api_surface_anchor": api_surface_anchor,
            "symbol_grounding": symbol_grounding,
            "construction_recipes": construction_recipes,
            "elapsed_seconds": round(time.perf_counter() - started, 3),
        }

    @staticmethod
    def _fallback_preanalysis_context(target: Target, source_file: Path, reason: str) -> dict[str, Any]:
        return {
            "status": "fallback",
            "reason": reason,
            "callgraph_ctx": "",
            "tatg_ctx": TypeAwareContext(target_class=target.class_name or source_file.stem),
            "method_is_private": False,
            "method_is_protected": False,
            "method_is_package_private": False,
            "method_is_static": False,
            "entry_points": [],
            "api_surface_anchor": "",
            "symbol_grounding": "",
            "construction_recipes": "",
            "elapsed_seconds": 0.0,
        }

    @staticmethod
    def _lookup_label_keyed_dict(mapping: Any, label: str) -> Any:
        if not isinstance(mapping, dict):
            return None
        text = str(label or "").strip()
        if not text:
            return None
        exact = mapping.get(text)
        if exact is not None:
            return exact
        matches = [
            value for key, value in mapping.items()
            if text.endswith(str(key or "")) or str(key or "").endswith(text)
        ]
        return matches[0] if len(matches) == 1 else None

    def _preanalysis_context_for_target(
        self,
        request: GenerationRequest,
        target: Target,
        source_file: Path,
        source_code: str,
    ) -> dict[str, Any]:
        cache = getattr(request, "tatg_preanalysis_cache", {}) or {}
        cached = cache.get(target.label) if isinstance(cache, dict) else None
        if isinstance(cached, dict):
            if cached.get("status") == "ok":
                return cached
            if cached.get("status") in {"timeout", "error"}:
                return self._fallback_preanalysis_context(
                    target,
                    source_file,
                    str(cached.get("reason") or cached.get("status") or "preanalysis_unavailable"),
                )
        return self.build_preanalysis_context(request, target, source_file, source_code)

    def _testing_stack_constraints(self, request: GenerationRequest) -> str:
        lines: list[str] = []
        requested_major = self._java_major_version(getattr(request, "java_version", "") or "")
        source_major = self._project_source_level_major(getattr(request, "project_root", None))
        effective_major = source_major or requested_major
        if request.java_version:
            lines.append(f"- Keep syntax compatible with Java {request.java_version}.")
        if source_major and requested_major and source_major < requested_major:
            lines.append(
                f"- Project compiler source level appears to be Java {source_major}; generated test source must not use syntax/APIs newer than that source level even if the runtime JDK is newer."
            )
        if effective_major:
            major = effective_major
            if major and major <= 7:
                lines.append("- Do NOT use lambda expressions, method references, streams, or java.util.function APIs; this source level predates Java 8.")
                lines.append("- For exception assertions, use explicit try/catch plus fail(...) instead of assertThrows/lambdas.")
            if major and major <= 8:
                lines.append("- Do NOT use Java 9+ collection factories such as List.of, Set.of, Map.of, or Optional.stream.")
            if major and major <= 10:
                lines.append("- Do NOT use local-variable type inference (`var`).")
            if major and major <= 14:
                lines.append("- Do NOT use Java text blocks or newer switch expression syntax.")
        family = (request.junit_family or "").lower()
        if family == "junit4":
            lines.append("- Use JUnit 4: org.junit.Test + org.junit.Assert.*.")
            lines.append("- Lifecycle hooks: @Before / @After for per-test setup/teardown.")
            lines.append("- Shared expensive fixtures: @BeforeClass / @AfterClass (must be static).")
            lines.append("- Do NOT use org.junit.jupiter.* APIs.")
        elif family == "junit5":
            lines.append("- Use JUnit 5: @ExtendWith(MockitoExtension.class), org.junit.jupiter.api.*.")
            lines.append("- Use Mockito 5 (@Mock, @InjectMocks, when/thenReturn).")
            lines.append("- Lifecycle hooks: @BeforeEach / @AfterEach for per-test setup/teardown.")
            lines.append("- Shared expensive fixtures: @BeforeAll / @AfterAll.")
            lines.append("- Do NOT use org.junit.Test or org.junit.Assert.*.")
        elif request.junit_version:
            lines.append(f"- Use a JUnit API compatible with version {request.junit_version}.")
            lines.append("- Use matching setup/teardown annotations for that JUnit version.")
        return "\n".join(lines)

    @classmethod
    def _project_source_level_major(cls, project_root: Path | str | None) -> int | None:
        if not project_root:
            return None
        try:
            root = Path(project_root)
            build_system = detect_build_system(root)
            java_version, _, _ = infer_runtime_versions(root, build_system)
            return cls._java_major_version(java_version)
        except Exception:
            return None

    @staticmethod
    def _java_major_version(value: str) -> int | None:
        text = str(value or "").strip().lower()
        if not text:
            return None
        text = text.removeprefix("java")
        text = text.removeprefix("jdk")
        text = text.strip(" -_=v")
        if text.startswith("1."):
            text = text[2:]
        match = re.search(r"\d+", text)
        if not match:
            return None
        try:
            return int(match.group(0))
        except ValueError:
            return None

    def _derive_test_file(self, source_file: Path) -> Path:
        if source_file.suffix == ".java":
            return derive_java_test_file(source_file)
        return source_file.with_name(source_file.stem + "Test" + source_file.suffix)

    @staticmethod
    def _should_isolate_generated_test_file(existing_test: str) -> bool:
        """Return True when appending to an existing test class is risky.

        Mature projects often have hand-written test classes with custom
        runners, Truth assertions, inherited fixtures, or helper base classes.
        Adding generated methods directly to those classes couples TATG output
        to project-specific setup paths and can make otherwise valid standalone
        tests fail during streaming validation.  The heuristic is deliberately
        generic and conservative: it only isolates when the file has clear
        non-plain-JUnit structure.
        """
        text = existing_test or ""
        if not text.strip():
            return False
        if os.getenv("TATG_ISOLATE_EXISTING_TEST_CONFLICTS", "1").lower() in {"0", "false", "no", "off"}:
            return False
        custom_runner = "@RunWith(" in text and "MockitoJUnitRunner" not in text
        custom_extension = "@ExtendWith(" in text and "MockitoExtension" not in text
        truth_assertions = "com.google.common.truth.Truth" in text or "assertThat(" in text and "org.assertj" not in text
        inherited_fixture = bool(re.search(r"\bclass\s+\w+Test\s+extends\s+(?!TestCase\b)\w+", text))
        custom_rules = bool(re.search(r"@(?:ClassRule|Rule)\b", text))
        malformed_static_imports = bool(
            re.search(r"(?m)^\s*import\s+(?:org\.junit\.jupiter\.api\.Assertions|org\.mockito\.Mockito)\.\*\s*;", text)
        )
        lifecycle_names = re.findall(
            r"@(?:BeforeEach|AfterEach|Before|After)\s+"
            r"(?:public|protected|private)?\s*(?:static\s+)?void\s+([A-Za-z_$][\w$]*)\s*\(",
            text,
        )
        duplicate_lifecycle = len(lifecycle_names) != len(set(lifecycle_names))
        return bool(
            custom_runner
            or custom_extension
            or truth_assertions
            or inherited_fixture
            or custom_rules
            or malformed_static_imports
            or duplicate_lifecycle
        )

    @staticmethod
    def _isolated_generated_test_file(test_file: Path) -> Path:
        if test_file.suffix:
            return test_file.with_name(f"{test_file.stem}_TATGTest{test_file.suffix}")
        return test_file.with_name(f"{test_file.name}_TATGTest")

    @staticmethod
    def _retarget_test_command_class_filter(command: str, old_stem: str, new_stem: str) -> str:
        """Point common Maven/Gradle single-test filters at the isolated class."""
        if not command or not old_stem or not new_stem or old_stem == new_stem:
            return command
        updated = command
        updated = re.sub(
            rf"(-Dtest=)([^\s]*\b){re.escape(old_stem)}(\b[^\s]*)",
            rf"\1\2{new_stem}\3",
            updated,
        )
        updated = re.sub(
            rf"(--tests\s+['\"]?)([^'\"\s]*\b){re.escape(old_stem)}(\b[^'\"\s]*)",
            rf"\1\2{new_stem}\3",
            updated,
        )
        return updated

    @staticmethod
    def _find_matching_brace(source_code: str, open_pos: int) -> int:
        """Return the index just past the closing ``}`` matching the ``{`` at
        *open_pos*, skipping braces inside string literals, char literals,
        Java text blocks (``\"\"\"...\"\"\"``), and line/block comments.

        Returns -1 if no matching brace is found.
        """
        n = len(source_code)
        depth = 0
        idx = open_pos
        while idx < n:
            ch = source_code[idx]
            # Line comment: skip to end of line
            if ch == '/' and idx + 1 < n and source_code[idx + 1] == '/':
                idx = source_code.find('\n', idx)
                if idx == -1:
                    break
                continue
            # Block comment: skip to */
            if ch == '/' and idx + 1 < n and source_code[idx + 1] == '*':
                end_comment = source_code.find('*/', idx + 2)
                idx = end_comment + 2 if end_comment != -1 else n
                continue
            # Java text block: """..."""  (Java 15+) — must be checked before
            # the regular string-literal branch because """ starts with "
            if (ch == '"'
                    and idx + 2 < n
                    and source_code[idx + 1] == '"'
                    and source_code[idx + 2] == '"'):
                idx += 3  # skip opening """
                while idx < n:
                    if (source_code[idx] == '"'
                            and idx + 2 < n
                            and source_code[idx + 1] == '"'
                            and source_code[idx + 2] == '"'):
                        idx += 3  # skip closing """
                        break
                    idx += 1
                continue
            # String or char literal: skip to closing unescaped quote
            if ch in ('"', "'"):
                quote = ch
                idx += 1
                while idx < n:
                    c = source_code[idx]
                    if c == '\\':   # escape sequence
                        idx += 2
                        continue
                    if c == quote:
                        break
                    idx += 1
                idx += 1
                continue
            if ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    return idx + 1
            idx += 1
        return -1

    def _collect_method_blocks(
        self,
        source_code: str,
        *,
        class_name: str | None = None,
    ) -> list[dict[str, object]]:
        blocks: list[dict[str, object]] = []
        effective_source = (
            scope_java_source_to_type(source_code, class_name)
            if class_name
            else source_code
        )
        def _strip_for_method_scan(text: str) -> str:
            out: list[str] = []
            idx = 0
            in_line_comment = False
            in_block_comment = False
            in_string = False
            in_char = False
            escaped = False
            while idx < len(text):
                ch = text[idx]
                nxt = text[idx + 1] if idx + 1 < len(text) else ""
                if in_line_comment:
                    if ch == "\n":
                        in_line_comment = False
                        out.append(ch)
                    else:
                        out.append(" ")
                elif in_block_comment:
                    if ch == "*" and nxt == "/":
                        in_block_comment = False
                        out.extend("  ")
                        idx += 1
                    else:
                        out.append("\n" if ch == "\n" else " ")
                elif escaped:
                    escaped = False
                    out.append(" ")
                elif ch == "\\" and (in_string or in_char):
                    escaped = True
                    out.append(" ")
                elif in_string:
                    if ch == '"':
                        in_string = False
                    out.append("\n" if ch == "\n" else " ")
                elif in_char:
                    if ch == "'":
                        in_char = False
                    out.append("\n" if ch == "\n" else " ")
                elif ch == "/" and nxt == "/":
                    in_line_comment = True
                    out.extend("  ")
                    idx += 1
                elif ch == "/" and nxt == "*":
                    in_block_comment = True
                    out.extend("  ")
                    idx += 1
                elif ch == '"':
                    in_string = True
                    out.append(" ")
                elif ch == "'":
                    in_char = True
                    out.append(" ")
                else:
                    out.append(ch)
                idx += 1
            return "".join(out)

        scan_code = _strip_for_method_scan(effective_source)
        direct_member_depths: list[int] | None = None
        if class_name:
            # ``scope_java_source_to_type`` intentionally preserves nested type
            # bodies.  A method scan over that text must still distinguish the
            # configured owner's direct members from methods declared by those
            # nested types; otherwise an inner class with the same name and JVM
            # descriptor makes exact target resolution ambiguous.
            direct_member_depths = [0] * (len(scan_code) + 1)
            depth = 0
            for index, char in enumerate(scan_code):
                direct_member_depths[index] = depth
                if char == "{":
                    depth += 1
                elif char == "}":
                    depth = max(0, depth - 1)
            direct_member_depths[len(scan_code)] = depth
        original_type_bounds: tuple[int, int] | None = None
        if class_name and effective_source != source_code:
            requested = str(class_name or "").strip().rsplit(".", 1)[-1]
            candidates = [requested]
            if "$" in requested and not requested.startswith("$"):
                candidates.append(requested.rsplit("$", 1)[-1])
            original_scan = _strip_for_method_scan(source_code)
            for candidate in dict.fromkeys(candidates):
                type_match = re.search(
                    rf"\b(?:class|interface|enum|record|@interface)\s+"
                    rf"{re.escape(candidate)}\b[^{{;]*\{{",
                    original_scan,
                )
                if type_match is None:
                    continue
                type_open = original_scan.find("{", type_match.start())
                type_end = self._find_matching_brace(original_scan, type_open)
                if type_open >= 0 and type_end > type_open:
                    original_type_bounds = (type_open + 1, type_end - 1)
                    break
        java_keywords = {
            "if", "else", "for", "while", "switch", "catch", "try", "do",
            "return", "throw", "new", "case", "default", "synchronized",
        }
        for match in self._RE_SOURCE_METHOD_SIGNATURE.finditer(scan_code):
            if (
                direct_member_depths is not None
                and direct_member_depths[match.start()] != 1
            ):
                continue
            method_name = str(match.group("name") or "")
            if method_name in java_keywords:
                continue
            start = match.start()
            # Abstract/interface declarations end in ';' and have no body to
            # mine.  For concrete methods the bounded declaration scanner
            # includes the opening brace as its final character.
            brace_start = scan_code.rfind("{", match.start(), match.end())
            if brace_start < 0:
                continue
            end = self._find_matching_brace(scan_code, brace_start)
            if end == -1:
                continue
            signature = effective_source[match.start():brace_start + 1]
            tokens = set(signature.split())
            access = "private" if "private" in tokens else "protected" if "protected" in tokens else "public" if "public" in tokens else "package-private"
            block_body = effective_source[start:end]
            original_start = start
            original_end = end
            offset_source = "original_source"
            if original_type_bounds is not None:
                type_start, type_end = original_type_bounds
                mapped_start = source_code.find(
                    block_body,
                    type_start,
                    type_end + 1,
                )
                if mapped_start >= 0:
                    original_start = mapped_start
                    original_end = mapped_start + len(block_body)
                    offset_source = "class_scoped_block_mapped_to_original"
                else:
                    # Keep the executable block for prompt context, but never
                    # expose a scoped-text offset as an original-file offset.
                    original_start = -1
                    original_end = -1
                    offset_source = "class_scoped_block_unmapped"
            blocks.append({
                "name": method_name,
                "signature": signature,
                "start": original_start,
                "end": original_end,
                "scoped_start": start,
                "scoped_end": end,
                "offset_source": offset_source,
                "body": block_body,
                "access": access,
                "is_private": access == "private",
                "is_protected": access == "protected",
                "is_static": "static" in tokens,
            })
        return blocks

    @classmethod
    def _target_method_access_in_source(
        cls,
        method_name: str,
        source_code: str,
        *,
        class_name: str | None = None,
    ) -> str:
        """Return a target declaration's access without treating calls as declarations.

        The primary method scanner is line-anchored to avoid catastrophic
        backtracking on large sources. This bounded fallback handles compact or
        generated one-line classes where a declaration starts immediately after
        the class opening brace.
        """
        scoped = (
            scope_java_source_to_type(source_code, class_name)
            if class_name
            else source_code
        )
        match = re.search(
            rf"(?:^|[;{{}}])[ \t\r\n]*"
            rf"(?P<mods>(?:(?:public|protected|private|static|final|synchronized|native|abstract|strictfp|default)[ \t\r\n]+)*)"
            rf"(?:<[^;{{}}()]+>[ \t\r\n]+)?"
            rf"[A-Za-z_$][A-Za-z0-9_$.\[\]?]*(?:[ \t]*<[^;{{}}()]+>)?(?:[ \t]*\[\])?[ \t\r\n]+"
            rf"{re.escape(method_name)}[ \t\r\n]*\([^;{{}}]*\)[ \t\r\n]*"
            rf"(?:throws[ \t\r\n]+[^;{{}}]+)?[ \t\r\n]*\{{",
            scoped,
        )
        if match is None:
            return ""
        modifiers = set(str(match.group("mods") or "").split())
        if "private" in modifiers:
            return "private"
        if "protected" in modifiers:
            return "protected"
        if "public" in modifiers:
            return "public"
        return "package-private"

    @classmethod
    def _is_package_private_in_source(cls, method_name: str, source_code: str) -> bool:
        """Return True if method_name exists in source as a package-private declaration.

        A method is package-private when it has no explicit public/protected/private modifier.
        We detect this by confirming: (a) no access-modified declaration exists AND
        (b) a method-declaration-like pattern with a body brace exists for the name.
        """
        has_modifier = bool(re.search(
            rf"(?m)\b(?:public|private|protected)\b[^{{;]*\b{re.escape(method_name)}\s*\(",
            source_code,
        ))
        if has_modifier:
            return False
        # Require a `{` after the parameter list (distinguishes declaration from call site)
        return bool(re.search(
            rf"(?m)\b{re.escape(method_name)}\s*\([^)]*\)\s*(?:throws[^{{]+)?\{{",
            source_code,
        ))

    @classmethod
    def _signature_param_types(cls, signature: str) -> list[str]:
        params = cls._outer_method_parameter_text(signature)
        if params is None:
            return []
        params = params.strip()
        if not params:
            return []
        types: list[str] = []
        for raw_part in cls._split_top_level_args(params):
            ptype = cls._java_param_type_from_decl(
                cls._strip_balanced_java_annotations(raw_part)
            )
            if ptype:
                types.append(ptype)
        return types

    @staticmethod
    def _outer_method_parameter_text(signature: str) -> str | None:
        """Return the last balanced top-level parenthesized declaration group."""

        text = str(signature or "")
        groups: list[tuple[int, int]] = []
        depth = 0
        start = -1
        quote = ""
        escaped = False
        for index, char in enumerate(text):
            if quote:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = ""
                continue
            if char in {'"', "'"}:
                quote = char
            elif char == "(":
                if depth == 0:
                    start = index
                depth += 1
            elif char == ")" and depth:
                depth -= 1
                if depth == 0 and start >= 0:
                    groups.append((start, index))
        if not groups:
            return None
        start, end = groups[-1]
        return text[start + 1:end]

    @staticmethod
    def _strip_balanced_java_annotations(text: str) -> str:
        source = str(text or "")
        out: list[str] = []
        index = 0
        while index < len(source):
            if source[index] != "@":
                out.append(source[index])
                index += 1
                continue
            name = re.match(r"@[A-Za-z_$][A-Za-z0-9_$.]*", source[index:])
            if name is None:
                out.append(source[index])
                index += 1
                continue
            end = index + name.end()
            cursor = end
            while cursor < len(source) and source[cursor].isspace():
                cursor += 1
            if cursor < len(source) and source[cursor] == "(":
                depth = 0
                quote = ""
                escaped = False
                scan = cursor
                while scan < len(source):
                    char = source[scan]
                    if quote:
                        if escaped:
                            escaped = False
                        elif char == "\\":
                            escaped = True
                        elif char == quote:
                            quote = ""
                    elif char in {'"', "'"}:
                        quote = char
                    elif char == "(":
                        depth += 1
                    elif char == ")":
                        depth -= 1
                        if depth == 0:
                            scan += 1
                            break
                    scan += 1
                if depth != 0:
                    out.append(source[index])
                    index += 1
                    continue
                end = scan
            while end < len(source) and source[end].isspace():
                end += 1
            out.append(" ")
            index = end
        return "".join(out)

    @classmethod
    def _signature_param_bindings(cls, signature: str) -> dict[str, str]:
        """Return source parameter names bound to their declared Java types.

        Descriptor-aware entry discovery needs more than call arity.  In
        particular, a class may contain same-name/same-arity overloads where
        one caller passes ``Object`` and another explicitly casts that value
        to ``Reader``.  These bindings let the source call graph distinguish
        those paths without depending on project or method names.
        """

        params = cls._outer_method_parameter_text(signature)
        if params is None:
            return {}
        bindings: dict[str, str] = {}
        for raw_part in cls._split_top_level_args(params):
            part = cls._strip_balanced_java_annotations(raw_part).strip()
            part = re.sub(r"\bfinal\b\s*", "", part).strip()
            if not part:
                continue
            name_match = re.search(r"([A-Za-z_$][\w$]*)\s*(?:\[\s*\])?\s*$", part)
            if not name_match:
                continue
            name = name_match.group(1)
            declared = part[:name_match.start()].strip()
            if "..." in declared:
                declared = declared.replace("...", "[]")
            declared = " ".join(declared.split())
            if declared:
                bindings[name] = declared
        return bindings

    @staticmethod
    def _java_param_type_from_decl(raw_param: str) -> str:
        """Return the type part of a Java parameter declaration.

        Use the last whitespace-separated token as the parameter name so
        generic commas remain inside the type, e.g. ``Map<String, Object>
        state`` stays intact instead of becoming ``Object> state``.
        """
        part = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", str(raw_param or "")).strip()
        part = re.sub(r"\bfinal\b\s*", "", part).strip()
        if not part:
            return ""
        if "..." in part:
            part = part.replace("...", "[]")
        depth = 0
        last_top_level_space = -1
        for idx, ch in enumerate(part):
            if ch == "<":
                depth += 1
            elif ch == ">":
                depth = max(0, depth - 1)
            elif ch.isspace() and depth == 0:
                last_top_level_space = idx
        if last_top_level_space >= 0:
            maybe_name = part[last_top_level_space:].strip()
            maybe_type = part[:last_top_level_space].strip()
            if maybe_type and re.fullmatch(r"[A-Za-z_$][\w$]*(?:\[\])?", maybe_name):
                return " ".join(maybe_type.split())
        return " ".join(part.split())

    @classmethod
    def _source_call_argument_type(
        cls,
        expression: str,
        *,
        caller_params: dict[str, str],
    ) -> str:
        """Infer a conservative Java type for one source call argument.

        This intentionally recognizes only syntax that is authoritative in
        the current source: explicit casts, caller parameters, array element
        projections, constructors, and primitive/string literals.  Unknown
        expressions stay unknown instead of guessing an overload.
        """

        value = str(expression or "").strip()
        if not value:
            return ""
        cast_match = re.match(
            r"^\(\s*(?P<type>[A-Za-z_$][\w$.\[\]<>?, \t]*)\s*\)\s*.+$",
            value,
            re.DOTALL,
        )
        if cast_match:
            return " ".join(cast_match.group("type").split())
        new_match = re.match(
            r"^new\s+(?P<type>[A-Za-z_$][\w$.]*(?:\s*<[^;(){}]+>)?(?:\[\])?)\b",
            value,
        )
        if new_match:
            return " ".join(new_match.group("type").split())
        array_match = re.match(
            r"^(?P<name>[A-Za-z_$][\w$]*)\s*\[.+\]$",
            value,
            re.DOTALL,
        )
        if array_match:
            declared = caller_params.get(array_match.group("name"), "")
            return declared[:-2].strip() if declared.endswith("[]") else ""
        if re.fullmatch(r"[A-Za-z_$][\w$]*", value):
            return caller_params.get(value, "")
        if value == "null":
            return "null"
        if value in {"true", "false"} or re.search(
            r"(?:==|!=|<=|>=|<|>|&&|\|\||\binstanceof\b)",
            value,
        ):
            return "boolean"
        if re.fullmatch(r'""(?:\s*)', value) or (
            len(value) >= 2 and value[0] == '"' and value[-1] == '"'
        ):
            return "String"
        if len(value) >= 3 and value[0] == "'" and value[-1] == "'":
            return "char"
        if re.fullmatch(r"[-+]?\d+[lL]", value):
            return "long"
        if re.fullmatch(r"[-+]?\d+", value):
            return "int"
        if re.fullmatch(
            r"[-+]?(?:\d+\.\d*|\d*\.\d+|\d+)(?:[eE][-+]?\d+)?[fF]",
            value,
        ):
            return "float"
        if re.fullmatch(
            r"[-+]?(?:\d+\.\d*|\d*\.\d+|\d+)(?:[eE][-+]?\d+)?[dD]?",
            value,
        ):
            return "double"
        return ""

    @classmethod
    def _source_argument_compatibility(
        cls,
        observed_type: str,
        expected_type: str,
    ) -> int | None:
        """Score source-proven overload compatibility, or reject a mismatch."""

        observed = cls._simple_type_name(str(observed_type or ""))
        expected = cls._simple_type_name(str(expected_type or ""))
        if not observed or observed == "null":
            return 0
        if not expected:
            return 0
        if observed == expected:
            return 8
        primitive_boxes = {
            "boolean": "Boolean",
            "byte": "Byte",
            "short": "Short",
            "char": "Character",
            "int": "Integer",
            "long": "Long",
            "float": "Float",
            "double": "Double",
        }
        if primitive_boxes.get(observed) == expected or primitive_boxes.get(expected) == observed:
            return 7
        if expected == "Object":
            return 1
        if expected == "CharSequence" and observed == "String":
            return 6
        return None

    @classmethod
    def _generic_type_arguments(cls, java_type: str) -> list[str]:
        text = str(java_type or "").strip()
        start = text.find("<")
        end = text.rfind(">")
        if start < 0 or end <= start:
            return []
        return [part.strip() for part in cls._split_top_level_args(text[start + 1:end]) if part.strip()]

    @classmethod
    def _functional_interface_lambda_hint(cls, java_type: str) -> str:
        """Render a source-backed lambda shape hint for common functional interfaces.

        This is intentionally taxonomy-only: it does not classify failures or
        change candidate promotion.  It simply makes an already visible
        callback/functional parameter executable by exposing arity and generic
        parameter roles when source signatures provide them.
        """
        param_type = " ".join(str(java_type or "").split())
        if not param_type:
            return ""
        simple = cls._simple_type_name(param_type)
        args = cls._generic_type_arguments(param_type)
        first = cls._simple_type_name(args[0]) if len(args) >= 1 else "value"
        second = cls._simple_type_name(args[1]) if len(args) >= 2 else "value2"
        third = cls._simple_type_name(args[2]) if len(args) >= 3 else "result"
        if simple in {"Runnable"}:
            return "lambda_shape=() -> ...; arity=0; returns=void"
        if simple in {"Supplier"}:
            return f"lambda_shape=() -> {first}; arity=0; returns={first}"
        if simple in {"Callable"}:
            return f"lambda_shape=() -> {first}; arity=0; returns={first}; may_throw=true"
        if simple in {"Consumer"}:
            return f"lambda_shape=({first.lower()}) -> ...; arity=1; param_types={first}; returns=void"
        if simple in {"BiConsumer"}:
            return (
                f"lambda_shape=({first.lower()}, {second.lower()}) -> ...; "
                f"arity=2; param_types={first}, {second}; returns=void"
            )
        if simple in {"Predicate"}:
            return f"lambda_shape=({first.lower()}) -> boolean; arity=1; param_types={first}; returns=boolean"
        if simple in {"BiPredicate"}:
            return (
                f"lambda_shape=({first.lower()}, {second.lower()}) -> boolean; "
                f"arity=2; param_types={first}, {second}; returns=boolean"
            )
        if simple in {"Function", "UnaryOperator"}:
            return f"lambda_shape=({first.lower()}) -> {second}; arity=1; param_types={first}; returns={second}"
        if simple in {"BiFunction", "BinaryOperator"}:
            return (
                f"lambda_shape=({first.lower()}, {second.lower()}) -> {third}; "
                f"arity=2; param_types={first}, {second}; returns={third}"
            )
        if simple in {"Comparator"}:
            return f"lambda_shape=({first.lower()}1, {first.lower()}2) -> int; arity=2; param_types={first}, {first}; returns=int"
        return ""

    @classmethod
    def _display_type_for_signature(cls, java_type: str) -> str:
        text = " ".join(str(java_type or "").split())
        if not text:
            return ""
        simple = cls._simple_type_name(text)
        if simple not in {
            "Runnable",
            "Supplier",
            "Callable",
            "Consumer",
            "BiConsumer",
            "Predicate",
            "BiPredicate",
            "Function",
            "BiFunction",
            "UnaryOperator",
            "BinaryOperator",
            "Comparator",
        }:
            return simple
        args = cls._generic_type_arguments(text)
        if not args:
            return simple
        rendered_args = ", ".join(cls._display_type_for_signature(arg) for arg in args if str(arg).strip())
        return f"{simple}<{rendered_args}>" if rendered_args else simple

    @classmethod
    def _functional_interface_hints_for_signature(cls, signature: str) -> list[str]:
        hints: list[str] = []
        for param_type in cls._signature_param_types(signature):
            hint = cls._functional_interface_lambda_hint(param_type)
            if hint and hint not in hints:
                hints.append(f"{param_type}: {hint}")
        return hints

    @staticmethod
    def _overload_id(method_name: str, param_types: list[str]) -> str:
        if not param_types:
            return f"{method_name}#noargs"
        cleaned: list[str] = []
        for typ in param_types:
            simple = re.sub(r"\s+", "", typ.strip())
            simple = simple.replace("...", "Array")
            simple = simple.replace("[]", "Array")
            simple = simple.rsplit(".", 1)[-1]
            simple = re.sub(r"[^A-Za-z0-9]+", "_", simple).strip("_") or "arg"
            cleaned.append(simple)
        return f"{method_name}#" + "-".join(cleaned)

    @classmethod
    def _normalize_llm_overload_id(
        cls,
        raw_overload_id: str,
        allowed_overload_ids: set[str] | list[str] | tuple[str, ...] | None,
    ) -> str:
        """Normalize common LLM overload-id variants back to tool ids.

        The prompt asks for ids such as ``method#String``. Models sometimes
        echo a Java signature like ``method(String value)`` instead. Accept
        only variants that map unambiguously to one listed id.
        """
        raw = str(raw_overload_id or "").strip()
        allowed = {str(item).strip() for item in (allowed_overload_ids or []) if str(item).strip()}
        if not raw or not allowed:
            return raw
        if raw in allowed:
            return raw

        candidates: set[str] = set()
        sig_match = re.match(r"^\s*([A-Za-z_$][\w$]*)\s*\((.*)\)\s*$", raw)
        if sig_match:
            method = sig_match.group(1)
            params = cls._signature_param_types(f"{method}({sig_match.group(2)})")
            candidates.add(cls._overload_id(method, params))

        compact = re.sub(r"\s+", "", raw)
        if compact in allowed:
            candidates.add(compact)

        if "#" in raw:
            method, param_text = raw.split("#", 1)
            method = method.strip()
            param_text = param_text.strip()
            if method and param_text:
                parts = [part.strip() for part in re.split(r"[-,]", param_text) if part.strip()]
                candidates.add(cls._overload_id(method, parts))

        matches = sorted(candidate for candidate in candidates if candidate in allowed)
        if len(matches) == 1:
            return matches[0]

        if re.match(r"^[A-Za-z_$][\w$]*\Z", raw):
            duplicate_family: set[str] = set()
            for item in allowed:
                method, _, suffix = item.partition("#")
                if method != raw or not suffix:
                    continue
                duplicate_family.add(re.sub(r"_\d+\Z", "", item))
            if len(duplicate_family) == 1:
                family_base = next(iter(duplicate_family))
                return family_base if family_base in allowed else sorted(
                    item for item in allowed if item.startswith(f"{raw}#")
                )[0]

        # If only one overload id is allowed, accept a signature/name variant
        # only when the method name matches that single id's method component.
        if len(allowed) == 1:
            only = next(iter(allowed))
            only_method = only.split("#", 1)[0]
            raw_method = sig_match.group(1) if sig_match else raw.split("#", 1)[0].strip()
            if raw_method == only_method:
                return only
        return raw

    @classmethod
    def _method_overload_contracts(
        cls,
        source_code: str,
        method_name: str | None,
        *,
        class_name: str | None = None,
    ) -> list[dict[str, object]]:
        if not source_code or not method_name:
            return []
        adapter = cls()
        contracts: list[dict[str, object]] = []
        seen: set[str] = set()
        for block in adapter._collect_method_blocks(source_code, class_name=class_name):
            if str(block.get("name") or "") != method_name:
                continue
            raw_signature = str(block.get("signature") or "")
            raw_signature = re.sub(r"//[^\r\n]*", " ", raw_signature)
            raw_signature = re.sub(r"/\*.*?\*/", " ", raw_signature, flags=re.DOTALL)
            signature = " ".join(raw_signature.split())
            param_types = cls._signature_param_types(signature)
            overload_id = cls._overload_id(method_name, param_types)
            if overload_id in seen:
                suffix = 2
                base = overload_id
                while f"{base}_{suffix}" in seen:
                    suffix += 1
                overload_id = f"{base}_{suffix}"
            seen.add(overload_id)
            arg_names = [f"arg{i + 1}" for i in range(len(param_types))]
            access_match = re.match(r"(?:@[\w.]+(?:\([^)]*\))?\s+)*(public|protected|private)\b", signature)
            access = access_match.group(1) if access_match else "package"
            direct_call_shape = f"target.{method_name}(" + ", ".join(arg_names) + ")"
            contracts.append({
                "overload_id": overload_id,
                "signature": signature,
                "param_types": param_types,
                "access": access,
                "required_call_shape": (
                    direct_call_shape
                    if access != "private"
                    else "DO_NOT_CALL_DIRECTLY_PRIVATE_OVERLOAD; use a source-visible entry path that reaches this overload"
                ),
            })
        return contracts

    @classmethod
    def _target_overload_ids_from_descriptor(
        cls,
        contracts: list[dict[str, object]],
        descriptor: str | None,
    ) -> set[str]:
        if not descriptor:
            return set()
        ids: set[str] = set()
        for contract in contracts:
            if cls._signature_matches_jvm_descriptor(str(contract.get("signature") or ""), descriptor):
                overload_id = str(contract.get("overload_id") or "").strip()
                if overload_id:
                    ids.add(overload_id)
        return ids

    @staticmethod
    def _preferred_unconditional_entry_contract(
        entry_points: list[dict[str, object]] | None,
    ) -> dict[str, object]:
        """Return one exact visible direct-forwarder entry, when proven.

        General call-graph reachability is insufficient here: forcing an
        indirect entry that has guards or setup can hide the target.  The
        resolver marks ``direct_forwarder_path`` only after uniquely binding
        every owner-local edge and proving every caller body is exactly one
        forwarding statement.  Prefer public, then protected/package access.
        """

        access_rank = {
            "public": 0,
            "protected": 1,
            "package-private": 2,
            "default": 2,
            "package": 2,
        }
        candidates = [
            dict(entry)
            for entry in list(entry_points or [])
            if isinstance(entry, dict)
            and bool(entry.get("direct_forwarder_path"))
            and str(entry.get("access") or "") in access_rank
            and str(entry.get("method") or "").strip()
            and str(entry.get("signature") or "").strip()
        ]
        if not candidates:
            return {}
        candidates.sort(key=lambda entry: (
            access_rank.get(str(entry.get("access") or ""), 9),
            len(list(entry.get("path") or [])),
            str(entry.get("signature") or ""),
        ))
        return candidates[0]

    @classmethod
    def _existing_source_proven_entry_scaffold_test_names(
        cls,
        existing_test: str,
        preferred_entry: dict[str, object] | None,
    ) -> list[str]:
        """Return green-test candidates that call one proven direct entry.

        The caller decides whether the existing file is a retained green
        suite.  Here we require the exact source-proven entry name and arity,
        so an unrelated same-name helper cannot satisfy the scaffold merely
        by appearing in comments or a declaration.
        """

        entry = dict(preferred_entry or {})
        method_name = str(entry.get("method") or "").strip()
        try:
            arity = int(entry.get("arity"))
        except (TypeError, ValueError):
            return []
        if not existing_test or not method_name or arity < 0:
            return []
        _setup, test_methods, _teardown = cls._categorize_methods(existing_test)
        names: list[str] = []
        for method_code in test_methods:
            if arity not in cls._test_code_call_arities(
                method_code,
                method_name,
            ):
                continue
            name = cls._extract_method_name(method_code)
            if name and name not in names:
                names.append(name)
        return names[:8]

    @classmethod
    def _retained_seed_target_positive_test_names(
        cls,
        existing_test: str,
        evidence: dict[str, object] | None,
        *,
        target_descriptor: str,
    ) -> list[str]:
        """Use immutable archive coverage proof to retire a baseline scaffold.

        A retained Java file alone is not proof that it reaches this exact
        overload.  The batch supplies this evidence only after validating an
        exact descriptor, a green target-positive artifact, and the artifact
        checksum.  Normal retained files and unproven manifests keep the
        existing baseline behavior.
        """

        proof = dict(evidence or {})
        if str(proof.get("status") or "") != "archive_target_positive_measured":
            return []
        descriptor = str(proof.get("target_descriptor") or "").strip()
        if not descriptor or descriptor != str(target_descriptor or "").strip():
            return []
        try:
            line_coverage = float(proof.get("target_line_coverage") or 0.0)
        except (TypeError, ValueError):
            return []
        if line_coverage <= 0.0 or not existing_test:
            return []
        _setup, test_methods, _teardown = cls._categorize_methods(existing_test)
        names: list[str] = []
        for method_code in test_methods:
            name = cls._extract_method_name(method_code)
            if name and name not in names:
                names.append(name)
        return names[:8]

    @staticmethod
    def _render_retained_seed_exact_coverage_frontier(
        source_code: str,
        evidence: dict[str, object] | None,
        *,
        max_rows: int = 10,
    ) -> str:
        """Render checksum-verified JaCoCo gaps without guessing test inputs."""

        proof = dict(evidence or {})
        if str(proof.get("status") or "") != "archive_target_positive_measured":
            return ""
        rows = [
            dict(row)
            for row in list(proof.get("branch_frontier") or [])
            if isinstance(row, dict)
        ]
        if not rows:
            return ""
        source_lines = str(source_code or "").splitlines()
        normalized: list[dict[str, object]] = []
        for row in rows:
            try:
                line_number = int(row.get("line") or 0)
                covered = int(row.get("branch_covered") or 0)
                missed = int(row.get("branch_missed") or 0)
            except (TypeError, ValueError):
                continue
            if line_number <= 0 or missed <= 0 or line_number > len(source_lines):
                continue
            statement = " ".join(source_lines[line_number - 1].strip().split())
            if not statement:
                continue
            normalized.append(
                {
                    "line": line_number,
                    "covered": covered,
                    "missed": missed,
                    "statement": statement[:360],
                }
            )
        if not normalized:
            return ""
        normalized.sort(
            key=lambda row: (
                0 if int(row["covered"]) == 0 else 1,
                -int(row["missed"]),
                int(row["line"]),
            )
        )
        selected = normalized[: max(1, int(max_rows))]
        lines = [
            "[Retained Seed Exact Coverage Frontier]",
            "The retained green suite has checksum-verified JaCoCo coverage for this exact descriptor. The rows below are the remaining missed/partial branch sites in the current checksum-matched source.",
            "Infer executable public input/state sequences from the target source and listed callers. Do not set internal locals/fields directly, and do not repeat existing tests merely because their comments name one of these conditions.",
        ]
        for row in selected:
            total = int(row["covered"]) + int(row["missed"])
            status = "fully_missed" if int(row["covered"]) == 0 else "partial"
            lines.append(
                f"- line={row['line']}; status={status}; branch_outcomes="
                f"{row['covered']}/{total} covered; source={row['statement']}"
            )
        if len(normalized) > len(selected):
            lines.append(
                f"- omitted_lower_priority_frontier_rows={len(normalized) - len(selected)}"
            )
        return "\n".join(lines)

    @staticmethod
    def _mark_existing_entry_scaffold_satisfied(
        skeletons: list[dict[str, Any]],
        test_names: list[str],
        *,
        satisfaction_source: str = "retained_green_source_proven_direct_entry",
    ) -> None:
        """Mark only the entry baseline satisfied by retained green evidence."""

        names = [str(name).strip() for name in test_names if str(name).strip()]
        if not names:
            return
        for skeleton in skeletons:
            if not isinstance(skeleton, dict):
                continue
            skeleton["existing_green_entry_scaffold_test_names"] = names
            skeleton["status"] = "partial_progress"
            for fact in list(skeleton.get("facts") or []):
                if (
                    isinstance(fact, dict)
                    and str(fact.get("kind") or "")
                    in {"target_call", "entry_call"}
                ):
                    fact["status"] = "satisfied"
                    fact["satisfaction_source"] = satisfaction_source

    @staticmethod
    def _bind_preferred_entry_to_overload_contracts(
        contracts: list[dict[str, object]],
        *,
        target_overload_ids: set[str] | None,
        preferred_entry: dict[str, object] | None,
    ) -> list[dict[str, object]]:
        """Make one proven visible entry the ACT contract for a non-public target."""

        entry = dict(preferred_entry or {})
        signature = " ".join(str(entry.get("signature") or "").split())
        if not signature:
            return [dict(contract) for contract in contracts]
        allowed = set(target_overload_ids or [])
        bound: list[dict[str, object]] = []
        for raw in contracts:
            contract = dict(raw)
            overload_id = str(contract.get("overload_id") or "")
            access = str(contract.get("access") or "")
            is_target = not allowed or overload_id in allowed
            if is_target and access != "public":
                contract.update({
                    "required_call_shape": (
                        "SOURCE_VISIBLE_ENTRY_CALL: " + signature
                    ),
                    "source_visible_entry_required": True,
                    "source_visible_entry_signature": signature,
                    "source_visible_entry_path": list(entry.get("path") or []),
                    "direct_nonpublic_target_call_forbidden": True,
                })
            bound.append(contract)
        return bound

    @staticmethod
    def _render_target_overload_binding_section(target_overload_ids: set[str]) -> str:
        if not target_overload_ids:
            return ""
        allowed = ", ".join(sorted(target_overload_ids))
        return "\n".join([
            "[Target Overload Binding]",
            f"This method request has an exact JVM descriptor. Every returned new_tests item must use overload_id in: {allowed}.",
            "Sibling overload ids may appear in source context only as entry paths or setup helpers; do not use them as the scenario overload_id.",
            "For a private target overload, set overload_id to the private target overload. Call a listed source-visible entry path when one is verified; only use reflection when the prompt explicitly lists a private-reflection fallback for a target with no verified entry path.",
        ])

    @staticmethod
    def _render_overload_contracts_section(contracts: list[dict[str, object]]) -> str:
        if not contracts:
            return ""
        lines = [
            "[Overload-Specific Scenario Contract]",
            "Use these signature-level contracts for method-scope generation.",
            "Every new_tests item must include overload_id equal to one listed below.",
            "For public overloads, the Java statement body must invoke that exact overload shape with compatible argument types.",
            "For a protected/package target with a SOURCE_VISIBLE_ENTRY_CALL contract, use that exact proven entry as the ACT step and keep the target overload_id for descriptor coverage; do not directly call the helper.",
            "For a protected/package target without such a proven entry contract, invoke the exact overload shape with compatible argument types.",
            "For private overloads, the Java statement body must execute through a verified source-visible entry path when available; use reflection only when no verified entry path exists and a private-reflection fallback is explicitly listed.",
            "If only one overload exists, still use its overload_id so validation and repair can keep the scenario identity.",
        ]
        for idx, contract in enumerate(contracts, 1):
            param_types = contract.get("param_types") if isinstance(contract.get("param_types"), list) else []
            param_desc = ", ".join(str(t) for t in param_types) or "no arguments"
            lines.extend([
                f"{idx}) overload_id={contract.get('overload_id')}",
                f"   signature={contract.get('signature')}",
                f"   access={contract.get('access', 'unknown')}",
                f"   parameter_types={param_desc}",
                f"   required_call_shape={contract.get('required_call_shape')}",
                (
                    "   scenario_rule=use the exact source-visible direct-forwarder entry above as ACT; retain this target overload_id; do not call the non-public helper directly or substitute a sibling overload."
                    if contract.get("source_visible_entry_required")
                    else (
                        "   scenario_rule=choose a verified source-visible entry path and public input family that reaches this private overload; if none is listed, use only an explicitly listed private-reflection fallback. Do not substitute a sibling overload."
                        if contract.get("access") == "private"
                        else "   scenario_rule=choose a distinct legal fixture for this signature; do not substitute a sibling overload."
                    )
                ),
            ])
        return "\n".join(lines)

    @staticmethod
    def _method_patch_json_response_format(
        *,
        max_tests: int = 2,
        require_overload_id: bool = False,
    ) -> dict[str, Any]:
        """Return a bounded JSON schema for local method-patch generation."""

        exact_test_count = TATGEngineAdapter._method_patch_json_test_budget(
            max_tests
        )
        item_properties: dict[str, Any] = {
            "test_name": {"type": "string", "maxLength": 160},
            "test_code_lines": {
                "type": "array",
                "minItems": 3,
                "maxItems": 160,
                "items": {"type": "string", "maxLength": 1200},
            },
            "new_imports_lines": {
                "type": "array",
                "maxItems": 40,
                "items": {"type": "string", "maxLength": 500},
            },
            "overload_id": {"type": "string", "maxLength": 240},
            "coverage_obligation_id": {"type": "string", "maxLength": 80},
            "objective_id": {"type": "string", "maxLength": 80},
            "candidate_role": {"type": "string", "maxLength": 80},
            "baseline_skeleton_id": {"type": "string", "maxLength": 40},
            "skeleton_fact_ids": {
                "type": "array",
                "maxItems": 24,
                "items": {"type": "string", "maxLength": 40},
            },
            "test_behavior": {"type": "string", "maxLength": 500},
            "input_family": {"type": "string", "maxLength": 120},
            "oracle_type": {"type": "string", "maxLength": 120},
            "repair_axis": {"type": "string", "maxLength": 120},
        }
        required_item_fields = [
            "test_name",
            "test_code_lines",
            "new_imports_lines",
        ]
        if require_overload_id:
            required_item_fields.append("overload_id")
        return {
            "type": "json_schema",
            "json_schema": {
                "name": "tatg_method_test_patch",
                "strict": True,
                "schema": {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": {
                        "new_tests": {
                            "type": "array",
                            # The method prompt and system contract both request
                            # an exact response budget. Keeping min/max aligned
                            # prevents local structured-output models from
                            # satisfying a four-scenario request with one shallow
                            # guard test while remaining schema-valid.
                            "minItems": exact_test_count,
                            "maxItems": exact_test_count,
                            "items": {
                                "type": "object",
                                "additionalProperties": False,
                                "properties": item_properties,
                                "required": required_item_fields,
                            },
                        }
                    },
                    "required": ["new_tests"],
                },
            },
        }

    @staticmethod
    def _method_patch_json_test_budget(max_tests: int) -> int:
        """Return the single authoritative local structured-patch budget.

        LM Studio enforces the response schema independently from the natural
        language prompt.  If the prompt asks for more items than the schema can
        represent, local models tend to pack sibling JSON fields and multiple
        tests into ``test_code_lines``.  Keep the bounded schema and make every
        prompt/retry use this same value instead of advertising an impossible
        count.

        The cap is an env knob rather than a literal because it is the binding
        constraint on the whole run: at 4 per response over 2 generation rounds
        a target can never exceed 8 tests, and the measured baseline already
        sits at that ceiling on most targets.  Meanwhile 35 of the 141 benchmark
        targets sit at 0.4-0.6 branch coverage and carry 43.8% of the deficit to
        0.70, needing a median ~2.2 more tests each.

        Raising it is the opposite intervention to round batching, which failed
        by splitting one ask into several smaller ones.  The risk described
        above -- local models packing several tests into one JSON item as the
        schema grows -- is real, and an A/B on this knob is what measures it.
        Default stays 4, so the change is opt-in.
        """

        ceiling = TATGEngineAdapter._env_int(
            "TATG_MAX_TESTS_PER_RESPONSE", 4, minimum=1, maximum=12
        )
        return max(1, min(ceiling, int(max_tests or 1)))

    @classmethod
    def _target_call_arity_mismatches(
        cls,
        java_code: str,
        *,
        method_name: str | None,
        overload_contracts: list[dict[str, object]],
        test_overload_map: dict[str, str] | None = None,
    ) -> list[dict[str, Any]]:
        """Find source-proven wrong-arity target calls before invoking javac."""

        if not java_code or not method_name or not overload_contracts:
            return []
        contracts_by_id = {
            str(contract.get("overload_id") or ""): contract
            for contract in overload_contracts
            if isinstance(contract, dict) and str(contract.get("overload_id") or "")
        }
        if not contracts_by_id:
            return []
        default_contract = (
            next(iter(contracts_by_id.values()))
            if len(contracts_by_id) == 1
            else None
        )
        overload_map = test_overload_map or {}
        _setup, test_methods, _teardown = cls._categorize_methods(java_code)
        methods_to_check = test_methods or [java_code]
        mismatches: list[dict[str, Any]] = []
        call_pattern = re.compile(
            rf"(?<![A-Za-z0-9_$])(?:[A-Za-z_$][A-Za-z0-9_$]*\s*\.\s*)?"
            rf"{re.escape(method_name)}\s*\("
        )
        for method_code in methods_to_check:
            test_name = cls._extract_method_name(method_code) or ""
            overload_id = str(overload_map.get(test_name) or "")
            contract = contracts_by_id.get(overload_id) or default_contract
            if not isinstance(contract, dict):
                continue
            param_types = [
                str(value or "").strip()
                for value in list(contract.get("param_types") or [])
            ]
            expected_arity = len(param_types)
            signature = str(contract.get("signature") or "")
            varargs = "..." in signature
            observed_arities: list[int] = []
            scan_code = cls._strip_java_comments_preserve_literal_tokens(method_code)
            for match in call_pattern.finditer(scan_code):
                open_index = scan_code.find("(", match.start())
                close_index = cls._find_matching_paren(scan_code, open_index)
                if close_index < 0:
                    continue
                argument_text = scan_code[open_index + 1:close_index].strip()
                arity = (
                    0
                    if not argument_text
                    else len(cls._split_top_level_args(argument_text))
                )
                observed_arities.append(arity)
            if not observed_arities:
                continue
            valid = (
                any(
                    arity >= max(0, expected_arity - 1)
                    for arity in observed_arities
                )
                if varargs
                else expected_arity in observed_arities
            )
            if valid:
                continue
            mismatches.append({
                "test_method": test_name,
                "overload_id": str(contract.get("overload_id") or ""),
                "signature": signature,
                "expected_arity": expected_arity,
                "observed_arities": sorted(set(observed_arities)),
                "required_call_shape": str(
                    contract.get("required_call_shape") or ""
                ),
            })
        return mismatches

    @staticmethod
    def _strip_java_comments_preserve_literal_tokens(code: str) -> str:
        """Mask comments and literal contents without deleting arguments.

        Arity checks need to ignore text such as ``"target()"`` while still
        counting a literal in ``target("value")`` as one argument. The general
        source scanner intentionally erases literals completely, so using it
        here turns literal-only calls into false zero-arity calls.
        """

        result: list[str] = []
        idx = 0
        n = len(code)
        while idx < n:
            ch = code[idx]
            if ch == "/" and idx + 1 < n and code[idx + 1] == "/":
                end = code.find("\n", idx + 2)
                if end == -1:
                    result.extend(" " * (n - idx))
                    break
                result.extend(" " * (end - idx))
                result.append("\n")
                idx = end + 1
                continue
            if ch == "/" and idx + 1 < n and code[idx + 1] == "*":
                end = code.find("*/", idx + 2)
                stop = n if end == -1 else end + 2
                result.extend(
                    "\n" if value == "\n" else " "
                    for value in code[idx:stop]
                )
                idx = stop
                continue
            if ch in {'"', "'"}:
                quote = ch
                start = idx
                idx += 1
                while idx < n:
                    value = code[idx]
                    if value == "\\":
                        idx = min(n, idx + 2)
                        continue
                    idx += 1
                    if value == quote:
                        break
                token = '""' if quote == '"' else "'x'"
                result.append(token)
                consumed = idx - start
                if consumed > len(token):
                    result.extend(" " * (consumed - len(token)))
                continue
            result.append(ch)
            idx += 1
        return "".join(result)

    @staticmethod
    def _strip_java_comments_preserve_code(code: str) -> str:
        """Remove Java comments while preserving executable literals/code.

        Archived generated tests can contain thousands of words of model
        speculation inside comments. Feeding that prose to the mutation
        semantic verifier makes an old guess look like green runtime evidence.
        This scanner preserves strings, characters, source lines, calls, and
        assertions while replacing comments with whitespace/newlines.
        """

        result: list[str] = []
        index = 0
        in_string: str | None = None
        escaped = False
        while index < len(code):
            char = code[index]
            nxt = code[index + 1] if index + 1 < len(code) else ""
            if in_string is not None:
                result.append(char)
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == in_string:
                    in_string = None
                index += 1
                continue
            if char in {'"', "'"}:
                in_string = char
                result.append(char)
                index += 1
                continue
            if char == "/" and nxt == "/":
                end = code.find("\n", index + 2)
                if end < 0:
                    result.extend(" " * (len(code) - index))
                    break
                result.extend(" " * (end - index))
                result.append("\n")
                index = end + 1
                continue
            if char == "/" and nxt == "*":
                end = code.find("*/", index + 2)
                stop = len(code) if end < 0 else end + 2
                result.extend(
                    "\n" if value == "\n" else " "
                    for value in code[index:stop]
                )
                index = stop
                continue
            result.append(char)
            index += 1
        return "".join(result)

    @staticmethod
    def _mutation_pit_covering_test_method_names(
        mutation_feedback: object,
    ) -> set[str]:
        """Return Java method names from exact PIT block-coverage evidence."""

        if not isinstance(mutation_feedback, dict):
            return set()
        names: set[str] = set()
        for objective in list(
            mutation_feedback.get("mutation_objectives") or []
        ):
            if not isinstance(objective, dict):
                continue
            facts = (
                objective.get("facts")
                if isinstance(objective.get("facts"), dict)
                else objective
            )
            for raw_name in list(facts.get("pit_covering_tests") or []):
                value = str(raw_name or "").strip()
                if not value:
                    continue
                # JUnit Platform reports PIT coverage using UniqueId segments,
                # for example ``...[method:testBoundary()]``. Preserve the
                # exact Java method name before trying legacy display formats.
                unique_id_match = re.search(
                    r"\[method:(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)"
                    r"(?:\([^\]]*\))?\]",
                    value,
                )
                if unique_id_match:
                    names.add(str(unique_id_match.group("name") or ""))
                    continue
                # PIT descriptions are commonly ``method(owner.Test)`` but
                # some plugins use ``owner.Test.method`` or ``owner#method``.
                head = value.split("(", 1)[0].strip()
                candidate = re.split(r"[.#]", head)[-1].strip()
                if re.fullmatch(r"[A-Za-z_$][A-Za-z0-9_$]*", candidate):
                    names.add(candidate)
        return names

    @classmethod
    def _existing_green_exact_reflection_test_methods(
        cls,
        existing_test: str,
        *,
        target_method: str,
        target_descriptor: str | None = None,
        target_source: str = "",
        target_class: str = "",
    ) -> list[str]:
        """Return green tests with an exact, executable reflective target ACT.

        This is deliberately stricter than looking for ``getDeclaredMethod``.
        The reflected name and erased parameter types must match the descriptor
        (or the sole source declaration), and the same Method local must be made
        accessible and invoked.  The proof is used only to reuse an already
        green mutation setup; it does not make arbitrary reflection acceptable.
        """

        source = str(existing_test or "")
        method_name = str(target_method or "").strip()
        if not source.strip() or not method_name:
            return []

        descriptor_text = str(target_descriptor or "").strip()
        signature_known = bool(
            descriptor_text.startswith("(") and ")" in descriptor_text
        )
        expected_types = cls._jvm_descriptor_param_types(target_descriptor)
        if not expected_types and str(target_source or "").strip():
            blocks = [
                block
                for block in cls()._collect_method_blocks(
                    str(target_source),
                    class_name=str(target_class or "").rsplit(".", 1)[-1],
                )
                if str(block.get("name") or "") == method_name
            ]
            if len(blocks) == 1:
                signature_known = True
                expected_types = [
                    cls._erased_signature_param_type(item)
                    for item in cls._signature_param_types(
                        str(blocks[0].get("signature") or "")
                    )
                ]
        if not signature_known:
            return []

        def _class_literal_type(expression: str) -> str:
            value = " ".join(str(expression or "").split())
            match = re.fullmatch(
                r"(?:[A-Za-z_$][\w$]*\.)*"
                r"(?P<type>[A-Za-z_$][\w$]*(?:\s*\[\s*\])*)\.class",
                value,
            )
            if not match:
                return ""
            return re.sub(r"\s+", "", match.group("type"))

        reflected: list[str] = []
        _setup, tests, _teardown = cls._categorize_methods(source)
        declaration = re.compile(
            r"\b(?P<var>[A-Za-z_$][\w$]*)\s*=\s*"
            r"(?:[A-Za-z_$][\w$]*\s*\.\s*)?class\s*\.\s*"
            r"getDeclaredMethod\s*\((?P<args>.*?)\)\s*;",
            re.DOTALL,
        )
        for raw_method in tests:
            method = cls._strip_java_comments_preserve_code(
                str(raw_method or "")
            )
            matched = False
            for call in declaration.finditer(method):
                args = cls._split_top_level_args(call.group("args") or "")
                if not args or args[0].strip() != f'"{method_name}"':
                    continue
                actual_types = [
                    _class_literal_type(item) for item in args[1:]
                ]
                if any(not item for item in actual_types):
                    continue
                if expected_types and actual_types != expected_types:
                    continue
                variable = re.escape(str(call.group("var") or ""))
                if not re.search(
                    rf"\b{variable}\s*\.\s*setAccessible\s*\(\s*true\s*\)",
                    method,
                ):
                    continue
                if not re.search(
                    rf"\b{variable}\s*\.\s*invoke\s*\(",
                    method,
                ):
                    continue
                matched = True
                break
            if matched:
                reflected.append(str(raw_method or "").strip())
        return reflected

    @classmethod
    def _mutation_survived_green_setup_prefixes(
        cls,
        existing_test: str,
        mutation_feedback: object,
        *,
        target_method: str,
        target_descriptor: str | None = None,
        target_source: str = "",
        target_class: str = "",
    ) -> dict[str, list[str]]:
        """Return exact green Arrange+ACT prefixes for SURVIVED M-ids.

        PIT has already proved that the named green test executes a SURVIVED
        mutant. Mutation hardening should preserve that reachability setup and
        change its oracle, not replace the fixture or input speculatively.
        These prefixes are used only by the mutation-only extraction gate.
        """

        source = str(existing_test or "")
        target_name = str(target_method or "").strip()
        if (
            not source.strip()
            or not target_name
            or not isinstance(mutation_feedback, dict)
        ):
            return {}
        test_methods = {
            str(cls._extract_method_name(method) or "").strip(): method
            for method in cls._categorize_methods(source)[1]
            if str(cls._extract_method_name(method) or "").strip()
        }
        exact_reflection_keys = {
            cls._mutation_seed_dedup_key(method)
            for method in cls._existing_green_exact_reflection_test_methods(
                source,
                target_method=target_name,
                target_descriptor=target_descriptor,
                target_source=target_source,
                target_class=target_class,
            )
        }
        result: dict[str, list[str]] = {}
        for objective in list(
            mutation_feedback.get("mutation_objectives") or []
        ):
            if not isinstance(objective, dict):
                continue
            objective_id = str(
                objective.get("id")
                or objective.get("objective_id")
                or ""
            ).strip().upper()
            facts = (
                objective.get("facts")
                if isinstance(objective.get("facts"), dict)
                else objective
            )
            if (
                not objective_id.startswith("M")
                or str(facts.get("status") or "").strip().upper()
                != "SURVIVED"
            ):
                continue
            names = cls._mutation_pit_covering_test_method_names({
                "mutation_objectives": [objective]
            })
            prefixes: list[str] = []
            for green_name in sorted(names):
                method = str(test_methods.get(green_name) or "")
                if not method:
                    continue
                if cls._mutation_seed_propagation_witness(
                    method,
                    {"mutation_objectives": [objective]},
                    target_method=target_name,
                ) <= 0:
                    continue
                open_brace = method.find("{")
                close_brace = (
                    cls._find_matching_brace(method, open_brace)
                    if open_brace >= 0
                    else -1
                )
                if open_brace < 0 or close_brace <= open_brace:
                    continue
                body = cls._strip_java_comments_preserve_code(
                    method[open_brace + 1:close_brace]
                )
                direct_calls = list(re.finditer(
                    rf"(?<![A-Za-z0-9_$]){re.escape(target_name)}\s*\(",
                    body,
                ))
                exact_reflection = bool(
                    cls._mutation_seed_dedup_key(method)
                    in exact_reflection_keys
                )
                reflection_calls = (
                    list(re.finditer(r"\.\s*invoke\s*\(", body))
                    if exact_reflection
                    else []
                )
                act_positions = [
                    match.start()
                    for match in [*direct_calls, *reflection_calls]
                ]
                if not act_positions:
                    continue
                act_position = min(act_positions)
                assertion = re.search(
                    r"(?m)^\s*(?:[A-Za-z0-9_$.]+\s*\.\s*)?"
                    r"(?:assert[A-Za-z0-9_$]*|verify|fail|expectThrows)\s*\(",
                    body,
                )
                # An ACT embedded in an assertion cannot be preserved while
                # independently strengthening that assertion.
                if assertion and assertion.start() <= act_position:
                    continue
                prefix = body[: assertion.start() if assertion else len(body)]
                prefix = prefix.strip()
                if not prefix or len(prefix) > 3600:
                    continue
                canonical = cls._canonical_java_tokens(prefix)
                if canonical and canonical not in prefixes:
                    prefixes.append(canonical)
            if prefixes:
                result[objective_id] = prefixes[:3]
        return result

    @classmethod
    def _compact_existing_green_tests_for_mutation_semantics(
        cls,
        existing_test: str,
        *,
        target_method: str,
        target_descriptor: str | None = None,
        target_source: str = "",
        target_class: str = "",
        source_visible_entry_candidates: (
            list[dict[str, object]] | None
        ) = None,
        mutation_feedback: object = None,
        max_methods: int = 4,
        max_chars: int = 9000,
    ) -> str:
        """Return executable green-test evidence without model commentary."""

        source = str(existing_test or "")
        if not source.strip():
            return ""
        imports = cls._dedupe_ordered([
            line.strip()
            for line in source.splitlines()
            if line.strip().startswith("import ")
        ])
        _setup, tests, _teardown = cls._categorize_methods(source)
        entry_methods = cls._dedupe_ordered([
            str(target_method or "").strip(),
            *[
                str(row.get("method") or "").strip()
                for row in list(source_visible_entry_candidates or [])
                if isinstance(row, dict)
                and str(row.get("method") or "").strip()
            ],
        ])
        relevance_terms = cls._mutation_seed_relevance_terms(
            mutation_feedback
        )
        pit_covering_test_names = (
            cls._mutation_pit_covering_test_method_names(
                mutation_feedback
            )
        )
        exact_reflection_methods = {
            cls._mutation_seed_dedup_key(method)
            for method in cls._existing_green_exact_reflection_test_methods(
                source,
                target_method=target_method,
                target_descriptor=target_descriptor,
                target_source=target_source,
                target_class=target_class,
            )
        }
        ranked: list[tuple[int, int, str]] = []
        seen: set[str] = set()
        for raw_method in tests:
            method = cls._strip_java_comments_preserve_code(
                str(raw_method or "")
            )
            method = re.sub(r"\n[ \t]*\n(?:[ \t]*\n)+", "\n\n", method).strip()
            key = cls._mutation_seed_dedup_key(method)
            exact_reflection = bool(key and key in exact_reflection_methods)
            if not method or not (
                cls._test_code_calls_any_method(method, entry_methods)
                or exact_reflection
            ):
                continue
            if not key or key in seen:
                continue
            seen.add(key)
            ranked.append((
                cls._mutation_seed_quality_score(
                    method,
                    coverage_proven=(
                        cls._extract_method_name(method)
                        in pit_covering_test_names
                    ),
                    relevance_terms=relevance_terms,
                ),
                len(method),
                method,
            ))
        selected: list[str] = []
        used = sum(len(item) + 1 for item in imports)
        for _score, _length, method in sorted(
            ranked,
            key=lambda item: (-item[0], item[1]),
        ):
            projected = used + len(method) + 2
            if selected and projected > max(1000, int(max_chars)):
                continue
            if projected > max(1000, int(max_chars)):
                continue
            selected.append(method)
            used = projected
            if len(selected) >= max(1, int(max_methods)):
                break
        if not selected:
            return "\n".join(imports)[: max(1000, int(max_chars))]
        return "\n".join([
            *imports,
            "",
            *selected,
        ]).strip()

    @classmethod
    def _mutation_project_test_setup_evidence(
        cls,
        *,
        project_root: Path,
        target_method: str,
        target_package: str = "",
        target_class_name: str = "",
        source_visible_entry_candidates: (
            list[dict[str, object]] | None
        ),
        mutation_feedback: object,
        excluded_source: str = "",
        max_methods: int = 1,
        max_chars: int = 4200,
    ) -> str:
        """Select bounded, mutation-relevant setup from project test sources.

        Retained generated tests remain the authoritative green baseline.  A
        project's checked-in tests are used only as compile-visible fixture and
        public-input syntax evidence for the semantic verifier.  They are never
        copied into the generated suite or treated as runtime proof.
        """

        test_root = Path(project_root) / "src" / "test"
        if not test_root.is_dir():
            return ""
        entry_methods = cls._dedupe_ordered([
            str(target_method or "").strip(),
            *[
                str(row.get("method") or "").strip()
                for row in list(source_visible_entry_candidates or [])
                if isinstance(row, dict)
                and str(row.get("method") or "").strip()
            ],
        ])
        if not entry_methods:
            return ""
        relevance_terms = cls._mutation_seed_relevance_terms(
            mutation_feedback
        )
        excluded_keys = {
            cls._mutation_seed_dedup_key(method)
            for method in cls._categorize_methods(str(excluded_source or ""))[1]
        }
        excluded_keys.discard("")
        target_package = str(target_package or "").strip()
        owner_tokens = cls._dedupe_ordered([
            str(target_class_name or "").strip().rsplit(".", 1)[-1],
            *[
                str(
                    row.get("owner")
                    or row.get("class_name")
                    or row.get("declaring_class")
                    or row.get("receiver_type")
                    or ""
                ).strip().rsplit(".", 1)[-1]
                for row in list(source_visible_entry_candidates or [])
                if isinstance(row, dict)
            ],
        ])
        candidates: list[tuple[str, set[str], bool, bool, bool]] = []
        exact_target_owner = str(target_class_name or "").strip().rsplit(
            ".", 1
        )[-1]
        seen = set(excluded_keys)
        for source_path in sorted(test_root.rglob("*.java"))[:500]:
            try:
                if source_path.stat().st_size > 1_000_000:
                    continue
                source = source_path.read_text(
                    encoding="utf-8",
                    errors="ignore",
                )
            except OSError:
                continue
            package_match = cls._RE_PACKAGE_DECL.search(source)
            candidate_package = str(
                package_match.group(1) if package_match else ""
            ).strip()
            same_package = bool(
                target_package and candidate_package == target_package
            )
            _setup, tests, _teardown = cls._categorize_methods(source)
            for raw_method in tests:
                method = cls._strip_java_comments_preserve_code(
                    str(raw_method or "")
                ).strip()
                if not method or not cls._test_code_calls_any_method(
                    method,
                    entry_methods,
                ):
                    continue
                key = cls._mutation_seed_dedup_key(method)
                if not key or key in seen:
                    continue
                seen.add(key)
                owner_visible = any(
                    token and re.search(rf"\b{re.escape(token)}\b", method)
                    for token in owner_tokens
                )
                exact_owner_visible = bool(
                    exact_target_owner
                    and re.search(
                        rf"\b{re.escape(exact_target_owner)}\b",
                        method,
                    )
                )
                candidates.append((
                    method,
                    cls._mutation_relevance_terms_from_text(method),
                    same_package,
                    owner_visible,
                    exact_owner_visible,
                ))
        if target_package:
            same_package_candidates = [
                row for row in candidates if row[2]
            ]
            if same_package_candidates:
                candidates = same_package_candidates
            else:
                # A common method name is not enough to establish that a test
                # from another package exercises the target owner.  Retain
                # cross-package evidence only when the owner is explicit.
                candidates = [row for row in candidates if row[3]]
        # Same-package sibling classes frequently expose common names such as
        # decode/read/put. If exact-owner setup exists, a sibling call is not
        # evidence for the target even when it mentions a shared base Context
        # type or entry owner. Keep source-visible-entry fallback only when the
        # project has no exact target-owner fixture at all.
        if exact_target_owner:
            exact_owner_candidates = [row for row in candidates if row[4]]
            if exact_owner_candidates:
                candidates = exact_owner_candidates
        # Broad terms such as ``value`` or a common operator family can occur
        # in many otherwise unrelated fixtures.  Rank current-mutant terms by
        # their discriminating power inside the actual candidate set, so a
        # rare source token such as a case label or input-shape literal wins
        # over several generic overlaps.  This is corpus-derived rather than a
        # domain/keyword table and remains bounded below the ordinary seed
        # quality signal.
        document_frequency = {
            term: sum(
                1
                for (
                    _method,
                    terms,
                    _same_package,
                    _owner_visible,
                    _exact_owner_visible,
                )
                in candidates if term in terms
            )
            for term in relevance_terms
        }
        candidate_count = len(candidates)
        ranked: list[tuple[int, int, str]] = []
        for (
            method,
            method_terms,
            same_package,
            owner_visible,
            exact_owner_visible,
        ) in candidates:
            relevance_score = sum(
                1.0
                + math.log(
                    (candidate_count + 1.0)
                    / (document_frequency.get(term, 0) + 1.0)
                )
                for term in relevance_terms & method_terms
            )
            # This last bonus is normally redundant because exact-owner
            # candidates are filtered above. Retain it for the no-exact-
            # fixture fallback where an entry row still names the target.
            ranked.append((
                cls._mutation_seed_quality_score(
                    method,
                    coverage_proven=False,
                    relevance_terms=None,
                )
                + min(320, int(round(relevance_score * 48.0)))
                + (80 if same_package else 0)
                + (120 if owner_visible else 0)
                + (200 if exact_owner_visible else 0),
                len(method),
                method,
            ))
        selected: list[str] = []
        used = 0
        for _score, _length, method in sorted(
            ranked,
            key=lambda item: (-item[0], item[1]),
        ):
            evidence_method = cls._mutation_compact_project_test_method_evidence(
                method,
                relevance_terms=relevance_terms,
                max_chars=max(1000, int(max_chars)) - used,
            )
            if not evidence_method:
                continue
            if used + len(evidence_method) > max(1000, int(max_chars)):
                continue
            selected.append(evidence_method)
            used += len(evidence_method) + 2
            if len(selected) >= max(1, int(max_methods)):
                break
        return "\n\n".join(selected)

    @classmethod
    def _mutation_compact_project_test_method_evidence(
        cls,
        method: str,
        *,
        relevance_terms: set[str],
        max_chars: int,
    ) -> str:
        """Keep only relevant literal/setup windows from a long native test."""

        text = str(method or "").strip()
        limit = max(600, int(max_chars or 0))
        if not text:
            return ""
        if len(text) <= min(1200, limit):
            return text
        lines = text.splitlines()
        scored: list[tuple[int, int]] = []
        for index, line in enumerate(lines):
            overlap = len(
                cls._mutation_relevance_terms_from_text(line)
                & set(relevance_terms or set())
            )
            if overlap:
                scored.append((overlap, index))
        if not scored:
            return text[:limit]
        selected_indexes: set[int] = set()
        for _score, center in sorted(
            scored,
            key=lambda item: (-item[0], item[1]),
        )[:3]:
            selected_indexes.update(
                range(max(0, center - 3), min(len(lines), center + 4))
            )
        chunks: list[str] = []
        current: list[str] = []
        previous = -2
        for index in sorted(selected_indexes):
            if index != previous + 1 and current:
                chunks.append("\n".join(current))
                current = []
            current.append(lines[index])
            previous = index
        if current:
            chunks.append("\n".join(current))
        rendered = "\n// ... unrelated test setup omitted ...\n".join(chunks)
        return rendered[:limit].rstrip()

    @staticmethod
    def _render_entry_path_coverage_strategy_section(
        method_name: str | None,
        entry_points: list[dict[str, object]],
        *,
        is_private: bool = False,
        allow_reflection_fallback: bool = False,
    ) -> str:
        if not method_name or not (entry_points or is_private):
            return ""
        private_act_rule = (
            "If the target is private and no verified entry path is listed, use the explicitly listed private-reflection fallback: getDeclaredMethod with exact parameter classes, setAccessible(true), method.invoke(...), then assert the reflected result or expected exception."
            if allow_reflection_fallback
            else "If the target is private, the ACT step must call a verified source-visible entry method whose runtime path reaches the private target; reflection and direct private calls are invalid."
        )
        lines = [
            "[Entry-Path Coverage Strategy]",
            f"Target `{method_name}` must be covered by observable behavior, not by shallow construction or neighboring API calls.",
            "Generate a compact portfolio where each test changes exactly one public input-family axis before asserting the result/exception/state.",
            private_act_rule,
            "Prefer entry paths reported by static analysis; if several paths are listed, spend tests on the shortest public path first, then vary inputs to reach different target branches.",
            "For helper parameters that are internal, derive them through the entry method's public parameters instead of constructing internal/private types directly.",
        ]
        if entry_points:
            lines.append("Entry-path candidates to prioritize:")
            for ep in entry_points[:6]:
                method = str(ep.get("method") or "")
                access = str(ep.get("access") or "public")
                path = " -> ".join(str(p) for p in list(ep.get("path") or [])[:6])
                lines.append(f"- {method} [{access}] path={path}")
        lines.extend([
            "Portfolio axes:",
            "- presence/cardinality: null, empty/minimal, populated, malformed, duplicate, and multi-element public inputs when accepted",
            "- boundary/text: prefix/suffix/case/escaping/invalid-token variants for strings or serialized public inputs",
            "- state/mode: call required setup/compile/parse/build methods before the entry path when the target depends on internal state",
            "- oracle: assert exact boolean/result/exception or a differential relation through a sibling public API; no no-op smoke assertions",
        ])
        return "\n".join(lines)

    def _render_serialized_entry_path_contract(
        self,
        source_code: str,
        method_name: str | None,
        entry_points: list[dict[str, object]],
        *,
        is_private: bool = False,
    ) -> str:
        if not method_name or not is_private or not entry_points:
            return ""
        entry_names = {str(ep.get("method") or "").strip() for ep in entry_points if str(ep.get("method") or "").strip()}
        if not entry_names:
            return ""
        transformed_string_entries: list[tuple[str, list[str]]] = []
        for block in self._collect_method_blocks(source_code):
            block_name = str(block.get("name") or "")
            if block_name not in entry_names or bool(block.get("is_private")):
                continue
            signature = " ".join(str(block.get("signature") or "").split())
            param_types = [str(p) for p in self._signature_param_types(signature)]
            param_names = self._source_method_param_names(signature)
            body = str(block.get("body") or "")
            string_params = {
                name
                for param_type, name in zip(param_types, param_names)
                if param_type.rsplit(".", 1)[-1] == "String" and name
            }
            if not string_params:
                continue

            body_open = body.find("{")
            executable_body = body[body_open + 1 :] if body_open >= 0 else body
            target_call = re.search(
                rf"\b{re.escape(method_name)}\s*\(",
                executable_body,
            )
            prefix = (
                executable_body[: target_call.start()]
                if target_call
                else executable_body
            )
            source_calls: list[str] = []
            call_re = re.compile(
                r"\b(?P<callee>[A-Za-z_$][A-Za-z0-9_$]*(?:\s*\.\s*"
                r"[A-Za-z_$][A-Za-z0-9_$]*)*)\s*\((?P<args>[^;{}()]*)\)"
            )
            for match in call_re.finditer(prefix):
                callee = re.sub(r"\s+", "", str(match.group("callee") or ""))
                if not callee or callee.rsplit(".", 1)[-1] == method_name:
                    continue
                args = str(match.group("args") or "")
                consumed = [
                    name
                    for name in sorted(string_params)
                    if re.search(rf"\b{re.escape(name)}\b", args)
                ]
                if consumed:
                    source_calls.append(f"{callee}({', '.join(consumed)})")
            source_calls = list(dict.fromkeys(source_calls))
            if source_calls:
                transformed_string_entries.append((signature, source_calls))
        if not transformed_string_entries:
            return ""

        entry_bodies = " ".join(
            str(block.get("body") or "")
            for block in self._collect_method_blocks(source_code)
            if str(block.get("name") or "") in entry_names
            and not bool(block.get("is_private"))
        )
        _key_re = re.compile(r'\bcase\s+"([^"]{1,60})"')
        dispatch_literals = list(
            dict.fromkeys(m.group(1) for m in _key_re.finditer(entry_bodies))
        )[:8]

        lines = [
            "[Source-Proven Transformed-String Entry Contract]",
            "The selected private overload is reached through a source-visible entry path "
            "that consumes String parameters in concrete calls before invoking the target.",
            "Construct String arguments accepted by those exact source calls. Do not infer "
            "a JSON, XML, expression, or other wire format unless the visible callable "
            "contract or source branch itself proves it.",
        ]
        lines.append(
            "First establish one passing entry input that reaches the target. Then vary one "
            "source-observed predicate, literal, or input relation at a time; do not invent "
            "schema fields or helper APIs."
        )
        if dispatch_literals:
            quoted = ", ".join(f'"{k}"' for k in dispatch_literals)
            lines.append(
                f"String dispatch literals observed in the entry path: {quoted}. "
                "They are admissible branch evidence, not proof of a document schema."
            )
        lines.append("Source-proven entry transformations:")
        for signature, calls in transformed_string_entries[:4]:
            lines.append(f"- {signature}")
            lines.extend(f"  - {call}" for call in calls[:4])
        return "\n".join(lines)

    @classmethod
    def _source_entry_guard_predicates(
        cls,
        *,
        source_code: str,
        body: str,
        path_call_names: set[str],
        limit: int = 4,
    ) -> list[str]:
        """Return exact receiver-state guards preceding a target-path call.

        This is deliberately shape-based. A zero-argument receiver read or a
        declared instance-field reference is state evidence regardless of
        whether the project calls it ``state``, ``token``, ``phase``, or
        something domain-specific. The predicate is quoted verbatim; this
        helper does not guess which outcome reaches the target.
        """
        if not body or not path_call_names:
            return []
        scan = cls._strip_java_comments_and_strings(body)
        declared_fields = set(cls._declared_instance_field_types(source_code))
        path_call_positions = [
            match.start()
            for name in sorted(path_call_names)
            for match in re.finditer(
                rf"(?<![A-Za-z0-9_$]){re.escape(name)}\s*\(",
                scan,
            )
        ]
        if not path_call_positions:
            return []
        final_path_call = max(path_call_positions)
        zero_arg_call_re = re.compile(
            r"(?<![A-Za-z0-9_$])"
            r"(?:this\s*\.\s*)?"
            r"(?:[A-Za-z_$][A-Za-z0-9_$]*\s*\.\s*)*"
            r"[A-Za-z_$][A-Za-z0-9_$]*\s*\(\s*\)"
        )
        field_re = (
            re.compile(
                r"(?<![A-Za-z0-9_$])(?:this\s*\.\s*)?"
                r"(?:" + "|".join(re.escape(name) for name in sorted(declared_fields)) + r")"
                r"(?![A-Za-z0-9_$])"
            )
            if declared_fields
            else None
        )
        predicates: list[str] = []
        for match in re.finditer(r"\bif\s*\(", scan):
            open_index = scan.find("(", match.start())
            close_index = cls._find_matching_paren(scan, open_index)
            if close_index <= open_index or close_index > final_path_call:
                continue
            predicate_scan = scan[open_index + 1:close_index]
            if not (
                zero_arg_call_re.search(predicate_scan)
                or (field_re is not None and field_re.search(predicate_scan))
            ):
                continue
            predicate = " ".join(
                body[open_index + 1:close_index].split()
            )
            if (
                predicate
                and len(predicate) <= 360
                and predicate not in predicates
            ):
                predicates.append(predicate)
            if len(predicates) >= max(1, int(limit)):
                break
        return predicates

    def _render_entry_precondition_section(
        self,
        source_code: str,
        method_name: str | None,
        entry_points: list[dict[str, object]],
        *,
        is_private: bool = False,
        target_descriptor: str | None = None,
    ) -> str:
        if not method_name or not is_private or not source_code:
            return ""
        if not entry_points:
            entry_points = self._find_public_entry_points(
                method_name,
                source_code,
                target_descriptor=target_descriptor,
            )
        path_names: set[str] = set()
        for ep in entry_points[:6]:
            for name in list(ep.get("path") or []):
                text = str(name or "").strip()
                if text and text != method_name:
                    path_names.add(text)
            ep_name = str(ep.get("method") or "").strip()
            if ep_name:
                path_names.add(ep_name)
        path_names.update(self._infer_private_target_call_chain_names(source_code, method_name))
        if not path_names:
            return ""
        guards: list[str] = []
        path_call_names = set(path_names)
        path_call_names.add(method_name)
        for block in self._collect_method_blocks(source_code):
            block_name = str(block.get("name") or "")
            if block_name not in path_names:
                continue
            body = str(block.get("body") or "")
            signature = " ".join(
                str(block.get("signature") or block_name).split()
            )
            for predicate in self._source_entry_guard_predicates(
                source_code=source_code,
                body=body,
                path_call_names=path_call_names - {block_name},
            ):
                guards.append(
                    f"{signature}: source guard `{predicate}` precedes the call path "
                    f"toward `{method_name}`; arrange the receiver so this exact guard "
                    "takes its target-reaching outcome"
                )
        if not guards:
            return ""
        lines = [
            "[Target Execution Receipt: Entry Preconditions]",
            "Every returned @Test for this private target must satisfy source-visible entry-path preconditions before the private target is reached. Private-target internal state comes later through natural entry-path advancement.",
        ]
        lines.extend(f"- {guard}" for guard in guards[:5])
        lines.extend([
            "Use only a source-visible constructor, writer, or ordered entry call that is cited by the state plan or validated semantic branch row; do not infer setup behavior from a method name.",
            "Preserve the quoted predicate and public call order. Do not guess its target-reaching truth value when the supplied control-flow evidence does not prove it.",
        ])
        return "\n".join(lines)

    @staticmethod
    def _strip_section_header(section: str, header: str, *, drop_intro_lines: int = 0) -> list[str]:
        lines = [line for line in str(section or "").splitlines() if line.strip()]
        if not lines:
            return []
        if lines[0].strip() != header:
            return lines
        return lines[1 + max(0, drop_intro_lines):]

    @classmethod
    def _render_target_execution_receipt_cluster(
        cls,
        *,
        method_name: str | None,
        compact_receipt: str = "",
        target_class_name: str = "",
        receiver_entry_preference: dict[str, str] | None = None,
        entry_preconditions: str = "",
        serialized_override: str = "",
        coverage_obligation_binding: str = "",
        private_obligation_binding: str = "",
    ) -> str:
        pieces: list[tuple[str, list[str]]] = []
        core_lines = cls._strip_section_header(
            compact_receipt,
            "[Target Execution Receipt]",
            drop_intro_lines=2,
        )
        entry_recipe = (
            dict(receiver_entry_preference)
            if isinstance(receiver_entry_preference, dict)
            else {}
        )
        if entry_recipe:
            target_simple = cls._simple_type_name(target_class_name)
            filtered_core: list[str] = []
            skip_construction_block = False
            for line in core_lines:
                stripped = str(line or "").strip()
                if stripped.startswith("- "):
                    skip_construction_block = bool(
                        target_simple
                        and stripped.lower().startswith("- construction:")
                        and target_simple.lower() in stripped.lower()
                    )
                    if skip_construction_block:
                        continue
                if skip_construction_block:
                    continue
                if cls._direct_target_construction_fact(
                    line,
                    target_class_name=target_simple,
                ):
                    continue
                filtered_core.append(line)
            core_lines = filtered_core
            call_shape = str(entry_recipe.get("preferred_call_shape") or "").strip()
            signature = str(entry_recipe.get("exact_signature") or "").strip()
            evidence = str(entry_recipe.get("entry_evidence") or "").strip()
            preferred_lines = [
                f"- source-proven receiver acquisition: `{call_shape}`",
                f"  exact public signature: `{signature}`",
                (
                    "  sequence: construct the public owner with the shown source-visible shape, "
                    f"call the entry/factory, then invoke `{method_name}(...)` on the returned receiver"
                ),
                (
                    f"  forbidden conflicting setup: do not copy internal `new {target_simple}(...)` "
                    "while this proven acquisition path exists"
                ),
            ]
            if evidence:
                preferred_lines.append(f"  source evidence: {evidence}")
            pieces.append(("Preferred receiver acquisition", preferred_lines))
        if core_lines:
            pieces.append(("Core recipe", core_lines))
        entry_lines = cls._strip_section_header(
            entry_preconditions,
            "[Target Execution Receipt: Entry Preconditions]",
        )
        if entry_lines:
            pieces.append(("Entry preconditions", entry_lines))
        obligation_lines = cls._strip_section_header(
            private_obligation_binding,
            "[Target Execution Receipt: Private Coverage Obligations]",
        )
        if obligation_lines:
            pieces.append(("Private target obligation binding", obligation_lines))
        serialized_lines = cls._strip_section_header(
            serialized_override,
            "[Target Execution Receipt: Serialized Coverage]",
        )
        if serialized_lines:
            pieces.append(("Serialized input coverage", serialized_lines))
        coverage_lines = cls._strip_section_header(
            coverage_obligation_binding,
            "[Target Execution Receipt: Coverage Obligations]",
        )
        if coverage_lines:
            pieces.append(("Coverage obligation binding", coverage_lines))
        if not pieces:
            return ""

        target_text = f" for `{method_name}`" if method_name else ""
        lines = [
            "[Target Execution Receipt]",
            f"Every returned @Test{target_text} must implement this unified receipt before asserting behavior.",
            "A mention in the test name, comment, or assertion message does not count; the Java statement body must invoke the target method or its required source-visible entry path.",
        ]
        for title, body_lines in pieces:
            lines.append(f"- {title}:")
            lines.extend(f"  {line}" for line in body_lines[:12])
        return "\n".join(lines)

    def _infer_private_target_call_chain_names(self, source_code: str, method_name: str) -> set[str]:
        blocks = self._collect_method_blocks(source_code)
        if not blocks:
            return set()
        by_name: dict[str, dict[str, object]] = {}
        for block in blocks:
            name = str(block.get("name") or "")
            if name and name not in by_name:
                by_name[name] = block
        if method_name not in by_name:
            return set()
        reverse_edges: dict[str, set[str]] = {name: set() for name in by_name}
        for caller, block in by_name.items():
            body = str(block.get("body") or "")
            for callee in by_name:
                if callee != caller and re.search(rf"\b{re.escape(callee)}\s*\(", body):
                    reverse_edges.setdefault(callee, set()).add(caller)
        inferred: set[str] = set()
        frontier = list(reverse_edges.get(method_name) or [])
        while frontier and len(inferred) < 16:
            caller = frontier.pop(0)
            if caller in inferred or caller == method_name:
                continue
            inferred.add(caller)
            frontier.extend(sorted(reverse_edges.get(caller) or []))
        return inferred

    @staticmethod
    def _detect_entry_cursor_preadvance_violation(generated_code: str, entry_method_names: set[str]) -> str:
        """Retired name-based cursor gate.

        A call named ``next`` or ``read`` may be required setup, an observer,
        or an unrelated operation.  Rejecting it from spelling alone caused
        valid public-entry paths to be rewritten.  Concrete source-validated
        semantic rows and candidate-level coverage now own this decision.
        """
        return ""

    @staticmethod
    def _semantic_branch_analysis_allows_preadvance(
        generated_code: str,
        *,
        target_method: str,
        coverage_feedback: object,
        generated_patch_metadata: object,
    ) -> tuple[bool, list[str]]:
        """Allow an exact pre-target writer required by a bound semantic row.

        Historical no-gain feedback can say that advancing a cursor before the
        target was shallow. A later source-validated branch row may prove that
        the same call is the writer needed for a different receiver state. Only
        an exact receiver+method call in a candidate bound to that SK-id may
        override the broad no-gain guard.
        """
        if (
            not generated_code
            or not target_method
            or not isinstance(coverage_feedback, dict)
            or not isinstance(generated_patch_metadata, dict)
        ):
            return False, []
        analysis = coverage_feedback.get("llm_branch_analysis")
        if not isinstance(analysis, dict):
            return False, []
        bound_ids = {
            str(value or "").strip()
            for value in dict(
                generated_patch_metadata.get("test_objective_map") or {}
            ).values()
            if str(value or "").strip()
        }
        if not bound_ids:
            return False, []

        allowed_calls: set[str] = set()
        call_re = re.compile(
            r"(?<![A-Za-z0-9_$])"
            r"(?P<receiver>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*"
            r"(?P<method>[A-Za-z_$][A-Za-z0-9_$]*)"
            r"\s*\("
        )
        state_dependency_markers = {
            "receiver_field",
            "field_relation",
            "external_collaborator",
            "protocol_state",
        }
        for sketch in list(analysis.get("frontier_sketches") or []):
            if not isinstance(sketch, dict):
                continue
            sketch_id = str(
                sketch.get("sketch_id") or sketch.get("id") or ""
            ).strip()
            if not sketch_id or sketch_id not in bound_ids:
                continue
            sketch_kind = str(sketch.get("kind") or "").strip()
            dependency_kind = str(
                sketch.get("dependency_kind") or ""
            ).strip()
            if not sketch_kind.startswith("semantic_"):
                continue
            if not (
                dependency_kind in state_dependency_markers
                or any(
                    marker in sketch_kind
                    for marker in state_dependency_markers
                )
            ):
                continue
            evidence_parts = [
                *list(sketch.get("required_arrange") or []),
                *list(
                    sketch.get(
                        "existing_green_protected_setup_actions"
                    ) or []
                ),
            ]
            for part in evidence_parts:
                for match in call_re.finditer(str(part or "")):
                    method = str(match.group("method") or "")
                    if method == target_method:
                        continue
                    allowed_calls.add(
                        f"{match.group('receiver')}.{method}"
                    )
        if not allowed_calls:
            return False, []

        observed_calls: set[str] = set()
        matched_calls: set[str] = set()
        target_re = re.compile(
            rf"(?<![A-Za-z0-9_$])"
            rf"(?P<receiver>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*"
            rf"{re.escape(target_method)}\s*\("
        )
        for chunk in re.split(r"(?=@Test\b)", generated_code):
            target_match = target_re.search(chunk)
            if target_match is None:
                continue
            target_receiver = str(target_match.group("receiver") or "")
            before_target = chunk[: target_match.start()]
            for match in call_re.finditer(before_target):
                if str(match.group("receiver") or "") != target_receiver:
                    continue
                method = str(match.group("method") or "")
                if method == target_method:
                    continue
                call = f"{target_receiver}.{method}"
                observed_calls.add(call)
                if call in allowed_calls:
                    matched_calls.add(call)
        if not matched_calls:
            return False, sorted(observed_calls)
        return True, sorted(matched_calls)

    @staticmethod
    def _coverage_feedback_has_stateful_cursor_obligation(coverage_feedback: object) -> bool:
        if not TATGEngineAdapter._legacy_name_heuristics_enabled():
            return False
        if not isinstance(coverage_feedback, dict):
            return False
        for key in ("coverage_obligations", "test_objectives"):
            for item in list(coverage_feedback.get(key) or []):
                if not isinstance(item, dict):
                    continue
                category = str(item.get("category") or item.get("kind") or "").strip()
                operators = " ".join(str(op) for op in list(item.get("recipe_operators") or []))
                text = " ".join(
                    str(item.get(name) or "")
                    for name in ("scenario", "goal", "target_call", "required_setup", "program_fact")
                )
                combined = f"{category} {operators} {text}".lower()
                if "statefulcursor" in category.replace(" ", "").lower():
                    return True
                if "sibling-advance-ablation" in combined or "state-advancing api" in combined:
                    return True
        return False

    @staticmethod
    def _coverage_feedback_has_no_gain_pre_target_state_advance(coverage_feedback: object) -> bool:
        """Return whether evidence justifies rejecting a pre-target state call.

        A target-positive candidate that closes no *new* suite gap is still
        valid reachability evidence. Historically those candidates activated a
        keyword-based hard rejection for calls named next/read/skip/etc. That
        conflated suite novelty with call validity and could contradict a later
        semantic state trace. Only an explicit source/data-flow-backed row may
        now activate the rejection path.
        """
        if not isinstance(coverage_feedback, dict):
            return False
        directional = coverage_feedback.get("measured_directional_feedback")
        if not isinstance(directional, dict):
            return False
        rows = directional.get("no_gain_pre_target_state_advances")
        for item in list(rows or []):
            if not isinstance(item, dict):
                continue
            if not bool(item.get("enforce_stateful_rejection")):
                continue
            evidence_kind = str(item.get("rejection_evidence_kind") or "").strip()
            if evidence_kind in {
                "source_dataflow",
                "validated_semantic_branch_analysis",
            }:
                return True
        return False

    @staticmethod
    def _strict_reject_stateful_preadvance_enabled() -> bool:
        return os.getenv("TATG_STATEFUL_PREADVANCE_STRICT_REJECT", "0").lower() in {"1", "true", "yes", "on"}

    @staticmethod
    def _render_serialized_target_coverage_override() -> str:
        return "\n".join([
            "[Target Execution Receipt: Serialized Coverage]",
            "If another prompt section suggests null/empty/malformed String boundary inputs, apply those only after at least one valid serialized baseline reaches the private target overload.",
            "For this private-target request, a parser/compiler exception before constructing internal parameters is a wrapper-entry test, not target coverage.",
            "Use valid serialized public inputs first, then vary data inside the serialized document to cover target branches.",
        ])

    @staticmethod
    def _render_private_target_obligation_receipt(
        method_name: str | None,
        entry_points: list[dict[str, object]],
    ) -> str:
        entry_names = ", ".join(
            sorted({str(ep.get("method") or "").strip() for ep in entry_points if str(ep.get("method") or "").strip()})
        )
        if not method_name or not entry_names:
            return ""
        return "\n".join([
            "[Target Execution Receipt: Private Coverage Obligations]",
            f"The listed O-ids belong to private target `{method_name}` and its exact descriptor, but the Java @Test body must satisfy them through source-visible entry methods: {entry_names}.",
            "Keep the private target overload_id for scenario identity when [Target Overload Binding] requires it, then call one listed entry method in ACT.",
            "Set up inputs for the source-visible entry method's own preconditions first; do not pre-position cursors, streams, iterators, builders, or mutable state only to the private target's internal state. Let the entry path advance state into the private target naturally.",
            "When entry and target states differ, entry preconditions win. If an entry method validates a stream/cursor start state before it reaches the private target, create the stream/cursor at the entry start state and use filters/data to steer the later private branch.",
            "This overrides coverage-obligation required_setup text when it asks for a private target's internal guard outcome by pre-positioning the cursor. For such O-ids, satisfy the reachable entry-path outcome first; do not manufacture an unreachable private precondition failure through the public entry.",
            "Do not call the private target directly, use reflection, instantiate private inner helper types, or replace the scenario with a sibling overload that does not reach the target descriptor.",
        ])

    @staticmethod
    def _render_coverage_obligation_binding_receipt(
        method_name: str | None,
        required_obligation_ids: set[str],
        test_budget: int,
        *,
        require_all_feedback_oids: bool = False,
    ) -> str:
        ordered = sorted(
            {str(item).strip() for item in required_obligation_ids if str(item).strip()},
            key=lambda item: int(item[1:]) if item.startswith("O") and item[1:].isdigit() else 10**9,
        )
        if not ordered:
            return ""
        target_text = f" for `{method_name}`" if method_name else ""
        plural = "item" if int(test_budget or 0) == 1 else "items"
        lines = [
            "[Target Execution Receipt: Coverage Obligations]",
            f"Coverage-guided round{target_text}: return exactly {int(test_budget)} new_tests {plural} unless the JSON schema itself cannot represent a valid compiling test.",
            "Required O-ids for this round: " + ", ".join(ordered) + ".",
            "Each new_tests item must bind exactly one required O-id in coverage_obligation_id and include the same O-id in the Java @Test method name.",
            "A coverage-feedback item is only useful if it reaches a still-missed source/branch anchor for its required O-id; do not repeat an already-covered target path under a new O-id name.",
            "Do not spend a new_tests item on a smoke/default path, sibling overload, wrapper-only path, or oracle-only rewrite that does not invoke the target descriptor or its required source-visible entry path.",
            "Use input_family, oracle_type, and repair_axis to name the actual arrange/search axes; if validation repair is needed, mutate repair_axis instead of only changing assertions.",
        ]
        if require_all_feedback_oids and len(ordered) <= int(test_budget or 0):
            lines.append("Cover every required O-id at least once in this response before adding any extra variation.")
        else:
            lines.append("Prioritize the required O-ids in order; if budget is smaller than the O-id count, cover the earliest listed O-ids first.")
        return "\n".join(lines)

    @staticmethod
    def _thin_wrapper_delegate(body: str) -> str | None:
        """Return the name of the delegated method if *body* is a thin wrapper, else None.

        A thin wrapper is a method whose body has at most two significant statements
        and whose only meaningful action is a ``return``/call forwarding to a sibling
        method.  Detecting this lets ``_render_source_context`` pull in the real
        implementation so the LLM sees actual branch logic rather than a one-liner.

        Only returns a name when the delegate is a *different* identifier (same-name
        overloads are handled implicitly by ``by_name`` keeping the last block).
        """
        # Collect non-trivial lines: exclude blank, comment, and brace-only lines
        sig_lines = []
        for ln in body.splitlines():
            stripped = ln.strip()
            if not stripped:
                continue
            if stripped.startswith("//") or stripped.startswith("*") or stripped.startswith("/*"):
                continue
            if stripped in ("{", "}"):
                continue
            sig_lines.append(stripped)

        # Thin wrapper: at most 3 significant lines (signature + ≤2 body statements)
        if len(sig_lines) > 3:
            return None

        # Extract the body content (lines that are not just the method signature)
        # Look for a single `return methodName(` or bare `methodName(` call.
        for line in sig_lines:
            m = re.match(r"^(?:return\s+)?(\w+)\s*\(", line)
            if m:
                name = m.group(1)
                _kw = frozenset({
                    "if", "while", "for", "switch", "try", "catch", "finally",
                    "new", "throw", "return", "super", "this", "assert",
                })
                if name not in _kw:
                    return name
        return None

    def _render_source_context(
        self,
        source_code: str,
        method_name: str | None,
        *,
        class_name: str | None = None,
        target_descriptor: str = "",
    ) -> str:
        if not method_name:
            return source_code

        blocks = self._collect_method_blocks(source_code, class_name=class_name)
        by_name: dict[str, dict[str, object]] = {}
        for block in blocks:
            by_name[str(block["name"])] = block
        exact_target_descriptor = str(target_descriptor or "").strip()
        target = None
        if exact_target_descriptor:
            for block in blocks:
                if str(block["name"]) == method_name and self._signature_matches_jvm_descriptor(
                    str(block.get("signature") or ""),
                    exact_target_descriptor,
                ):
                    target = block
                    break
        if target is None:
            target = by_name.get(method_name)
        if not target:
            return source_code

        selected_keys: list[str] = []
        selected_names: list[str] = []
        pending: list[dict[str, object]] = [target]
        if bool(target.get("is_private")):
            pending.extend(
                block for block in blocks
                if str(block.get("name") or "") == method_name and not bool(block.get("is_private"))
            )
        while pending:
            block = pending.pop(0)
            current = str(block.get("name") or "")
            block_key = f"{current}@{block.get('start')}"
            if block_key in selected_keys:
                continue
            selected_keys.append(block_key)
            selected_names.append(current)
            body = str(block["body"])

            # Thin-wrapper expansion: when the primary target is a short forwarding
            # method, also include the public method it delegates to.  This ensures
            # the LLM sees the real branch logic rather than a one-line stub.
            if current == method_name:
                delegate_name = TATGEngineAdapter._thin_wrapper_delegate(body)
                if (
                    delegate_name
                    and delegate_name != method_name
                    and delegate_name in by_name
                    and delegate_name not in selected_names
                    and delegate_name not in pending
                ):
                    pending.append(by_name[delegate_name])

            for candidate_name, candidate in by_name.items():
                if candidate_name in selected_names or candidate_name == current:
                    continue
                if re.search(rf"\b{re.escape(candidate_name)}\s*\(", body):
                    if bool(candidate["is_private"]) or candidate_name == method_name:
                        pending.append(candidate)

        class_open = source_code.find("{")
        if class_open == -1:
            return source_code
        header = source_code[: class_open + 1].rstrip()
        selected_by_key = {f"{str(block.get('name') or '')}@{block.get('start')}": block for block in blocks}
        selected_blocks = [str(selected_by_key[key]["body"]).rstrip() for key in selected_keys if key in selected_by_key]
        return header + "\n\n" + "\n\n".join(selected_blocks) + "\n}\n"

    @staticmethod
    def _truncate_prompt_context(text: str, max_chars: int) -> str:
        if max_chars <= 0 or len(text) <= max_chars:
            return text
        head_chars = max(0, int(max_chars * 0.72))
        tail_chars = max(0, max_chars - head_chars)
        omitted = len(text) - head_chars - tail_chars
        return (
            text[:head_chars].rstrip()
            + f"\n\n[... omitted {omitted} chars from oversized context ...]\n\n"
            + text[-tail_chars:].lstrip()
        )

    @classmethod
    def _mutation_seed_dedup_key(cls, method_code: str) -> str:
        """Return a stable key for regenerated copies of one test method."""

        method = str(method_code or "").strip()
        if not method:
            return ""
        method_name = cls._extract_method_name(method)
        if method_name:
            method = re.sub(
                rf"\b{re.escape(method_name)}\s*\(",
                "__tatg_seed__(",
                method,
                count=1,
            )
        return re.sub(r"\s+", " ", method).strip()

    @classmethod
    def _mutation_seed_quality_score(
        cls,
        method_code: str,
        *,
        coverage_proven: bool,
        relevance_terms: set[str] | None = None,
        propagation_witness: int = 0,
    ) -> int:
        """Rank green setup examples without pretending they reach a mutant.

        A short early-exception test is often the worst mutation seed even
        though it is green. Prefer normal-return tests with behavior-linked
        assertions. Candidate-level coverage proof remains a much stronger
        signal than this syntactic ranking.
        """

        code = str(method_code or "")
        cleaned = cls._strip_java_comments_and_strings(code)
        score = 1000 if coverage_proven else 0
        # A covered seed is useful for SURVIVED hardening only when its
        # observation differs from the replacement value. Keep this stronger
        # than setup-shape/relevance tie-breakers, but below actual coverage
        # proof. Negative means the seed explicitly accepts the mutant value.
        score += max(-1, min(1, int(propagation_witness or 0))) * 420
        has_exception_oracle = bool(
            re.search(
                r"\b(?:assertThrows|expectThrows)\s*\(|"
                r"@Test\s*\(\s*expected\s*=",
                cleaned,
            )
        )
        has_behavior_oracle = cls._test_code_has_mutation_adequate_oracle(code)
        has_observable_check = cls._test_code_has_observable_check(code)
        if has_behavior_oracle and not has_exception_oracle:
            score += 140
        elif has_observable_check and not has_exception_oracle:
            score += 60
        if has_exception_oracle:
            # Keep exception tests available when no normal-return seed exists,
            # but do not let their small bodies dominate seed selection.
            score -= 40
        if re.search(
            r"\b(?:assertNotNull|assertDoesNotThrow)\s*\(",
            cleaned,
        ) and not has_behavior_oracle:
            score -= 30
        # Among equally green exact-call tests, prefer a seed that already
        # demonstrates more of the project's compiling setup surface. This is
        # especially useful for mutation hardening of stateful targets: a
        # one-line guard test is a poor basis for reaching a live mutant even
        # when its oracle is exact. Keep the bonus bounded so candidate-level
        # target-coverage proof and oracle quality remain dominant.
        setup_shape = cls._mutation_seed_setup_call_shape(code)
        score += min(72, max(0, len(setup_shape) - 2) * 12)
        if relevance_terms:
            method_terms = cls._mutation_relevance_terms_from_text(code)
            # One semantically adjacent green setup is more useful than a
            # shorter unrelated test, but explicit candidate-level coverage
            # proof remains the dominant signal.
            score += min(240, len(method_terms & relevance_terms) * 40)
        return score

    @classmethod
    def _mutation_seed_propagation_witness(
        cls,
        method_code: str,
        mutation_feedback: object,
        *,
        target_method: str,
    ) -> int:
        """Classify whether a green oracle separates a return replacement.

        ``1`` means an assertion on the target result contradicts the mutant's
        replacement value, ``-1`` means it explicitly accepts that value, and
        ``0`` means no safe conclusion. This is conservative seed ranking and
        gating evidence, not a claim that PIT will kill the mutant.
        """

        code = cls._strip_java_comments_preserve_code(str(method_code or ""))
        target_name = str(target_method or "").strip()
        if not code or not target_name or not isinstance(
            mutation_feedback, dict
        ):
            return 0
        descriptions = " ".join(
            str(facts.get("description") or objective.get("description") or "")
            + " "
            + str(facts.get("mutator") or facts.get("mutator_short") or "")
            for objective in list(
                mutation_feedback.get("mutation_objectives") or []
            )
            if isinstance(objective, dict)
            for facts in [
                objective.get("facts")
                if isinstance(objective.get("facts"), dict)
                else objective
            ]
            if str(facts.get("status") or "").strip().upper() == "SURVIVED"
        ).lower()
        replacement = ""
        if "null" in descriptions and "return" in descriptions:
            replacement = "null"
        elif re.search(r"(?:return|returned|with)\s+(?:value\s+)?false\b", descriptions):
            replacement = "false"
        elif re.search(r"(?:return|returned|with)\s+(?:value\s+)?true\b", descriptions):
            replacement = "true"
        elif "empty string" in descriptions or 'with ""' in descriptions:
            replacement = "empty"
        if not replacement:
            return 0
        result_names = {
            str(match.group("name") or "")
            for match in re.finditer(
                rf"\b(?:final\s+)?[A-Za-z_$][A-Za-z0-9_$.<>?, \[\]]*\s+"
                rf"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*[^;\n]*"
                rf"(?<![A-Za-z0-9_$]){re.escape(target_name)}\s*\(",
                code,
            )
        }
        if not result_names:
            return 0
        for name in sorted(result_names):
            escaped = re.escape(name)
            if replacement == "null":
                if re.search(rf"\bassertNotNull\s*\(\s*{escaped}\s*\)", code):
                    return 1
                if re.search(
                    rf"\bassertEquals\s*\(\s*(?!null\b)[^,()]+\s*,\s*{escaped}\s*\)",
                    code,
                ):
                    return 1
                if re.search(rf"\bassertNull\s*\(\s*{escaped}\s*\)", code):
                    return -1
                if re.search(
                    rf"\bassertEquals\s*\(\s*null\s*,\s*{escaped}\s*\)",
                    code,
                ):
                    return -1
            elif replacement in {"true", "false"}:
                opposite = "False" if replacement == "true" else "True"
                same = "True" if replacement == "true" else "False"
                if re.search(rf"\bassert{opposite}\s*\(\s*{escaped}\s*\)", code):
                    return 1
                if re.search(rf"\bassert{same}\s*\(\s*{escaped}\s*\)", code):
                    return -1
            elif replacement == "empty":
                if re.search(
                    rf"\bassertEquals\s*\(\s*\"[^\"]+\"\s*,\s*{escaped}\s*\)",
                    code,
                ):
                    return 1
                if re.search(
                    rf"\bassertEquals\s*\(\s*\"\"\s*,\s*{escaped}\s*\)",
                    code,
                ):
                    return -1
        return 0

    @staticmethod
    def _mutation_relevance_terms_from_text(text: str) -> set[str]:
        """Return generic semantic tokens used to match a mutant to a seed.

        Preserve string literals because they often contain the public input
        syntax that reaches an internal parser/dispatch branch. Splitting
        camel-case and punctuation makes this independent of method/domain
        names and avoids keyword-specific rules.
        """
        expanded = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
        stop = {
            "assert", "assertion", "boolean", "case", "class", "else",
            "false", "final", "if", "import", "int", "java", "line",
            "new", "null", "private", "public", "return", "static",
            "string", "test", "this", "true", "void",
        }
        return {
            token
            for token in re.findall(r"[A-Za-z][A-Za-z0-9]{2,}", expanded.lower())
            if token not in stop
        }

    @classmethod
    def _mutation_seed_relevance_terms(cls, coverage_feedback: object) -> set[str]:
        if not isinstance(coverage_feedback, dict):
            return set()
        fragments: list[str] = []
        for objective in list(coverage_feedback.get("mutation_objectives") or []):
            if not isinstance(objective, dict):
                continue
            facts = objective.get("facts") if isinstance(objective.get("facts"), dict) else {}
            for key in ("source_line", "source_statement", "description", "mutator_short"):
                value = facts.get(key) or objective.get(key)
                if isinstance(value, str):
                    fragments.append(value)
            evidence = facts.get("mutation_reachability_source_evidence")
            if isinstance(evidence, dict):
                for key in ("source_statement", "evidence_kind"):
                    value = evidence.get(key)
                    if isinstance(value, str):
                        fragments.append(value)
                for row in list(evidence.get("control_path") or []):
                    if not isinstance(row, dict):
                        continue
                    for key in ("statement", "predicate", "outcome", "case_value"):
                        value = row.get(key)
                        if isinstance(value, str):
                            fragments.append(value)
            for row in list(facts.get("static_required_ancestor_paths") or []):
                if isinstance(row, dict):
                    fragments.extend(
                        str(row.get(key) or "")
                        for key in ("predicate", "outcome", "statement")
                    )
        return cls._mutation_relevance_terms_from_text("\n".join(fragments))

    @classmethod
    def _mutation_seed_setup_call_shape(
        cls,
        method_code: str,
    ) -> set[tuple[str, int]]:
        """Return a compact, value-independent setup/call fingerprint."""

        code = cls._strip_java_comments_and_strings(str(method_code or ""))
        ignored = {
            "assertEquals",
            "assertFalse",
            "assertNotEquals",
            "assertNotNull",
            "assertNull",
            "assertThrows",
            "assertTrue",
            "fail",
        }
        shape: set[tuple[str, int]] = set()
        for match in re.finditer(
            r"(?:\.|\b)(?P<method>[A-Za-z_$][A-Za-z0-9_$]*)\s*\(",
            code,
        ):
            method = str(match.group("method") or "")
            if method.lower().startswith("test") or method in ignored or method in {
                "if", "for", "while", "switch", "catch", "try",
            }:
                continue
            open_index = code.find("(", match.start())
            close_index = cls._find_matching_paren(code, open_index)
            if open_index < 0 or close_index < 0:
                continue
            arguments = code[open_index + 1 : close_index]
            shape.add((method, len(cls._split_top_level_args(arguments))))
        return shape

    def _render_existing_test_context(
        self,
        existing_test: str,
        target_method: str,
        *,
        mutation_feedback_only: bool = False,
        target_descriptor: str | None = None,
        target_source: str = "",
        target_class: str = "",
        target_positive_test_methods: list[str] | None = None,
        entry_method_names: list[str] | None = None,
        retained_target_positive_baseline: bool = False,
        mutation_feedback: object = None,
    ) -> str:
        imports = [line for line in existing_test.splitlines() if line.strip().startswith("import ")]
        test_names = re.findall(
            r"@Test\s+(?:public\s+)?(?:void|[\w<>\[\]]+)\s+(\w+)\s*\(",
            existing_test,
        )
        parts = [
            "Existing test file summary (for context only; do NOT reproduce it; "
            f"only output NEW @Test methods for `{target_method}`):"
        ]
        if imports:
            parts.append("Imports already present:\n" + "\n".join(sorted(set(imports))))
        if test_names:
            capped_names = test_names[:80]
            suffix = "" if len(capped_names) == len(test_names) else f"\n- ... and {len(test_names) - len(capped_names)} more"
            parts.append("Existing @Test methods:\n" + "\n".join(f"- {name}" for name in capped_names) + suffix)
        if retained_target_positive_baseline:
            parts.append(
                "The retained suite has checksum-verified green target-positive "
                "coverage for this exact descriptor. Its full method bodies are "
                "intentionally omitted to prevent verbatim regeneration. Reuse "
                "the separately listed source-visible entry/state sequences and "
                "generate only behaviorally distinct missed-branch variants."
            )
            return "\n\n".join(parts)
        # Structural rounds may use the recent file tail for local style.
        # Mutation rounds instead select complete green methods with an exact
        # target/entry call; raw tails mix stale oracle commentary with live
        # mutant instructions and have no per-method reachability proof.
        existing_shell_valid = self._is_valid_class_structure(existing_test)
        existing_has_markdown_fence = "```" in existing_test
        if existing_shell_valid and not existing_has_markdown_fence:
            proven_target_tests: list[str] = []
            green_entry_examples: list[str] = []
            if mutation_feedback_only and target_method:
                _setup, test_methods, _teardown = self._categorize_methods(
                    existing_test
                )
                target_param_types = self._jvm_descriptor_param_types(
                    target_descriptor
                )
                target_arity = (
                    len(target_param_types)
                    if target_param_types
                    else None
                )
                target_positive_names = {
                    str(name).strip()
                    for name in list(target_positive_test_methods or [])
                    if str(name).strip()
                }
                verified_entry_calls = self._dedupe_ordered(
                    [
                        str(name).strip()
                        for name in list(entry_method_names or [])
                        if str(name).strip()
                    ]
                )
                ranked_methods: list[tuple[int, int, str, bool, int]] = []
                relevance_terms = self._mutation_seed_relevance_terms(
                    mutation_feedback
                )
                pit_covering_test_names = (
                    self._mutation_pit_covering_test_method_names(
                        mutation_feedback
                    )
                )
                exact_reflection_method_keys = {
                    self._mutation_seed_dedup_key(method)
                    for method in self._existing_green_exact_reflection_test_methods(
                        existing_test,
                        target_method=target_method,
                        target_descriptor=target_descriptor,
                        target_source=target_source,
                        target_class=target_class,
                    )
                }
                seen_method_bodies: set[str] = set()
                for method in test_methods:
                    method = method.strip()
                    method_name = self._extract_method_name(method)
                    coverage_proven = (
                        method_name in target_positive_names
                        or method_name in pit_covering_test_names
                    )
                    calls_exact_target = (
                        self._test_code_calls_any_method(
                            method,
                            [target_method],
                        )
                        and (
                            target_arity is None
                            or target_arity
                            in self._test_code_call_arities(
                                method,
                                target_method,
                            )
                        )
                    )
                    calls_visible_entry = bool(
                        verified_entry_calls
                        and self._test_code_calls_any_method(
                            method,
                            verified_entry_calls,
                        )
                    )
                    exact_green_reflection = bool(
                        self._mutation_seed_dedup_key(method)
                        in exact_reflection_method_keys
                    )
                    # An exact already-green reflection ACT is stronger setup
                    # evidence than asking mutation generation to reconstruct a
                    # complex private-owner fixture. It remains a seed only;
                    # arbitrary or descriptor-ambiguous reflection is excluded.
                    eligible = (
                        calls_visible_entry or exact_green_reflection
                        if verified_entry_calls
                        else (
                            coverage_proven
                            or calls_exact_target
                            or exact_green_reflection
                        )
                    )
                    if not eligible:
                        continue
                    dedup_key = self._mutation_seed_dedup_key(method)
                    if not dedup_key or dedup_key in seen_method_bodies:
                        continue
                    seen_method_bodies.add(dedup_key)
                    quality_score = self._mutation_seed_quality_score(
                        method,
                        coverage_proven=coverage_proven,
                        relevance_terms=relevance_terms,
                        propagation_witness=(
                            self._mutation_seed_propagation_witness(
                                method,
                                mutation_feedback,
                                target_method=target_method,
                            )
                        ),
                    )
                    propagation_witness = (
                        self._mutation_seed_propagation_witness(
                            method,
                            mutation_feedback,
                            target_method=target_method,
                        )
                    )
                    ranked_methods.append(
                        (
                            quality_score,
                            len(method),
                            method,
                            coverage_proven,
                            propagation_witness,
                        )
                    )
                total_chars = 0
                proven_target_witnesses: list[int] = []
                max_green_seeds = (
                    self._env_int(
                        "TATG_MUTATION_MAX_GREEN_SEEDS",
                        1,
                        minimum=1,
                        maximum=3,
                    )
                    if mutation_feedback_only
                    else 3
                )
                for (
                    _score,
                    _length,
                    method,
                    coverage_proven,
                    propagation_witness,
                ) in sorted(
                    ranked_methods,
                    key=lambda item: (-item[0], item[1]),
                ):
                    prompt_method = self._strip_java_comments_preserve_code(
                        method
                    )
                    prompt_method = re.sub(
                        r"\n[ \t]*\n(?:[ \t]*\n)+",
                        "\n\n",
                        prompt_method,
                    ).strip()
                    if not prompt_method or len(prompt_method) > 3600:
                        continue
                    projected = total_chars + len(prompt_method) + 2
                    if (
                        proven_target_tests or green_entry_examples
                    ) and projected > 6200:
                        break
                    if coverage_proven:
                        proven_target_tests.append(prompt_method)
                        proven_target_witnesses.append(
                            propagation_witness
                        )
                    else:
                        green_entry_examples.append(prompt_method)
                    total_chars = projected
                    if (
                        len(proven_target_tests) + len(green_entry_examples)
                        >= max_green_seeds
                    ):
                        break
            if proven_target_tests:
                propagation_rule = (
                    "The first seed has an existing assertion which is "
                    "source-compatible with a value different from the "
                    "mutant replacement. Preserve its Arrange and ACT "
                    "exactly and strengthen that observation."
                    if proven_target_witnesses
                    and proven_target_witnesses[0] > 0
                    else
                    "The listed green seed proves execution only; its current "
                    "observation does not distinguish the mutant replacement. "
                    "Do not preserve a mutant-equivalent input merely because "
                    "it is green. Reuse its compile-visible construction shape, "
                    "but derive a source-backed input/state whose original "
                    "observable value differs from the replacement."
                )
                parts.append(
                    "[Existing Green Target-Reaching Tests]\n"
                    "Candidate-level coverage or exact PIT block coverage "
                    "proved that these complete methods passed and reached "
                    "the target descriptor or selected live mutant block. "
                    + propagation_rule
                    + " Return executable code, not reasoning comments.\n\n"
                    + "\n\n".join(proven_target_tests)
                )
            if green_entry_examples:
                parts.append(
                    "[Existing Green Exact-Call Setup Examples]\n"
                    "These complete methods pass and call the exact target or "
                    "a source-visible entry, but candidate-level execution of "
                    "the selected mutant line is NOT proven. Reuse only their "
                    "compiling construction/call shape. Clone the first method "
                    "as the seed and make only the minimum input/state and oracle "
                    "edits required by the single live M-id. Do not emit analysis "
                    "as Java comments. Candidate-level coverage and PITest remain "
                    "authoritative.\n\n"
                    + "\n\n".join(green_entry_examples)
                )
            if proven_target_tests or green_entry_examples:
                return "\n\n".join(parts)
            if mutation_feedback_only:
                parts.append(
                    "No complete green test method with an exact target or "
                    "source-visible entry call was selected. Raw test-file "
                    "tail content is intentionally omitted because its "
                    "mutant-line reachability and oracle comments are "
                    "unproven; use the live M-id recipe and callable surface."
                )
                return "\n\n".join(parts)
            max_tail_env = (
                "TATG_MAX_MUTATION_EXISTING_TEST_CONTEXT_CHARS"
                if mutation_feedback_only
                else "TATG_MAX_EXISTING_TEST_CONTEXT_CHARS"
            )
            max_tail_default = "2600" if mutation_feedback_only else "6000"
            max_tail = int(os.getenv(max_tail_env, max_tail_default))
            tail_text = existing_test[-max_tail:] if len(existing_test) > max_tail else existing_test
            parts.append(
                (
                    "Recent green-test setup tail for mutation reuse:\n"
                    if mutation_feedback_only
                    else "Recent test-file content (tail) for local class/style reference:\n"
                )
                + tail_text
            )
        else:
            reason = "invalid Java class structure" if not existing_shell_valid else "markdown fenced generated content"
            parts.append(
                "Recent test-file content omitted: existing generated test shell has "
                f"{reason}. Use only the imports/test names summary above; do not reproduce old file body text."
            )
        return "\n\n".join(parts)

    @staticmethod
    def _mutation_conditional_block_line_span(
        source_code: str,
        line_number: int,
        *,
        max_lines: int = 120,
    ) -> tuple[int, int] | None:
        """Return a bounded complete ``if``/``else`` source span.

        Fixed mutation neighborhoods can end on the ``else`` token and hide
        the opposite behavior of a negated conditional.  This helper uses
        comment/string-masked brace matching only; it does not infer branch
        semantics. Large or malformed blocks retain the legacy window rather
        than expanding an unbounded prompt section.
        """

        source = str(source_code or "")
        if not source or line_number <= 0:
            return None
        masked = TATGEngineAdapter._strip_java_comments_and_strings(source)
        offsets = [0]
        offsets.extend(match.end() for match in re.finditer(r"\n", masked))
        if line_number > len(offsets):
            return None
        start = offsets[line_number - 1]
        line_end = masked.find("\n", start)
        if line_end < 0:
            line_end = len(masked)
        line = masked[start:line_end]
        if re.match(r"\s*if\s*\(", line) is None:
            return None

        # A multiline condition may place the opening brace below the source
        # line. Bound the search so a declaration later in the method cannot
        # be mistaken for this conditional's body.
        open_brace = masked.find("{", start, min(len(masked), line_end + 800))
        semicolon = masked.find(";", start, min(len(masked), line_end + 800))
        if open_brace < 0 or (semicolon >= 0 and semicolon < open_brace):
            return None
        close_brace = TATGEngineAdapter._find_matching_brace(
            masked,
            open_brace,
        )
        if close_brace < 0:
            return None

        end = close_brace + 1
        while True:
            cursor = end
            while cursor < len(masked) and masked[cursor].isspace():
                cursor += 1
            if not (
                masked.startswith("else", cursor)
                and (
                    cursor + 4 >= len(masked)
                    or not (
                        masked[cursor + 4].isalnum()
                        or masked[cursor + 4] in "_$"
                    )
                )
            ):
                break
            else_open = masked.find(
                "{",
                cursor + 4,
                min(len(masked), cursor + 804),
            )
            else_semicolon = masked.find(
                ";",
                cursor + 4,
                min(len(masked), cursor + 804),
            )
            if else_open >= 0 and not (
                else_semicolon >= 0 and else_semicolon < else_open
            ):
                else_close = TATGEngineAdapter._find_matching_brace(
                    masked,
                    else_open,
                )
                if else_close >= 0:
                    end = else_close + 1
                    continue
            break

        # ``end`` is exclusive and points immediately after the closing
        # brace.  Counting through it includes the newline that starts the
        # following source line, expanding the context one line too far.
        end_line = masked.count("\n", 0, max(0, end - 1)) + 1
        if end_line < line_number or end_line - line_number + 1 > max_lines:
            return None
        return line_number, end_line

    @staticmethod
    def _mutation_enclosing_conditional_block_line_span(
        source_code: str,
        line_number: int,
        *,
        max_lines: int = 120,
    ) -> tuple[int, int] | None:
        """Return the nearest bounded conditional containing a mutant line.

        Return-value and call-removal mutants commonly sit inside a branch,
        not on its ``if`` line. A fixed neighborhood can therefore omit the
        controlling predicate or opposite arm. Search only the preceding
        bounded corridor and reuse brace-proven complete spans; this exposes
        syntax without guessing branch semantics from names or domains.
        """

        if line_number <= 0:
            return None
        first = max(1, line_number - max_lines + 1)
        for candidate_line in range(line_number, first - 1, -1):
            span = TATGEngineAdapter._mutation_conditional_block_line_span(
                source_code,
                candidate_line,
                max_lines=max_lines,
            )
            if span is not None and span[0] <= line_number <= span[1]:
                return span
        return None

    @staticmethod
    def _render_mutation_source_context(
        source_code: str,
        method_name: str | None,
        coverage_feedback: object,
    ) -> str:
        """Render exact mutant neighborhoods instead of a structural source dump.

        For a NO_COVERAGE helper mutant, the helper body alone often cannot
        explain which caller-side token/state dispatches into it. Include a
        small source-only neighborhood around real call sites in the same
        owner. This is deliberately absent for SURVIVED mutants, where
        reachability is already proven and caller context would only add noise.
        """
        lines = str(source_code or "").splitlines()
        mutation_objectives = (
            [
                item
                for item in list(coverage_feedback.get("mutation_objectives") or [])
                if isinstance(item, dict)
            ]
            if isinstance(coverage_feedback, dict)
            else []
        )
        source_line_numbers: list[int] = []
        for objective in mutation_objectives:
            facts = objective.get("facts") if isinstance(objective.get("facts"), dict) else {}
            try:
                line_number = int(facts.get("line"))
            except (TypeError, ValueError):
                continue
            if 1 <= line_number <= len(lines) and line_number not in source_line_numbers:
                source_line_numbers.append(line_number)
        if not source_line_numbers:
            return TATGEngineAdapter._truncate_prompt_context(source_code, 5000)
        no_coverage_lines: set[int] = set()
        for objective in mutation_objectives:
            facts = (
                objective.get("facts")
                if isinstance(objective.get("facts"), dict)
                else {}
            )
            if str(
                facts.get("status") or objective.get("status") or ""
            ).strip().upper() != "NO_COVERAGE":
                continue
            try:
                no_coverage_lines.add(int(facts.get("line")))
            except (TypeError, ValueError):
                continue

        selected: set[int] = set()
        for line_number in source_line_numbers[:6]:
            # Reaching a NO_COVERAGE mutant often depends on avoiding a return
            # in the immediately preceding source block.  A symmetric six-line
            # window showed the mutant itself but hid that predecessor (for
            # example, a prior numeric-conversion return or parser dispatch).
            # Expose a bounded source corridor and let the model reason from
            # the actual code; do not infer domain rules from identifiers.
            before = 18 if line_number in no_coverage_lines else 6
            selected.update(
                range(
                    max(1, line_number - before),
                    min(len(lines), line_number + 6) + 1,
                )
            )
            conditional_span = (
                TATGEngineAdapter._mutation_conditional_block_line_span(
                    source_code,
                    line_number,
                )
                or TATGEngineAdapter._mutation_enclosing_conditional_block_line_span(
                    source_code,
                    line_number,
                )
            )
            if conditional_span is not None:
                selected.update(
                    range(
                        conditional_span[0],
                        min(len(lines), conditional_span[1]) + 1,
                    )
                )
        rendered_lines = [
            "[Mutation Source Neighborhoods]",
            "Only these source neighborhoods are mutation objectives; use other source solely for callable setup.",
        ]
        previous = 0
        for line_number in sorted(selected):
            if previous and line_number > previous + 1:
                rendered_lines.append("...")
            marker = ">>" if line_number in source_line_numbers else "  "
            rendered_lines.append(f"{marker} L{line_number}: {lines[line_number - 1]}")
            previous = line_number
        has_no_coverage = any(
            str(
                (
                    objective.get("facts")
                    if isinstance(objective.get("facts"), dict)
                    else {}
                ).get("status")
                or objective.get("status")
                or ""
            ).strip().upper()
            == "NO_COVERAGE"
            for objective in mutation_objectives
        )
        target_method = str(method_name or "").strip()
        if has_no_coverage and target_method:
            masked_lines = TATGEngineAdapter._strip_java_comments_and_strings(
                str(source_code or "")
            ).splitlines()
            call_pattern = re.compile(rf"\b{re.escape(target_method)}\s*\(")
            declaration_pattern = re.compile(
                rf"^\s*(?:(?:public|protected|private|static|final|synchronized|"
                rf"native|abstract|strictfp|default)\s+)*(?:<[^>]+>\s+)?"
                rf"[A-Za-z_$][A-Za-z0-9_$.,<>?\[\]\s]*\s+"
                rf"{re.escape(target_method)}\s*\("
            )
            caller_centers: list[int] = []
            for index, masked_line in enumerate(masked_lines, start=1):
                if not call_pattern.search(masked_line):
                    continue
                if declaration_pattern.search(masked_line):
                    continue
                caller_centers.append(index)
                if len(caller_centers) >= 2:
                    break
            if caller_centers:
                rendered_lines.extend([
                    "",
                    "Direct source call-site context for NO_COVERAGE reachability:",
                    "These are source excerpts, not inferred setup facts.",
                ])
                previous_end = 0
                for center in caller_centers:
                    start = max(1, center - 6)
                    end = min(len(lines), center + 6)
                    if previous_end and start > previous_end + 1:
                        rendered_lines.append("...")
                    for line_number in range(start, end + 1):
                        marker = ">>" if line_number == center else "  "
                        rendered_lines.append(
                            f"{marker} L{line_number}: {lines[line_number - 1]}"
                        )
                    previous_end = end
        return "\n".join(rendered_lines)

    @classmethod
    def _mutation_only_prompt_sections(cls, sections: list[str]) -> list[str]:
        """Keep mutation-extra prompts focused without touching structural prompts.

        Mutation generation starts from a green suite and exact PITest
        objectives. Broad project/domain prose and structural assertion advice
        compete with those facts, while target state/entry/callable evidence is
        still required for NO_COVERAGE mutants. Drop only generic modules and
        compact the large grounding modules as complete items.
        """
        dropped_prefixes = (
            "[Target Method Obligation]",
            "[Target Execution Receipt",
            "[Type-Guided Execution Recipes]",
            "[Visible Type Construction APIs]",
            "[Fixture Isolation Rules]",
            "[Source-Derived Target State/Call Plan]",
            "[Observed Construction Recipes]",
            "[Assertion-Quality Guidance]",
            "[Entry-Path Coverage Strategy]",
            "[Per-Method Output Rule]",
        )
        dropped_plain_prefixes = (
            "Strict type contracts (must follow exactly):",
            "Dependency context for the class under test:",
            "Generate comprehensive JUnit tests for:",
            "Testing stack constraints:",
            "Domain type field shapes (use these for fixture construction):",
            "Coverage-quality guidance:",
            "Source code under test:",
        )
        compact_caps = (
            ("[CALLABLE SURFACE", 3600),
            ("[Classpath Symbol Grounding]", 2800),
            ("[Mutation Feedback For Mutation Extra Round]", 14000),
            ("[Source-Visible Mutation Entry Paths]", 5200),
            ("[Mutation Reachability Recipe]", 6200),
            ("[Mutation Objective Context]", 7600),
            ("[Mutation Execution Receipt]", 1800),
            ("[Mutation Source Neighborhoods]", 5200),
            ("[Source-Derived Visible State Sequence]", 2200),
            ("[Inherited Setup Methods", 1800),
            ("[Source-Exact Receiver Construction Contract]", 1800),
            ("[Overload-Specific Scenario Contract]", 1800),
        )
        selected: list[str] = []
        for raw_section in sections:
            for raw_part in cls._split_embedded_high_priority_generation_sections(
                str(raw_section or "")
            ):
                section = str(raw_part or "").strip()
                if not section:
                    continue
                if section.startswith(dropped_prefixes) or section.startswith(
                    dropped_plain_prefixes
                ):
                    continue
                cap = next(
                    (
                        max_chars
                        for prefix, max_chars in compact_caps
                        if section.startswith(prefix)
                    ),
                    None,
                )
                if cap is not None and len(section) > cap:
                    section = cls._compact_complete_item_section(
                        section,
                        cap,
                        allow_partial_first_item=False,
                    )
                if section:
                    selected.append(section)
        return selected

    @staticmethod
    def _mutation_objective_ids_from_feedback(
        coverage_feedback: object,
    ) -> set[str]:
        if not isinstance(coverage_feedback, dict):
            return set()
        return {
            str(item.get("id") or "").strip().upper()
            for item in list(coverage_feedback.get("mutation_objectives") or [])
            if (
                isinstance(item, dict)
                and re.fullmatch(r"M\d+", str(item.get("id") or "").strip(), re.IGNORECASE)
            )
        }

    @staticmethod
    def _mutation_objective_ids_from_prompt(prompt: str) -> set[str]:
        """Return only M-ids declared by live mutation objective rows.

        Mutation prompts legitimately mention older M-ids in existing green
        test names, schema examples, and explanatory references.  Treating
        every ``M\\d+`` token as an active objective made the final prompt
        guard report stale-context leakage and needlessly rebuild an already
        correct prompt.  Active objectives have a stricter rendered shape.
        """

        return {
            match.group(1).upper()
            for match in re.finditer(
                r"(?m)^\s*-\s*(M\d+)\s+\[Mutation(?:Assertion|Reachability)\]",
                str(prompt or ""),
                re.IGNORECASE,
            )
        }

    @staticmethod
    def _prompt_heading_count(prompt: str, heading: str) -> int:
        return len(
            re.findall(
                rf"(?m)^\s*{re.escape(str(heading or '').strip())}\s*$",
                str(prompt or ""),
            )
        )

    @classmethod
    def _ensure_mutation_feedback_in_final_prompt(
        cls,
        user_prompt: str,
        *,
        coverage_feedback: object,
        mutation_feedback_section: str,
    ) -> tuple[str, dict[str, object]]:
        """Ensure the actual request contains current M-id evidence.

        Metadata saying that mutation feedback was requested is not sufficient:
        section compaction previously left only an M-id schema example while
        dropping the live PITest rows.  This final, mutation-only guard inserts
        the complete feedback section near the front when the rendered request
        lacks its marker or any current objective id.
        """
        prompt = str(user_prompt or "")
        expected_ids = cls._mutation_objective_ids_from_feedback(coverage_feedback)
        actual_ids = cls._mutation_objective_ids_from_prompt(prompt)
        marker_present = "[Mutation Feedback For Mutation Extra Round]" in prompt
        missing_ids = sorted(expected_ids - actual_ids, key=cls._oid_sort_key)
        unexpected_ids = sorted(actual_ids - expected_ids, key=cls._oid_sort_key)
        duplicate_mutation_sections = {
            marker: cls._prompt_heading_count(prompt, marker)
            for marker in (
                "[Mutation Feedback For Mutation Extra Round]",
                "[Mutation Objective Context]",
                "[Mutation Reachability Recipe]",
                "[Source-Visible Mutation Entry Paths]",
            )
            if cls._prompt_heading_count(prompt, marker) > 1
        }
        audit: dict[str, object] = {
            "expected_objective_ids": sorted(expected_ids, key=cls._oid_sort_key),
            "actual_objective_ids": sorted(actual_ids, key=cls._oid_sort_key),
            "marker_present_before_guard": marker_present,
            "missing_objective_ids_before_guard": missing_ids,
            "unexpected_objective_ids_before_guard": unexpected_ids,
            "duplicate_mutation_sections_before_guard": (
                duplicate_mutation_sections
            ),
            "feedback_reinserted": False,
        }
        feedback = str(mutation_feedback_section or "").strip()
        if (
            marker_present
            and not missing_ids
            and not unexpected_ids
            and not duplicate_mutation_sections
        ):
            return prompt, audit
        if not feedback or not expected_ids:
            audit["guard_failure_reason"] = (
                "mutation_feedback_section_missing"
                if not feedback
                else "mutation_objective_ids_missing_from_feedback"
            )
            return prompt, audit

        separator = "\n\n---\n\n"
        mutation_prefixes = (
            "[Mutation Feedback For Mutation Extra Round]",
            "[Source-Visible Mutation Entry Paths]",
            "[Mutation Reachability Recipe]",
            "[Mutation Objective Context]",
        )
        sections = [
            section
            for section in prompt.split(separator)
            if not str(section).lstrip().startswith(mutation_prefixes)
        ]
        insert_at = 0
        for index, section in enumerate(sections):
            if str(section).lstrip().startswith(
                (
                    "[Generation Control Receipt]",
                    "[Prompt Module Guide]",
                    "[Target Overload Binding]",
                )
            ):
                insert_at = index + 1
        sections.insert(insert_at, feedback)
        guarded = separator.join(cls._order_generation_prompt_sections(sections))
        guarded_ids = cls._mutation_objective_ids_from_prompt(guarded)
        audit.update({
            "feedback_reinserted": True,
            "marker_present_after_guard": (
                "[Mutation Feedback For Mutation Extra Round]" in guarded
            ),
            "actual_objective_ids_after_guard": sorted(
                guarded_ids,
                key=cls._oid_sort_key,
            ),
            "missing_objective_ids_after_guard": sorted(
                expected_ids - guarded_ids,
                key=cls._oid_sort_key,
            ),
            "unexpected_objective_ids_after_guard": sorted(
                guarded_ids - expected_ids,
                key=cls._oid_sort_key,
            ),
        })
        return guarded, audit

    @staticmethod
    def _strip_code_fences(code: str) -> str:
        """Remove markdown code fences and reasoning-model thinking blocks from LLM output.

        Models sometimes wrap even when instructed not to.  Stripping before
        writing prevents the fences from reaching the .java file.
        Also strips <think>...</think> blocks emitted by reasoning models (Qwen3,
        DeepSeek-R1) so the remaining text is parseable JSON or Java.
        """
        stripped = code.strip()
        # Strip <think>...</think> reasoning blocks (Qwen3, DeepSeek-R1 style)
        if "<think>" in stripped:
            stripped = re.sub(r"<think>.*?</think>", "", stripped, flags=re.DOTALL).strip()
        # ``` fence with optional language tag on first line
        if stripped.startswith("```"):
            # Remove opening fence line
            first_newline = stripped.find("\n")
            if first_newline != -1:
                stripped = stripped[first_newline + 1:]
            # Remove closing fence
            if stripped.rstrip().endswith("```"):
                last_fence = stripped.rstrip().rfind("```")
                stripped = stripped[:last_fence].rstrip()
        # Single-backtick fence: some models use `java\n...\n` style
        elif stripped.startswith("`") and "\n" in stripped:
            first_newline = stripped.find("\n")
            inner = stripped[first_newline + 1:]
            if inner.rstrip().endswith("`"):
                stripped = inner.rstrip()[:-1].rstrip()
            else:
                stripped = inner
        return stripped

    @staticmethod
    def _remove_markdown_fence_lines(code: str) -> str:
        if "```" not in str(code or ""):
            return code
        kept: list[str] = []
        for line in str(code or "").splitlines():
            stripped = line.strip()
            if stripped.startswith("```") or stripped.endswith("```"):
                continue
            kept.append(line)
        return "\n".join(kept) + ("\n" if str(code or "").endswith("\n") else "")

    @staticmethod
    def _sanitize_java_backticks(code: str) -> str:
        """Remove backtick characters from generated Java code.

        Backticks arise from LLM markdown habits (inline `code` in comments,
        unfenced single-backtick blocks).  Outside string/char literals they
        are not valid Java tokens; inside strings they are technically valid
        but cause some Java formatters (google-java-format / fmt-maven-plugin)
        to reject the file.  We replace them context-sensitively:
          - Outside literals/comments: remove (illegal token)
          - In line/block comments: replace with single-quote (harmless)
          - In string literals: replace with the Unicode escape \\u0060
        """
        if "`" not in code:
            return code
        result: list[str] = []
        i = 0
        n = len(code)
        in_string: str | None = None    # '"' or "'"
        in_line_comment = False
        in_block_comment = False

        while i < n:
            ch = code[i]

            if in_line_comment:
                if ch == "\n":
                    in_line_comment = False
                elif ch == "`":
                    result.append("'")
                    i += 1
                    continue
            elif in_block_comment:
                if ch == "*" and i + 1 < n and code[i + 1] == "/":
                    result.append("*/")
                    i += 2
                    in_block_comment = False
                    continue
                elif ch == "`":
                    result.append("'")
                    i += 1
                    continue
            elif in_string is not None:
                if ch == "\\" and i + 1 < n:
                    # Escaped character — pass through both chars unchanged
                    result.append(ch)
                    result.append(code[i + 1])
                    i += 2
                    continue
                if ch == in_string:
                    in_string = None
                elif ch == "`":
                    result.append("\\u0060")
                    i += 1
                    continue
            else:
                if ch == "/" and i + 1 < n and code[i + 1] == "/":
                    in_line_comment = True
                elif ch == "/" and i + 1 < n and code[i + 1] == "*":
                    in_block_comment = True
                    result.append("/*")
                    i += 2
                    continue
                elif ch in ('"', "'"):
                    in_string = ch
                elif ch == "`":
                    i += 1
                    continue

            result.append(ch)
            i += 1

        return "".join(result)

    @staticmethod
    def _split_top_level_java_args(arg_text: str) -> list[str]:
        """Split a Java argument list on top-level commas only."""
        args: list[str] = []
        start = 0
        depth = 0
        in_string: str | None = None
        escape = False
        for i, ch in enumerate(arg_text):
            if in_string:
                if escape:
                    escape = False
                elif ch == "\\":
                    escape = True
                elif ch == in_string:
                    in_string = None
                continue
            if ch in {'"', "'"}:
                in_string = ch
                continue
            if ch in "([{<":
                depth += 1
                continue
            if ch in ")]}>":
                depth = max(0, depth - 1)
                continue
            if ch == "," and depth == 0:
                args.append(arg_text[start:i].strip())
                start = i + 1
        tail = arg_text[start:].strip()
        if tail:
            args.append(tail)
        return args

    @classmethod
    def _rewrite_junit_boolean_assertions_for_functionless_classpath(cls, code: str) -> str:
        """Avoid JUnit boolean assertion overloads that require java.util.function."""
        if "assertTrue" not in code and "assertFalse" not in code and "assertEquals" not in code:
            return code
        junit5_style = "org.junit.jupiter" in code or "Assertions." in code

        def _find_matching_paren(text: str, open_index: int) -> int:
            depth = 0
            in_string: str | None = None
            escape = False
            for i in range(open_index, len(text)):
                ch = text[i]
                if in_string:
                    if escape:
                        escape = False
                    elif ch == "\\":
                        escape = True
                    elif ch == in_string:
                        in_string = None
                    continue
                if ch in {'"', "'"}:
                    in_string = ch
                    continue
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        return i
            return -1

        def _is_boolean_literal(arg: str) -> bool:
            return str(arg or "").strip() in {"true", "false"}

        def _is_string_literal(arg: str) -> bool:
            value = str(arg or "").strip()
            return len(value) >= 2 and value[0] == '"' and value[-1] == '"'

        pattern = re.compile(r"\b(?P<prefix>(?:org\.junit\.jupiter\.api\.Assertions\.|Assertions\.)?)assert(?P<kind>True|False|Equals)\s*\(")
        out: list[str] = []
        pos = 0
        for match in pattern.finditer(code):
            open_index = match.end() - 1
            close_index = _find_matching_paren(code, open_index)
            if close_index < 0:
                continue
            args = cls._split_top_level_java_args(code[open_index + 1:close_index])
            prefix = match.group("prefix") or ""
            uses_junit5_order = bool(prefix) or junit5_style
            kind = match.group("kind")
            if kind in {"True", "False"}:
                if len(args) not in {1, 2}:
                    continue
                expected = "true" if kind == "True" else "false"
                replacement_args = [expected, args[0]]
                if len(args) == 2:
                    if uses_junit5_order:
                        replacement_args.append(args[1])
                    else:
                        # JUnit4 assertTrue/assertFalse uses
                        # (String message, boolean condition). Preserve that
                        # order when rewriting to
                        # assertEquals(String, expected, actual). Also recover
                        # the common LLM-produced JUnit5 ordering when the
                        # second argument is visibly the message literal.
                        if _is_string_literal(args[0]):
                            message, condition = args[0], args[1]
                        elif _is_string_literal(args[1]):
                            message, condition = args[1], args[0]
                        else:
                            continue
                        replacement_args = [message, expected, condition]
            else:
                if uses_junit5_order or len(args) != 3 or not _is_string_literal(args[2]):
                    continue
                if _is_boolean_literal(args[0]) and not _is_boolean_literal(args[1]):
                    replacement_args = [args[2], args[0], args[1]]
                elif _is_boolean_literal(args[1]) and not _is_boolean_literal(args[0]):
                    replacement_args = [args[2], args[1], args[0]]
                else:
                    continue
            out.append(code[pos:match.start()])
            out.append(f"{prefix}assertEquals({', '.join(replacement_args)})")
            pos = close_index + 1
        if not out:
            return code
        out.append(code[pos:])
        return "".join(out)

    @classmethod
    def _drop_junit5_string_message_assertion_args(cls, code: str) -> str:
        """Drop String message args from JUnit5 assertions for Java 7 toolchains.

        Some older projects compile tests with a source/bootclasspath that lacks
        ``java.util.function.Supplier``.  JUnit5's message overload family can
        make javac resolve/load Supplier even when the generated test uses a
        String message.  Removing only the trailing String message is
        semantics-preserving for coverage and keeps the assertion itself.
        """
        text = str(code or "")
        if "assert" not in text or "org.junit.jupiter" not in text and "Assertions." not in text:
            return text

        def _find_matching_paren(local_text: str, open_index: int) -> int:
            depth = 0
            in_string: str | None = None
            escape = False
            for i in range(open_index, len(local_text)):
                ch = local_text[i]
                if in_string:
                    if escape:
                        escape = False
                    elif ch == "\\":
                        escape = True
                    elif ch == in_string:
                        in_string = None
                    continue
                if ch in {'"', "'"}:
                    in_string = ch
                    continue
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        return i
            return -1

        def _is_string_literal(arg: str) -> bool:
            value = str(arg or "").strip()
            return len(value) >= 2 and value[0] == '"' and value[-1] == '"'

        pattern = re.compile(
            r"\b(?P<prefix>(?:org\.junit\.jupiter\.api\.Assertions\.|Assertions\.)?)"
            r"(?P<name>assert(?:Equals|NotEquals|Same|NotSame|True|False|Null|NotNull|ArrayEquals))\s*\("
        )
        out: list[str] = []
        pos = 0
        for match in pattern.finditer(text):
            open_index = match.end() - 1
            close_index = _find_matching_paren(text, open_index)
            if close_index < 0:
                continue
            args = cls._split_top_level_java_args(text[open_index + 1:close_index])
            if len(args) < 2 or not _is_string_literal(args[-1]):
                continue
            out.append(text[pos:match.start()])
            out.append(f"{match.group('prefix') or ''}{match.group('name')}({', '.join(args[:-1])})")
            pos = close_index + 1
        if not out:
            return text
        out.append(text[pos:])
        return "".join(out)

    @classmethod
    def _sanitize_raw_java_generation(cls, code: str) -> str:
        """Normalize raw Java-class LLM output before structural validation."""
        text = str(code or "")
        fenced = re.search(r"```[A-Za-z0-9_-]*\s*\n(.*?)```", text, re.DOTALL)
        if fenced:
            text = fenced.group(1)
        else:
            text = code or ""
        return cls._sanitize_java_backticks(
            cls._remove_markdown_fence_lines(cls._strip_code_fences(text))
        )

    @staticmethod
    def _remove_non_generic_target_class_diamond(
        code: str,
        *,
        source_code: str,
        class_name: str | None,
    ) -> str:
        """Remove `new Target<>()` when source proves Target is non-generic."""
        simple = str(class_name or "").strip()
        if not code or not source_code or not simple:
            return code
        declaration = re.search(
            rf"\b(?:class|interface|enum)\s+{re.escape(simple)}\b(?P<tail>\s*<)?",
            str(source_code),
        )
        if not declaration or declaration.group("tail"):
            return code
        return re.sub(
            rf"\bnew\s+((?:[A-Za-z_$][\w$]*\.)*{re.escape(simple)})\s*<\s*>\s*\(",
            r"new \1(",
            str(code),
        )

    @classmethod
    def _source_generic_type_arity_map(
        cls,
        code: str,
        *,
        source_code: str,
        project_root: Path | None,
    ) -> dict[str, int]:
        """Map generated simple type references to source-declared generic arity."""
        generated = str(code or "")
        if not generated:
            return {}
        referenced = {
            match.group("name")
            for match in re.finditer(r"\b(?P<name>[A-Z][A-Za-z0-9_$]*)\s*<", generated)
        }
        if not referenced:
            return {}
        arities: dict[str, int] = {}

        def _record_from_text(text: str) -> None:
            if not text:
                return
            for match in re.finditer(
                r"\b(?:public|protected|private|abstract|final|static|\s)*"
                r"(?:class|interface|record)\s+(?P<name>[A-Za-z_$][\w$]*)\b",
                text,
            ):
                name = str(match.group("name") or "").strip()
                if name not in referenced or name in arities:
                    continue
                idx = match.end()
                while idx < len(text) and text[idx].isspace():
                    idx += 1
                if idx >= len(text) or text[idx] != "<":
                    arities[name] = 0
                    continue
                close_idx = cls._find_matching_angle(text, idx)
                if close_idx < 0:
                    arities[name] = 0
                    continue
                inner = text[idx + 1:close_idx].strip()
                arities[name] = len([p for p in cls._split_top_level_args(inner) if p.strip()])

        _record_from_text(str(source_code or ""))

        imports: dict[str, str] = {}
        for match in re.finditer(r"(?m)^\s*import\s+(?:static\s+)?(?P<fqn>[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)\s*;", generated):
            fqn = str(match.group("fqn") or "").strip()
            simple = fqn.rsplit(".", 1)[-1]
            if simple in referenced:
                imports[simple] = fqn

        root = Path(project_root) if project_root else None
        if root and root.exists():
            for simple in sorted(referenced - set(arities.keys())):
                candidate_paths: list[Path] = []
                fqn = imports.get(simple)
                if fqn:
                    rel = Path(*fqn.split(".")).with_suffix(".java")
                    candidate_paths.extend([
                        root / "src/main/java" / rel,
                        root / "src/test/java" / rel,
                    ])
                if not candidate_paths:
                    try:
                        candidate_paths.extend(list((root / "src/main/java").rglob(f"{simple}.java"))[:4])
                    except Exception:
                        candidate_paths = []
                for path in candidate_paths[:6]:
                    try:
                        text = path.read_text(encoding="utf-8", errors="ignore")
                    except Exception:
                        continue
                    before = dict(arities)
                    _record_from_text(text)
                    if simple in arities and arities != before:
                        break
        return arities

    @classmethod
    def _rewrite_source_declared_generic_arities(
        cls,
        code: str,
        *,
        source_code: str,
        project_root: Path | None,
    ) -> tuple[str, list[str]]:
        """Repair generated type-argument arity when source declarations prove it."""
        text = str(code or "")
        arities = cls._source_generic_type_arity_map(
            text,
            source_code=source_code,
            project_root=project_root,
        )
        if not text or not arities:
            return text, []
        out: list[str] = []
        rewrites: list[str] = []
        emit_pos = 0
        search_pos = 0
        pattern = re.compile(r"\b(?P<name>[A-Z][A-Za-z0-9_$]*)\s*<")
        while True:
            match = pattern.search(text, search_pos)
            if not match:
                break
            name = str(match.group("name") or "")
            required = arities.get(name)
            if required is None:
                search_pos = match.end()
                continue
            open_idx = text.find("<", match.start())
            close_idx = cls._find_matching_angle(text, open_idx)
            if close_idx < 0:
                search_pos = match.end()
                continue
            args_text = text[open_idx + 1:close_idx]
            args = [arg.strip() for arg in cls._split_top_level_args(args_text) if arg.strip()]
            prefix = text[max(0, match.start() - 16):match.start()]
            is_constructor_diamond = bool(re.search(r"\bnew\s*$", prefix))
            if len(args) == required:
                if required > 0 or args:
                    out.append(text[emit_pos:close_idx + 1])
                    emit_pos = close_idx + 1
                    search_pos = emit_pos
                    continue
            if not args and is_constructor_diamond and required > 0:
                out.append(text[emit_pos:close_idx + 1])
                emit_pos = close_idx + 1
                search_pos = emit_pos
                continue
            out.append(text[emit_pos:match.start()])
            if required <= 0:
                out.append(name)
                rewrites.append(f"{name}: {len(args)} type arg(s)->0")
            elif not args:
                inferred = ["Object"] * required
                out.append(f"{name}<" + ", ".join(inferred) + ">")
                rewrites.append(f"{name}: diamond LHS->{required} inferred arg(s)")
            else:
                inferred = list(args[:required])
                if len(inferred) < required:
                    inferred.extend([inferred[-1]] * (required - len(inferred)))
                out.append(f"{name}<" + ", ".join(inferred) + ">")
                rewrites.append(f"{name}: {len(args)} type arg(s)->{required}")
            emit_pos = close_idx + 1
            search_pos = emit_pos
        if not rewrites:
            return text, []
        out.append(text[emit_pos:])
        return "".join(out), rewrites[:12]

    @staticmethod
    def _find_matching_angle(text: str, open_index: int) -> int:
        if open_index < 0 or open_index >= len(text) or text[open_index] != "<":
            return -1
        depth = 0
        in_string: str | None = None
        escape = False
        for idx in range(open_index, len(text)):
            ch = text[idx]
            if in_string:
                if escape:
                    escape = False
                elif ch == "\\":
                    escape = True
                elif ch == in_string:
                    in_string = None
                continue
            if ch in {'"', "'"}:
                in_string = ch
                continue
            if ch == "<":
                depth += 1
            elif ch == ">":
                depth -= 1
                if depth == 0:
                    return idx
        return -1

    @classmethod
    def _source_visible_self_factory_methods(
        cls,
        project_root: Path,
        fqn: str,
    ) -> dict[str, str]:
        """Return public static factory methods whose return type is the owner type.

        The result maps method name to its raw parameter text.  This is used by
        generation-time sanitizers to replace inaccessible empty anonymous
        construction with source-proven public factories.  It intentionally
        requires source evidence and public static visibility.
        """
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            return {}
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return {}
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        factories: dict[str, str] = {}
        method_re = re.compile(
            r"\bpublic\s+static\s+(?:<[^>]+>\s+)?"
            r"(?P<ret>[A-Za-z_$][\w$]*(?:\s*<[^;{}()]+?>)?)\s+"
            r"(?P<name>[A-Za-z_$][\w$]*)\s*\((?P<params>[^)]*)\)"
        )
        for match in method_re.finditer(code):
            ret_simple = match.group("ret").split("<", 1)[0].rsplit(".", 1)[-1].strip()
            if ret_simple == simple:
                factories[match.group("name")] = " ".join(match.group("params").split())
        return factories

    @staticmethod
    def _java_class_literal_for_type(type_expr: str) -> str | None:
        """Convert a Java type expression into a class literal when safe."""
        value = " ".join(str(type_expr or "").strip().split())
        if not value:
            return None
        value = re.sub(r"^\s*(?:final\s+)?", "", value)
        if "?" in value or re.search(r"\b(?:extends|super)\b", value):
            return None
        raw = value.split("<", 1)[0].strip()
        if not raw:
            return None
        if re.search(r"[^A-Za-z0-9_.$\[\]]", raw):
            return None
        return f"{raw}.class"

    @classmethod
    def _factory_expr_for_empty_anonymous_generic(
        cls,
        owner: str,
        generic_args: str,
        *,
        factories: dict[str, str],
    ) -> str | None:
        args_text = str(generic_args or "").strip()
        if not args_text:
            return None
        get_params = factories.get("get", "")
        parameterized_params = factories.get("getParameterized", "")
        has_class_or_type_get = bool(
            re.search(r"\b(?:Class|Type)\s*(?:<[^>]+>)?(?:\s+\w+|\.\.\.\s*\w+|\[\]\s*\w+)", get_params)
        )
        has_parameterized = bool(
            parameterized_params
            and "Type" in parameterized_params
            and ("..." in parameterized_params or "[]" in parameterized_params or "," in parameterized_params)
        )
        raw = args_text.split("<", 1)[0].strip()
        raw_literal = cls._java_class_literal_for_type(raw)
        if "<" not in args_text:
            if has_class_or_type_get:
                literal = cls._java_class_literal_for_type(args_text)
                return f"{owner}.get({literal})" if literal else None
            return None
        if not raw_literal:
            return None
        inner_start = args_text.find("<")
        inner_end = args_text.rfind(">")
        if inner_end <= inner_start:
            return f"{owner}.get({raw_literal})" if has_class_or_type_get else None
        type_args = cls._split_top_level_args(args_text[inner_start + 1:inner_end])
        arg_literals = [cls._java_class_literal_for_type(arg) for arg in type_args]
        if has_parameterized and arg_literals and all(arg_literals):
            return f"{owner}.getParameterized({raw_literal}, {', '.join(arg_literals)})"
        if has_class_or_type_get:
            return f"{owner}.get({raw_literal})"
        return None

    @classmethod
    def _rewrite_empty_anonymous_generic_factories(
        cls,
        code: str,
        *,
        project_root: Path,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Rewrite `new X<Y>() {}` to source-visible `X` factories when possible.

        This is deliberately narrow.  It only rewrites empty anonymous generic
        subclasses and only when project source proves that the owner has public
        static factories returning the owner type.  Anonymous classes with
        methods/fields are left untouched because they are often valid fakes.
        """
        text = str(code or "")
        if "new " not in text or "{}" not in text:
            return text, []
        index = symbol_index if symbol_index is not None else cls._build_symbol_index(project_root)
        package_match = cls._RE_PACKAGE_DECL.search(text)
        current_package = package_match.group(1) if package_match else ""
        import_map: dict[str, str] = {}
        for import_match in cls._RE_IMPORT_DECL.finditer(text):
            qname = import_match.group(2)
            if qname.endswith(".*"):
                continue
            import_map[qname.rsplit(".", 1)[-1]] = qname

        changes: list[str] = []
        pattern = re.compile(
            r"\bnew\s+(?P<owner>(?:[A-Za-z_$][\w$]*\.)*[A-Za-z_$][\w$]*)"
            r"\s*<(?P<args>[^;{}()]+?)>\s*\(\s*\)\s*\{\s*\}",
            re.DOTALL,
        )

        def _replacement(match: re.Match[str]) -> str:
            owner_expr = match.group("owner")
            owner_simple = owner_expr.rsplit(".", 1)[-1]
            candidates: list[str] = []
            if "." in owner_expr and owner_expr not in index:
                candidates = [owner_expr]
            elif owner_simple in import_map:
                candidates = [import_map[owner_simple]]
            else:
                candidates = list(index.get(owner_simple) or [])
            fqn = cls._resolve_best_fqn(
                owner_simple,
                candidates=candidates,
                current_package=current_package,
                source_package=current_package,
            )
            if not fqn:
                return match.group(0)
            factories = cls._source_visible_self_factory_methods(project_root, fqn)
            if not factories:
                return match.group(0)
            replacement = cls._factory_expr_for_empty_anonymous_generic(
                owner_expr,
                match.group("args"),
                factories=factories,
            )
            if not replacement:
                return match.group(0)
            changes.append(f"{owner_simple}: anonymous-generic-constructor -> {replacement}")
            return replacement

        rewritten = pattern.sub(_replacement, text)
        if changes and "getParameterized(" in rewritten:
            rewritten = re.sub(
                r"\bObjectConstructor\s*<[^;\n=]+>\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\n]*\.get\s*\(\s*[A-Za-z_$][\w$.]*\.getParameterized\s*\()",
                r"ObjectConstructor<?> \1 = \2",
                rewritten,
            )
        return rewritten, changes

    @classmethod
    def _rewrite_source_factory_token_assignments(
        cls,
        code: str,
        *,
        project_root: Path,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Relax/fix generic token local assignments built through source factories.

        Some projects expose token/capture factories whose source return type is
        intentionally ``Owner<?>`` for Type-based factories and ``Owner<T>`` for
        raw ``Class<T>`` factories.  Generated tests often assign those factory
        calls to ``Owner<Parameterized<...>>`` locals, which javac rejects before
        the target can run.  If source proves matching owner factories exist,
        rewrite the local to ``Owner<?>`` and use a parameterized factory when
        available.
        """
        text = str(code or "")
        if ".get(" not in text and ".getParameterized(" not in text:
            return text, []
        index = symbol_index if symbol_index is not None else cls._build_symbol_index(project_root)
        package_match = cls._RE_PACKAGE_DECL.search(text)
        current_package = package_match.group(1) if package_match else ""
        import_map: dict[str, str] = {}
        for import_match in cls._RE_IMPORT_DECL.finditer(text):
            qname = import_match.group(2)
            if not qname.endswith(".*"):
                import_map[qname.rsplit(".", 1)[-1]] = qname
        changes: list[str] = []
        changed_vars: set[str] = set()

        def _factory_assignment(owner: str, var_name: str, declared_type: str, raw: str) -> str | None:
            candidates = [import_map[owner]] if owner in import_map else list(index.get(owner) or [])
            fqn = cls._resolve_best_fqn(
                owner,
                candidates=candidates,
                current_package=current_package,
                source_package=current_package,
            )
            if not fqn:
                return None
            factories = cls._source_visible_self_factory_methods(project_root, fqn)
            if "get" not in factories and "getParameterized" not in factories:
                return None
            declared = " ".join(str(declared_type or "").split())
            rhs = f"{owner}.get({raw}.class)"
            if "<" in declared and "getParameterized" in factories:
                inner_start = declared.find("<")
                inner_end = declared.rfind(">")
                raw_declared = declared.split("<", 1)[0].strip()
                if inner_end > inner_start and raw_declared.rsplit(".", 1)[-1] == raw.rsplit(".", 1)[-1]:
                    type_args = cls._split_top_level_args(declared[inner_start + 1:inner_end])
                    arg_literals = [cls._java_class_literal_for_type(arg) for arg in type_args]
                    if arg_literals and all(arg_literals):
                        rhs = f"{owner}.getParameterized({raw}.class, {', '.join(arg_literals)})"
            changed_vars.add(var_name)
            changes.append(f"{owner}: factory-token-local -> wildcard")
            return f"{owner}<?> {var_name} = {rhs};"

        pattern = re.compile(
            r"\b(?P<owner>[A-Z][A-Za-z0-9_$]*)\s*<(?P<type>[^;\n=]+?)>\s+"
            r"(?P<var>[A-Za-z_$][\w$]*)\s*=\s*(?P=owner)\.get\s*\(\s*"
            r"(?P<raw>[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.class\s*\)\s*;",
        )

        def _replacement(match: re.Match[str]) -> str:
            replacement = _factory_assignment(
                match.group("owner"),
                match.group("var"),
                match.group("type"),
                match.group("raw"),
            )
            return replacement or match.group(0)

        rewritten = pattern.sub(_replacement, text)
        mock_pattern = re.compile(
            r"\b(?P<owner>[A-Z][A-Za-z0-9_$]*)\s*<(?P<type>[^;\n=]+?)>\s+"
            r"(?P<var>[A-Za-z_$][\w$]*)\s*=\s*(?:org\.mockito\.)?Mockito\.mock\s*\(\s*"
            r"(?P=owner)\s*<(?P=type)>\s*\.class\s*\)\s*;",
        )

        def _mock_replacement(match: re.Match[str]) -> str:
            declared_type = " ".join(match.group("type").split())
            raw = declared_type.split("<", 1)[0].strip()
            replacement = _factory_assignment(
                match.group("owner"),
                match.group("var"),
                declared_type,
                raw,
            )
            return replacement or match.group(0)

        rewritten = mock_pattern.sub(_mock_replacement, rewritten)
        if changed_vars:
            var_alt = "|".join(re.escape(var) for var in sorted(changed_vars))
            rewritten = re.sub(
                rf"\b(ObjectConstructor)\s*<[^;\n=]+>\s+([A-Za-z_$][\w$]*)\s*=\s*([^;\n]*\.\s*get\s*\(\s*(?:{var_alt})\s*\))",
                r"\1<?> \2 = \3",
                rewritten,
            )
        return rewritten, changes

    @classmethod
    def _source_visible_constructor_param_lists(
        cls,
        project_root: Path,
        fqn: str,
    ) -> tuple[list[list[str]], dict[str, str]]:
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            return [], {}
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return [], {}
        import_map = {
            match.group(2).rsplit(".", 1)[-1]: match.group(2)
            for match in cls._RE_IMPORT_DECL.finditer(source_text)
            if not match.group(2).endswith(".*")
        }
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        param_lists: list[list[str]] = []
        ctor_re = re.compile(
            rf"\b(?:public|protected)\s+{re.escape(simple)}\s*\((?P<params>[^)]*)\)"
        )
        for match in ctor_re.finditer(code):
            params: list[str] = []
            for raw_param in cls._split_top_level_args(match.group("params")):
                cleaned = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", raw_param).strip()
                cleaned = re.sub(r"\bfinal\s+", "", cleaned).strip()
                param_match = re.match(r"(?P<type>.+?)\s+[A-Za-z_$][\w$]*$", cleaned)
                if param_match:
                    params.append(" ".join(param_match.group("type").split()))
            param_lists.append(params)
        return param_lists, import_map

    @staticmethod
    def _qualify_source_type_expr(type_expr: str, import_map: dict[str, str]) -> str:
        primitives = {"boolean", "byte", "short", "int", "long", "float", "double", "char", "void"}

        def _replace(match: re.Match[str]) -> str:
            token = match.group(0)
            if token in primitives or token in {"extends", "super"}:
                return token
            if len(token) == 1 and token.isupper():
                return token
            return import_map.get(token, token)

        return re.sub(r"\b[A-Z][A-Za-z0-9_$]*\b", _replace, str(type_expr or ""))

    @classmethod
    def _rewrite_collections_empty_args_for_source_constructors(
        cls,
        code: str,
        *,
        project_root: Path,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Add explicit generic witnesses to Collections.empty* constructor args.

        This helps older javac/source-level projects where method inference
        chooses ``Object`` for ``Collections.emptyList()``/``emptyMap()`` in
        generated constructor calls.  The expected generic type is taken only
        from source-visible constructor signatures.
        """
        text = str(code or "")
        if "Collections.empty" not in text or "new " not in text:
            return text, []
        index = symbol_index if symbol_index is not None else cls._build_symbol_index(project_root)
        package_match = cls._RE_PACKAGE_DECL.search(text)
        current_package = package_match.group(1) if package_match else ""
        changes: list[str] = []
        ctor_re = re.compile(
            r"\bnew\s+(?P<owner>(?:[A-Za-z_$][\w$]*\.)*[A-Za-z_$][\w$]*)\s*\((?P<args>[^;\n()]*(?:Collections\.empty(?:List|Map)\(\)[^;\n()]*)*)\)"
        )

        def _replacement(match: re.Match[str]) -> str:
            owner_expr = match.group("owner")
            owner_simple = owner_expr.rsplit(".", 1)[-1]
            candidates = [owner_expr] if "." in owner_expr else list(index.get(owner_simple) or [])
            fqn = cls._resolve_best_fqn(
                owner_simple,
                candidates=candidates,
                current_package=current_package,
                source_package=current_package,
            )
            if not fqn:
                return match.group(0)
            param_lists, import_map = cls._source_visible_constructor_param_lists(project_root, fqn)
            args = cls._split_top_level_args(match.group("args"))
            param_list = next((params for params in param_lists if len(params) == len(args)), None)
            if not param_list:
                return match.group(0)
            changed = False
            new_args = list(args)
            for idx, (arg, param_type) in enumerate(zip(args, param_list)):
                stripped = arg.strip()
                if stripped == "Collections.emptyList()" and re.search(r"\bList\s*<(.+)>", param_type):
                    inner = re.search(r"\bList\s*<(.+)>", param_type)
                    assert inner is not None
                    witness = cls._qualify_source_type_expr(inner.group(1).strip(), import_map)
                    new_args[idx] = f"Collections.<{witness}>emptyList()"
                    changed = True
                elif stripped == "Collections.emptyMap()" and re.search(r"\bMap\s*<(.+)>", param_type):
                    inner = re.search(r"\bMap\s*<(.+)>", param_type)
                    assert inner is not None
                    parts = cls._split_top_level_args(inner.group(1).strip())
                    if len(parts) == 2:
                        left = cls._qualify_source_type_expr(parts[0], import_map)
                        right = cls._qualify_source_type_expr(parts[1], import_map)
                        new_args[idx] = f"Collections.<{left}, {right}>emptyMap()"
                        changed = True
            if not changed:
                return match.group(0)
            changes.append(f"{owner_simple}: explicit-collections-empty-generics")
            return f"new {owner_expr}({', '.join(new_args)})"

        rewritten = ctor_re.sub(_replacement, text)
        return rewritten, changes

    @staticmethod
    def _wildcard_cast_for_declared_type(type_expr: str) -> str:
        raw = str(type_expr or "").strip().split("<", 1)[0].strip()
        if not raw:
            return "Object"
        if raw.endswith("Map") or raw.endswith("Map.Entry") or raw.endswith("Entry"):
            return f"{raw}<?, ?>"
        if "<" in str(type_expr or ""):
            return f"{raw}<?>"
        return raw

    @classmethod
    def _rewrite_wildcard_construct_result_assignments(cls, code: str) -> tuple[str, list[str]]:
        """Make capture-of-wildcard constructor results compile without losing oracles."""
        text = str(code or "")
        if "ObjectConstructor<?> " not in text or ".construct()" not in text:
            return text, []
        constructor_vars = {
            match.group(1)
            for match in re.finditer(r"\bObjectConstructor\s*<\s*\?\s*>\s+([A-Za-z_$][\w$]*)\s*=", text)
        }
        if not constructor_vars:
            return text, []
        changes: list[str] = []
        cast_by_var: dict[str, str] = {}

        def _assignment_replacement(match: re.Match[str]) -> str:
            declared_type = " ".join(match.group("type").split())
            var_name = match.group("var")
            ctor_var = match.group("ctor")
            if ctor_var not in constructor_vars or declared_type == "Object":
                return match.group(0)
            cast_by_var[var_name] = cls._wildcard_cast_for_declared_type(declared_type)
            changes.append(f"{var_name}: wildcard-construct-result -> Object")
            return f"{match.group('indent')}Object {var_name} = {ctor_var}.construct();"

        assignment_re = re.compile(
            r"(?m)^(?P<indent>\s*)(?:final\s+)?(?P<type>(?:[a-z_][\w$]*\.)*[A-Z][A-Za-z0-9_$.]*(?:\s*<[^;\n=]+>)?)\s+"
            r"(?P<var>[A-Za-z_$][\w$]*)\s*=\s*(?P<ctor>[A-Za-z_$][\w$]*)\.construct\s*\(\s*\)\s*;"
        )
        rewritten = assignment_re.sub(_assignment_replacement, text)
        for var_name, cast_type in cast_by_var.items():
            rewritten = re.sub(
                rf"\b{re.escape(var_name)}\.(?P<method>(?:isEmpty|size|containsKey|contains|entrySet|keySet|values)\s*\()",
                rf"(({cast_type}) {var_name}).\g<method>",
                rewritten,
            )
        return rewritten, changes

    @staticmethod
    def _repair_json_common(text: str) -> str:
        """Apply minimal, safe structural repairs to LLM-produced JSON.

        Handles patterns that appear when reasoning models produce JSON5-like
        output or include markdown-style formatting:
          - Single-line // comments (JSON5 syntax, not standard JSON)
          - Trailing commas before ] or } (JSON5)
          - Null-byte artifacts
        Does NOT attempt to fix unclosed strings or missing brackets.
        """
        # Remove // comments (only outside string literals — simple heuristic:
        # skip if the comment character is preceded by an even number of unescaped quotes)
        lines = text.splitlines()
        cleaned: list[str] = []
        for line in lines:
            # Strip // comment that is not inside a string (heuristic: odd quote count before //)
            comment_idx = line.find("//")
            if comment_idx >= 0:
                before = line[:comment_idx]
                # Count unescaped double-quotes before the comment marker
                q_count = before.count('"') - before.count('\\"')
                if q_count % 2 == 0:
                    line = line[:comment_idx].rstrip()
            cleaned.append(line)
        text = "\n".join(cleaned)
        # Remove trailing commas before } or ]
        text = re.sub(r",\s*([}\]])", r"\1", text)
        # Remove null bytes and other non-printable non-whitespace control chars
        text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", text)
        return text

    @staticmethod
    def _try_recover_truncated_new_tests(text: str, exc: "json.JSONDecodeError") -> "dict | None":
        """Salvage complete new_tests entries from a truncated JSON response.

        When a reasoning model (Qwen3, DeepSeek-R1) exhausts its output-token budget
        mid-JSON, the payload ends abruptly. This method finds every syntactically
        complete {…} entry within the new_tests array and returns a repaired dict.
        Returns None if no complete entry can be found or the error is not truncation.
        """
        truncation_signals = (
            "unterminated string", "unexpected end", "end of file", "end of data",
            "expecting ',' delimiter", "expecting property name", "expecting value",
        )
        if not any(sig in str(exc).lower() for sig in truncation_signals):
            return None

        def _decode_string_array_at(open_bracket: int) -> list[str]:
            values: list[str] = []
            decoder = json.JSONDecoder(strict=False)
            pos = open_bracket + 1
            n = len(text)
            while pos < n:
                while pos < n and text[pos] in " \t\n\r,":
                    pos += 1
                if pos >= n or text[pos] == "]":
                    break
                if text[pos] != '"':
                    break
                try:
                    value, end = decoder.raw_decode(text, pos)
                except json.JSONDecodeError:
                    break
                if isinstance(value, str):
                    values.append(value)
                pos = end
            return values

        def _decode_string_field(fragment: str, key: str) -> str:
            match = re.search(rf'"{re.escape(key)}"\s*:\s*"', fragment)
            if not match:
                return ""
            decoder = json.JSONDecoder(strict=False)
            try:
                value, _ = decoder.raw_decode(fragment, match.end() - 1)
            except json.JSONDecodeError:
                return ""
            return value if isinstance(value, str) else ""

        def _recover_incomplete_entry_from(pos: int) -> dict | None:
            fragment = text[pos:]
            lines_match = re.search(r'"test_code_lines"\s*:\s*\[', fragment)
            if not lines_match:
                return None
            lines_open = pos + lines_match.end() - 1
            lines = _decode_string_array_at(lines_open)
            if not lines:
                return None
            raw_patch = "\n".join(lines).strip()
            if not TATGEngineAdapter._contains_test_annotation(raw_patch):
                return None
            recovered_patch = TATGEngineAdapter._recover_balanced_test_patch(raw_patch)
            if not recovered_patch:
                return None
            recovered_lines = recovered_patch.splitlines()
            prefix = text[pos : lines_open]
            entry: dict[str, object] = {
                "test_code_lines": recovered_lines,
                "new_imports_lines": [],
            }
            for key in (
                "overload_id",
                "coverage_obligation_id",
                "objective_id",
                "candidate_role",
                "role",
                "test_behavior",
                "input_family",
                "oracle_type",
                "repair_axis",
            ):
                value = _decode_string_field(prefix, key)
                if value:
                    entry[key] = value
            test_name = _decode_string_field(prefix, "test_name")
            if not test_name:
                test_name = TATGEngineAdapter._extract_method_name(recovered_patch) or ""
            if test_name:
                entry["test_name"] = test_name
            imports_match = re.search(r'"new_imports_lines"\s*:\s*\[', fragment)
            if imports_match:
                imports_open = pos + imports_match.end() - 1
                imports = _decode_string_array_at(imports_open)
                if imports:
                    entry["new_imports_lines"] = imports
            return entry

        match = re.search(r'"new_tests"\s*:\s*\[', text)
        if not match:
            return None
        array_start = match.end()

        entries: list[dict] = []
        pos = array_start
        n = len(text)

        while pos < n:
            # Skip whitespace and commas between entries
            while pos < n and text[pos] in " \t\n\r,":
                pos += 1
            if pos >= n or text[pos] != "{":
                break

            # Walk forward tracking brace depth, respecting string literals
            depth = 0
            in_string = False
            escape_next = False
            end_pos = -1

            for i in range(pos, n):
                c = text[i]
                if escape_next:
                    escape_next = False
                    continue
                if c == "\\" and in_string:
                    escape_next = True
                    continue
                if c == '"':
                    in_string = not in_string
                    continue
                if in_string:
                    continue
                if c == "{":
                    depth += 1
                elif c == "}":
                    depth -= 1
                    if depth == 0:
                        end_pos = i + 1
                        break

            if end_pos == -1:
                # Incomplete object — stop here
                recovered_entry = _recover_incomplete_entry_from(pos)
                if recovered_entry:
                    entries.append(recovered_entry)
                    pos = n
                break

            fragment = text[pos:end_pos]
            try:
                entry = json.loads(fragment, strict=False)
                if isinstance(entry, dict) and (
                    "test_code_lines" in entry or "test_code" in entry
                ):
                    entries.append(entry)
            except json.JSONDecodeError:
                break
            pos = end_pos

        # If the response ended inside the final object but after at least a
        # complete test_code/test_code_lines field, try a conservative close.
        # This recovers common stream-timeout shapes such as:
        # {"new_tests":[{"test_code":"..."}   <timeout>
        if pos < n:
            while pos < n and text[pos] in " \t\n\r,":
                pos += 1
            if pos < n and text[pos] == "{":
                tail = text[pos:]
                for suffix in ("}", "}]}", "}]}"):
                    candidate = tail.rstrip().rstrip(",") + suffix
                    try:
                        entry = json.loads(candidate, strict=False)
                    except json.JSONDecodeError:
                        continue
                    if isinstance(entry, dict) and (
                        "test_code_lines" in entry or "test_code" in entry
                    ):
                        entries.append(entry)
                        break
                else:
                    recovered_entry = _recover_incomplete_entry_from(pos)
                    if recovered_entry:
                        entries.append(recovered_entry)

        if not entries:
            return None
        return {"new_tests": entries}

    @classmethod
    def _extract_patch_from_json_output(
        cls,
        raw_output: str,
        max_tests: int | None = None,
        target_call_names: list[str] | None = None,
        target_reflection_names: list[str] | None = None,
        require_observable_check: bool = False,
        require_lazy_terminal_execution: bool = False,
        lazy_terminal_markers: list[str] | None = None,
        required_call_order: list[tuple[str, str]] | None = None,
        overload_contract_ids: set[str] | None = None,
        target_overload_ids: set[str] | None = None,
        required_obligation_ids: set[str] | None = None,
        required_mutation_objective_ids: set[str] | None = None,
        mutation_reachability_probe_objective_ids: set[str] | None = None,
        required_mutation_direct_entry_methods: (
            dict[str, set[str]] | None
        ) = None,
        required_semantic_replay_entry_methods: (
            dict[str, set[str]] | None
        ) = None,
        mutation_pre_act_forbidden_methods: (
            dict[str, set[str]] | None
        ) = None,
        required_mutation_survived_setup_prefixes: (
            dict[str, list[str]] | None
        ) = None,
        return_metadata: bool = False,
    ) -> str | tuple[str, dict[str, Any]]:
        """Extract Java patch text from a JSON-only LLM response.

                Expected schema:
        {
          "new_tests": [
            {
              "test_behavior": "...",
              "test_name": "...",
                            "test_code_lines": ["@Test", "public void testX() {", "  ...", "}"],
                            "new_imports_lines": ["import ...;"]
            }
          ]
        }
        """
        payload_text = cls._strip_code_fences(raw_output).strip()
        if not payload_text:
            raise ValueError("Empty JSON response")

        semantic_replay_entry_methods = {
            str(objective_id).strip().upper(): {
                str(method).strip()
                for method in methods
                if str(method).strip()
            }
            for objective_id, methods in (
                required_semantic_replay_entry_methods or {}
            ).items()
            if str(objective_id).strip()
        }

        def _satisfies_direct_target_call(test_code: str) -> bool:
            if target_call_names and cls._test_code_calls_any_method(test_code, target_call_names):
                return True
            if target_reflection_names and cls._test_code_reflectively_invokes_any_method(test_code, target_reflection_names):
                return True
            return not target_call_names and not target_reflection_names

        def _satisfies_semantic_replay_entry(
            test_code: str,
            objective_id: str,
        ) -> bool:
            methods = semantic_replay_entry_methods.get(
                str(objective_id or "").strip().upper(),
                set(),
            )
            return bool(
                methods
                and cls._test_code_calls_any_method(
                    test_code,
                    sorted(methods),
                )
            )

        def _satisfies_target_call(
            test_code: str,
            objective_id: str = "",
        ) -> bool:
            return bool(
                _satisfies_direct_target_call(test_code)
                or _satisfies_semantic_replay_entry(
                    test_code,
                    objective_id,
                )
            )

        raw_java_patch = cls._recover_balanced_test_patch(payload_text)
        if raw_java_patch and not payload_text.lstrip().startswith(("{", "[")):
            if required_mutation_objective_ids:
                raise cls.PatchExtractionError(
                    "Mutation-extra raw Java patch cannot preserve required M-id bindings",
                    skip_counts={"mutation_objective_id_missing": 1},
                )
            if target_call_names or target_reflection_names:
                methods = [
                    method
                    for method in cls._categorize_methods(raw_java_patch)[1]
                    if method.strip()
                ]
                if not any(_satisfies_target_call(method) for method in methods):
                    raise cls.PatchExtractionError(
                        "Raw Java patch response contained @Test methods, but none called the required target",
                        skip_counts={"without_target_call": len(methods) or 1},
                    )
            if require_observable_check:
                methods = [
                    method
                    for method in cls._categorize_methods(raw_java_patch)[1]
                    if method.strip()
                ]
                if not any(cls._test_code_has_observable_check(method) for method in methods):
                    raise cls.PatchExtractionError(
                        "Raw Java patch response contained @Test methods, but none had an observable assertion",
                        skip_counts={"without_observable_check": len(methods) or 1},
                    )
            metadata = cls._metadata_for_salvaged_patch(
                raw_java_patch,
                required_obligation_ids=required_obligation_ids,
            )
            metadata["salvaged_raw_java_patch_direct"] = True
            return (raw_java_patch, metadata) if return_metadata else raw_java_patch

        truncated_json_salvaged = False
        try:
            # strict=False: accept literal control chars (newlines, tabs) in string values.
            # Real LLMs frequently return {"test_code": "@Test\nvoid foo() {}"} with
            # unescaped newlines, which strict=True (the default) rejects.
            payload = json.loads(payload_text, strict=False)
        except json.JSONDecodeError as exc:
            # Pass 2: apply light structural repairs common in LLM output, then retry.
            repaired = cls._repair_json_common(payload_text)
            try:
                payload = json.loads(repaired, strict=False)
            except json.JSONDecodeError:
                # Pass 3: try to salvage complete entries from a truncated response.
                payload = cls._try_recover_truncated_new_tests(payload_text, exc)
                if payload is None:
                    raise ValueError(f"Invalid JSON response: {exc}") from exc
                truncated_json_salvaged = True

        if not isinstance(payload, dict):
            raise ValueError("JSON response must be an object")

        new_tests = payload.get("new_tests")
        if not isinstance(new_tests, list) or not new_tests:
            raise ValueError("JSON response must contain non-empty new_tests array")

        import_lines: list[str] = []
        seen_imports: set[str] = set()
        method_blocks: list[str] = []
        skipped_without_target_call = 0
        skipped_without_observable_check = 0
        skipped_without_lazy_terminal_execution = 0
        skipped_without_required_order = 0
        skipped_with_pre_target_setup_assertion = 0
        skipped_without_overload_id = 0
        skipped_with_unknown_overload_id = 0
        skipped_with_sibling_overload_id = 0
        skipped_without_obligation_id = 0
        skipped_with_unknown_obligation_id = 0
        skipped_with_conflicting_obligation_id = 0
        skipped_mutation_candidate_missing_target_call = 0
        skipped_mutation_objective_id_missing = 0
        skipped_mutation_objective_id_unknown = 0
        skipped_mutation_objective_id_conflicting = 0
        skipped_mutation_required_direct_entry_missing = 0
        skipped_mutation_survived_setup_not_preserved = 0
        skipped_with_weak_mutation_oracle = 0
        lazy_terminal_autowrapped_count = 0
        schema_sentinel_lines_removed = 0
        schema_metadata_lines_removed = 0
        multi_test_item_count = 0
        multi_test_methods_dropped = 0
        test_overload_map: dict[str, str] = {}
        test_behavior_map: dict[str, str] = {}
        test_objective_map: dict[str, str] = {}
        test_candidate_role_map: dict[str, str] = {}
        test_baseline_skeleton_map: dict[str, str] = {}
        test_skeleton_fact_ids_map: dict[str, list[str]] = {}
        test_obligation_map: dict[str, str] = {}
        test_inferred_obligation_map: dict[str, bool] = {}
        test_unbound_obligation_methods: list[str] = []
        test_input_family_map: dict[str, str] = {}
        test_oracle_type_map: dict[str, str] = {}
        test_repair_axis_map: dict[str, str] = {}
        test_semantic_replay_entry_map: dict[str, dict[str, str]] = {}
        mutation_initial_state_prepatches: list[dict[str, Any]] = []
        rejected_entries: list[dict[str, Any]] = []
        required_obligation_ids = {str(item) for item in (required_obligation_ids or set()) if str(item)}
        required_mutation_objective_ids = {
            str(item).strip().upper()
            for item in (required_mutation_objective_ids or set())
            if str(item).strip()
        }
        mutation_reachability_probe_objective_ids = {
            str(item).strip().upper()
            for item in (
                mutation_reachability_probe_objective_ids or set()
            )
            if str(item).strip().upper().startswith("M")
        }
        required_mutation_direct_entry_methods = {
            str(objective_id).strip().upper(): {
                str(method).strip()
                for method in methods
                if str(method).strip()
            }
            for objective_id, methods in (
                required_mutation_direct_entry_methods or {}
            ).items()
            if str(objective_id).strip()
        }
        required_mutation_survived_setup_prefixes = {
            str(objective_id).strip().upper(): [
                str(prefix).strip()
                for prefix in list(prefixes or [])
                if str(prefix).strip()
            ]
            for objective_id, prefixes in (
                required_mutation_survived_setup_prefixes or {}
            ).items()
            if str(objective_id).strip()
        }
        mutation_pre_act_forbidden_methods = {
            str(objective_id).strip().upper(): {
                str(method).strip()
                for method in methods
                if str(method).strip()
            }
            for objective_id, methods in (
                mutation_pre_act_forbidden_methods or {}
            ).items()
            if str(objective_id).strip()
        }
        target_overload_id_list = sorted(str(item) for item in (target_overload_ids or set()) if str(item))
        allowed_overload_ids = {
            str(item).strip()
            for item in set(overload_contract_ids or set()).union(target_overload_ids or set())
            if str(item).strip()
        }

        def _observed_call_names(code: str) -> list[str]:
            calls: list[str] = []
            for match in re.finditer(r"(?:\.|\b)([A-Za-z_$][\w$]*)\s*\(", code or ""):
                name = match.group(1)
                if name in {"if", "for", "while", "switch", "catch", "assert", "new", "return", "throw"}:
                    continue
                if name not in calls:
                    calls.append(name)
                if len(calls) >= 16:
                    break
            return calls

        def _record_rejected(reason: str, code: str, item: dict[str, Any], method_name: str = "") -> None:
            if len(rejected_entries) >= 12:
                return
            excerpt = "\n".join((code or "").strip().splitlines()[:16]).strip()
            rejected_entries.append({
                "reason": reason,
                "test_name": str(item.get("test_name") or "").strip(),
                "method": method_name,
                "calls": _observed_call_names(code),
                "excerpt": excerpt[:1200],
                "candidate_role": str(item.get("candidate_role") or item.get("role") or "").strip(),
                "objective_id": str(item.get("objective_id") or item.get("coverage_obligation_id") or "").strip(),
                "overload_id": str(item.get("overload_id") or "").strip(),
            })

        def _add_imports(imports_blob: str) -> None:
            for line in imports_blob.splitlines():
                stripped = line.strip()
                if not stripped:
                    continue
                if not cls._RE_IMPORT_DECL.match(stripped):
                    continue
                if stripped in seen_imports:
                    continue
                seen_imports.add(stripped)
                import_lines.append(stripped)

        def _normalize_test_code(test_code: str) -> str:
            nonlocal schema_sentinel_lines_removed
            nonlocal schema_metadata_lines_removed
            code = cls._strip_code_fences(test_code).strip()
            if not code:
                return ""
            class_match = cls._outer_test_class_wrapper_match(code)
            if class_match:
                open_brace = code.find("{", class_match.start())
                close_brace = cls._find_matching_brace(code, open_brace)
                if close_brace != -1:
                    code = code[open_brace + 1 : close_brace - 1].strip()
                else:
                    code = code[class_match.end() :].strip()
            schema_metadata_keys = {
                "test_behavior",
                "test_name",
                "input_family",
                "oracle_type",
                "repair_axis",
                "objective_id",
                "coverage_obligation_id",
                "candidate_role",
                "role",
                "baseline_skeleton_id",
                "skeleton_id",
                "skeleton_fact_ids",
                "overload_id",
            }
            lines: list[str] = []
            drop_next_schema_value = False
            for line in code.splitlines():
                stripped = line.strip()
                if cls._RE_PACKAGE_DECL.match(stripped) or cls._RE_IMPORT_DECL.match(stripped):
                    continue
                unquoted = stripped.strip('"\'').rstrip(":").strip()
                if drop_next_schema_value and stripped:
                    drop_next_schema_value = False
                    # A structured-output backend may flatten a sibling JSON
                    # property into two test_code_lines entries: first the bare
                    # schema key, then its value.  The key is conclusive evidence
                    # that the following non-Java line is metadata.  Never drop
                    # a real annotation/method declaration even after a corrupt
                    # key so a valid @Test remains salvageable.
                    if not (
                        stripped.startswith("@")
                        or re.search(r"\b(?:public|protected|private)\s+void\s+", stripped)
                        or stripped in {"{", "}"}
                    ):
                        schema_metadata_lines_removed += 1
                        continue
                if unquoted in schema_metadata_keys:
                    schema_metadata_lines_removed += 1
                    drop_next_schema_value = True
                    continue
                # Truncated JSON salvage can occasionally copy a neighboring
                # schema key into test_code_lines. A bare schema key is never
                # executable Java; remove only the exact invalid sentinel so
                # ordinary identifiers and statements remain untouched.
                if stripped.strip('"') in {"new_imports_lines", "test_code_lines"}:
                    schema_sentinel_lines_removed += 1
                    continue
                # Some OpenAI-compatible models copy sibling JSON metadata
                # fields into ``test_code_lines`` after a complete @Test
                # method. Bare ``key=value`` rows without a Java semicolon
                # cannot be executable source. Remove only the exact response
                # schema keys; retain ordinary Java assignments, including
                # similarly named typed locals and semicolon-terminated
                # statements.
                if (
                    not stripped.endswith(";")
                    and re.fullmatch(
                        r"(?:test_behavior|test_name|input_family|"
                        r"oracle_type|repair_axis|objective_id|"
                        r"coverage_obligation_id|candidate_role|role|"
                        r"baseline_skeleton_id|skeleton_id|"
                        r"skeleton_fact_ids|overload_id)\s*=\s*.+",
                        stripped,
                    )
                ):
                    schema_metadata_lines_removed += 1
                    continue
                lines.append(line)
            return "\n".join(lines).strip()

        required_obligation_id_list = sorted(required_obligation_ids)
        for item_index, item in enumerate(new_tests):
            if not isinstance(item, dict):
                continue

            raw_imports = item.get("new_imports_lines")
            if isinstance(raw_imports, list):
                _add_imports("\n".join(str(line) for line in raw_imports))
            else:
                _add_imports(str(item.get("new_imports_code") or ""))

            raw_lines = item.get("test_code_lines")
            if raw_lines in (None, "", []):
                for alt_key in (
                    "code_lines",
                    "java_code_lines",
                    "test_body_lines",
                    "body_lines",
                    "statements",
                    "statement_lines",
                ):
                    alt_lines = item.get(alt_key)
                    if alt_lines not in (None, "", []):
                        raw_lines = alt_lines
                        break
            if isinstance(raw_lines, list) and raw_lines:
                raw_test_code = "\n".join(str(line) for line in raw_lines).strip()
            elif isinstance(raw_lines, str) and raw_lines.strip():
                raw_test_code = cls._strip_code_fences(raw_lines).strip()
            else:
                raw_test_code = ""
                for alt_key in (
                    "test_code",
                    "code",
                    "java_code",
                    "test_body",
                    "body",
                    "method_body",
                ):
                    alt_code = str(item.get(alt_key) or "").strip()
                    if alt_code:
                        raw_test_code = cls._strip_code_fences(alt_code).strip()
                        break
            if not raw_test_code:
                arranged_parts: list[str] = []
                for alt_key in (
                    "arrange",
                    "arrange_code",
                    "setup",
                    "setup_code",
                    "act",
                    "act_code",
                    "assert",
                    "assert_code",
                    "assertions",
                    "oracle",
                    "oracle_code",
                ):
                    part = item.get(alt_key)
                    if isinstance(part, list):
                        arranged_parts.extend(str(line) for line in part if str(line).strip())
                    elif isinstance(part, str) and part.strip():
                        arranged_parts.extend(part.strip().splitlines())
                if arranged_parts:
                    test_name = str(item.get("test_name") or f"testGeneratedPatch{item_index + 1}").strip()
                    if not re.match(r"[A-Za-z_$][\w$]*\Z", test_name):
                        test_name = f"testGeneratedPatch{item_index + 1}"
                    raw_test_code = "\n".join(
                        ["@Test", f"public void {test_name}() throws Exception {{", *("    " + line.strip() for line in arranged_parts), "}"]
                    )
            _add_imports(raw_test_code)
            if raw_test_code and not cls._contains_test_annotation(raw_test_code) and not re.search(
                r"\b(?:public\s+|protected\s+|private\s+)?(?:static\s+)?(?:void|[\w<>\[\].?,\s]+)\s+[A-Za-z_$][\w$]*\s*\(",
                raw_test_code,
            ):
                test_name = str(item.get("test_name") or f"testGeneratedPatch{item_index + 1}").strip()
                if not re.match(r"[A-Za-z_$][\w$]*\Z", test_name):
                    test_name = f"testGeneratedPatch{item_index + 1}"
                body_lines = []
                for line in raw_test_code.splitlines():
                    stripped = line.strip()
                    if not stripped:
                        continue
                    if cls._RE_PACKAGE_DECL.match(stripped) or cls._RE_IMPORT_DECL.match(stripped):
                        continue
                    body_lines.append("    " + stripped)
                if body_lines:
                    raw_test_code = "\n".join(
                        ["@Test", f"public void {test_name}() throws Exception {{", *body_lines, "}"]
                    )
            test_code = _normalize_test_code(raw_test_code)
            if test_code:
                item_test_methods = cls._categorize_methods(test_code)[1]
                if len(item_test_methods) > 1:
                    # The response contract is one @Test per new_tests item.
                    # Keeping a packed multi-method item defeats the response
                    # budget and duplicates any leaked sibling metadata into
                    # every streaming candidate.  Preserve the first complete
                    # method and let the next generation/feedback round request
                    # the remaining scenarios explicitly.
                    multi_test_item_count += 1
                    multi_test_methods_dropped += len(item_test_methods) - 1
                    test_code = item_test_methods[0].strip()
                method_name = cls._extract_method_name(test_code)
                overload_id = str(item.get("overload_id") or "").strip()
                overload_id = cls._normalize_llm_overload_id(overload_id, allowed_overload_ids)
                if target_overload_id_list and not overload_id:
                    if len(target_overload_id_list) == 1:
                        overload_id = target_overload_id_list[0]
                if overload_contract_ids:
                    if not overload_id:
                        skipped_without_overload_id += 1
                        _record_rejected("without_overload_id", test_code, item, method_name)
                        continue
                    if overload_id not in overload_contract_ids:
                        skipped_with_unknown_overload_id += 1
                        _record_rejected("unknown_overload_id", test_code, item, method_name)
                        continue
                if target_overload_ids and overload_id not in target_overload_ids:
                    skipped_with_sibling_overload_id += 1
                    _record_rejected("sibling_overload_id", test_code, item, method_name)
                    continue
                raw_objective_id = str(
                    item.get("objective_id") or ""
                ).strip()
                objective_key = raw_objective_id.upper()
                forbidden_pre_act = mutation_pre_act_forbidden_methods.get(
                    objective_key,
                    set(),
                )
                if forbidden_pre_act:
                    rewritten_lines = test_code.splitlines()
                    target_line_index = next(
                        (
                            index
                            for index, line in enumerate(rewritten_lines)
                            if any(
                                re.search(
                                    rf"(?:\.|\b){re.escape(call_name)}\s*\(",
                                    line,
                                )
                                for call_name in (target_call_names or [])
                            )
                            and not re.search(
                                r"\b(?:public|protected|private)\b.*\([^;]*\)"
                                r"\s*(?:throws\b[^\{]+)?\{?\s*$",
                                line,
                            )
                        ),
                        -1,
                    )
                    removed_methods: list[str] = []
                    if target_line_index >= 0:
                        for index in range(target_line_index):
                            line = rewritten_lines[index]
                            for forbidden_method in sorted(forbidden_pre_act):
                                if re.fullmatch(
                                    rf"\s*[A-Za-z_$][\w$]*"
                                    rf"(?:\s*\.\s*[A-Za-z_$][\w$]*)*"
                                    rf"\s*\.\s*{re.escape(forbidden_method)}"
                                    rf"\s*\([^;]*\)\s*;\s*(?://.*)?",
                                    line,
                                ):
                                    rewritten_lines[index] = ""
                                    removed_methods.append(forbidden_method)
                                    break
                    if removed_methods:
                        test_code = "\n".join(rewritten_lines)
                        mutation_initial_state_prepatches.append({
                            "test_method": (
                                cls._extract_method_name(test_code)
                                or "<unknown>"
                            ),
                            "objective_id": objective_key,
                            "removed_pre_act_methods": sorted(
                                set(removed_methods)
                            ),
                            "proof": "source_proven_initial_state",
                        })
                direct_target_call_satisfied = (
                    _satisfies_direct_target_call(test_code)
                )
                semantic_replay_entry_satisfied = (
                    _satisfies_semantic_replay_entry(
                        test_code,
                        raw_objective_id,
                    )
                )
                if (
                    target_call_names or target_reflection_names
                ) and not (
                    direct_target_call_satisfied
                    or semantic_replay_entry_satisfied
                ):
                    candidate_role = cls._normalize_search_metadata(
                        str(item.get("candidate_role") or item.get("role") or ""),
                        prefix="role",
                    )
                    if candidate_role.removeprefix("role:") in {"mutation_reachability", "mutation_oracle"}:
                        skipped_mutation_candidate_missing_target_call += 1
                        _record_rejected("mutation_candidate_missing_target_call", test_code, item, method_name)
                        continue
                    skipped_without_target_call += 1
                    _record_rejected("without_target_call", test_code, item, method_name)
                    continue
                if method_name and semantic_replay_entry_satisfied and not (
                    direct_target_call_satisfied
                ):
                    objective_key = raw_objective_id.upper()
                    test_semantic_replay_entry_map[method_name] = {
                        "objective_id": objective_key,
                        "entry_method": next(
                            (
                                entry_method
                                for entry_method in sorted(
                                    semantic_replay_entry_methods.get(
                                        objective_key,
                                        set(),
                                    )
                                )
                                if cls._test_code_calls_any_method(
                                    test_code,
                                    [entry_method],
                                )
                            ),
                            "",
                        ),
                    }
                if (
                    require_lazy_terminal_execution
                    and not cls._test_code_has_lazy_terminal_execution(
                        test_code,
                        lazy_terminal_markers or [],
                    )
                ):
                    rewritten_test_code, terminal_added = cls._rewrite_bare_lazy_target_call_to_terminal_assertion(
                        test_code,
                        target_call_names or [],
                        lazy_terminal_markers or [],
                    )
                    if terminal_added and cls._test_code_has_lazy_terminal_execution(
                        rewritten_test_code,
                        lazy_terminal_markers or [],
                    ):
                        test_code = rewritten_test_code
                        lazy_terminal_autowrapped_count += 1
                    else:
                        skipped_without_lazy_terminal_execution += 1
                        _record_rejected("without_lazy_terminal_execution", test_code, item, method_name)
                        continue
                if required_call_order and not cls._test_code_satisfies_call_order(test_code, required_call_order):
                    skipped_without_required_order += 1
                    _record_rejected("without_required_order", test_code, item, method_name)
                    continue
                if required_call_order:
                    test_code = cls._strip_pre_target_setup_assertions(test_code, required_call_order)
                if required_call_order and cls._test_code_has_pre_target_setup_assertion(test_code, required_call_order):
                    skipped_with_pre_target_setup_assertion += 1
                    _record_rejected("with_pre_target_setup_assertion", test_code, item, method_name)
                    continue
                if (
                    require_observable_check
                    and not cls._test_code_has_observable_check(test_code)
                ):
                    probe_role = cls._normalize_search_metadata(
                        str(
                            item.get("candidate_role")
                            or item.get("role")
                            or ""
                        ),
                        prefix="role",
                    ).removeprefix("role:")
                    probe_objective_id = str(
                        item.get("objective_id") or ""
                    ).strip().upper()
                    allow_reachability_probe = bool(
                        probe_role == "mutation_reachability"
                        and probe_objective_id
                        in mutation_reachability_probe_objective_ids
                        and probe_objective_id
                        in required_mutation_objective_ids
                    )
                    if not allow_reachability_probe:
                        skipped_without_observable_check += 1
                        _record_rejected(
                            "without_observable_check",
                            test_code,
                            item,
                            method_name,
                        )
                        continue
                obligation_id = ""
                if required_obligation_ids:
                    obligation_sources = [
                        str(item.get("coverage_obligation_id") or ""),
                        str(item.get("test_name") or ""),
                        str(item.get("test_behavior") or ""),
                        method_name or "",
                        test_code,
                    ]
                    obligation_ids = [
                        found
                        for found in (cls._extract_coverage_obligation_id(source) for source in obligation_sources)
                        if found
                    ]
                    unique_obligation_ids = set(obligation_ids)
                    if len(unique_obligation_ids) > 1:
                        skipped_with_conflicting_obligation_id += 1
                        _record_rejected("conflicting_obligation_id", test_code, item, method_name)
                        continue
                    obligation_id = obligation_ids[0] if obligation_ids else ""
                inferred_obligation_id = False
                if required_obligation_ids:
                    allow_implicit_single_oid = os.getenv(
                        "TATG_ALLOW_IMPLICIT_SINGLE_OBLIGATION_ID",
                        "0",
                    ).lower() in {"1", "true", "yes", "on"}
                    if not obligation_id and len(required_obligation_id_list) == 1 and allow_implicit_single_oid:
                        obligation_id = required_obligation_id_list[0]
                        inferred_obligation_id = True
                    if not obligation_id:
                        # O-id binding is planning metadata, not executable Java
                        # semantics. The candidate has already passed target-call,
                        # call-order, and oracle gates, so keep it for sandbox
                        # measurement without crediting any obligation.
                        if method_name:
                            test_unbound_obligation_methods.append(method_name)
                    if obligation_id not in required_obligation_ids:
                        if not obligation_id:
                            pass
                        else:
                            skipped_with_unknown_obligation_id += 1
                            _record_rejected("unknown_obligation_id", test_code, item, method_name)
                            continue
                    if obligation_id and method_name and not cls._extract_coverage_obligation_id(method_name):
                        renamed_method_name = f"{method_name}_{obligation_id}"
                        test_code = cls._rename_method_name(test_code, method_name, renamed_method_name)
                        method_name = renamed_method_name
                objective_id = str(item.get("objective_id") or "").strip()
                if required_mutation_objective_ids:
                    if re.fullmatch(r"M\d{1,4}", objective_id, re.IGNORECASE):
                        objective_id = objective_id.upper()
                    mutation_id_sources = [
                        objective_id,
                        str(item.get("test_name") or ""),
                        str(item.get("test_behavior") or ""),
                        method_name or "",
                        test_code,
                    ]
                    observed_mutation_ids = {
                        match.group(0).upper()
                        for source in mutation_id_sources
                        for match in re.finditer(r"\bM\d{1,4}\b", source, re.IGNORECASE)
                    }
                    matching_mutation_ids = (
                        observed_mutation_ids & required_mutation_objective_ids
                    )
                    if len(matching_mutation_ids) > 1:
                        skipped_mutation_objective_id_conflicting += 1
                        _record_rejected(
                            "mutation_objective_id_conflicting",
                            test_code,
                            item,
                            method_name,
                        )
                        continue
                    if not objective_id and len(matching_mutation_ids) == 1:
                        objective_id = next(iter(matching_mutation_ids))
                    if not objective_id and len(required_mutation_objective_ids) == 1:
                        objective_id = next(iter(required_mutation_objective_ids))
                    if not objective_id:
                        skipped_mutation_objective_id_missing += 1
                        _record_rejected(
                            "mutation_objective_id_missing",
                            test_code,
                            item,
                            method_name,
                        )
                        continue
                    if objective_id not in required_mutation_objective_ids:
                        skipped_mutation_objective_id_unknown += 1
                        _record_rejected(
                            "mutation_objective_id_unknown",
                            test_code,
                            item,
                            method_name,
                        )
                        continue
                    required_direct_methods = (
                        required_mutation_direct_entry_methods.get(
                            objective_id,
                            set(),
                        )
                    )
                    if (
                        required_direct_methods
                        and not cls._test_code_calls_any_method(
                            test_code,
                            sorted(required_direct_methods),
                        )
                    ):
                        skipped_mutation_required_direct_entry_missing += 1
                        _record_rejected(
                            "mutation_candidate_missing_required_direct_entry",
                            test_code,
                            item,
                            method_name,
                        )
                        continue
                if not objective_id and obligation_id:
                    objective_id = obligation_id
                candidate_role = cls._normalize_search_metadata(
                    str(item.get("candidate_role") or item.get("role") or ""),
                    prefix="role",
                )
                protected_setup_prefixes = (
                    required_mutation_survived_setup_prefixes.get(
                        str(objective_id or "").strip().upper(),
                        [],
                    )
                )
                if (
                    candidate_role.removeprefix("role:")
                    == "mutation_oracle"
                    and protected_setup_prefixes
                ):
                    canonical_candidate = cls._canonical_java_tokens(
                        test_code
                    )
                    if not any(
                        prefix in canonical_candidate
                        for prefix in protected_setup_prefixes
                    ):
                        skipped_mutation_survived_setup_not_preserved += 1
                        _record_rejected(
                            "mutation_survived_seed_setup_not_preserved",
                            test_code,
                            item,
                            method_name,
                        )
                        continue
                if (
                    candidate_role.removeprefix("role:") == "mutation_oracle"
                    and not cls._test_code_has_mutation_adequate_oracle(test_code)
                ):
                    skipped_with_weak_mutation_oracle += 1
                    _record_rejected("weak_mutation_oracle", test_code, item, method_name)
                    continue
                raw_skeleton_id = str(item.get("baseline_skeleton_id") or item.get("skeleton_id") or "").strip()
                match_skeleton_id = re.search(r"\bB\d{1,3}\b", raw_skeleton_id, re.IGNORECASE)
                baseline_skeleton_id = match_skeleton_id.group(0).upper() if match_skeleton_id else ""
                raw_fact_ids = item.get("skeleton_fact_ids")
                if isinstance(raw_fact_ids, str):
                    fact_ids = [
                        part.strip()
                        for part in re.split(r"[,;\s]+", raw_fact_ids)
                        if part.strip()
                    ]
                elif isinstance(raw_fact_ids, list):
                    fact_ids = [
                        str(part).strip()
                        for part in raw_fact_ids
                        if str(part).strip()
                    ]
                else:
                    fact_ids = []
                fact_ids = [
                    fid for fid in fact_ids
                    if re.fullmatch(r"F\d{1,3}", fid, re.IGNORECASE)
                ][:12]
                method_blocks.append(test_code)
                if method_name:
                    if overload_id:
                        test_overload_map[method_name] = overload_id
                    behavior = str(item.get("test_behavior") or "").strip()
                    if behavior:
                        test_behavior_map[method_name] = behavior
                    if objective_id:
                        test_objective_map[method_name] = objective_id
                    if candidate_role:
                        test_candidate_role_map[method_name] = candidate_role
                    if baseline_skeleton_id:
                        test_baseline_skeleton_map[method_name] = baseline_skeleton_id
                    if fact_ids:
                        test_skeleton_fact_ids_map[method_name] = fact_ids
                    if obligation_id:
                        test_obligation_map[method_name] = obligation_id
                        if inferred_obligation_id:
                            test_inferred_obligation_map[method_name] = True
                    search_metadata = cls._infer_search_metadata(
                        test_behavior=str(item.get("test_behavior") or ""),
                        test_code=test_code,
                        explicit_input_family=str(item.get("input_family") or ""),
                        explicit_oracle_type=str(item.get("oracle_type") or ""),
                        explicit_repair_axis=str(item.get("repair_axis") or ""),
                    )
                    input_family = search_metadata.get("input_family", "")
                    if input_family:
                        test_input_family_map[method_name] = input_family
                    oracle_type = search_metadata.get("oracle_type", "")
                    if oracle_type:
                        test_oracle_type_map[method_name] = oracle_type
                    repair_axis = search_metadata.get("repair_axis", "")
                    if repair_axis:
                        test_repair_axis_map[method_name] = repair_axis
                if max_tests is not None and max_tests > 0 and len(method_blocks) >= max_tests:
                    break

        if not method_blocks:
            skip_counts = {
                "without_overload_id": skipped_without_overload_id,
                "unknown_overload_id": skipped_with_unknown_overload_id,
                "sibling_overload_id": skipped_with_sibling_overload_id,
                "without_target_call": skipped_without_target_call,
                "without_observable_check": skipped_without_observable_check,
                "without_lazy_terminal_execution": skipped_without_lazy_terminal_execution,
                "without_required_order": skipped_without_required_order,
                "with_pre_target_setup_assertion": skipped_with_pre_target_setup_assertion,
                "without_obligation_id": skipped_without_obligation_id,
                "unknown_obligation_id": skipped_with_unknown_obligation_id,
                "conflicting_obligation_id": skipped_with_conflicting_obligation_id,
                "mutation_candidate_missing_target_call": skipped_mutation_candidate_missing_target_call,
                "mutation_objective_id_missing": skipped_mutation_objective_id_missing,
                "mutation_objective_id_unknown": skipped_mutation_objective_id_unknown,
                "mutation_objective_id_conflicting": skipped_mutation_objective_id_conflicting,
                "mutation_candidate_missing_required_direct_entry": skipped_mutation_required_direct_entry_missing,
                "mutation_survived_seed_setup_not_preserved": skipped_mutation_survived_setup_not_preserved,
                "weak_mutation_oracle": skipped_with_weak_mutation_oracle,
            }
            if skipped_without_overload_id:
                raise cls.PatchExtractionError(
                    "JSON response contained test_code entries, but none declared the required overload_id",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_with_unknown_overload_id:
                allowed = ", ".join(sorted(overload_contract_ids or []))
                raise cls.PatchExtractionError(
                    "JSON response contained test_code entries with unknown overload_id. "
                    f"Allowed overload_id values: {allowed}",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_with_sibling_overload_id:
                allowed = ", ".join(sorted(target_overload_ids or []))
                raise cls.PatchExtractionError(
                    "JSON response targeted a sibling overload instead of the exact requested JVM descriptor. "
                    f"Use only overload_id values: {allowed}",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_without_target_call:
                allowed = ", ".join([
                    *list(target_call_names or []),
                    *[
                        f'getDeclaredMethod("{name}", exact descriptor types)'
                        for name in list(target_reflection_names or [])
                    ],
                ])
                raise cls.PatchExtractionError(
                    "JSON response contained test_code entries, but none invoked "
                    f"the required target/entry method(s): {allowed}",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_mutation_candidate_missing_target_call:
                allowed = ", ".join([
                    *list(target_call_names or []),
                    *[
                        f'getDeclaredMethod("{name}", exact descriptor types)'
                        for name in list(target_reflection_names or [])
                    ],
                ])
                raise cls.PatchExtractionError(
                    "Mutation candidate omitted the exact target/entry method call required for the prompted live mutant. "
                    f"Call one of: {allowed}",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if (
                skipped_mutation_objective_id_missing
                or skipped_mutation_objective_id_unknown
                or skipped_mutation_objective_id_conflicting
            ):
                allowed = ", ".join(sorted(required_mutation_objective_ids))
                raise cls.PatchExtractionError(
                    "Mutation candidate did not bind unambiguously to one prompted mutation objective. "
                    f"Use exactly one objective_id from: {allowed}",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_mutation_required_direct_entry_missing:
                required_rows = [
                    f"{objective_id}=>{','.join(sorted(methods))}"
                    for objective_id, methods in sorted(
                        required_mutation_direct_entry_methods.items()
                    )
                    if methods
                ]
                raise cls.PatchExtractionError(
                    "Mutation replay candidate used a transitive facade "
                    "instead of its source-proven direct entry. Invoke the "
                    "required direct entry for the matching M-id: "
                    + "; ".join(required_rows),
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_mutation_survived_setup_not_preserved:
                raise cls.PatchExtractionError(
                    "Mutation oracle candidate replaced the PIT-proven green "
                    "Arrange/ACT sequence. Clone the named green test setup "
                    "and target invocation exactly; change or append only "
                    "the observable oracle.",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_without_observable_check:
                raise cls.PatchExtractionError(
                    "JSON response contained test_code entries that invoked the target, "
                    "but none asserted observable behavior or an expected exception",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_with_weak_mutation_oracle:
                raise cls.PatchExtractionError(
                    "JSON response contained mutation_oracle candidates, but none used an oracle strong enough to kill a SURVIVED mutant. "
                    "Use exact-value, two-input differential, state/output, or specific-exception assertions; do not submit assertNotNull-only, no-throw, or smoke tests.",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_without_lazy_terminal_execution:
                markers = ", ".join(lazy_terminal_markers or [])
                raise cls.PatchExtractionError(
                    "JSON response contained test_code entries that invoked a lazy/async target, "
                    "but none consumed the returned computation with a terminal operation"
                    + (f" such as: {markers}" if markers else ""),
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_without_required_order:
                required = ", ".join(f"{before} before {after}" for before, after in (required_call_order or []))
                raise cls.PatchExtractionError(
                    "JSON response contained test_code entries that invoked the target, "
                    "but none preserved the capsule-required call order: "
                    f"{required}",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_with_pre_target_setup_assertion:
                raise cls.PatchExtractionError(
                    "JSON response contained test_code entries that invoked the target, "
                    "but they asserted exact capsule setup/advance results before invoking the target",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_without_obligation_id:
                allowed = ", ".join(sorted(required_obligation_ids))
                raise cls.PatchExtractionError(
                    "JSON response contained coverage-guided test_code entries, but none bound to a required "
                    f"coverage obligation id in the actual @Test method name. Required ids: {allowed}",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_with_unknown_obligation_id:
                allowed = ", ".join(sorted(required_obligation_ids))
                raise cls.PatchExtractionError(
                    "JSON response contained coverage-guided test_code entries with unknown coverage obligation ids. "
                    f"Allowed ids: {allowed}",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            if skipped_with_conflicting_obligation_id:
                raise cls.PatchExtractionError(
                    "JSON response contained coverage-guided test_code entries whose coverage_obligation_id "
                    "conflicted with the O-id in the actual @Test method name or body",
                    skip_counts=skip_counts,
                    rejected_entries=rejected_entries,
                )
            raise cls.PatchExtractionError(
                "JSON response contains no test_code entries",
                skip_counts=skip_counts,
                rejected_entries=rejected_entries,
            )

        merged_parts: list[str] = []
        if import_lines:
            merged_parts.append("\n".join(import_lines))
        merged_parts.append("\n\n".join(method_blocks))
        patch = "\n\n".join(part for part in merged_parts if part).strip() + "\n"
        if return_metadata:
            metadata = {
                "test_overload_map": test_overload_map,
                "test_behavior_map": test_behavior_map,
                "test_objective_map": test_objective_map,
                "test_candidate_role_map": test_candidate_role_map,
                "test_baseline_skeleton_map": test_baseline_skeleton_map,
                "test_skeleton_fact_ids_map": test_skeleton_fact_ids_map,
                "test_obligation_map": test_obligation_map,
                "test_inferred_obligation_map": test_inferred_obligation_map,
                "test_unbound_obligation_methods": test_unbound_obligation_methods,
                "test_input_family_map": test_input_family_map,
                "test_oracle_type_map": test_oracle_type_map,
                "test_repair_axis_map": test_repair_axis_map,
                "test_semantic_replay_entry_map": (
                    test_semantic_replay_entry_map
                ),
                "accepted_test_count": len(method_blocks),
            }
            if mutation_initial_state_prepatches:
                metadata["mutation_initial_state_prepatches"] = (
                    mutation_initial_state_prepatches
                )
            if lazy_terminal_autowrapped_count:
                metadata["lazy_terminal_autowrapped_count"] = lazy_terminal_autowrapped_count
            if schema_sentinel_lines_removed:
                metadata["schema_sentinel_lines_removed"] = schema_sentinel_lines_removed
            if schema_metadata_lines_removed:
                metadata["schema_metadata_lines_removed"] = (
                    schema_metadata_lines_removed
                )
            if multi_test_item_count:
                metadata["multi_test_item_count"] = multi_test_item_count
                metadata["multi_test_methods_dropped"] = (
                    multi_test_methods_dropped
                )
            if truncated_json_salvaged:
                metadata["salvaged_truncated_json_response"] = True
                metadata["salvaged_truncated_new_tests_count"] = len(method_blocks)
            return patch, metadata
        return patch

    @staticmethod
    def _extract_coverage_obligation_id(*parts: str) -> str:
        """Extract a CGPO obligation id (O1, O2, ...) from generated metadata."""
        for part in parts:
            text = str(part or "")
            match = re.search(r"O(\d{1,3})(?!\d)", text)
            if match:
                return f"O{match.group(1)}"
        return ""

    @staticmethod
    def _normalize_search_metadata(value: str, *, prefix: str | None = None) -> str:
        """Return a compact, stable metadata token for feedback aggregation."""
        text = str(value or "").strip().lower()
        if not text:
            return ""
        text = re.sub(r"[`'\"]+", "", text)
        text = re.sub(r"[^a-z0-9:+/_-]+", "-", text)
        text = re.sub(r"-+", "-", text).strip("-_: /")
        if not text or text in {"none", "n/a", "na", "unknown"}:
            return ""
        if prefix and not text.startswith(f"{prefix}:"):
            text = f"{prefix}:{text}"
        return text[:96]

    @classmethod
    def _infer_search_metadata(
        cls,
        *,
        test_behavior: str,
        test_code: str,
        explicit_input_family: str = "",
        explicit_oracle_type: str = "",
        explicit_repair_axis: str = "",
    ) -> dict[str, str]:
        """Infer coarse search metadata from Java syntax, not domain words.

        Optional model-provided metadata remains authoritative. Fallbacks only
        recognize concrete literals, collection/array construction, and
        assertion call shapes in the returned Java. Natural-language behavior
        descriptions and API names must not route tests into parser/cursor/
        protocol families.
        """
        behavior = str(test_behavior or "")
        code = str(test_code or "")
        del behavior
        code_without_literals = cls._strip_java_comments_and_strings(code)

        input_family = cls._normalize_search_metadata(explicit_input_family)
        oracle_type = cls._normalize_search_metadata(explicit_oracle_type)
        repair_axis = cls._normalize_search_metadata(explicit_repair_axis)

        if not input_family:
            has_null_literal = bool(
                re.search(r"(?<![A-Za-z0-9_$])null(?![A-Za-z0-9_$])", code_without_literals)
            )
            has_empty_literal = bool(
                re.search(r'(?<!\\)""', code)
                or re.search(
                    r"\b(?:List|Set|Map)\s*\.\s*of\s*\(\s*\)",
                    code_without_literals,
                )
                or re.search(
                    r"\bnew\s+[A-Za-z_$][A-Za-z0-9_$.<>?]*\s*\[\s*0\s*\]",
                    code_without_literals,
                )
            )
            if has_null_literal or has_empty_literal:
                input_family = "presence:null-empty-absent"
            elif re.search(
                r"\bnew\s+[A-Za-z_$][A-Za-z0-9_$.<>?]*\s*\[",
                code_without_literals,
            ):
                input_family = "shape:array-construction"
            elif re.search(
                r"\b(?:List|Set|Map)\s*\.\s*of\s*\(",
                code_without_literals,
            ):
                input_family = "shape:collection-construction"
            elif re.search(
                r"(?<![A-Za-z0-9_$])[-+]?(?:\d+\.\d+|\d+)[fFdDlL]?"
                r"(?![A-Za-z0-9_$])",
                code_without_literals,
            ):
                input_family = "literal:numeric"

        if not oracle_type:
            if re.search(r"\bassertThrows\s*\(", code_without_literals):
                oracle_type = "exact-exception-oracle"
            elif re.search(
                r"\bassert(?:Equals|ArrayEquals|Same|NotEquals)\s*\(",
                code_without_literals,
            ):
                oracle_type = "exact-value-or-state-oracle"
            elif re.search(r"\bverify\s*\(", code_without_literals):
                oracle_type = "interaction-oracle"
            elif re.search(
                r"\bassert(?:True|False|Null|NotNull)\s*\(",
                code_without_literals,
            ):
                oracle_type = "predicate-oracle"

        if not repair_axis and input_family:
            repair_axis = input_family.split(":", 1)[0] + "-axis"

        return {
            "input_family": input_family,
            "oracle_type": oracle_type,
            "repair_axis": repair_axis,
        }

    @staticmethod
    def _test_code_calls_any_method(test_code: str, method_names: list[str]) -> bool:
        """Return true when a generated test body appears to invoke a required method.

        This is intentionally syntactic. It prevents method-scope patches from
        silently spending their budget on nearby smoke tests that compile and
        pass but never execute the requested target method.
        """
        if not test_code or not method_names:
            return False
        if TATGEngineAdapter._test_code_reflectively_invokes_any_method(test_code, method_names):
            return True
        cleaned = TATGEngineAdapter._strip_java_comments_and_strings(test_code)
        for raw_line in cleaned.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            # Skip test/helper declarations so a declaration name does not
            # count as an invocation. For a one-line generated test, retain
            # the body after the opening brace so real calls are still seen.
            if re.search(r"\b(?:public|protected|private)\b[^;{=]*\([^)]*\)\s*(?:throws\b[^{}]*)?\{?\s*$", line):
                continue
            decl_with_body = re.search(
                r"\b(?:public|protected|private)\b[^;{=]*\([^)]*\)\s*(?:throws\b[^{}]*)?\{",
                line,
            )
            if decl_with_body:
                line = line[decl_with_body.end():]
                if not line.strip():
                    continue
            for method_name in method_names:
                if not method_name:
                    continue
                escaped = re.escape(method_name)
                receiver_call = rf"(?:\.|::)\s*{escaped}\s*\("
                local_call = rf"(?<![\w$]){escaped}\s*\("
                if re.search(receiver_call, line) or re.search(local_call, line):
                    return True
        return False

    @classmethod
    def _test_code_call_arities(
        cls,
        test_code: str,
        method_name: str,
    ) -> set[int]:
        """Return syntactic invocation arities for one Java method name.

        Literal contents are masked but retained as one argument token. Method
        declarations are ignored by scanning only categorized test bodies and
        by rejecting declaration-shaped matches. Candidate-level compilation
        and descriptor coverage remain the authoritative semantic gates.
        """

        if not test_code or not method_name:
            return set()
        _setup, test_methods, _teardown = cls._categorize_methods(test_code)
        methods_to_scan = test_methods or [test_code]
        pattern = re.compile(
            rf"(?<![A-Za-z0-9_$])"
            rf"(?:[A-Za-z_$][A-Za-z0-9_$]*\s*\.\s*)?"
            rf"{re.escape(method_name)}\s*\("
        )
        arities: set[int] = set()
        for method_code in methods_to_scan:
            scan = cls._strip_java_comments_preserve_literal_tokens(method_code)
            for match in pattern.finditer(scan):
                open_index = scan.find("(", match.start())
                close_index = cls._find_matching_paren(scan, open_index)
                if close_index < 0:
                    continue
                line_start = scan.rfind("\n", 0, match.start()) + 1
                prefix = scan[line_start:match.start()]
                suffix = scan[close_index + 1:]
                if (
                    "." not in match.group(0).split(method_name, 1)[0]
                    and re.search(
                        r"\b(?:public|protected|private|static|final|"
                        r"synchronized|native|abstract|default)\b",
                        prefix,
                    )
                    and re.match(r"\s*(?:throws\b[^{]*)?\{", suffix)
                ):
                    continue
                argument_text = scan[open_index + 1:close_index].strip()
                arities.add(
                    0
                    if not argument_text
                    else len(cls._split_top_level_args(argument_text))
                )
        return arities

    @classmethod
    def _private_target_direct_call_violation(
        cls,
        *,
        test_code: str,
        method_name: str,
        target_descriptor: str | None,
        entry_points: list[dict[str, object]] | None,
    ) -> bool:
        """Reject only calls that can bind the exact private overload.

        A public sibling overload may legitimately be the source-visible entry
        path to a private target with the same method name. Name-only rejection
        creates false zero-coverage outcomes. Ambiguous same-arity public
        siblings are allowed through this early gate and resolved by javac plus
        candidate-level descriptor coverage.
        """

        if not cls._test_code_calls_any_method(test_code, [method_name]):
            return False
        target_types = cls._jvm_descriptor_param_types(target_descriptor)
        if not target_types:
            return True
        observed_arities = cls._test_code_call_arities(test_code, method_name)
        if not observed_arities:
            return True
        target_arity = len(target_types)
        if target_arity not in observed_arities:
            return False

        accessible_same_name_arities: set[int] = set()
        for entry in list(entry_points or []):
            if str(entry.get("method") or "") != method_name:
                continue
            raw_arity = entry.get("arity")
            if isinstance(raw_arity, int):
                accessible_same_name_arities.add(raw_arity)
                continue
            signature = str(entry.get("signature") or "").strip()
            if not signature:
                signature_path = list(entry.get("signature_path") or [])
                signature = (
                    str(signature_path[0] or "").strip()
                    if signature_path
                    else ""
                )
            if signature:
                accessible_same_name_arities.add(
                    len(cls._signature_param_types(signature))
                )
        return target_arity not in accessible_same_name_arities

    @staticmethod
    def _test_code_reflectively_invokes_any_method(test_code: str, method_names: list[str]) -> bool:
        if not test_code or not method_names:
            return False
        # Reflection keeps the target method name in a string literal.  The
        # regular detector strips strings before scanning calls, so protected
        # and private target candidates such as
        # Foo.class.getDeclaredMethod("hidden", ...).invoke(...) need this
        # narrow pre-check.  Candidate-level JaCoCo still decides promotion.
        has_invoke = bool(re.search(r"\.\s*invoke\s*\(", test_code))
        if not has_invoke:
            return False
        for method_name in method_names:
            if not method_name:
                continue
            escaped = re.escape(str(method_name))
            if re.search(r"\b(?:getDeclaredMethod|getMethod)\s*\(\s*\"" + escaped + r"\"", test_code):
                return True
        return False

    @staticmethod
    def _test_code_uses_private_reflection(test_code: str, method_name: str | None) -> bool:
        if not test_code or not method_name:
            return False
        escaped = re.escape(str(method_name))
        return bool(
            re.search(r"\bgetDeclaredMethod\s*\(\s*\"" + escaped + r"\"", test_code)
            and re.search(r"\.\s*setAccessible\s*\(\s*true\s*\)", test_code)
            and re.search(r"\.\s*invoke\s*\(", test_code)
        )

    @staticmethod
    def _private_entry_feedback_allows_reflection_fallback(feedback: Any) -> bool:
        """Return True when live feedback proves a visible entry path is blocked.

        Normally private targets should be reached through source-visible entry
        paths.  Some helpers are pure/private but their visible callers require
        annotations, terminal execution, network-ish collaborators, or other
        setup guards before the helper can be reached.  In that live-feedback
        case, allowing one direct reflection fallback is safer than repeatedly
        asking the model to repair a failing wrapper path.  Keep the gate narrow:
        source facts alone never enable it; only current validation feedback can.
        """
        if os.getenv("TATG_ENABLE_ENTRY_GUARD_REFLECTION_FALLBACK", "0").strip().lower() not in {
            "1",
            "true",
            "yes",
            "on",
        }:
            return False
        if not isinstance(feedback, dict) or not feedback:
            return False
        try:
            text = json.dumps(feedback, ensure_ascii=False, sort_keys=True).lower()
        except Exception:
            text = str(feedback).lower()
        if not text:
            return False
        guard_markers = (
            "method must be annotated",
            "not annotated",
            "is not annotated",
            # "@curlcommand" was listed here: a project-specific annotation name,
            # and redundant since the generic "annotation" marker below already
            # matches any message mentioning it.
            "annotation",
            "terminal",
            "lazy",
            "blocking",
            "subscribe",
            "external",
            "http",
            "network",
            "executor",
            "producer returned null",
            "missing-required-initialization",
            "required collaborator",
            "setup failed",
        )
        failure_markers = (
            "streaming_validation_failed",
            "coverage_positive_failed",
            "validation_failure",
            "compile_blocker",
            "runtime-validation-failure",
            "target_positive",
            "no_retained",
            "0% coverage",
        )
        return any(marker in text for marker in guard_markers) and any(
            marker in text for marker in failure_markers
        )

    def _private_reflection_fallback_recipe(
        self,
        source_code: str,
        *,
        class_name: str | None,
        method_name: str | None,
    ) -> ExecutionRecipe | None:
        if not source_code or not class_name or not method_name:
            return None
        selected_block = None
        for block in self._collect_method_blocks(source_code):
            if str(block.get("name") or "") == method_name and bool(block.get("is_private")):
                selected_block = block
                break
        if not selected_block:
            access = self._target_method_access_in_source(
                method_name,
                source_code,
                class_name=class_name,
            )
            if access != "private":
                return None
            compact_match = re.search(
                rf"\bprivate[ \t\r\n]+"
                rf"(?:(?:static|final|synchronized|native|strictfp)[ \t\r\n]+)*"
                rf"(?:<[^;{{}}()]+>[ \t\r\n]+)?"
                rf"[A-Za-z_$][A-Za-z0-9_$.\[\]?]*(?:[ \t]*<[^;{{}}()]+>)?(?:[ \t]*\[\])?[ \t\r\n]+"
                rf"{re.escape(method_name)}[ \t\r\n]*\((?P<params>[^;{{}}]*)\)",
                source_code,
            )
            if compact_match is None:
                return None
            selected_block = {
                "name": method_name,
                "signature": compact_match.group(0),
                "access": "private",
                "is_private": True,
            }
        signature = str(selected_block.get("signature") or "")
        params_match = re.search(r"\(([^)]*)\)", signature)
        raw_params = params_match.group(1).strip() if params_match else ""
        param_classes = self._reflection_param_class_literals(raw_params)
        arg_hint = self._reflection_arg_hint(raw_params)
        return ExecutionRecipe(
            method_name=str(method_name),
            category="private-reflection-entry",
            title=f"Private target `{method_name}`: use reflection for direct target-hit coverage",
            observations=[
                f"`{method_name}` is private and no verified source-visible entry path was found in static analysis",
                "reflection is allowed here only as a target-hit fallback; keep any overload_id bound to the private target descriptor",
            ],
            setup_steps=[
                f"construct a real {class_name} receiver or concrete project subclass when {class_name} is abstract",
                f"obtain the exact private method: `{class_name}.class.getDeclaredMethod(\"{method_name}\", {param_classes})`",
                "call `method.setAccessible(true)` before invocation",
                f"invoke via `method.invoke(receiver, ...)` with arguments matching: {arg_hint}",
            ],
            path_goals=[
                "include at least one reflection-direct test that proves the private target itself is covered",
                "assert the exact return value, thrown exception, or externally visible state change from the reflected invocation",
            ],
            avoid=[
                "do not invent public wrapper methods or substitute a sibling overload",
                "do not stop at construction-only smoke tests whose JaCoCo target-hit remains zero",
            ],
            receipt={
                "fixture_kind": "private_reflection_direct_hit",
                "required_trace": [
                    f"real {class_name} receiver construction",
                    f"getDeclaredMethod({method_name}, exact parameter classes)",
                    "setAccessible(true)",
                    f"invoke {method_name} and assert observable behavior",
                ],
                "oracle": "assert the reflected target result, expected exception, or state change; not only that invocation completed",
            },
        )

    @staticmethod
    def _reflection_param_class_literals(raw_params: str) -> str:
        if not raw_params.strip():
            return "/* no params */"
        literals: list[str] = []
        for raw_param in raw_params.split(","):
            part = re.sub(r"@\w+(?:\([^)]*\))?", "", raw_param).strip()
            part = re.sub(r"\bfinal\b", "", part).strip()
            if not part:
                continue
            tokens = part.rsplit(None, 1)
            type_text = tokens[0] if len(tokens) == 2 else part
            type_text = re.sub(r"<.*>", "", type_text).strip().replace("...", "[]")
            array_suffix = ""
            while type_text.endswith("[]"):
                array_suffix += "[]"
                type_text = type_text[:-2].strip()
            simple_type = type_text.split(".")[-1] if type_text else "Object"
            if array_suffix:
                literals.append(f"{simple_type}{array_suffix}.class")
            else:
                literals.append(f"{simple_type}.class")
        return ", ".join(literals) if literals else "/* exact parameter classes from signature */"

    @staticmethod
    def _reflection_arg_hint(raw_params: str) -> str:
        if not raw_params.strip():
            return "no arguments"
        names: list[str] = []
        for raw_param in raw_params.split(","):
            part = re.sub(r"@\w+(?:\([^)]*\))?", "", raw_param).strip()
            part = re.sub(r"\bfinal\b", "", part).strip()
            tokens = part.rsplit(None, 1)
            if len(tokens) == 2:
                names.append(tokens[1].replace("...", "").replace("[]", ""))
        return ", ".join(names) if names else "arguments in the exact declared order"

    @staticmethod
    def _test_code_satisfies_call_order(test_code: str, ordered_calls: list[tuple[str, str]]) -> bool:
        if not test_code or not ordered_calls:
            return True
        cleaned = TATGEngineAdapter._strip_java_comments_and_strings(test_code)
        for before, after in ordered_calls:
            if not before or not after or before == after:
                continue
            before_pos = TATGEngineAdapter._first_method_invocation_pos(cleaned, before)
            after_pos = TATGEngineAdapter._first_method_invocation_pos(cleaned, after)
            if before_pos == -1 or after_pos == -1 or before_pos > after_pos:
                return False
        return True

    @staticmethod
    def _first_method_invocation_pos(cleaned_code: str, method_name: str) -> int:
        escaped = re.escape(method_name)
        invocation = re.compile(rf"(?:\.|::|(?<![\w$]))\s*{escaped}\s*\(")
        for match in invocation.finditer(cleaned_code or ""):
            line_start = cleaned_code.rfind("\n", 0, match.start()) + 1
            line = cleaned_code[line_start:match.start()].strip()
            if re.search(r"\b(?:public|protected|private)\b", line):
                continue
            return match.start()
        return -1

    @staticmethod
    def _test_code_has_pre_target_setup_assertion(test_code: str, ordered_calls: list[tuple[str, str]]) -> bool:
        """Reject brittle exact assertions about setup/advance calls before target.

        Stateful capsules use advance methods to move cursor/protocol objects to
        a useful state. Exact assertions on those intermediate return values are
        often guesses and can fail before the requested target method executes.
        The final oracle should be the target result, exception, or target-visible
        state after the target call.
        """
        if not test_code or not ordered_calls:
            return False
        cleaned = TATGEngineAdapter._strip_java_comments_and_strings(test_code)
        for before, after in ordered_calls:
            if not before or not after or before == after:
                continue
            after_pos = TATGEngineAdapter._first_method_invocation_pos(cleaned, after)
            if after_pos == -1:
                continue
            prefix = cleaned[:after_pos]
            escaped_before = re.escape(before)
            exact_assert_with_call = (
                r"\bassert(?:Equals|ArrayEquals|Same|NotEquals|NotSame|That)\s*\([^;]*"
                rf"(?:\.|::|(?<![\w$]))\s*{escaped_before}\s*\("
            )
            if re.search(exact_assert_with_call, prefix, flags=re.DOTALL):
                return True

            assigned_vars: set[str] = set()
            assignment = re.compile(
                rf"(?:[\w$<>\[\].?,]+\s+)?([A-Za-z_$][\w$]*)\s*=\s*[^;]*"
                rf"(?:\.|::|(?<![\w$]))\s*{escaped_before}\s*\([^;]*;",
                re.DOTALL,
            )
            for match in assignment.finditer(prefix):
                assigned_vars.add(match.group(1))
            if not assigned_vars:
                continue

            for var_name in assigned_vars:
                escaped_var = re.escape(var_name)
                exact_assert_with_var = (
                    r"\bassert(?:Equals|ArrayEquals|Same|NotEquals|NotSame|That)\s*\([^;]*"
                    rf"\b{escaped_var}\b"
                )
                boolean_compare_with_var = (
                    r"\bassert(?:True|False)\s*\([^;]*(?:"
                    rf"\b{escaped_var}\b\s*(?:==|!=)|(?:==|!=)\s*\b{escaped_var}\b)"
                )
                if re.search(exact_assert_with_var, prefix, flags=re.DOTALL):
                    return True
                if re.search(boolean_compare_with_var, prefix, flags=re.DOTALL):
                    return True
        return False

    @staticmethod
    def _strip_pre_target_setup_assertions(test_code: str, ordered_calls: list[tuple[str, str]]) -> str:
        """Remove simple brittle assertions about setup/advance calls before target.

        This is intentionally conservative and line-oriented. It only removes a
        single assertion statement when it is before the target call and exactly
        compares either an advance call or a variable assigned from an advance
        call. The resulting test still needs a target oracle and still goes
        through normal compile/run validation.
        """
        if not test_code or not ordered_calls:
            return test_code

        lines = test_code.splitlines()
        cleaned_lines = TATGEngineAdapter._strip_java_comments_and_strings(test_code).splitlines()
        remove_indices: set[int] = set()
        replacement_lines: dict[int, str] = {}

        for before, after in ordered_calls:
            if not before or not after or before == after:
                continue
            escaped_before = re.escape(before)
            escaped_after = re.escape(after)
            target_line_index = -1
            after_invocation = re.compile(rf"(?:\.|::|(?<![\w$]))\s*{escaped_after}\s*\(")
            before_invocation = re.compile(rf"(?:\.|::|(?<![\w$]))\s*{escaped_before}\s*\(")

            for index, line in enumerate(cleaned_lines):
                if after_invocation.search(line):
                    target_line_index = index
                    break
            if target_line_index <= 0:
                continue

            assigned_vars: set[str] = set()
            assignment = re.compile(
                rf"(?:[\w$<>\[\].?,]+\s+)?([A-Za-z_$][\w$]*)\s*=\s*.*"
                rf"(?:\.|::|(?<![\w$]))\s*{escaped_before}\s*\("
            )
            for index, line in enumerate(cleaned_lines[:target_line_index]):
                if before_invocation.search(line):
                    match = assignment.search(line)
                    if match:
                        assigned_vars.add(match.group(1))

            exact_asserts = re.compile(r"\bassert(?:Equals|ArrayEquals|Same|NotEquals|NotSame|That)\s*\(")
            boolean_asserts = re.compile(r"\bassert(?:True|False)\s*\(")
            for index, line in enumerate(cleaned_lines[:target_line_index]):
                if not exact_asserts.search(line) and not boolean_asserts.search(line):
                    continue
                if before_invocation.search(line) and exact_asserts.search(line):
                    setup_call = TATGEngineAdapter._extract_simple_method_call(lines[index], before)
                    if setup_call:
                        indent = re.match(r"\s*", lines[index]).group(0)
                        replacement_lines[index] = f"{indent}{setup_call};"
                    else:
                        remove_indices.add(index)
                    continue
                for var_name in assigned_vars:
                    escaped_var = re.escape(var_name)
                    if exact_asserts.search(line) and re.search(rf"\b{escaped_var}\b", line):
                        remove_indices.add(index)
                        break
                    if boolean_asserts.search(line) and re.search(rf"\b{escaped_var}\b\s*(?:==|!=)|(?:==|!=)\s*\b{escaped_var}\b", line):
                        remove_indices.add(index)
                        break

        if not remove_indices:
            if not replacement_lines:
                return test_code
        rewritten: list[str] = []
        for index, line in enumerate(lines):
            if index in replacement_lines:
                rewritten.append(replacement_lines[index])
            elif index not in remove_indices:
                rewritten.append(line)
        return "\n".join(rewritten).strip()

    @staticmethod
    def _extract_simple_method_call(line: str, method_name: str) -> str:
        if not line or not method_name:
            return ""
        escaped = re.escape(method_name)
        call = re.search(
            rf"((?:[A-Za-z_$][\w$]*\s*\.\s*)?{escaped}\s*\([^();]*\))",
            line,
        )
        if not call:
            return ""
        return call.group(1).strip()

    @classmethod
    def _test_code_has_observable_check(cls, test_code: str) -> bool:
        if not test_code:
            return False
        cleaned = cls._strip_java_comments_and_strings(test_code)
        independently_observable_patterns = [
            r"@Test\s*\(\s*expected\s*=",
            r"\bfail\s*\(",
            r"\bverify\s*\(",
            r"\bassertThat\s*\(",
            r"\bthrown\.expect\w*\s*\(",
            r"\bexpectThrows\s*\(",
            r"\bassertThrows\s*\(",
        ]
        if any(
            re.search(pattern, cleaned)
            for pattern in independently_observable_patterns
        ):
            return True

        def _normalized(expression: str) -> str:
            return re.sub(
                r"\s+",
                "",
                str(expression or ""),
            ).strip("()")

        for name, args in cls._java_assertion_arguments(cleaned):
            if not args:
                continue
            first = _normalized(args[0])
            if name == "assertTrue" and first in {
                "true",
                "Boolean.TRUE",
            }:
                continue
            if name == "assertFalse" and first in {
                "false",
                "Boolean.FALSE",
            }:
                continue
            if name == "assertNull" and first == "null":
                continue
            if (
                name
                in {
                    "assertEquals",
                    "assertArrayEquals",
                    "assertSame",
                    "assertNotEquals",
                    "assertNotSame",
                }
                and len(args) >= 2
                and first == _normalized(args[1])
            ):
                continue
            return True
        return False

    @staticmethod
    def _mutation_oracle_is_partial_projection(expression: str) -> bool:
        """Return true for assertions that observe only a coarse output projection."""
        compact = " ".join(str(expression or "").split())
        if not compact:
            return False
        projection_patterns = (
            r"\.\s*startsWith\s*\(",
            r"\.\s*endsWith\s*\(",
            r"\.\s*contains\s*\(",
            r"\.\s*matches\s*\(",
            r"\.\s*isEmpty\s*\(",
            r"\.\s*(?:length|size)\s*\(\s*\)",
            r"\.\s*length\b",
        )
        return any(re.search(pattern, compact) for pattern in projection_patterns)

    @classmethod
    def _java_assertion_arguments(
        cls,
        test_code: str,
    ) -> list[tuple[str, list[str]]]:
        """Extract top-level Java assertion arguments without requiring a Java parser."""
        assertions: list[tuple[str, list[str]]] = []
        for match in re.finditer(r"\b(assert[A-Za-z0-9_]*|expectThrows)\s*\(", test_code):
            open_index = test_code.find("(", match.start())
            close_index = cls._find_matching_paren(test_code, open_index)
            if open_index < 0 or close_index < 0:
                continue
            args = cls._split_top_level_args(test_code[open_index + 1:close_index])
            assertions.append((match.group(1), [str(arg).strip() for arg in args]))
        return assertions

    @classmethod
    def _java_local_initializer_map(cls, test_code: str) -> dict[str, str]:
        """Return simple local-variable initializers for oracle data-flow checks."""
        initializers: dict[str, str] = {}
        statement_pattern = re.compile(
            r"(?:^|[;{}])\s*"
            r"(?:final\s+)?"
            r"(?:[A-Za-z_$][\w$]*(?:\s*<[^;=]+?>)?(?:\s*\[\s*\])?(?:\s*\.\.\.)?"
            r"(?:\s*\.\s*[A-Za-z_$][\w$]*(?:\s*<[^;=]+?>)?)*)"
            r"\s+([A-Za-z_$][\w$]*)\s*=",
            re.MULTILINE,
        )
        for match in statement_pattern.finditer(test_code):
            expression_start = match.end()
            paren = bracket = brace = angle = 0
            index = expression_start
            while index < len(test_code):
                char = test_code[index]
                if char == "(":
                    paren += 1
                elif char == ")":
                    paren = max(0, paren - 1)
                elif char == "[":
                    bracket += 1
                elif char == "]":
                    bracket = max(0, bracket - 1)
                elif char == "{":
                    brace += 1
                elif char == "}":
                    brace = max(0, brace - 1)
                elif char == "<":
                    angle += 1
                elif char == ">":
                    angle = max(0, angle - 1)
                elif char == ";" and paren == bracket == brace == angle == 0:
                    break
                index += 1
            if index >= len(test_code):
                continue
            expression = " ".join(test_code[expression_start:index].split())
            if expression:
                initializers[match.group(1)] = expression
        return initializers

    @staticmethod
    def _normalize_java_oracle_expression(expression: str) -> str:
        compact = re.sub(r"\s+", "", str(expression or ""))
        while compact.startswith("(") and compact.endswith(")"):
            close = TATGEngineAdapter._find_matching_paren(compact, 0)
            if close != len(compact) - 1:
                break
            compact = compact[1:-1]
        return compact

    @classmethod
    def _resolve_java_oracle_operand(
        cls,
        expression: str,
        initializers: dict[str, str],
    ) -> str:
        compact = cls._normalize_java_oracle_expression(expression)
        visited: set[str] = set()
        while re.fullmatch(r"[A-Za-z_$][\w$]*", compact) and compact in initializers:
            if compact in visited:
                break
            visited.add(compact)
            compact = cls._normalize_java_oracle_expression(initializers[compact])
        return compact

    @classmethod
    def _mutation_oracle_is_same_computation_comparison(
        cls,
        assertion_name: str,
        args: list[str],
        initializers: dict[str, str],
    ) -> bool:
        """Detect determinism-only assertions that no deterministic mutant can fail."""
        if assertion_name not in {
            "assertEquals",
            "assertArrayEquals",
            "assertIterableEquals",
            "assertLinesMatch",
            "assertSame",
        } or len(args) < 2:
            return False
        left = cls._resolve_java_oracle_operand(args[-2], initializers)
        right = cls._resolve_java_oracle_operand(args[-1], initializers)
        if not left or left != right:
            return False
        return bool(re.search(r"\b[A-Za-z_$][\w$]*\s*\(", left))

    @classmethod
    def _mutation_oracle_has_unenforced_catch_only_assertion(
        cls,
        test_code: str,
    ) -> bool:
        """Detect strong assertions that execute only if an optional catch runs."""

        source = str(test_code or "")
        for try_match in re.finditer(r"\btry\s*\{", source):
            try_open = source.find("{", try_match.start())
            try_close = cls._find_matching_brace(source, try_open)
            if try_open < 0 or try_close < 0:
                continue
            cursor = try_close + 1
            catch_bodies: list[str] = []
            block_end = try_close + 1
            while True:
                catch_match = re.match(
                    r"\s*catch\s*\([^)]*\)\s*\{",
                    source[cursor:],
                )
                if catch_match is None:
                    break
                catch_open = source.find(
                    "{",
                    cursor + catch_match.start(),
                )
                catch_close = cls._find_matching_brace(source, catch_open)
                if catch_open < 0 or catch_close < 0:
                    break
                catch_bodies.append(source[catch_open + 1 : catch_close])
                cursor = catch_close + 1
                block_end = cursor
            if not catch_bodies or not any(
                cls._java_assertion_arguments(body)
                for body in catch_bodies
            ):
                continue
            try_body = source[try_open + 1 : try_close]
            if cls._test_code_has_mutation_adequate_oracle(try_body):
                continue
            outside = source[: try_match.start()] + source[block_end:]
            if cls._test_code_has_mutation_adequate_oracle(outside):
                continue
            return True
        return False

    @classmethod
    def _test_code_has_mutation_adequate_oracle(cls, test_code: str) -> bool:
        """Reject mutation oracles that only check existence or an output projection.

        The gate remains deliberately conservative. Exact values, differential
        relations, state/output verification, and specific exceptions pass.
        Prefix/contains/length-only checks do not, because they routinely leave
        internal-computation mutants alive even when the full result is
        deterministic and already available to the test.
        """
        if not test_code:
            return False
        cleaned = cls._strip_java_comments_and_strings(test_code)
        if cls._mutation_oracle_has_unenforced_catch_only_assertion(cleaned):
            return False
        unconditionally_strong_patterns = [
            r"\bassert(?:NotEquals|NotSame|That|Null)\s*\(",
            r"\bassertThrows\s*\(",
            r"\bexpectThrows\s*\(",
            r"\bthrown\.expect\w*\s*\(",
            r"\bverify\s*\(",
            r"\bassertThat\s*\(",
            r"\bfail\s*\(",
        ]
        if any(re.search(pattern, cleaned) for pattern in unconditionally_strong_patterns):
            return True
        assertion_calls = cls._java_assertion_arguments(cleaned)
        if not assertion_calls:
            return False
        initializers = cls._java_local_initializer_map(cleaned)
        weak_only_names = {
            "assertNotNull",
            "assertDoesNotThrow",
            "assertAll",
        }
        if all(name in weak_only_names for name, _args in assertion_calls):
            return False
        for name, args in assertion_calls:
            if name in weak_only_names or not args:
                continue
            if cls._mutation_oracle_is_same_computation_comparison(
                name,
                args,
                initializers,
            ):
                continue
            if name == "assertEquals":
                if len(args) < 2:
                    continue
                expected, actual = args[0], args[1]
                expected_bool = expected.strip() in {"true", "false", "Boolean.TRUE", "Boolean.FALSE"}
                actual_bool = actual.strip() in {"true", "false", "Boolean.TRUE", "Boolean.FALSE"}
                if (
                    expected_bool
                    and cls._mutation_oracle_is_partial_projection(actual)
                ) or (
                    actual_bool
                    and cls._mutation_oracle_is_partial_projection(expected)
                ):
                    continue
                if cls._mutation_oracle_is_partial_projection(actual) or cls._mutation_oracle_is_partial_projection(expected):
                    continue
                return True
            if name in {
                "assertArrayEquals",
                "assertIterableEquals",
                "assertLinesMatch",
                "assertSame",
            }:
                return True
            if name in {"assertTrue", "assertFalse"}:
                expr = " ".join(args[0].split())
                if not expr or expr in {"true", "false"}:
                    continue
                if re.fullmatch(r"[A-Za-z_$][\w$]*\s*!=\s*null", expr) or re.fullmatch(
                    r"null\s*!=\s*[A-Za-z_$][\w$]*",
                    expr,
                ):
                    continue
                if cls._mutation_oracle_is_partial_projection(expr):
                    continue
                return True
            if name == "assertNull":
                return True
            if name.startswith("assert"):
                # Unknown assertion helpers may encode a project-specific exact
                # oracle. Do not reject them unless every known assertion above
                # was demonstrably weak.
                return True
            if name == "expectThrows":
                return True
        return False

    @staticmethod
    def _test_code_has_lazy_terminal_execution(test_code: str, markers: list[str]) -> bool:
        """Return true when a lazy/async target result is actually consumed.

        This intentionally checks for terminal APIs anywhere in the accepted
        test method.  It allows common two-step styles such as
        ``Mono<T> result = target(); assertEquals(x, result.block())`` while
        rejecting shallow assertions that only prove a Publisher/Future object
        was constructed.
        """
        if not test_code:
            return False
        marker_list = [m for m in markers if m]
        if not marker_list:
            marker_list = [
                ".block(",
                ".blockOptional(",
                ".blockFirst(",
                ".blockLast(",
                ".subscribe(",
                "StepVerifier.create(",
                ".join(",
                ".get(",
            ]
        cleaned = TATGEngineAdapter._strip_java_comments_and_strings(test_code)
        return any(marker in cleaned for marker in marker_list)

    @staticmethod
    def _rewrite_bare_lazy_target_call_to_terminal_assertion(
        test_code: str,
        target_call_names: list[str],
        markers: list[str],
    ) -> tuple[str, bool]:
        """Add terminal consumption for simple, otherwise-rejected lazy target calls.

        This is intentionally narrow. It only rewrites a standalone target call
        statement or a local variable initialized directly from a target call.
        It does not rewrite assertions, Mockito stubbing, verification, or other
        nested expressions, because those can change test intent.
        """
        code = str(test_code or "")
        targets = [str(name or "").strip() for name in (target_call_names or []) if str(name or "").strip()]
        if not code.strip() or not targets:
            return code, False
        if TATGEngineAdapter._test_code_has_lazy_terminal_execution(code, markers or []):
            return code, False

        marker_list = [m for m in markers if m] or [
            ".block(",
            ".blockOptional(",
            ".blockingGet(",
            ".blockingAwait(",
            ".join(",
            ".get(",
            "StepVerifier.create(",
        ]
        terminal = ""
        for candidate in (".block(", ".blockingGet(", ".blockOptional(", ".join(", ".get(", ".blockingAwait("):
            if candidate in marker_list:
                terminal = candidate[:-1] + "()"
                break
        use_step_verifier = not terminal and any("StepVerifier.create(" in marker for marker in marker_list)
        if not terminal and not use_step_verifier:
            return code, False

        def _target_call_pattern() -> str:
            names = "|".join(re.escape(name) for name in targets)
            return rf"\b(?:{names})\s*\("

        call_pat = _target_call_pattern()
        lines = code.splitlines()
        rewritten: list[str] = []
        changed = False

        for line in lines:
            if changed:
                rewritten.append(line)
                continue
            stripped = line.strip()
            if not stripped or not re.search(call_pat, stripped):
                rewritten.append(line)
                continue
            if re.search(r"\b(?:when|verify|assert\w*|assertDoesNotThrow|assertThrows|StepVerifier\.create)\s*\(", stripped):
                rewritten.append(line)
                continue
            if ".thenReturn(" in stripped or ".thenThrow(" in stripped or ".doReturn(" in stripped:
                rewritten.append(line)
                continue
            if not stripped.endswith(";"):
                rewritten.append(line)
                continue

            indent = line[: len(line) - len(line.lstrip())]
            assignment = re.match(
                r"^(?P<indent>\s*)(?:(?:final\s+)?[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*(?:\s*<[^;=]+>)?(?:\s*\[\s*\])?\s+|var\s+)?"
                r"(?P<var>[A-Za-z_$][\w$]*)\s*=\s*(?P<call>.+?)\s*;\s*$",
                line,
            )
            if assignment and re.search(call_pat, assignment.group("call") or ""):
                rewritten.append(line)
                var_name = assignment.group("var")
                if terminal == ".blockingAwait()":
                    rewritten.append(f"{indent}{var_name}{terminal};")
                    rewritten.append(f"{indent}assertTrue(true);")
                elif use_step_verifier:
                    rewritten.append(f"{indent}StepVerifier.create({var_name}).verifyComplete();")
                else:
                    rewritten.append(f"{indent}Object tatgTerminalResult = {var_name}{terminal};")
                    rewritten.append(f"{indent}assertNotNull(tatgTerminalResult);")
                changed = True
                continue

            statement = re.match(r"^(?P<indent>\s*)(?P<call>.+?)\s*;\s*$", line)
            if statement and re.search(call_pat, statement.group("call") or ""):
                prefix_before_call = re.split(call_pat, stripped, maxsplit=1)[0]
                if "=" in prefix_before_call:
                    rewritten.append(line)
                    continue
                call_expr = statement.group("call").strip()
                if terminal == ".blockingAwait()":
                    rewritten.append(f"{indent}{call_expr}{terminal};")
                    rewritten.append(f"{indent}assertTrue(true);")
                elif use_step_verifier:
                    rewritten.append(f"{indent}StepVerifier.create({call_expr}).verifyComplete();")
                else:
                    rewritten.append(f"{indent}Object tatgTerminalResult = {call_expr}{terminal};")
                    rewritten.append(f"{indent}assertNotNull(tatgTerminalResult);")
                changed = True
                continue
            rewritten.append(line)

        if not changed:
            return code, False
        return "\n".join(rewritten) + ("\n" if code.endswith("\n") else ""), True

    @staticmethod
    def _strip_java_comments_and_strings(text: str) -> str:
        """Remove comments/string contents while preserving rough line shape."""
        out: list[str] = []
        idx = 0
        in_line_comment = False
        in_block_comment = False
        in_string = False
        in_char = False
        escaped = False
        while idx < len(text):
            ch = text[idx]
            nxt = text[idx + 1] if idx + 1 < len(text) else ""
            if in_line_comment:
                if ch == "\n":
                    in_line_comment = False
                    out.append(ch)
                else:
                    out.append(" ")
            elif in_block_comment:
                if ch == "*" and nxt == "/":
                    in_block_comment = False
                    out.extend("  ")
                    idx += 1
                else:
                    out.append("\n" if ch == "\n" else " ")
            elif escaped:
                escaped = False
                out.append(" ")
            elif ch == "\\" and (in_string or in_char):
                escaped = True
                out.append(" ")
            elif in_string:
                if ch == '"':
                    in_string = False
                out.append("\n" if ch == "\n" else " ")
            elif in_char:
                if ch == "'":
                    in_char = False
                out.append("\n" if ch == "\n" else " ")
            elif ch == "/" and nxt == "/":
                in_line_comment = True
                out.extend("  ")
                idx += 1
            elif ch == "/" and nxt == "*":
                in_block_comment = True
                out.extend("  ")
                idx += 1
            elif ch == '"':
                in_string = True
                out.append(" ")
            elif ch == "'":
                in_char = True
                out.append(" ")
            else:
                out.append(ch)
            idx += 1
        return "".join(out)

    @staticmethod
    def _detect_junit_family(test_source: str) -> str:
        """Infer the JUnit family used in an existing test file.

        Returns 'junit5', 'junit4', or 'unknown'.  Uses import and annotation
        patterns only — no domain-specific knowledge required.
        """
        if not test_source or not test_source.strip():
            return "unknown"
        if "import org.junit.jupiter" in test_source:
            return "junit5"
        if (
            "import org.junit.Test" in test_source
            or "import org.junit.runner" in test_source
            or "import org.junit.Before" in test_source
            or "@RunWith" in test_source
            or "import junit.framework" in test_source
        ):
            return "junit4"
        return "unknown"

    def _ensure_test_class_skeleton(self, test_file: Path, source_code: str) -> None:
        """Create a minimal test class skeleton when the test file is missing/empty.

        Mirrors Lance behavior at a high level: preserve source package/import
        header context, then emit an empty ``<ClassName>Test`` shell.
        """
        if test_file.exists() and test_file.stat().st_size > 0:
            return

        package_match = self._RE_PACKAGE_DECL.search(source_code)
        import_matches = self._RE_IMPORT_DECL.findall(source_code)
        class_name = test_file.stem

        lines: list[str] = []
        if package_match:
            lines.append(f"package {package_match.group(1)};")
            lines.append("")

        # _RE_IMPORT_DECL.findall returns tuples: (is_static, path)
        for is_static, path in import_matches:
            static_prefix = "static " if is_static else ""
            lines.append(f"import {static_prefix}{path};")
        if import_matches:
            lines.append("")

        lines.append(f"public class {class_name} {{}}")
        lines.append("")

        test_file.parent.mkdir(parents=True, exist_ok=True)
        test_file.write_text("\n".join(lines), encoding="utf-8")

    @staticmethod
    def _dedupe_import_lines(generated_code: str) -> str:
        """Remove duplicate Java import lines while preserving order."""
        seen: set[str] = set()
        out: list[str] = []
        for line in generated_code.splitlines():
            m = re.match(r"^\s*import\s+.+;\s*$", line)
            if not m:
                out.append(line)
                continue
            norm = line.strip()
            if norm in seen:
                continue
            seen.add(norm)
            out.append(line)
        return "\n".join(out) + ("\n" if generated_code.endswith("\n") else "")

    @staticmethod
    def _strip_conflicting_junit_constructs(generated_code: str, junit_family: str) -> str:
        """Drop obvious JUnit4/JUnit5 mixed constructs that break compilation.

        This pass is intentionally conservative and line-based:
        * JUnit4 mode: remove JUnit5 imports and MockitoExtension annotations.
        * JUnit5 mode: remove JUnit4 imports and MockitoJUnitRunner annotations.
        """
        fam = (junit_family or "").lower().strip()
        lines = generated_code.splitlines()
        out: list[str] = []
        for line in lines:
            stripped = line.strip()
            if fam == "junit4":
                if stripped.startswith("import org.junit.jupiter."):
                    continue
                if stripped.startswith("import org.mockito.junit.jupiter."):
                    continue
                if "@ExtendWith(" in stripped or "MockitoExtension" in stripped:
                    continue
            elif fam == "junit5":
                if stripped.startswith("import org.junit."):
                    continue
                if stripped.startswith("import org.mockito.junit.MockitoJUnitRunner"):
                    continue
                if "@RunWith(" in stripped or "MockitoJUnitRunner" in stripped:
                    continue
            out.append(line)
        return "\n".join(out) + ("\n" if generated_code.endswith("\n") else "")

    @staticmethod
    def _rewrite_junit_assert_qualifier_for_family(generated_code: str, junit_family: str) -> str:
        """Normalize JUnit Assert qualifier usage for the selected test family."""
        fam = (junit_family or "").lower().strip()
        if fam != "junit5":
            return generated_code
        rewritten = re.sub(
            r"\borg\.junit\.jupiter\.api\."
            r"(assert[A-Za-z0-9_]*|fail)\s*\(",
            r"org.junit.jupiter.api.Assertions.\1(",
            generated_code,
        )
        rewritten = re.sub(
            r"\bAssert\.(assert[A-Za-z0-9_]*|fail)\s*\(",
            r"\1(",
            rewritten,
        )
        if rewritten == generated_code:
            return generated_code
        lines = []
        for line in rewritten.splitlines():
            stripped = line.strip()
            if stripped in {
                "import org.junit.Assert;",
                "import static org.junit.Assert.*;",
            }:
                continue
            lines.append(line)
        rewritten = "\n".join(lines) + ("\n" if generated_code.endswith("\n") else "")
        if "import static org.junit.jupiter.api.Assertions.*;" not in rewritten:
            import_line = "import static org.junit.jupiter.api.Assertions.*;"
            split_lines = rewritten.splitlines()
            insert_at = 0
            for idx, line in enumerate(split_lines):
                if line.strip().startswith("import "):
                    insert_at = idx + 1
            split_lines.insert(insert_at, import_line)
            rewritten = "\n".join(split_lines) + ("\n" if generated_code.endswith("\n") else "")
        return rewritten

    @staticmethod
    def _rewrite_junit_static_member_imports(generated_code: str) -> str:
        """Convert invalid JUnit member imports into static imports.

        LLMs sometimes emit ``import org.junit.jupiter.api.Assertions.assertThrows;``.
        Java treats that as a type import and javac fails with "class
        assertThrows".  The referenced symbol is source-independent and known
        to be a static assertion member, so rewriting the import is safe.
        """
        text = str(generated_code or "")
        if not text.strip():
            return text
        member_import = re.compile(
            r"(?m)^(\s*)import\s+"
            r"(org\.junit(?:\.jupiter\.api)?\.(?:Assertions|Assert)\.(?:assert[A-Za-z0-9_]*|fail))"
            r"\s*;\s*$"
        )
        rewritten = member_import.sub(r"\1import static \2;", text)
        if rewritten == text:
            return text
        seen: set[str] = set()
        out: list[str] = []
        for line in rewritten.splitlines():
            stripped = line.strip()
            if stripped.startswith("import static org.junit") and stripped in seen:
                continue
            if stripped.startswith("import static org.junit"):
                seen.add(stripped)
            out.append(line)
        return "\n".join(out) + ("\n" if text.endswith("\n") else "")

    @classmethod
    def _rewrite_simple_assert_throws_for_junit4(
        cls,
        generated_code: str,
        junit_family: str,
    ) -> str:
        """Rewrite standalone JUnit 5-style exception assertions for JUnit 4.

        Mutation candidates occasionally ignore the already-rendered JUnit
        family constraint. A standalone ``assertThrows`` has an exact,
        semantics-preserving JUnit 4 representation, so normalize that narrow
        shape before spending a Maven validation. Assigned forms are left
        untouched because later reads of the returned exception require
        data-flow-aware repair.
        """

        if (
            (junit_family or "").strip().lower() != "junit4"
            or "assertThrows" not in str(generated_code or "")
        ):
            return generated_code
        pattern = re.compile(
            r"\b(?P<prefix>"
            r"(?:org\.junit\.jupiter\.api\.Assertions\.|Assertions\.)?"
            r")assertThrows\s*\("
        )
        replacements: list[tuple[int, int, str]] = []
        ordinal = 0
        for match in pattern.finditer(generated_code):
            open_index = match.end() - 1
            close_index = cls._find_matching_paren(
                generated_code,
                open_index,
            )
            if close_index < 0:
                continue
            semicolon = close_index + 1
            while (
                semicolon < len(generated_code)
                and generated_code[semicolon].isspace()
            ):
                semicolon += 1
            if (
                semicolon >= len(generated_code)
                or generated_code[semicolon] != ";"
            ):
                continue
            line_start = generated_code.rfind(
                "\n",
                0,
                match.start(),
            ) + 1
            statement_prefix = generated_code[
                line_start:match.start()
            ]
            if statement_prefix.strip():
                continue
            args = cls._split_top_level_args(
                generated_code[open_index + 1:close_index]
            )
            if len(args) < 2:
                continue
            expected_type = str(args[0] or "").strip()
            if not re.fullmatch(
                r"(?:[A-Za-z_$][\w$]*\.)*"
                r"[A-Za-z_$][\w$]*\.class",
                expected_type,
            ):
                continue
            exception_type = expected_type[:-6]
            lambda_body = str(args[1] or "").strip()
            arrow = lambda_body.find("->")
            if not lambda_body.startswith("()") or arrow < 0:
                continue
            body = lambda_body[arrow + 2:].strip()
            if body.startswith("{") and body.endswith("}"):
                body = body[1:-1].strip()
            else:
                body = body.rstrip(";").strip() + ";"
            if not body:
                continue
            ordinal += 1
            indent = re.match(r"[ \t]*", statement_prefix).group(0)
            flag = f"tatgCaughtExpected{ordinal}"
            caught = f"tatgExpected{ordinal}"
            body_lines = [
                f"{indent}    {line.strip()}"
                for line in body.splitlines()
                if line.strip()
            ]
            replacement = "\n".join([
                f"{indent}boolean {flag} = false;",
                f"{indent}try {{",
                *body_lines,
                f"{indent}}} catch ({exception_type} {caught}) {{",
                f"{indent}    {flag} = true;",
                f"{indent}}}",
                f"{indent}if (!{flag}) {{",
                (
                    f'{indent}    org.junit.Assert.fail('
                    f'"Expected {exception_type}");'
                ),
                f"{indent}}}",
            ])
            replacements.append(
                (line_start, semicolon + 1, replacement)
            )
        rewritten = generated_code
        for start, end, replacement in sorted(
            replacements,
            key=lambda item: item[0],
            reverse=True,
        ):
            rewritten = (
                rewritten[:start] + replacement + rewritten[end:]
            )
        if rewritten == generated_code:
            return generated_code
        lines = [
            line
            for line in rewritten.splitlines()
            if not line.strip().startswith(
                "import org.junit.jupiter."
            )
        ]
        return "\n".join(lines) + (
            "\n" if generated_code.endswith("\n") else ""
        )

    @staticmethod
    def _promote_junit4_test_methods_to_public(generated_code: str, junit_family: str) -> str:
        """Make JUnit 4 test/lifecycle methods public before validation.

        Some model outputs use package-private methods even when the project is
        inferred as JUnit 4. Surefire then fails at initialization time with
        "method ... should be public". This pass is intentionally narrow: it
        only rewrites method declarations that directly follow common JUnit 4
        annotations.
        """
        fam = (junit_family or "").lower().strip()
        if fam != "junit4":
            return generated_code

        annotation_re = re.compile(r"^\s*@(Test|Before|After|BeforeClass|AfterClass)\b")

        lines = generated_code.splitlines()
        out: list[str] = []
        pending_public = False
        for line in lines:
            stripped = line.strip()
            if annotation_re.match(stripped):
                pending_public = True
                out.append(line)
                continue

            if pending_public:
                if (
                    "(" in stripped
                    and ")" in stripped
                    and "{" in stripped
                    and not re.search(r"\b(public|protected|private)\b", stripped)
                ):
                    indent = line[: len(line) - len(line.lstrip())]
                    line = f"{indent}public {stripped}"
                pending_public = False

            if stripped and not stripped.startswith("@"):
                pending_public = False
            out.append(line)

        return "\n".join(out) + ("\n" if generated_code.endswith("\n") else "")

    def _render_coverage_quality_hints(
        self,
        *,
        source_code: str,
        class_name: str,
        method_name: str | None,
    ) -> str:
        """Render scenario-level hints that steer tests toward real execution.

        These hints specifically target low-coverage anti-patterns observed in
        generated tests:
        * over-mocking parser/generator internals
        * hundreds of trivial flag/getter assertions with little line reach
        * compile-fragile mixed JUnit4/JUnit5 annotations
        """
        simple = (class_name or "").strip()
        legacy_name_heuristics = self._legacy_name_heuristics_enabled()
        looks_parser_or_generator = False
        looks_stream_parser_or_generator = False
        if legacy_name_heuristics:
            lower_simple = simple.lower()
            looks_parser_or_generator = (
                "parser" in lower_simple
                or "generator" in lower_simple
                or "xml" in lower_simple
            )
            looks_stream_parser_or_generator = self._looks_stream_parser_or_generator(
                class_name=simple,
                source_code=source_code,
            )

        lines = [
            "Coverage-quality guidance:",
            "- Avoid tests that only assert constants/default getters/bitmasks.",
            "- Prioritize behavior-driving scenarios that execute real control flow.",
            "- Do NOT access private/protected/internal fields of the CUT directly.",
            "- Keep imports non-duplicated and framework-consistent (single JUnit family only).",
        ]

        if looks_stream_parser_or_generator:
            lines.extend(
                [
                    "- For parser/generator classes, prefer real IO-style inputs over deep mocks:",
                    "  use serialized payload strings/bytes/readers/writers plus project-observed factories, builders, constructors, or existing fixtures where feasible.",
                    "- Include at least one happy-path scenario that processes real tokens/content/output through the public API.",
                    "- Include at least one error/edge scenario that reaches a guard/branch condition.",
                    "- Avoid creating large volumes of near-duplicate tests; focus on branch diversity.",
                ]
            )
        elif looks_parser_or_generator:
            lines.extend(
                [
                    "- For parser/mapper-style classes without stream-token APIs, use real serialized payloads or DTO fixtures instead of parser internals.",
                    "- Assert mapped fields, null/empty/default handling, and malformed-input behavior tied to the target method.",
                    "- Avoid creating large volumes of near-duplicate tests; focus on branch diversity.",
                ]
            )
        if looks_parser_or_generator and self._has_output_sink_calls(source_code):
            lines.extend(
                [
                    "- For branch-focused writer/generator protocol tests, a focused fake/mock output sink is preferred when real output backends reject intermediate document states before the target branch can be asserted.",
                    "- When using a focused sink, assert the exact sink method call or emitted value after invoking the target; keep at least one separate real-output happy path when feasible.",
                ]
            )
        delegated_state_hint = self._render_delegated_state_realism_hint(
            source_code=source_code,
            method_name=method_name,
        )
        if delegated_state_hint:
            lines.append(delegated_state_hint)
        callback_matrix = self._render_delegated_callback_outcome_matrix(
            source_code=source_code,
            method_name=method_name,
        )
        if callback_matrix:
            lines.append(callback_matrix)

        if method_name:
            lines.append(
                f"- Ensure at least one test drives execution through target method path: {method_name}."
            )

        assertion_hints = self._render_assertion_quality_hints(
            source_code=source_code,
            class_name=class_name,
            method_name=method_name,
        )
        if assertion_hints:
            lines.append(assertion_hints)

        # P4: Stateful API sequence template for parser/generator classes.
        # When the class is a streaming parser or generator, the LLM needs to see
        # a concrete token-advancing sequence so it doesn't generate isolated
        # method calls that crash because the parser state hasn't been advanced.
        if looks_stream_parser_or_generator:
            seq_template = self._render_stateful_api_template(
                class_name=simple,
                source_code=source_code,
                method_name=method_name,
            )
            if seq_template:
                lines.append(seq_template)
        protocol_template = self._render_public_state_sequence_template(
            class_name=simple,
            source_code=source_code,
            method_name=method_name,
        )
        if protocol_template:
            lines.append(protocol_template)

        return "\n".join(lines)

    @staticmethod
    def _legacy_name_heuristics_enabled() -> bool:
        """Return false: historical name/keyword routing is retired.

        The default TATG path derives state/callback facts from source data flow
        and the separately validated semantic branch analysis. Environment or
        batch configuration must not reactivate case-specific production logic.
        Historical helpers remain callable only from isolated regression tests.
        """

        return False

    @staticmethod
    def _has_output_sink_calls(source_code: str) -> bool:
        return bool(re.search(
            r"\.\s*write(?:Attribute|Characters|CData|Start\w*|End\w*|Raw|Binary)\s*\(",
            source_code or "",
        ))

    @staticmethod
    def _render_delegated_state_realism_hint(*, source_code: str, method_name: str | None) -> str:
        if not method_name:
            return ""
        source = source_code or ""
        method_block = ""
        try:
            for block in TATGEngineAdapter._collect_method_blocks(source):
                if str(block.get("name") or "") == str(method_name):
                    method_block = str(block.get("text") or block.get("body") or block.get("source") or "")
                    if not method_block:
                        method_block = str(block.get("signature") or "")
                    break
        except Exception:
            method_block = ""
        if not method_block:
            method_match = re.search(
                rf"\b{re.escape(str(method_name))}\s*\([^;{{}}]*\)\s*(?:throws\s+[\w\s.,<>]+)?\{{",
                source,
            )
            if method_match:
                method_block = source[method_match.start(): method_match.start() + 5000]
        text = method_block or source[:8000]
        declared_fields = TATGEngineAdapter._declared_instance_field_names(source)
        if not declared_fields:
            return ""
        field_pattern = "|".join(
            re.escape(name) for name in sorted(declared_fields, key=len, reverse=True)
        )
        branch_uses_receiver_state = bool(re.search(
            rf"\b(?:if|while|switch)\s*\([^)]*\b(?:this\.)?(?:{field_pattern})\b",
            text,
            flags=re.DOTALL,
        ))
        # A collaborator call is identified by syntax and ownership, not by a
        # method-name vocabulary. Calls on receiver fields are source-proven
        # external/protocol interactions.
        collaborator_calls = re.findall(
            r"\b([A-Za-z_$][\w$]*)\s*\.\s*([A-Za-z_$][\w$]*)\s*\(",
            text,
        )
        collaborator_advances = any(
            receiver in declared_fields and receiver != "this"
            for receiver, _method in collaborator_calls
        )
        # Receiver state is considered coupled when a target-owned field is
        # assigned from an expression that contains a method invocation, or
        # when a collaborator result variable is later assigned to such a
        # field. This remains valid for arbitrary naming conventions.
        context_mutation = bool(re.search(
            rf"\b(?:this\.)?(?:{field_pattern})\s*=\s*[^;]*"
            r"[A-Za-z_$][\w$]*\s*\.\s*[A-Za-z_$][\w$]*\s*\(",
            text,
            flags=re.DOTALL,
        ))
        if not context_mutation:
            call_result_vars = {
                match.group(1)
                for match in re.finditer(
                    r"\b([A-Za-z_$][\w$]*)\s*=\s*"
                    r"[A-Za-z_$][\w$]*\s*\.\s*[A-Za-z_$][\w$]*\s*\(",
                    text,
                )
            }
            context_mutation = any(
                re.search(
                    rf"\b(?:this\.)?(?:{field_pattern})\s*=\s*{re.escape(var)}\b",
                    text,
                )
                for var in call_result_vars
            )
        if not (branch_uses_receiver_state and collaborator_advances and context_mutation):
            return ""
        return "\n".join([
            "[Delegated State Realism]",
            "The target method's branches combine receiver state/context with calls to a collaborator/underlying stream.",
            "Prefer real public construction/fixture paths or observed construction recipes that let the receiver update its own context naturally before the target call.",
            "Use Mockito/deep mocks only for focused failure injection; a mock that only returns tokens/values may not update receiver context flags, buffered context, parent/child state, or current-position state needed by missed branches.",
            "When a missed branch mentions receiver state, create a paired public sequence that advances the receiver into that state, then call the target and assert exact output/state/exception.",
        ])

    @staticmethod
    def _target_method_text(source_code: str, method_name: str | None, *, fallback_chars: int = 8000) -> str:
        if not source_code or not method_name:
            return source_code[:fallback_chars] if source_code else ""
        try:
            for block in TATGEngineAdapter._collect_method_blocks(source_code):
                if str(block.get("name") or "") == str(method_name):
                    text = str(block.get("text") or block.get("body") or block.get("source") or "")
                    if text:
                        return text
        except Exception:
            pass
        method_match = re.search(
            rf"\b{re.escape(str(method_name))}\s*\([^;{{}}]*\)\s*(?:throws\s+[\w\s.,<>]+)?\{{",
            source_code,
        )
        if method_match:
            return source_code[method_match.start(): method_match.start() + fallback_chars]
        return source_code[:fallback_chars]

    @staticmethod
    def _declared_instance_field_names(source_code: str) -> set[str]:
        """Extract instance field names without inferring semantics from names."""

        return set(TATGEngineAdapter._declared_instance_field_types(source_code))

    @staticmethod
    def _declared_instance_field_types(source_code: str) -> dict[str, str]:
        """Extract outer-class instance fields and their declared types.

        The extraction is deliberately structural: only declarations at outer
        class brace depth one are considered. This keeps method locals and
        nested-class fields out of collaborator/state analysis without relying
        on field naming conventions.
        """

        fields: dict[str, str] = {}
        cleaned = TATGEngineAdapter._strip_java_comments_and_strings(source_code or "")
        field_re = re.compile(
            r"^[ \t]*(?P<modifiers>"
            r"(?:(?:public|protected|private|static|final|transient|volatile)\s+)*)"
            r"(?P<type>[A-Za-z_$][A-Za-z0-9_$<>\[\].?,\s]*?)\s+"
            r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*(?:=|;)"
        )
        depth = 0
        for line in cleaned.splitlines():
            # A top-level member of the outer class starts at depth one.
            # Initializers commonly contain constructor/factory calls.  The
            # declaration regex already requires ``name =`` or ``name ;``, so
            # excluding every line containing ``(`` silently drops precisely
            # the stateful fields that need setup analysis.
            if depth == 1:
                match = field_re.match(line)
                if match:
                    # Parse modifiers as a closed token set, then reject
                    # ``static`` explicitly.  An optional access-modifier
                    # regex followed by ``(?!static)`` can backtrack and let
                    # ``private static final`` leak into the type capture.
                    modifiers = set(str(match.group("modifiers") or "").split())
                    if "static" in modifiers:
                        depth += line.count("{") - line.count("}")
                        depth = max(0, depth)
                        continue
                    fields[match.group("name")] = " ".join(match.group("type").split())
            depth += line.count("{") - line.count("}")
            depth = max(0, depth)
        return fields

    @classmethod
    def _render_delegated_callback_outcome_matrix(cls, *, source_code: str, method_name: str | None) -> str:
        text = cls._target_method_text(source_code, method_name, fallback_chars=12000)
        if not text:
            return ""
        signature = cls._extract_method_signature_text(source_code, str(method_name or ""))
        symbols = cls._infer_target_body_symbols(signature, text, source_code)
        target_param_names = set(cls._source_method_param_names(signature))
        receiver_field_names = set(cls._declared_instance_field_types(source_code))
        direct_receiver_names = target_param_names | receiver_field_names

        def is_source_visible_collaborator(receiver: str, *, has_arguments: bool) -> bool:
            root = str(receiver or "").split(".", 1)[-1] if receiver.startswith("this.") else str(receiver or "")
            if root not in direct_receiver_names:
                return False
            declared_type = str(symbols.get(root) or "").strip()
            if not declared_type:
                return False
            simple = cls._simple_type_name(declared_type)
            if not simple or cls._is_common_jdk_simple_type(simple):
                return False
            # A zero-argument call on a direct method parameter is normally an
            # input projection (record/DTO/config/context accessor), not an
            # external callback outcome. Receiver fields remain collaborators;
            # parameter callbacks with an actual invocation payload remain
            # eligible. Ambiguous zero-argument parameter dependencies are
            # handled by the separate LLM branch analysis instead of being
            # mislabeled here.
            if root in target_param_names and not has_arguments:
                return False
            return True

        def invocation_has_arguments(match: re.Match[str], haystack: str) -> bool:
            open_idx = haystack.find(
                "(",
                match.start("callback") + len(match.group("callback")),
            )
            close_idx = cls._find_matching_paren(haystack, open_idx)
            return bool(close_idx > open_idx and haystack[open_idx + 1:close_idx].strip())

        lines = text.splitlines()
        assignment_re = re.compile(
            r"\b(?P<var>[A-Za-z_$][\w$]*)\s*=\s*"
            r"(?P<receiver>[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\s*\.\s*"
            r"(?P<callback>[A-Za-z_$][\w$]*)\s*\("
        )
        direct_condition_re = re.compile(
            r"\b(?P<receiver>[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\s*\.\s*"
            r"(?P<callback>[A-Za-z_$][\w$]*)\s*\([^;{}]*\)"
        )
        direct_return_re = re.compile(
            r"\breturn\s+"
            r"(?P<receiver>[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)\s*\.\s*"
            r"(?P<callback>[A-Za-z_$][\w$]*)\s*\([^;{}]*\)\s*\?"
        )
        rows: list[str] = []
        seen: set[tuple[str, str, str]] = set()
        for idx, line in enumerate(lines):
            for match in assignment_re.finditer(line):
                var_name = match.group("var")
                receiver = match.group("receiver")
                callback = match.group("callback")
                if not is_source_visible_collaborator(
                    receiver,
                    has_arguments=invocation_has_arguments(match, line),
                ):
                    continue
                lookahead = " ".join(item.strip() for item in lines[idx:min(len(lines), idx + 12)])
                branch_terms: list[str] = []
                for branch_match in re.finditer(
                    rf"\b{re.escape(var_name)}\s*(?:==|!=)\s*(?:null|[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)?)",
                    lookahead,
                ):
                    branch_terms.append(branch_match.group(0))
                if not branch_terms:
                    continue
                key = (receiver, callback, " | ".join(branch_terms[:4]))
                if key in seen:
                    continue
                seen.add(key)
                selector = TATGEngineAdapter._nearest_switch_selector(lines, idx)
                config_axes = TATGEngineAdapter._callback_protocol_config_axes(lookahead)
                continuation = TATGEngineAdapter._callback_protocol_continuation(lookahead)
                parts = [f"callback=`{receiver}.{callback}(...)`", "branches=" + " | ".join(branch_terms[:4])]
                if selector:
                    parts.insert(0, f"selector={selector}")
                if config_axes:
                    parts.append("config=" + ",".join(config_axes[:3]))
                if continuation:
                    parts.append(f"continuation={continuation}")
                rows.append("- " + "; ".join(parts))
            for match in direct_return_re.finditer(line):
                receiver = match.group("receiver")
                callback = match.group("callback")
                if not is_source_visible_collaborator(
                    receiver,
                    has_arguments=invocation_has_arguments(match, line),
                ):
                    continue
                key = (receiver, callback, "boolean return partition")
                if key in seen:
                    continue
                seen.add(key)
                rows.append(
                    "- "
                    f"callback=`{receiver}.{callback}(...)`; "
                    "branches=boolean true/false selects the source-visible return alternatives"
                )
            stripped = line.strip()
            if not stripped.startswith("if"):
                continue
            condition_window = " ".join(
                item.strip()
                for item in lines[idx:min(len(lines), idx + 8)]
            )
            open_paren = condition_window.find("(")
            close_paren = cls._find_matching_paren(
                condition_window,
                open_paren,
            )
            if open_paren < 0 or close_paren <= open_paren:
                continue
            # Only calls in the boolean condition are collaborator outcomes.
            # Looking into following body lines mislabels ordinary receiver
            # mutations such as counters/collections as callbacks.
            condition_text = condition_window[
                open_paren + 1:close_paren
            ].strip()
            for match in direct_condition_re.finditer(condition_text):
                receiver = match.group("receiver")
                callback = match.group("callback")
                if not is_source_visible_collaborator(
                    receiver,
                    has_arguments=invocation_has_arguments(match, condition_text),
                ):
                    continue
                key = (receiver, callback, condition_text[:160])
                if key in seen:
                    continue
                seen.add(key)
                selector = TATGEngineAdapter._nearest_switch_selector(lines, idx)
                config_axes = TATGEngineAdapter._callback_protocol_config_axes(condition_text)
                continuation = TATGEngineAdapter._callback_protocol_continuation(condition_text)
                parts = [f"callback=`{receiver}.{callback}(...)`", f"condition={condition_text[:140]}"]
                if selector:
                    parts.insert(0, f"selector={selector}")
                if config_axes:
                    parts.append("config=" + ",".join(config_axes[:3]))
                if continuation:
                    parts.append(f"continuation={continuation}")
                rows.append("- " + "; ".join(parts))
        if not rows:
            return ""
        if os.getenv("TATG_RENDER_DETAILED_CALLBACK_PROTOCOL", "").strip().lower() in {"1", "true", "yes", "on"}:
            rows = TATGEngineAdapter._compact_callback_protocol_rows(rows)
            return "\n".join([
                "[Delegated Callback Outcome Matrix]",
                "Source-derived callback protocol axes. For each row, combine selector/input shape, the exact callback-result comparisons shown by source, relevant receiver fields, and enough public target calls to observe the resulting control transfer.",
                "Use only type-compatible return partitions proved by the listed comparisons (for example null/non-null, boolean, enum/constant, or distinct object outcomes).",
                *rows[:5],
            ])
        summary_rows = TATGEngineAdapter._compact_callback_partition_summary(rows)
        return "\n".join([
            "[Delegated Callback Outcome Matrix]",
            "Source-derived callback partitions. Cover these only when they are tied to current missed/partial anchors; keep setup minimal and assert exact behavior.",
            "Partitions come from the exact source comparisons listed below; do not invent a callback outcome that is not type-compatible.",
            *summary_rows[:5],
        ])

    @staticmethod
    def _compact_callback_protocol_rows(rows: list[str]) -> list[str]:
        if not rows:
            return []
        best_by_callback: dict[str, tuple[int, int, str]] = {}
        callback_re = re.compile(r"callback=`[^`]*\.([A-Za-z_$][\w$]*)\(\.\.\.\)`")
        for index, row in enumerate(rows):
            match = callback_re.search(row)
            callback = match.group(1) if match else f"__row_{index}"
            score = 0
            for marker, weight in (
                ("branches=", 16),
                ("selector=", 8),
                ("config=", 4),
                ("continuation=", 4),
            ):
                if marker in row:
                    score += weight
            current = best_by_callback.get(callback)
            if current is None or score > current[0]:
                best_by_callback[callback] = (score, index, row)
        compact = [
            (-score, index, row)
            for _callback, (score, index, row) in best_by_callback.items()
        ]
        compact.sort()
        return [row for _score, _index, row in compact]

    @staticmethod
    def _compact_callback_partition_summary(rows: list[str]) -> list[str]:
        compact = TATGEngineAdapter._compact_callback_protocol_rows(rows)
        out: list[str] = []
        callback_re = re.compile(r"callback=`([^`]+)`")
        for row in compact:
            match = callback_re.search(row)
            if not match:
                continue
            callback = match.group(1)
            branch = ""
            branch_match = re.search(r"branches=([^;]+)", row)
            if branch_match:
                branch = branch_match.group(1).strip()
            elif "condition=" in row:
                condition = row.split("condition=", 1)[1].split(";", 1)[0].strip()
                branch = condition[:120]
            entry = f"- callback=`{callback}`"
            if branch:
                entry += f"; observed={branch}"
            out.append(entry)
        return out

    @staticmethod
    def _nearest_switch_selector(lines: list[str], idx: int) -> str:
        for prev in range(idx, max(-1, idx - 16), -1):
            stripped = lines[prev].strip()
            case_match = re.match(r"case\s+([^:]+):", stripped)
            if case_match:
                return "case " + case_match.group(1).strip()[:80]
            if re.match(r"default\s*:", stripped):
                return "default"
        return ""

    @staticmethod
    def _callback_protocol_config_axes(text: str) -> list[str]:
        axes: list[str] = []
        for match in re.finditer(r"\b_[A-Za-z_$][\w$]*\b", text or ""):
            name = match.group(0)
            if name not in axes:
                axes.append(name)
        return axes[:4]

    @staticmethod
    def _callback_protocol_continuation(text: str) -> str:
        source = text or ""
        if re.search(r"\bcontinue\s*;|\b(?:while|for)\s*\(", source):
            return "loop-continuation"
        if re.search(
            r"\b[A-Za-z_$][\w$]*\s*\.\s*[A-Za-z_$][\w$]*\s*\([^;]*\)\s*;"
            r"[^{}]{0,180}\b(?:return|break)\b",
            source,
            flags=re.DOTALL,
        ):
            return "collaborator-effect-then-control-transfer"
        if len(re.findall(
            r"\b[A-Za-z_$][\w$]*\s*\.\s*[A-Za-z_$][\w$]*\s*\(",
            source,
        )) >= 2:
            return "chained-protocol"
        return ""

    @staticmethod
    def _render_state_dependency_plan(plan: object, *, indent: str = "") -> list[str]:
        if not isinstance(plan, dict) or not plan:
            return []
        lines: list[str] = []
        max_target_state = TATGEngineAdapter._env_int("TATG_RENDER_MAX_STATE_FACTS", 4, minimum=1, maximum=12)
        max_entry_candidates = TATGEngineAdapter._env_int("TATG_RENDER_MAX_STATE_ENTRY_CANDIDATES", 2, minimum=1, maximum=8)
        max_callback_partitions = TATGEngineAdapter._env_int("TATG_RENDER_MAX_CALLBACK_PARTITIONS", 3, minimum=1, maximum=8)
        max_observations = TATGEngineAdapter._env_int("TATG_RENDER_MAX_ORACLE_OBSERVATIONS", 2, minimum=1, maximum=8)
        target_state = [
            TATGEngineAdapter._shorten_inline(item, 260)
            for item in list(plan.get("target_state") or [])[:max_target_state]
            if str(item).strip()
        ]
        if target_state:
            lines.append(f"{indent}target_state: " + "; ".join(target_state))
        entry_candidates = [
            TATGEngineAdapter._shorten_inline(item, 300)
            for item in list(plan.get("state_entry_sequence_candidates") or [])[:max_entry_candidates]
            if str(item).strip()
        ]
        if entry_candidates:
            lines.append(f"{indent}state_entry_sequence_candidates: " + "; ".join(entry_candidates))
        partitions = [
            TATGEngineAdapter._shorten_inline(item, 240)
            for item in list(plan.get("callback_outcome_partition") or [])[:max_callback_partitions]
            if str(item).strip()
        ]
        if partitions:
            lines.append(f"{indent}callback_outcome_partition: " + "; ".join(partitions))
        observations = [
            TATGEngineAdapter._shorten_inline(item, 220)
            for item in list(plan.get("oracle_observation_to_assert") or [])[:max_observations]
            if str(item).strip()
        ]
        if observations:
            lines.append(f"{indent}oracle_observation_to_assert: " + "; ".join(observations))
        return lines

    @staticmethod
    def _env_int(name: str, default: int, *, minimum: int = 0, maximum: int | None = None) -> int:
        raw = str(os.getenv(name, str(default)) or str(default)).strip()
        try:
            value = int(raw)
        except (TypeError, ValueError):
            value = default
        value = max(minimum, value)
        if maximum is not None:
            value = min(value, maximum)
        return value

    @staticmethod
    def _oid_sort_key(oid: str) -> tuple[int, str]:
        text = str(oid or "").strip()
        if len(text) > 1 and text[0].upper() == "O" and text[1:].isdigit():
            return (int(text[1:]), text)
        return (10**9, text)

    @staticmethod
    def _feedback_has_source_backed_compile_blockers(coverage_feedback: dict) -> bool:
        if not isinstance(coverage_feedback, dict):
            return False
        directional = coverage_feedback.get("measured_directional_feedback")
        if not isinstance(directional, dict):
            return False
        blockers = directional.get("source_backed_compile_blockers")
        if not isinstance(blockers, dict):
            return False
        blocker_fields = (
            "missing_known_type_methods",
            "missing_nested_types",
            "intrinsic_value_mock_blockers",
            "generic_arity_mismatches",
            "wrong_overload_or_arity",
            "compile_type_mismatches",
            "declared_type_method_blockers",
            "inaccessible_api_blockers",
            "toolchain_api_incompatibilities",
            "unimplemented_abstract_method_blockers",
            "abstract_instantiation_blockers",
            "missing_static_member_blockers",
            "missing_unqualified_symbol_blockers",
            "source_level_syntax_blockers",
        )
        return any(bool(blockers.get(field)) for field in blocker_fields)

    @staticmethod
    def _repair_candidates_for_missing_api(method: str, known_methods: list[str]) -> list[str]:
        """Choose source-backed alternatives for a missing method name.

        The candidates are intentionally heuristic and evidence-bounded: every
        returned value must already be present in ``known_methods`` from source
        or classpath analysis.  This keeps the repair map generic and prevents
        domain-specific substitutions.
        """
        missing = str(method or "").strip()
        known = [str(value).strip() for value in list(known_methods or []) if str(value).strip()]
        if not missing or not known:
            return []

        def _property_name(name: str) -> str:
            for prefix in ("set", "get", "is"):
                if name.startswith(prefix) and len(name) > len(prefix):
                    tail = name[len(prefix):]
                    return tail[:1].lower() + tail[1:]
            return name

        prop = _property_name(missing)
        scored: list[tuple[int, str]] = []
        for candidate in known:
            cand_prop = _property_name(candidate)
            score = 0
            if candidate == prop or cand_prop == prop:
                score = 100
            elif candidate.lower() == prop.lower() or cand_prop.lower() == prop.lower():
                score = 92
            elif prop and (candidate.lower().endswith(prop.lower()) or prop.lower().endswith(candidate.lower())):
                score = 78
            elif missing[:3].lower() == candidate[:3].lower():
                score = 50
            if score:
                scored.append((score, candidate))
        if not scored and len(known) <= 4:
            scored = [(20, candidate) for candidate in known]
        scored.sort(key=lambda item: (-item[0], item[1]))
        result: list[str] = []
        for _score, candidate in scored:
            if candidate not in result:
                result.append(candidate)
            if len(result) >= 3:
                break
        return result

    @staticmethod
    def _render_source_backed_compile_blocker_lines(compile_blockers: object) -> list[str]:
        if not isinstance(compile_blockers, dict) or not compile_blockers:
            return []
        missing_methods = [
            item for item in list(compile_blockers.get("missing_known_type_methods") or [])
            if isinstance(item, dict)
        ]
        missing_nested = [
            str(item).strip()
            for item in list(compile_blockers.get("missing_nested_types") or [])
            if str(item).strip()
        ]
        intrinsic_value_mocks = [
            item
            for item in list(
                compile_blockers.get("intrinsic_value_mock_blockers") or []
            )
            if isinstance(item, dict)
        ]
        generic_arity = [
            item for item in list(compile_blockers.get("generic_arity_mismatches") or [])
            if isinstance(item, dict)
        ]
        wrong_arity = [
            item for item in list(compile_blockers.get("wrong_overload_or_arity") or [])
            if isinstance(item, dict)
        ]
        type_mismatches = [
            item for item in list(compile_blockers.get("compile_type_mismatches") or [])
            if isinstance(item, dict)
        ]
        declared_method_blockers = [
            item for item in list(compile_blockers.get("declared_type_method_blockers") or [])
            if isinstance(item, dict)
        ]
        inaccessible_api = [
            item for item in list(compile_blockers.get("inaccessible_api_blockers") or [])
            if isinstance(item, dict)
        ]
        abstract_instantiation = [
            item for item in list(compile_blockers.get("abstract_instantiation_blockers") or [])
            if isinstance(item, dict)
        ]
        missing_static_members = [
            item for item in list(compile_blockers.get("missing_static_member_blockers") or [])
            if isinstance(item, dict)
        ]
        missing_unqualified_symbols = [
            item for item in list(compile_blockers.get("missing_unqualified_symbol_blockers") or [])
            if isinstance(item, dict)
        ]
        source_level = [
            item for item in list(compile_blockers.get("source_level_syntax_blockers") or [])
            if isinstance(item, dict)
        ]
        if not any((
            missing_methods,
            missing_nested,
            intrinsic_value_mocks,
            generic_arity,
            wrong_arity,
            type_mismatches,
            declared_method_blockers,
            inaccessible_api,
            abstract_instantiation,
            missing_static_members,
            missing_unqualified_symbols,
            source_level,
        )):
            return []
        lines = [
            "[Source-Backed Compile Blockers]",
            "Fix construction/signature/symbol use before adding more coverage variety. Do not repeat these observed javac/static-validation blockers; use only constructors, factories, overloads, and methods shown in the callable/helper surface.",
        ]
        repair_rows: list[str] = []
        def _short(value: object, limit: int = 260) -> str:
            text = " ".join(str(value or "").split())
            if len(text) <= limit:
                return text
            return text[: max(limit - 3, 0)].rstrip() + "..."

        def _evidence_bits(item: dict, *, include_alternatives: bool = True) -> list[str]:
            bits: list[str] = []
            forbidden = TATGEngineAdapter._shorten_high_priority_hint(
                item.get("forbidden_call")
            )
            exact = TATGEngineAdapter._shorten_high_priority_hint(
                item.get("exact_diagnostic")
            )
            declared = TATGEngineAdapter._shorten_high_priority_hint(
                item.get("declared_receiver_or_signature")
            )
            alternatives = [
                TATGEngineAdapter._shorten_high_priority_hint(value)
                for value in list(item.get("source_visible_alternatives") or [])[:4]
                if str(value).strip()
            ]
            no_alt = TATGEngineAdapter._shorten_high_priority_hint(
                item.get("no_alternative_reason")
            )
            if forbidden:
                bits.append(f"forbidden_call={forbidden}")
            if declared:
                bits.append(f"declared_signature={declared}")
            if exact:
                bits.append(f"exact_diagnostic={exact}")
            if include_alternatives and alternatives:
                bits.append("source_visible_alternatives=" + ", ".join(alternatives))
            elif no_alt:
                bits.append(f"no_alternative_reason={no_alt}")
            return bits

        for item in intrinsic_value_mocks[:5]:
            type_name = _short(item.get("type"), 100) or "Java value type"
            bits = _evidence_bits(item)
            repair_rows.append(
                "- intrinsic value mock: "
                + type_name
                + ("; " + "; ".join(bits) if bits else "")
                + ". Use a concrete language value from the supplied input row; "
                "Mockito is only for collaborators."
            )

        for item in wrong_arity[:5]:
            kind = str(item.get("kind") or "call").strip()
            owner = str(item.get("owner") or "").strip()
            member = str(item.get("member") or "").strip()
            required = str(item.get("required") or "").strip()
            found = str(item.get("found") or "").strip()
            reason = str(item.get("reason") or "").strip()
            diagnostic = _short(item.get("diagnostic"), 300)
            callee = f"{owner}.{member}" if owner and member else member or owner or "call"
            bits = [f"{kind}={callee}"]
            if required:
                bits.append(f"required=({required})")
            if found:
                bits.append(f"found=({found})")
            if reason:
                bits.append(f"reason={reason}")
            if diagnostic:
                bits.append(f"diagnostic={diagnostic}")
            bits.extend(_evidence_bits(item))
            lines.append(
                "- wrong overload/arity: "
                + "; ".join(bits)
                + "; call the exact source/callable-surface signature for the target or collaborator, not a sibling overload or shortened argument list."
            )
        for item in type_mismatches[:5]:
            expected = str(item.get("expected_type") or "").strip()
            provided = str(item.get("provided_type") or "").strip()
            reason = str(item.get("reason") or "incompatible_types").strip()
            diagnostic = _short(item.get("diagnostic"), 300)
            bits = [
                f"expected={expected}" if expected else "",
                f"provided={provided}" if provided else "",
                f"reason={reason}",
                f"diagnostic={diagnostic}" if diagnostic else "",
            ]
            if item.get("type_conflict"):
                bits.append(f"type_conflict={item.get('type_conflict')}")
            if item.get("repair_hint"):
                bits.append(f"repair_hint={_short(item.get('repair_hint'), 260)}")
            bits.extend(_evidence_bits(item))
            lines.append(
                "- type mismatch: "
                + "; ".join(bit for bit in bits if bit)
                + "; construct or mock the exact declared type required by the callable signature before varying assertions."
            )
        for item in declared_method_blockers[:5]:
            declared = str(item.get("declared_type") or "").strip()
            method = str(item.get("method") or "").strip()
            variable = str(item.get("variable") or "").strip()
            args = str(item.get("args") or "").strip()
            receiver = variable or declared or "receiver"
            evidence = _evidence_bits(item)
            lines.append(
                f"- unavailable receiver method: {receiver}.{method}({args}); receiver declared type={declared or 'unknown'}"
                + ("; " + "; ".join(evidence) if evidence else "")
                + "; use only methods visible on that declared type or a source-proven adapter/wrapper."
            )
        for item in inaccessible_api[:5]:
            owner = str(item.get("owner") or "").strip()
            member = str(item.get("member") or "").strip()
            evidence = _evidence_bits(item)
            lines.append(
                f"- inaccessible API: {owner}.{member}"
                + ("; " + "; ".join(evidence) if evidence else "")
                + "; do not call private/protected/package-private members directly; use a public entry/factory path proven by source."
            )
        for item in missing_methods[:5]:
            owner = str(item.get("owner") or "").strip()
            method = str(item.get("method") or "").strip()
            known = [
                str(value).strip()
                for value in list(item.get("known_methods") or [])[:5]
                if str(value).strip()
            ]
            if owner and method:
                line = f"- unavailable call: {owner}.{method}(...)"
                if known:
                    line += "; source-known methods include: " + ", ".join(known)
                evidence = _evidence_bits(item)
                if evidence:
                    line += "; " + "; ".join(evidence)
                lines.append(line)
                candidates = TATGEngineAdapter._repair_candidates_for_missing_api(method, known)
                if candidates:
                    repair_rows.append(
                        f"- replace/avoid `{owner}.{method}(...)`: verified alternatives on `{owner}` include "
                        + ", ".join(f"`{candidate}(...)`" for candidate in candidates)
                    )
        if missing_nested:
            lines.append("- unavailable nested types: " + ", ".join(missing_nested[:6]))
        for item in abstract_instantiation[:5]:
            type_name = str(item.get("type") or "").strip()
            if type_name:
                evidence = _evidence_bits(item)
                lines.append(
                    f"- abstract/interface instantiation: {type_name}"
                    + ("; " + "; ".join(evidence) if evidence else "")
                    + "; use a source-visible concrete subtype/factory or anonymous implementation of required abstract methods."
                )
        for item in missing_static_members[:5]:
            owner = str(item.get("owner") or "").strip()
            member = str(item.get("member") or "").strip()
            visible = [
                str(value).strip()
                for value in list(item.get("source_visible_members") or [])[:8]
                if str(value).strip()
            ]
            line = f"- missing static member: {owner}.{member}"
            if visible:
                line += "; source-visible members include: " + ", ".join(visible)
            evidence = _evidence_bits(item)
            if evidence:
                line += "; " + "; ".join(evidence)
            line += "; do not invent enum constants/static fields."
            lines.append(line)
        for item in missing_unqualified_symbols[:5]:
            symbol = str(item.get("symbol") or "").strip()
            kind = str(item.get("kind") or "symbol").strip()
            owner = str(item.get("owner") or "").strip()
            expected_type = str(item.get("expected_type_fqn") or item.get("expected_type") or "").strip()
            local_repair = TATGEngineAdapter._shorten_high_priority_hint(
                item.get("candidate_local_repair")
            )
            bits = [
                f"{kind}={symbol}" if symbol else f"kind={kind}",
                f"generated_test_owner={owner}" if owner else "",
                f"expected_type={expected_type}" if expected_type else "",
            ]
            bits.extend(_evidence_bits(item))
            if local_repair:
                bits.append(f"candidate_local_repair={local_repair}")
            lines.append(
                "- undeclared generated-test symbol: "
                + "; ".join(bit for bit in bits if bit)
                + "; do not return a test that calls an undeclared helper or references a missing fixture."
            )
        for item in source_level[:3]:
            feature = str(item.get("feature") or "").strip()
            source = str(item.get("source_level") or "").strip()
            if feature:
                lines.append(
                    f"- source-level syntax blocker: {feature} is unavailable under -source {source or 'configured'}; use syntax compatible with the project compiler level."
                )
        for item in generic_arity[:5]:
            reason = str(item.get("reason") or "generic_arity_mismatch").strip()
            type_name = str(item.get("type") or "").strip()
            required = str(item.get("required_type_arguments") or "").strip()
            observed = str(item.get("observed_type_arguments") or "").strip()
            diagnostic = str(item.get("diagnostic") or "").strip()
            bits = [reason]
            if type_name:
                bits.append(f"type={type_name}")
            if observed:
                bits.append(f"observed_type_arguments={observed}")
            if required:
                bits.append(f"required_type_arguments={required}")
            if diagnostic:
                bits.append(f"javac={diagnostic}")
            bits.extend(_evidence_bits(item))
            lines.append(
                "- generic arity mismatch: "
                + "; ".join(bits)
                + "; use the exact source/callable-surface declaration, remove diamond/type args for non-generic types, or supply the required arity only when the declaration is generic."
            )
        if repair_rows:
            lines.extend([
                "",
                "[Missing API Repair Map]",
                "Use this only because previous generated candidates failed static/source-backed validation. Preserve the coverage objective and change the construction/call site to a verified alternative.",
                *repair_rows[:5],
            ])
        return lines

    @staticmethod
    def _source_backed_forbidden_calls_in_code(code: str, coverage_feedback: dict | None) -> list[str]:
        """Return source-proven unavailable calls still present in generated code."""
        if not code or not isinstance(coverage_feedback, dict):
            return []
        directional = coverage_feedback.get("measured_directional_feedback")
        if not isinstance(directional, dict):
            return []
        blockers = directional.get("source_backed_compile_blockers")
        if not isinstance(blockers, dict):
            return []
        found: list[str] = []
        for item in list(blockers.get("missing_known_type_methods") or []):
            if not isinstance(item, dict):
                continue
            owner = str(item.get("owner") or "").strip()
            method = str(item.get("method") or "").strip()
            if not owner or not method:
                continue
            if method[:1].isupper():
                continue
            pattern = rf"\b{re.escape(owner)}\s*\.\s*{re.escape(method)}\s*\("
            if re.search(pattern, code):
                found.append(f"{owner}.{method}")
        return sorted(set(found))

    @staticmethod
    def _known_type_unavailable_calls_in_code(code: str, type_shapes: object) -> list[str]:
        """Find `KnownType.missingMethod(...)` calls using source-derived type shapes."""
        if not code or not isinstance(type_shapes, dict):
            return []
        known_methods_by_owner: dict[str, set[str]] = {}
        for key, shape in type_shapes.items():
            owner_candidates = {
                str(key or "").rsplit(".", 1)[-1],
                str(getattr(shape, "name", "") or "").rsplit(".", 1)[-1],
                str(getattr(shape, "simple_name", "") or "").rsplit(".", 1)[-1],
                str(getattr(shape, "class_name", "") or "").rsplit(".", 1)[-1],
            }
            methods: set[str] = set()
            for method in list(getattr(shape, "methods", []) or []):
                name = ""
                if isinstance(method, dict):
                    name = str(method.get("name") or method.get("method") or "").strip()
                else:
                    name = str(getattr(method, "name", "") or getattr(method, "method", "") or "").strip()
                    if not name:
                        name = str(method or "").strip()
                if "(" in name:
                    name = name.split("(", 1)[0].strip().split()[-1]
                if name:
                    methods.add(name)
            if not methods:
                continue
            for owner in owner_candidates:
                owner = owner.strip()
                if owner and owner[:1].isupper():
                    known_methods_by_owner.setdefault(owner, set()).update(methods)
        if not known_methods_by_owner:
            return []
        found: list[str] = []
        for match in re.finditer(r"\b([A-Z][A-Za-z0-9_$]*)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(", code):
            owner, method = match.group(1), match.group(2)
            if method[:1].isupper():
                continue
            known = known_methods_by_owner.get(owner)
            if known is not None and method not in known:
                found.append(f"{owner}.{method}")
        return sorted(set(found))

    @classmethod
    def _project_source_unavailable_calls_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find static-looking calls to project source types whose method is absent."""
        if not code or not project_root:
            return []
        root = Path(project_root)
        if not root.exists():
            return []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        symbol_index = symbol_index or {}
        imports = cls._extract_source_import_map(code)
        candidates: set[tuple[str, str, int]] = set()
        for match in re.finditer(
            r"\b([A-Z][A-Za-z0-9_$]*)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(",
            code,
        ):
            open_idx = code.find("(", match.end() - 1)
            close_idx = cls._find_matching_paren(code, open_idx)
            if open_idx < 0 or close_idx < 0:
                continue
            raw_args = code[open_idx + 1:close_idx].strip()
            arity = 0 if not raw_args else len(cls._split_top_level_args(raw_args))
            candidates.add((match.group(1), match.group(2), arity))
        ordered_candidates = sorted(candidates)
        if not ordered_candidates:
            return []
        found: list[str] = []
        nested_type_cache: dict[str, set[str]] = {}

        def _nested_types_for_fqn(fqn: str) -> set[str]:
            if fqn in nested_type_cache:
                return nested_type_cache[fqn]
            nested_types: set[str] = set()
            source_file = cls._find_project_source_for_fqn(root, fqn)
            if source_file is not None:
                try:
                    source_text = source_file.read_text(encoding="utf-8", errors="ignore")
                except OSError:
                    source_text = ""
                src = cls._strip_java_comments_and_strings(source_text)
                for match in re.finditer(
                    r"(?:\b(?:class|interface|enum|record)\s+|@interface\s+)([A-Z][A-Za-z0-9_$]*)\b",
                    src,
                ):
                    nested_types.add(match.group(1))
            nested_type_cache[fqn] = nested_types
            return nested_types

        for owner, method, arity in ordered_candidates[:24]:
            fqn = imports.get(owner)
            if not fqn:
                fqn = cls._resolve_best_fqn(
                    owner,
                    candidates=symbol_index.get(owner, []),
                    current_package="",
                    source_package="",
                )
            if not fqn:
                continue
            if method[:1].isupper() and method in _nested_types_for_fqn(fqn):
                continue
            components = cls._project_source_record_components_for_fqn(root, fqn)
            if components is not None and method in components:
                static_arities = cls._project_source_static_method_arities_for_fqn(root, fqn)
                if arity not in (static_arities or {}).get(method, set()):
                    found.append(f"{owner}.{method}:record-accessor-used-statically")
                    continue
            known = cls._project_source_method_names_for_fqn(root, fqn)
            if known is not None and method not in known:
                found.append(f"{owner}.{method}")
        return sorted(set(found))

    @classmethod
    def _project_source_unavailable_nested_type_refs_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find ``Owner.Nested`` references absent from source-known Owner."""
        if not code or not project_root:
            return []
        root = Path(project_root)
        if not root.exists():
            return []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        symbol_index = symbol_index or {}
        imports = cls._extract_source_import_map(code)
        candidates = sorted({
            (match.group(1), match.group(2))
            for match in re.finditer(r"\b([A-Z][A-Za-z0-9_$]*)\s*\.\s*([A-Z][A-Za-z0-9_$]*)\b", code)
        })
        found: list[str] = []
        for owner, nested in candidates[:40]:
            fqn = imports.get(owner)
            if not fqn:
                fqn = cls._resolve_best_fqn(
                    owner,
                    candidates=symbol_index.get(owner, []),
                    current_package="",
                    source_package="",
                )
            if not fqn:
                continue
            source_file = cls._find_project_source_for_fqn(root, fqn)
            if source_file is None:
                continue
            try:
                source_text = source_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            src = cls._strip_java_comments_and_strings(source_text)
            if nested in cls._source_static_or_enum_members(src):
                continue
            if not re.search(rf"(?:\b(?:class|interface|enum|record)\s+|@interface\s+){re.escape(nested)}\b", src):
                found.append(f"{owner}.{nested}")
        return sorted(set(found))

    @staticmethod
    def _source_static_or_enum_members(src: str) -> set[str]:
        members: set[str] = set()
        text = str(src or "")
        for enum_match in re.finditer(r"\benum\s+[A-Za-z_$][\w$]*\s*\{", text):
            body_start = enum_match.end()
            depth = 1
            idx = body_start
            while idx < len(text) and depth > 0:
                if text[idx] == "{":
                    depth += 1
                elif text[idx] == "}":
                    depth -= 1
                idx += 1
            if depth != 0:
                continue
            head = text[body_start:idx - 1].split(";", 1)[0]
            current: list[str] = []
            paren_depth = 0
            brace_depth = 0
            for ch in head + ",":
                if ch == "(":
                    paren_depth += 1
                elif ch == ")" and paren_depth:
                    paren_depth -= 1
                elif ch == "{":
                    brace_depth += 1
                elif ch == "}" and brace_depth:
                    brace_depth -= 1
                if ch == "," and paren_depth == 0 and brace_depth == 0:
                    token = "".join(current).strip().split("(", 1)[0].split("{", 1)[0].strip()
                    if re.fullmatch(r"[A-Z][A-Z0-9_]*", token):
                        members.add(token)
                    current = []
                else:
                    current.append(ch)
        for match in re.finditer(
            r"\b(?:public|protected|private)?\s*static\s+(?:final\s+)?[\w.<>,?$ \[\]]+\s+([A-Z_][A-Za-z0-9_$]*)\s*(?:=|;)",
            text,
        ):
            members.add(match.group(1))
        return members

    @classmethod
    def _project_source_unavailable_static_members_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find ``Type.MEMBER`` references absent from source-known project types."""
        if not code or not project_root:
            return []
        root = Path(project_root)
        if not root.exists():
            return []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        imports = cls._extract_source_import_map(code)
        candidates = sorted({
            (match.group(1), match.group(2))
            for match in re.finditer(
                r"\b([A-Z][A-Za-z0-9_$]*)\s*\.\s*([A-Z_][A-Za-z0-9_$]*)\b(?!\s*\()",
                code,
            )
        })
        unavailable: list[str] = []

        def _members_for(owner: str, fqn: str) -> set[str] | None:
            source_file = cls._find_project_source_for_fqn(root, fqn)
            if source_file is None:
                return None
            try:
                source_text = source_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                return None
            src = cls._strip_java_comments_and_strings(source_text)
            members: set[str] = cls._source_static_or_enum_members(src)
            for match in re.finditer(r"\b(?:class|interface|enum|record)\s+([A-Z][A-Za-z0-9_$]*)\b", src):
                nested = match.group(1)
                if nested != owner:
                    members.add(nested)
            return members

        for owner, member in candidates[:40]:
            fqn = imports.get(owner)
            if not fqn:
                fqn = cls._resolve_best_fqn(
                    owner,
                    candidates=symbol_index.get(owner, []),
                    current_package="",
                    source_package="",
                )
            if not fqn:
                continue
            members = _members_for(owner, fqn)
            if members is not None and member not in members:
                unavailable.append(f"{owner}.{member}")
        return sorted(set(unavailable))

    @classmethod
    def _source_void_method_value_misuses_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find Mockito.when(voidMethod(...)) on project-source declared void methods."""
        if not code or not project_root:
            return []
        root = Path(project_root)
        if not root.exists():
            return []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        imports = cls._extract_source_import_map(code)
        var_types: dict[str, str] = {}
        for match in re.finditer(
            r"\b([A-Z][A-Za-z0-9_$]*)\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*(?:Mockito\.)?mock\s*\(\s*\1\s*\.class\s*\)",
            code,
        ):
            var_types[match.group(2)] = match.group(1)
        if not var_types:
            return []

        return_cache: dict[str, dict[str, str] | None] = {}

        def _returns_for(simple: str) -> dict[str, str] | None:
            fqn = imports.get(simple)
            if not fqn:
                fqn = cls._resolve_best_fqn(
                    simple,
                    candidates=symbol_index.get(simple, []),
                    current_package="",
                    source_package="",
                )
            if not fqn:
                return None
            if fqn in return_cache:
                return return_cache[fqn]
            source_file = cls._find_project_source_for_fqn(root, fqn)
            if source_file is None:
                return_cache[fqn] = None
                return None
            try:
                source_text = source_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                return_cache[fqn] = None
                return None
            src = cls._strip_java_comments_and_strings(source_text)
            returns: dict[str, str] = {}
            for m in cls._RE_METHOD_DECL.finditer(src):
                signature = m.group(0)
                name = m.group(2)
                prefix = signature[: signature.find(name)].strip()
                parts = prefix.split()
                return_type = parts[-1] if parts else ""
                if name and return_type:
                    returns[name] = return_type
            for m in re.finditer(
                r"\b(?:public|protected|private|default|static|final|abstract|\s)*"
                r"([A-Za-z_$][A-Za-z0-9_$<>\[\].?, ]*)\s+"
                r"([A-Za-z_$][A-Za-z0-9_$]*)\s*\([^)]*\)\s*(?:throws\s+[^;{]+)?[;{]",
                src,
            ):
                return_type = " ".join((m.group(1) or "").split())
                name = (m.group(2) or "").strip()
                if name and return_type and name not in {"if", "for", "while", "switch"}:
                    returns.setdefault(name, return_type)
            return_cache[fqn] = returns
            return returns

        found: list[str] = []
        for match in re.finditer(
            r"(?:Mockito\.)?when\s*\(\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(",
            code,
        ):
            var_name, method = match.group(1), match.group(2)
            simple = var_types.get(var_name)
            if not simple:
                continue
            returns = _returns_for(simple)
            if returns is not None and returns.get(method) == "void":
                found.append(f"{simple}.{method}:void-used-as-value")
        return sorted(set(found))

    @classmethod
    def _source_method_declared_throws(
        cls,
        project_root: Path | str | None,
        type_simple: str,
        method_name: str,
        *,
        imports: dict[str, str] | None = None,
        symbol_index: dict[str, list[str]] | None = None,
        limit: int = 4,
    ) -> list[str]:
        if not project_root or not type_simple or not method_name:
            return []
        root = Path(project_root)
        if not root.exists():
            return []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        fqn = (imports or {}).get(type_simple)
        if not fqn:
            fqn = cls._resolve_best_fqn(
                type_simple,
                candidates=(symbol_index or {}).get(type_simple, []),
                current_package="",
                source_package="",
            )
        if not fqn:
            return []
        source_file = cls._find_project_source_for_fqn(root, fqn)
        if source_file is None:
            return []
        try:
            src = cls._strip_java_comments_and_strings(source_file.read_text(encoding="utf-8", errors="ignore"))
        except OSError:
            return []
        method_re = re.compile(
            r"\b(?:public|protected|private|default|static|final|abstract|\s)*"
            r"[A-Za-z_$][A-Za-z0-9_$<>\[\].?, \s]*\s+"
            rf"{re.escape(method_name)}\s*\([^)]*\)\s*"
            r"(?:throws\s+([^;{]+))?[;{]",
            re.DOTALL,
        )
        out: list[str] = []
        for match in method_re.finditer(src):
            for part in cls._split_top_level_args((match.group(1) or "").strip()):
                exc = part.strip().split()[-1].rsplit(".", 1)[-1] if part.strip() else ""
                if exc and exc not in out:
                    out.append(exc)
                if len(out) >= limit:
                    return out
        return out

    @classmethod
    def _source_checked_exception_stubbing_misuses_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find Mockito.doThrow(new CheckedException()).when(mock).method(...) mismatches.

        This is intentionally source-evidence bounded: it only reports a
        problem when the mocked receiver type resolves to project source and
        the target method's throws clause is visible.
        """
        if not code or not project_root or "doThrow" not in code:
            return []
        root = Path(project_root)
        if not root.exists():
            return []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        imports = cls._extract_source_import_map(code)
        var_types: dict[str, str] = {}
        for match in re.finditer(
            r"\b(?:final\s+)?([A-Z][A-Za-z0-9_$]*(?:<[^;=(){}]+>)?)\s+"
            r"([a-z_$][A-Za-z0-9_$]*)\s*=\s*(?:Mockito\.)?mock\s*\(\s*([A-Z][A-Za-z0-9_$]*)\s*\.class\s*\)",
            code,
        ):
            declared = match.group(1).split("<", 1)[0]
            mocked = match.group(3)
            var_types[match.group(2)] = mocked or declared
        if not var_types:
            return []

        method_throws_cache: dict[str, dict[str, set[str]] | None] = {}

        def _method_throws_for(simple: str) -> dict[str, set[str]] | None:
            if simple in method_throws_cache:
                return method_throws_cache[simple]
            fqn = imports.get(simple)
            if not fqn:
                fqn = cls._resolve_best_fqn(
                    simple,
                    candidates=(symbol_index or {}).get(simple, []),
                    current_package="",
                    source_package="",
                )
            if not fqn:
                method_throws_cache[simple] = None
                return None
            source_file = cls._find_project_source_for_fqn(root, fqn)
            if source_file is None:
                method_throws_cache[simple] = None
                return None
            try:
                source_text = source_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                method_throws_cache[simple] = None
                return None
            src = cls._strip_java_comments_and_strings(source_text)
            out: dict[str, set[str]] = {}
            method_re = re.compile(
                r"\b(?:public|protected|private|default|static|final|abstract|\s)*"
                r"[A-Za-z_$][A-Za-z0-9_$<>\[\].?, \s]*\s+"
                r"([A-Za-z_$][A-Za-z0-9_$]*)\s*\([^)]*\)\s*"
                r"(?:throws\s+([^;{]+))?[;{]",
                re.DOTALL,
            )
            for m in method_re.finditer(src):
                name = (m.group(1) or "").strip()
                if not name or name in {"if", "for", "while", "switch"}:
                    continue
                thrown = {
                    part.strip().split()[-1].rsplit(".", 1)[-1]
                    for part in cls._split_top_level_args((m.group(2) or "").strip())
                    if part.strip()
                }
                out.setdefault(name, set()).update(thrown)
            method_throws_cache[simple] = out
            return out

        def _is_likely_unchecked(exception_simple: str) -> bool:
            if not exception_simple:
                return False
            if exception_simple in {"RuntimeException", "ExceptionInInitializerError", "AssertionError", "Error"}:
                return True
            if exception_simple.endswith("RuntimeException") or exception_simple.endswith("Error"):
                return True
            # Project-specific protocol errors often extend RuntimeException; if
            # the source is not resolved here, avoid over-reporting them.
            fqn = imports.get(exception_simple)
            if not fqn:
                fqn = cls._resolve_best_fqn(
                    exception_simple,
                    candidates=(symbol_index or {}).get(exception_simple, []),
                    current_package="",
                    source_package="",
                )
            if fqn:
                source_file = cls._find_project_source_for_fqn(root, fqn)
                if source_file is not None:
                    try:
                        src = cls._strip_java_comments_and_strings(source_file.read_text(encoding="utf-8", errors="ignore"))
                    except OSError:
                        src = ""
                    if re.search(r"\bextends\s+(?:[A-Za-z0-9_$.]*\.)?(?:RuntimeException|Error)\b", src):
                        return True
            return False

        found: list[str] = []
        pattern = re.compile(
            r"(?:Mockito\.)?doThrow\s*\(\s*new\s+([A-Z][A-Za-z0-9_$]*)\s*\([^)]*\)\s*\)"
            r"\s*\.\s*when\s*\(\s*([a-z_$][A-Za-z0-9_$]*)\s*\)\s*"
            r"\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(",
            re.DOTALL,
        )
        for match in pattern.finditer(code):
            exception_simple, var_name, method = match.group(1), match.group(2), match.group(3)
            if _is_likely_unchecked(exception_simple):
                continue
            receiver_simple = var_types.get(var_name)
            if not receiver_simple:
                continue
            throws_by_method = _method_throws_for(receiver_simple)
            if throws_by_method is None or method not in throws_by_method:
                continue
            declared = throws_by_method.get(method) or set()
            if exception_simple not in declared and "Exception" not in declared and "Throwable" not in declared:
                found.append(f"{receiver_simple}.{method}:{exception_simple}:checked-exception-not-declared")
        return sorted(set(found))

    @classmethod
    def _rewrite_source_checked_exception_stubs_to_runtime(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Rewrite Mockito checked-exception stubs that source proves illegal.

        Mockito permits unchecked exceptions for any method, so this keeps the
        candidate compilable without inventing a domain-specific exception.
        Validation/repair can then decide whether the failure path is useful.
        """
        if not code or not project_root or "doThrow" not in code:
            return code, []
        root = Path(project_root)
        if not root.exists():
            return code, []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        misuses = set(cls._source_checked_exception_stubbing_misuses_in_code(
            code,
            root,
            symbol_index=symbol_index,
        ))
        if not misuses:
            return code, []
        var_types: dict[str, str] = {}
        for match in re.finditer(
            r"\b(?:final\s+)?([A-Z][A-Za-z0-9_$]*(?:<[^;=(){}]+>)?)\s+"
            r"([a-z_$][A-Za-z0-9_$]*)\s*=\s*(?:Mockito\.)?mock\s*\(\s*([A-Z][A-Za-z0-9_$]*)\s*\.class\s*\)",
            code,
        ):
            declared = match.group(1).split("<", 1)[0]
            mocked = match.group(3)
            var_types[match.group(2)] = mocked or declared
        replacements: list[tuple[int, int, str, str]] = []
        pattern = re.compile(
            r"((?:Mockito\.)?doThrow\s*\(\s*)new\s+([A-Z][A-Za-z0-9_$]*)\s*\([^)]*\)(\s*\)"
            r"\s*\.\s*when\s*\(\s*([a-z_$][A-Za-z0-9_$]*)\s*\)\s*"
            r"\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\()",
            re.DOTALL,
        )
        for match in pattern.finditer(code):
            exception_simple = match.group(2)
            var_name = match.group(4)
            method = match.group(5)
            receiver_simple = var_types.get(var_name)
            if not receiver_simple:
                continue
            label = f"{receiver_simple}.{method}:{exception_simple}:checked-exception-not-declared"
            if label not in misuses:
                continue
            replacement = f'{match.group(1)}new RuntimeException("source-declared unchecked failure"){match.group(3)}'
            replacements.append((match.start(), match.end(), replacement, label))
        if not replacements:
            return code, []
        replacements.sort(key=lambda item: item[0])
        parts: list[str] = []
        pos = 0
        applied: list[str] = []
        for start, end, replacement, label in replacements:
            if start < pos:
                continue
            parts.append(code[pos:start])
            parts.append(replacement)
            pos = end
            applied.append(label)
        parts.append(code[pos:])
        return "".join(parts), applied

    @classmethod
    def _rewrite_source_void_when_thenreturn_stubs(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Rewrite Mockito when(...).thenReturn(...) on source-known void methods."""
        if not code or not project_root or "thenReturn" not in code:
            return code, []
        root = Path(project_root)
        if not root.exists():
            return code, []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        symbol_index = symbol_index or {}
        imports = cls._extract_source_import_map(code)
        var_types: dict[str, str] = {}
        decl_re = re.compile(
            r"\b(?:final\s+)?([A-Z][A-Za-z0-9_$]*(?:<[^;=(){}]+>)?)\s+"
            r"([a-z_$][A-Za-z0-9_$]*)\s*=\s*(?:Mockito\.)?mock\s*\(\s*\1\s*\.class\s*\)"
        )
        for match in decl_re.finditer(code):
            var_types[match.group(2)] = match.group(1).split("<", 1)[0]
        if not var_types:
            return code, []

        return_cache: dict[str, dict[str, str] | None] = {}

        def _returns_for(simple: str) -> dict[str, str] | None:
            if simple in return_cache:
                return return_cache[simple]
            fqn = imports.get(simple)
            if not fqn:
                fqn = cls._resolve_best_fqn(
                    simple,
                    candidates=symbol_index.get(simple, []),
                    current_package="",
                    source_package="",
                )
            if not fqn:
                return_cache[simple] = None
                return None
            source_file = cls._find_project_source_for_fqn(root, fqn)
            if source_file is None:
                return_cache[simple] = None
                return None
            try:
                source_text = source_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                return_cache[simple] = None
                return None
            src = cls._strip_java_comments_and_strings(source_text)
            returns: dict[str, str] = {}
            for m in re.finditer(
                r"(?<![A-Za-z0-9_$])(?:public|protected|private|default|static|final|abstract|\s)*"
                r"([A-Za-z_$][A-Za-z0-9_$<>\[\].?, ]*)\s+"
                r"([A-Za-z_$][A-Za-z0-9_$]*)\s*\([^)]*\)\s*(?:throws\s+[^;{]+)?[;{]",
                src,
            ):
                return_type = " ".join(m.group(1).split())
                if any(ch in return_type for ch in "{};"):
                    continue
                returns.setdefault(m.group(2), return_type)
            return_cache[simple] = returns
            return returns

        rewrites: list[str] = []

        def repl(match: re.Match[str]) -> str:
            indent, var_name, method, args = match.group(1), match.group(2), match.group(3), match.group(4)
            simple = var_types.get(var_name)
            returns = _returns_for(simple) if simple else None
            if not returns or returns.get(method) != "void":
                return match.group(0)
            rewrites.append(f"{simple}.{method}:void-when-thenReturn-to-doNothing")
            return f"{indent}org.mockito.Mockito.doNothing().when({var_name}).{method}({args});"

        rewritten = re.sub(
            r"(?m)^(\s*)(?:Mockito\.)?when\s*\(\s*([a-z_$][A-Za-z0-9_$]*)\s*\.\s*"
            r"([A-Za-z_$][A-Za-z0-9_$]*)\s*\(([^;{}]*)\)\s*\)\s*\.thenReturn\s*\([^;]*\)\s*;",
            repl,
            code,
        )
        return rewritten, sorted(set(rewrites))

    @classmethod
    def _source_annotation_value_type_misuses_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find source-backed annotations used as value/object types.

        Constructor parameters may be annotated as ``@Qualifier Executor``.
        Generated tests sometimes import the annotation simple name and declare
        ``Qualifier value = ...``.  Annotation types are metadata, not
        constructible collaborator values, so these candidates are
        source-proven compile failures.
        """
        if not code or not project_root:
            return []
        root = Path(project_root)
        if not root.exists():
            return []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        symbol_index = symbol_index or {}

        declared_type_tokens: set[str] = set()
        declaration_re = re.compile(
            r"(?<![\w$.])(?:final\s+)?([A-Z][A-Za-z0-9_$]*(?:<[^;=(){}]+>)?(?:\[\])?)\s+"
            r"[a-z_$][A-Za-z0-9_$]*\s*(?:=|;|,)"
        )
        for match in declaration_re.finditer(code):
            raw_type = match.group(1).strip()
            simple = raw_type.split("<", 1)[0].replace("[]", "").rsplit(".", 1)[-1]
            if simple and simple not in cls._JAVA_LANG_TYPES:
                declared_type_tokens.add(simple)
            if len(declared_type_tokens) >= 60:
                break
        for match in re.finditer(r"\bmock\s*\(\s*([A-Z][A-Za-z0-9_$]*)\s*\.class\s*\)", code):
            declared_type_tokens.add(match.group(1))
        for match in re.finditer(r"\bnew\s+([A-Z][A-Za-z0-9_$]*)\s*\(", code):
            declared_type_tokens.add(match.group(1))
        if not declared_type_tokens:
            return []

        found: list[str] = []
        for simple in sorted(declared_type_tokens):
            for fqn in list(symbol_index.get(simple) or [])[:4]:
                source_file = cls._find_project_source_for_fqn(root, fqn)
                if source_file is None:
                    continue
                try:
                    source_text = source_file.read_text(encoding="utf-8", errors="ignore")
                except OSError:
                    continue
                stripped = cls._strip_java_comments_and_strings(source_text)
                if re.search(rf"@interface\s+{re.escape(simple)}\b", stripped):
                    found.append(f"{simple}:annotation-used-as-value-type")
                    break
        return sorted(set(found))

    @classmethod
    def _project_source_record_components_for_fqn(cls, project_root: Path, fqn: str) -> set[str] | None:
        """Return Java record component names for a project-source record type.

        ``None`` means the type is unavailable or not a source-backed record.
        An empty set means the record was found but no components were parsed.
        """
        cache_key = (str(project_root.resolve() if project_root.exists() else project_root), fqn)
        if cache_key in cls._SOURCE_RECORD_COMPONENT_CACHE:
            return cls._SOURCE_RECORD_COMPONENT_CACHE[cache_key]
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            cls._SOURCE_RECORD_COMPONENT_CACHE[cache_key] = None
            return None
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            cls._SOURCE_RECORD_COMPONENT_CACHE[cache_key] = None
            return None
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        match = re.search(rf"\brecord\s+{re.escape(simple)}\s*\(", code)
        if not match:
            cls._SOURCE_RECORD_COMPONENT_CACHE[cache_key] = None
            return None
        open_idx = code.find("(", match.end() - 1)
        close_idx = cls._find_matching_paren(code, open_idx)
        if open_idx < 0 or close_idx < 0:
            cls._SOURCE_RECORD_COMPONENT_CACHE[cache_key] = set()
            return set()
        components: set[str] = set()
        for raw in cls._split_top_level_args(code[open_idx + 1:close_idx]):
            cleaned = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", raw).strip()
            cleaned = re.sub(r"\b(?:final|volatile|transient)\s+", "", cleaned).strip()
            parts = cleaned.split()
            if len(parts) >= 2:
                name = parts[-1].strip()
                if re.fullmatch(r"[A-Za-z_$][A-Za-z0-9_$]*", name):
                    components.add(name)
        cls._SOURCE_RECORD_COMPONENT_CACHE[cache_key] = components
        return components

    @classmethod
    def _project_source_static_method_arities_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> dict[str, set[int]] | None:
        """Return source-declared static method arities for one project type."""
        cache_key = (str(project_root.resolve() if project_root.exists() else project_root), fqn)
        if cache_key in cls._SOURCE_STATIC_METHOD_ARITY_CACHE:
            return cls._SOURCE_STATIC_METHOD_ARITY_CACHE[cache_key]
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            cls._SOURCE_STATIC_METHOD_ARITY_CACHE[cache_key] = None
            return None
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            cls._SOURCE_STATIC_METHOD_ARITY_CACHE[cache_key] = None
            return None
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        type_match = re.search(
            rf"\b(?:class|interface|record|enum)\s+{re.escape(simple)}\b[^\{{]*\{{",
            code,
            re.DOTALL,
        )
        if type_match:
            open_brace = code.find("{", type_match.end() - 1)
            close_brace = cls._find_matching_brace(code, open_brace)
            if open_brace >= 0 and close_brace > open_brace:
                code = code[open_brace + 1:close_brace]
        method_re = re.compile(
            r"(?m)^\s*((?:(?:public|protected|private|static|final|abstract|default|"
            r"synchronized|native|strictfp)\s+)*)"
            r"(?:<[^>\n]+>\s*)?[\w.<>,? \[\]]+?\s+"
            r"([A-Za-z_$][A-Za-z0-9_$]*)\s*\("
        )
        arities: dict[str, set[int]] = {}
        for match in method_re.finditer(code):
            modifiers = set(str(match.group(1) or "").split())
            if "static" not in modifiers:
                continue
            prefix = code[:match.start()]
            if prefix.count("{") != prefix.count("}"):
                continue
            open_idx = code.find("(", match.end() - 1)
            close_idx = cls._find_matching_paren(code, open_idx)
            if open_idx < 0 or close_idx < 0:
                continue
            raw_params = code[open_idx + 1:close_idx].strip()
            arity = 0 if not raw_params else len(cls._split_top_level_args(raw_params))
            arities.setdefault(match.group(2), set()).add(arity)
        cls._SOURCE_STATIC_METHOD_ARITY_CACHE[cache_key] = arities
        return arities

    @classmethod
    def _record_accessor_argument_misuses_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find calls that treat Java record accessors as setters/factories.

        A record component accessor is a zero-argument method.  If generated
        tests call ``params.message(value)`` on a source-backed ``record
        MessageSendParams(Message message, ...)``, the candidate is
        source-proven uncompilable and should be repaired before Maven.
        """
        if not code or not project_root:
            return []
        root = Path(project_root)
        if not root.exists():
            return []
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        symbol_index = symbol_index or {}
        declarations: dict[str, str] = {}
        decl_re = re.compile(
            r"(?<![\w$.])(?:final\s+)?([A-Z][A-Za-z0-9_$.]*(?:<[^;=(){}]+>)?(?:\[\])?)\s+"
            r"([a-z_$][A-Za-z0-9_$]*)\s*(?:=|;|,)"
        )
        for match in decl_re.finditer(code):
            raw_type = match.group(1).strip()
            var_name = match.group(2).strip()
            simple = raw_type.split("<", 1)[0].replace("[]", "").rsplit(".", 1)[-1]
            if simple and var_name:
                declarations.setdefault(var_name, simple)
            if len(declarations) >= 60:
                break
        if not declarations:
            return []

        component_cache: dict[str, set[str] | None] = {}

        def _components_for(simple: str) -> set[str] | None:
            if simple in component_cache:
                return component_cache[simple]
            fqns = list(symbol_index.get(simple) or [])
            if len(fqns) != 1:
                component_cache[simple] = None
                return None
            components = cls._project_source_record_components_for_fqn(root, fqns[0])
            component_cache[simple] = components
            return components

        found: list[str] = []
        for match in re.finditer(
            r"\b([a-z_$][A-Za-z0-9_$]*)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(",
            code,
        ):
            var_name, method = match.group(1), match.group(2)
            simple = declarations.get(var_name)
            if not simple:
                continue
            components = _components_for(simple)
            if not components or method not in components:
                continue
            open_idx = code.find("(", match.end() - 1)
            close_idx = cls._find_matching_paren(code, open_idx)
            if open_idx < 0 or close_idx < 0:
                continue
            args = cls._split_top_level_args(code[open_idx + 1:close_idx].strip())
            arity = 0 if len(args) == 1 and not args[0].strip() else len(args)
            if arity > 0:
                found.append(f"{simple}.{method}:record-accessor-takes-no-args")
        return sorted(set(found))

    @classmethod
    def _classpath_methods_for_fqn(cls, project_root: Path | str | None, fqn: str) -> set[str] | None:
        """Return classpath-visible method names for *fqn* using ``javap``.

        This is a best-effort guard for dependency APIs. It only rejects calls
        when the class can be inspected successfully; missing tools/classpath
        simply degrade to no early rejection.
        """
        if not project_root or not fqn or "." not in fqn:
            return None
        root = Path(project_root)
        javap_candidates = java_tool_candidates("javap")
        cache_key = (
            str(root.resolve() if root.exists() else root),
            fqn,
            tuple(javap_candidates),
        )
        if cache_key in cls._CLASSPATH_METHOD_CACHE:
            return cls._CLASSPATH_METHOD_CACHE[cache_key]

        known: set[str] | None = None
        try:
            timeout = int(os.getenv("TATG_CLASSPATH_TIMEOUT_SECONDS", "30"))
            javap_timeout = max(2, min(10, int(os.getenv("TATG_JAVAP_TIMEOUT_SECONDS", "5"))))
            if fqn.startswith(("java.", "javax.")):
                javap_args = [fqn]
            else:
                classpath = build_classpath_for_project(root, timeout=timeout)
                javap_args = ["-classpath", classpath, fqn]
            for javap in javap_candidates:
                result = subprocess.run(
                    [javap, *javap_args],
                    cwd=str(root),
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    timeout=javap_timeout,
                    check=False,
                )
                if result.returncode != 0 or not result.stdout:
                    continue
                simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
                methods: set[str] = set()
                for line in result.stdout.splitlines():
                    line = line.strip()
                    if "(" not in line or line.startswith(("Compiled from", "class ", "interface ")):
                        continue
                    prefix = line.split("(", 1)[0].strip()
                    name = prefix.rsplit(" ", 1)[-1].rsplit(".", 1)[-1]
                    if not name or name == simple or name.startswith("<"):
                        continue
                    methods.add(name)
                known = methods or set()
                break
        except (ClasspathError, OSError, subprocess.SubprocessError, ValueError) as exc:
            log.debug("Classpath method inspection skipped for %s in %s: %s", fqn, root, exc)

        cls._CLASSPATH_METHOD_CACHE[cache_key] = known
        return known

    @classmethod
    def _project_source_method_names_for_fqn(cls, project_root: Path, fqn: str) -> set[str] | None:
        return cls._project_source_method_names_for_fqn_inner(project_root, fqn, visited=set())

    @classmethod
    def _project_source_method_names_for_fqn_inner(
        cls,
        project_root: Path,
        fqn: str,
        *,
        visited: set[str],
    ) -> set[str] | None:
        cache_key = (str(project_root.resolve() if project_root.exists() else project_root), fqn)
        if cache_key in cls._SOURCE_METHOD_CACHE:
            return cls._SOURCE_METHOD_CACHE[cache_key]
        if fqn in visited:
            return set()
        visited.add(fqn)
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            cls._SOURCE_METHOD_CACHE[cache_key] = None
            return None
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            cls._SOURCE_METHOD_CACHE[cache_key] = None
            return None
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        type_match = re.search(
            rf"\b(?:class|interface|record|enum)\s+{re.escape(simple)}\b[^\{{]*\{{",
            code,
            re.DOTALL,
        )
        if type_match:
            type_decl_text = type_match.group(0)
            type_kind_match = re.search(r"\b(class|interface|record|enum)\b", type_decl_text)
            is_interface_type = bool(type_kind_match and type_kind_match.group(1) == "interface")
            open_brace = code.find("{", type_match.end() - 1)
            close_brace = cls._find_matching_brace(code, open_brace)
            if open_brace >= 0 and close_brace > open_brace:
                code = code[open_brace + 1:close_brace - 1]
        else:
            is_interface_type = False
        method_re = re.compile(
            r"\b(?:(?:public|protected|private|static|final|abstract|default|synchronized|native)\s+)*"
            r"[\w.<>,? \[\]]+\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*\([^)]*\)\s*"
            r"(?:throws[^{;]+)?[;{]"
        )
        methods: set[str] = set()
        for match in method_re.finditer(code):
            name = match.group(1)
            if not name or name == simple:
                continue
            # Only keep methods declared directly on the target type. Nested
            # builder/helper classes have their own methods (e.g. build()) and
            # advertising them on the outer receiver lets invalid calls such as
            # `EventQueue queue; queue.build()` slip past preflight.
            prefix = code[:match.start()]
            depth = 0
            for ch in prefix:
                if ch == "{":
                    depth += 1
                elif ch == "}":
                    depth = max(0, depth - 1)
            if depth == 0:
                methods.add(name)
        # The compact regex above cannot safely balance parentheses inside
        # parameter annotations such as ``@ToolParam(name = "x")``. Reuse
        # the balanced declaration scanner as a positive-only supplement so
        # a source-declared target is not reported as unavailable merely
        # because its parameters are annotated. Keep the regex path for
        # abstract/interface declarations, which have no method body.
        try:
            for block in cls()._collect_method_blocks(
                source_text,
                class_name=simple,
            ):
                name = str(block.get("name") or "").strip()
                if name and name != simple:
                    methods.add(name)
        except Exception:
            pass
        components = cls._project_source_record_components_for_fqn(project_root, fqn)
        if components:
            methods.update(components)
        parent_fqn = cls._project_source_parent_fqn(project_root, fqn, source_text)
        if parent_fqn:
            parent_methods = cls._project_source_method_names_for_fqn_inner(
                project_root,
                parent_fqn,
                visited=set(visited),
            )
            if parent_methods:
                methods.update(parent_methods)
        cls._SOURCE_METHOD_CACHE[cache_key] = methods or set()
        return methods

    @classmethod
    def _project_source_parent_fqn(cls, project_root: Path, fqn: str, source_text: str) -> str | None:
        src = cls._strip_java_comments_and_strings(source_text or "")
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        header_match = re.search(
            rf"\b(?:class|interface|record|enum)\s+{re.escape(simple)}\b([^\{{]*)\{{",
            src,
            re.DOTALL,
        )
        if not header_match:
            return None
        header_tail = header_match.group(1) or ""
        extends_match = re.search(r"\bextends\s+([A-Za-z_$][A-Za-z0-9_$.]*)", header_tail)
        if not extends_match:
            return None
        parent = extends_match.group(1).strip()
        if not parent or parent.startswith("java."):
            return None
        parent_simple = parent.rsplit(".", 1)[-1]
        imports = cls._extract_source_import_map(source_text or "")
        imported = imports.get(parent_simple)
        if imported:
            return imported
        package_match = cls._RE_PACKAGE_DECL.search(source_text or "")
        package = package_match.group(1) if package_match else ""
        if "." in parent:
            return parent
        same_package = f"{package}.{parent}" if package else parent
        if cls._find_project_source_for_fqn(project_root, same_package) is not None:
            return same_package
        symbol_index = cls._build_symbol_index(project_root)
        resolved = cls._resolve_best_fqn(
            parent,
            candidates=symbol_index.get(parent, []),
            current_package=package,
            source_package=package,
        )
        return resolved if resolved and cls._find_project_source_for_fqn(project_root, resolved) is not None else None

    @classmethod
    def _known_methods_for_fqn(cls, project_root: Path, fqn: str) -> set[str] | None:
        source_methods = cls._project_source_method_names_for_fqn(project_root, fqn)
        if source_methods is not None:
            methods = set(source_methods)
            methods.update({
                "equals",
                "getClass",
                "hashCode",
                "notify",
                "notifyAll",
                "toString",
                "wait",
            })
            source_file = cls._find_project_source_for_fqn(project_root, fqn)
            if source_file is not None:
                try:
                    source_text = source_file.read_text(encoding="utf-8", errors="ignore")
                except OSError:
                    source_text = ""
                src = cls._strip_java_comments_and_strings(source_text) if source_text else ""
                simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
                header_match = re.search(
                    rf"\b(?:class|interface|record|enum)\s+{re.escape(simple)}\b[^\{{]*\{{",
                    src,
                    re.DOTALL,
                )
                header = header_match.group(0) if header_match else ""
                if re.search(r"\bextends\s+(?:[A-Za-z_$][\w$]*\.)*(?:Throwable|Exception|RuntimeException|Error)\b", header):
                    methods.update({
                        "addSuppressed",
                        "fillInStackTrace",
                        "getCause",
                        "getLocalizedMessage",
                        "getMessage",
                        "getStackTrace",
                        "getSuppressed",
                        "initCause",
                        "printStackTrace",
                        "setStackTrace",
                    })
            return methods
        return cls._classpath_methods_for_fqn(project_root, fqn)

    @classmethod
    def _classpath_public_type_exists(cls, project_root: Path | str | None, fqn: str) -> bool | None:
        """Return whether a fully-qualified dependency/JDK type is public and inspectable.

        ``None`` means the classpath could not be inspected; callers should
        degrade to no early rejection in that case.
        """
        if not project_root or not fqn or "." not in fqn:
            return None
        root = Path(project_root)
        javap_candidates = java_tool_candidates("javap")
        cache_key = (
            str(root.resolve() if root.exists() else root),
            fqn,
            tuple(javap_candidates),
        )
        if cache_key in cls._CLASSPATH_PUBLIC_TYPE_CACHE:
            return cls._CLASSPATH_PUBLIC_TYPE_CACHE[cache_key]
        exists: bool | None = None
        try:
            timeout = int(os.getenv("TATG_CLASSPATH_TIMEOUT_SECONDS", "30"))
            classpath = build_classpath_for_project(root, timeout=timeout)
            javap_timeout = max(2, min(10, int(os.getenv("TATG_JAVAP_TIMEOUT_SECONDS", "5"))))
            for javap in javap_candidates:
                result = subprocess.run(
                    [javap, "-public", "-classpath", classpath, fqn],
                    cwd=str(root),
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    timeout=javap_timeout,
                    check=False,
                )
                if result.returncode != 0 or not result.stdout:
                    continue
                header = " ".join(
                    line.strip()
                    for line in result.stdout.splitlines()
                    if line.strip() and not line.startswith("Compiled from")
                )
                exists = bool(re.search(r"\bpublic\s+(?:abstract\s+|final\s+)?(?:class|interface|enum|@interface)\s+", header))
                break
        except (ClasspathError, OSError, subprocess.SubprocessError, ValueError) as exc:
            log.debug("Classpath public type inspection skipped for %s in %s: %s", fqn, root, exc)
        cls._CLASSPATH_PUBLIC_TYPE_CACHE[cache_key] = exists
        return exists

    @classmethod
    def _unavailable_fully_qualified_type_refs_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
    ) -> list[str]:
        """Find fully-qualified type references that are absent or not public.

        This catches generated code such as ``new javax.xml.stream.Factory...``
        before it enters a slow Maven validation loop. The check is intentionally
        limited to fully-qualified references where the model has asserted an
        exact package path.
        """
        if not code or not project_root:
            return []
        root = Path(project_root)
        candidates: set[str] = set()
        for match in re.finditer(r"(?m)^\s*import\s+(?:static\s+)?((?:[a-z_][A-Za-z0-9_$]*\.)+[A-Z][A-Za-z0-9_$]*(?:\.[A-Z][A-Za-z0-9_$]*)*)\s*;", code):
            candidates.add(match.group(1))
        for match in re.finditer(r"\bnew\s+((?:[a-z_][A-Za-z0-9_$]*\.)+[A-Z][A-Za-z0-9_$]*(?:\.[A-Z][A-Za-z0-9_$]*)*)\s*[\(.]", code):
            candidates.add(match.group(1))
        for match in re.finditer(r"\b((?:[a-z_][A-Za-z0-9_$]*\.)+[A-Z][A-Za-z0-9_$]*(?:\.[A-Z][A-Za-z0-9_$]*)*)\s*\.\s*[A-Za-z_$][A-Za-z0-9_$]*\s*\(", code):
            candidates.add(match.group(1))

        unavailable: list[str] = []
        for fqn in sorted(candidates)[:32]:
            if fqn.endswith(".*"):
                continue
            if cls._is_test_framework_fqn(fqn):
                continue
            if cls._find_project_source_for_fqn(root, fqn) is not None:
                continue
            exists = cls._classpath_public_type_exists(root, fqn)
            if exists is False:
                unavailable.append(fqn)
        return unavailable

    @classmethod
    def _rewrite_unavailable_project_fqns_to_source_fqns(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Rewrite wrong project-local FQNs to unique source-backed FQNs.

        LLMs often invent a plausible subpackage while using the correct simple
        type name, for example ``a.b.content.TextBlock`` when the source only has
        ``a.b.TextBlock``.  This rewrite is intentionally narrow: it only fires
        when the wrong FQN is not source-backed, the simple name resolves to a
        unique source FQN, and both packages share the same project prefix.
        """
        text = str(code or "")
        if not text.strip() or not project_root:
            return text, []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return text, []

        package_match = cls._RE_PACKAGE_DECL.search(text)
        current_package = package_match.group(1) if package_match else ""
        project_prefix = cls._project_package_prefix(current_package) if current_package else ""

        candidates = sorted({
            match.group(1)
            for match in re.finditer(
                r"\b((?:[a-z_][A-Za-z0-9_$]*\.)+[A-Z][A-Za-z0-9_$]*(?:\.[A-Z][A-Za-z0-9_$]*)*)\b",
                text,
            )
        })
        replacements: dict[str, str] = {}
        for bad_fqn in candidates[:64]:
            if cls._is_test_framework_fqn(bad_fqn):
                continue
            if cls._find_project_source_for_fqn(root, bad_fqn) is not None:
                continue
            # An exact dependency import used by production code is stronger
            # evidence than a best-effort classpath probe. Multi-module Maven
            # classpaths are occasionally incomplete during isolated test
            # generation; rewriting such a type to a same-simple-name project
            # class changes a valid candidate into uncompilable Java.
            if cls._project_source_explicitly_imports_fqn(root, bad_fqn):
                continue
            # A dependency type is not a hallucinated project-local FQN.  In
            # particular, same-simple-name project classes must never replace
            # an exact external type that javac can already resolve.
            if cls._classpath_public_type_exists(root, bad_fqn) is True:
                continue
            simple = bad_fqn.rsplit(".", 1)[-1]
            source_fqns = [
                fqn for fqn in sorted(set(symbol_index.get(simple) or []))
                if fqn != bad_fqn and cls._find_project_source_for_fqn(root, fqn) is not None
            ]
            if len(source_fqns) != 1:
                continue
            good_fqn = source_fqns[0]
            good_package = good_fqn.rsplit(".", 1)[0]
            bad_package = bad_fqn.rsplit(".", 1)[0]
            shared_project_prefix = project_prefix and (
                bad_fqn.startswith(project_prefix + ".")
                and good_fqn.startswith(project_prefix + ".")
            )
            shared_package_prefix = False
            bad_parts = bad_package.split(".")
            good_parts = good_package.split(".")
            if len(bad_parts) >= 2 and len(good_parts) >= 2:
                shared_package_prefix = bad_parts[:2] == good_parts[:2]
            if not shared_project_prefix and not shared_package_prefix:
                continue
            replacements[bad_fqn] = good_fqn
        if not replacements:
            return text, []
        rewritten = text
        applied: list[str] = []
        for bad_fqn, good_fqn in sorted(replacements.items(), key=lambda item: len(item[0]), reverse=True):
            rewritten_next = re.sub(rf"\b{re.escape(bad_fqn)}\b", good_fqn, rewritten)
            if rewritten_next != rewritten:
                rewritten = rewritten_next
                applied.append(f"{bad_fqn}->{good_fqn}")
        return rewritten, applied[:12]

    @classmethod
    def _project_source_explicitly_imports_fqn(
        cls,
        project_root: Path | str,
        fqn: str,
    ) -> bool:
        """Return whether production Java explicitly imports ``fqn``."""

        root = Path(project_root)
        scan_root = cls._find_scan_root(root)
        cache_key = str(scan_root)
        with cls._SYMBOL_INDEX_CACHE_LOCK:
            cached = cls._PROJECT_SOURCE_IMPORT_CACHE.get(cache_key)
            if cached is not None:
                cls._PROJECT_SOURCE_IMPORT_CACHE.move_to_end(cache_key)
                return fqn in cached

        imports: set[str] = set()
        for java_file in cls._production_java_files(scan_root):
            try:
                source = java_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            for match in cls._RE_IMPORT_DECL.finditer(source):
                if not match.group(1):
                    imported = str(match.group(2) or "").strip()
                    if imported and not imported.endswith(".*"):
                        imports.add(imported)

        with cls._SYMBOL_INDEX_CACHE_LOCK:
            if len(cls._PROJECT_SOURCE_IMPORT_CACHE) >= cls._MAX_SYMBOL_CACHE_SIZE:
                cls._PROJECT_SOURCE_IMPORT_CACHE.popitem(last=False)
            cls._PROJECT_SOURCE_IMPORT_CACHE[cache_key] = imports
        return fqn in imports

    @staticmethod
    def _is_test_framework_fqn(fqn: str) -> bool:
        """Return true for common test-scope APIs that may not be on main classpath.

        The early source/classpath guard is meant to reject hallucinated
        production APIs before a slow Maven validation loop. Test frameworks are
        commonly provided only in test scope, and their compatibility is already
        handled by the JUnit-family normalizer and Maven validation.
        """
        normalized = str(fqn or "").strip()
        return normalized.startswith((
            "org.junit.",
            "junit.",
            "org.mockito.",
            "org.hamcrest.",
            "org.assertj.",
        ))

    @classmethod
    def _project_source_visible_constructor_arities_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> set[int] | None:
        cache_key = (str(project_root.resolve() if project_root.exists() else project_root), fqn)
        if cache_key in cls._SOURCE_CONSTRUCTOR_CACHE:
            return cls._SOURCE_CONSTRUCTOR_CACHE[cache_key]
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            cls._SOURCE_CONSTRUCTOR_CACHE[cache_key] = None
            return None
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            cls._SOURCE_CONSTRUCTOR_CACHE[cache_key] = None
            return None
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        type_decl = re.search(
            rf"\b(?:(abstract)\s+)?(class|interface|enum|record)\s+{re.escape(simple)}\b",
            code,
        )
        if type_decl and (type_decl.group(2) == "interface" or type_decl.group(1) == "abstract"):
            cls._SOURCE_CONSTRUCTOR_CACHE[cache_key] = set()
            return set()
        record_component_arity: int | None = None
        if type_decl and type_decl.group(2) == "record":
            open_idx = code.find("(", type_decl.end())
            close_idx = cls._find_matching_paren(code, open_idx) if open_idx >= 0 else -1
            if close_idx >= 0:
                components = code[open_idx + 1: close_idx].strip()
                record_component_arity = 0 if not components else len(cls._split_top_level_args(components))
        arities: set[int] = set()
        saw_ctor = False
        ctor_re = re.compile(
            rf"(?m)^\s*(?P<visibility>public|protected|private)?\s*{re.escape(simple)}\s*\("
        )
        for match in ctor_re.finditer(code):
            saw_ctor = True
            if (match.group("visibility") or "").strip() == "private":
                continue
            open_idx = code.find("(", match.start())
            close_idx = cls._find_matching_paren(code, open_idx)
            if close_idx < 0:
                continue
            params = code[open_idx + 1: close_idx].strip()
            if not params:
                arities.add(0)
            else:
                arities.add(len(cls._split_top_level_args(params)))
        if not saw_ctor:
            # Records without an explicit compact/canonical constructor expose
            # the canonical constructor with one parameter per component, not
            # an implicit no-arg constructor. Treating them as no-arg makes the
            # static source-surface gate reject valid generated tests before
            # compile/repair can run.
            arities.add(record_component_arity if record_component_arity is not None else 0)
        cls._SOURCE_CONSTRUCTOR_CACHE[cache_key] = arities
        return arities

    @classmethod
    def _project_source_constructor_details_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> list[dict[str, Any]] | None:
        """Return source-declared constructor details, including modifiers.

        This is deliberately source-only.  The construction repair map uses it
        to explain why ``new Type(...)`` is unsafe when the type itself is
        public but the matching constructor is not.  A missing constructor list
        represents Java's implicit public no-arg constructor.
        """
        cache_key = (str(project_root.resolve() if project_root.exists() else project_root), fqn)
        if cache_key in cls._SOURCE_CONSTRUCTOR_DETAIL_CACHE:
            return cls._SOURCE_CONSTRUCTOR_DETAIL_CACHE[cache_key]
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            cls._SOURCE_CONSTRUCTOR_DETAIL_CACHE[cache_key] = None
            return None
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            cls._SOURCE_CONSTRUCTOR_DETAIL_CACHE[cache_key] = None
            return None
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        record_components: list[str] | None = None
        record_decl = re.search(rf"\bpublic\s+record\s+{re.escape(simple)}\s*\(", code)
        if record_decl:
            open_idx = code.find("(", record_decl.start())
            close_idx = cls._find_matching_paren(code, open_idx)
            if close_idx >= 0:
                components_text = code[open_idx + 1 : close_idx].strip()
                record_components = [] if not components_text else cls._split_top_level_args(components_text)
        ctor_re = re.compile(
            rf"(?m)^(?P<prefix>\s*(?:(?:public|protected|private|static|final)\s+)*)"
            rf"{re.escape(simple)}\s*\("
        )
        details: list[dict[str, Any]] = []
        for match in ctor_re.finditer(code):
            prefix = str(match.group("prefix") or "")
            modifiers = re.findall(r"\b(public|protected|private|static|final)\b", prefix)
            visibility = "package-private"
            for candidate in ("public", "protected", "private"):
                if candidate in modifiers:
                    visibility = candidate
                    break
            open_idx = code.find("(", match.start())
            close_idx = cls._find_matching_paren(code, open_idx)
            if close_idx < 0:
                continue
            params_text = code[open_idx + 1: close_idx].strip()
            params = [] if not params_text else cls._split_top_level_args(params_text)
            line_no = code.count("\n", 0, match.start()) + 1
            display_params = [
                re.sub(r"@\w+(?:\s*\([^)]*\))?\s*", "", param).strip()
                for param in params
                if str(param).strip()
            ]
            signature = f"{simple}(" + ", ".join(param for param in display_params if param) + ")"
            details.append({
                "type": simple,
                "visibility": visibility,
                "modifiers": modifiers,
                "params": params,
                "arity": len(params),
                "signature": signature,
                "line": line_no,
            })
        if not details:
            if record_components is not None:
                display_params = [
                    re.sub(r"@\w+(?:\s*\([^)]*\))?\s*", "", param).strip()
                    for param in record_components
                    if str(param).strip()
                ]
                details.append({
                    "type": simple,
                    "visibility": "public",
                    "modifiers": ["public", "record-canonical"],
                    "params": record_components,
                    "arity": len(record_components),
                    "signature": f"{simple}(" + ", ".join(param for param in display_params if param) + ")",
                    "line": code.count("\n", 0, record_decl.start()) + 1 if record_decl else None,
                    "record_canonical": True,
                })
            else:
                details.append({
                    "type": simple,
                    "visibility": "public",
                    "modifiers": ["public", "implicit"],
                    "params": [],
                    "arity": 0,
                    "signature": f"{simple}()",
                    "line": None,
                    "implicit": True,
                })
        cls._SOURCE_CONSTRUCTOR_DETAIL_CACHE[cache_key] = details
        return details

    @classmethod
    def _source_builder_recipe_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> dict[str, Any] | None:
        """Return a compact public builder recipe for a source-visible type."""
        cache_key = (str(project_root.resolve() if project_root.exists() else project_root), fqn)
        if cache_key in cls._SOURCE_BUILDER_RECIPE_CACHE:
            return cls._SOURCE_BUILDER_RECIPE_CACHE[cache_key]
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            cls._SOURCE_BUILDER_RECIPE_CACHE[cache_key] = None
            return None
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            cls._SOURCE_BUILDER_RECIPE_CACHE[cache_key] = None
            return None
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        builder_match = re.search(
            r"\bpublic\s+static\s+(?P<builder>[A-Z][A-Za-z0-9_$]*(?:\s*<[^;{}()]+>)?)\s+"
            r"builder\s*\((?P<params>[^)]*)\)",
            code,
        )
        if not builder_match:
            cls._SOURCE_BUILDER_RECIPE_CACHE[cache_key] = None
            return None
        builder_type_raw = str(builder_match.group("builder") or "").strip()
        builder_type = builder_type_raw.split("<", 1)[0].rsplit(".", 1)[-1]
        builder_params = str(builder_match.group("params") or "").strip()
        builder_line = code.count("\n", 0, builder_match.start()) + 1
        build_match = re.search(
            rf"\bpublic\s+{re.escape(simple)}\s+(?P<terminal>build|get)\s*\(\s*\)",
            code,
        )
        if not build_match:
            cls._SOURCE_BUILDER_RECIPE_CACHE[cache_key] = None
            return None
        terminal_name = str(build_match.group("terminal") or "build")
        build_line = code.count("\n", 0, build_match.start()) + 1
        setter_re = re.compile(
            rf"\bpublic\s+{re.escape(builder_type)}(?:\s*<[^;{{}}()]+>)?\s+"
            r"(?P<name>[a-zA-Z_$][A-Za-z0-9_$]*)\s*\((?P<params>[^)]*)\)"
        )
        setters: list[dict[str, Any]] = []
        for method_match in setter_re.finditer(code):
            method_name = str(method_match.group("name") or "").strip()
            if method_name in {"build", "get"}:
                continue
            params_text = str(method_match.group("params") or "").strip()
            params = [] if not params_text else cls._split_top_level_args(params_text)
            if len(params) != 1:
                continue
            line_no = code.count("\n", 0, method_match.start()) + 1
            setters.append({
                "name": method_name,
                "param": params[0].strip(),
                "line": line_no,
            })

        # A concrete builder commonly inherits its fluent configuration API
        # from a generic abstract builder.  Treat those methods as callable
        # only when the target builder's source names one unambiguous parent
        # and that parent's source proves a public, one-argument, fluent
        # method.  Without this evidence the later sanitizer can incorrectly
        # erase valid setup from an otherwise correct generated test.
        builder_decl = re.search(
            rf"\bclass\s+{re.escape(builder_type)}\b[^{{;]*?\bextends\s+"
            r"(?P<parent>[A-Za-z_$][A-Za-z0-9_$.]*)",
            code,
        )
        if builder_decl is not None:
            parent_simple = str(builder_decl.group("parent") or "").rsplit(".", 1)[-1]
            symbol_index = cls._build_symbol_index(project_root)
            parent_fqns = list(symbol_index.get(parent_simple) or [])
            if len(parent_fqns) == 1:
                parent_fqn = parent_fqns[0]
                parent_resolved = cls._project_source_type_body_for_fqn(
                    project_root,
                    parent_fqn,
                )
                if parent_resolved is not None:
                    parent_source, _parent_body = parent_resolved
                    parent_class = parent_fqn.replace("$", ".").rsplit(".", 1)[-1]
                    for block in cls()._collect_method_blocks(
                        parent_source,
                        class_name=parent_class,
                    ):
                        if str(block.get("access") or "") != "public":
                            continue
                        signature = str(block.get("signature") or "")
                        method_name = str(block.get("name") or "").strip()
                        params = cls._signature_param_types(signature)
                        return_match = re.search(
                            rf"\bpublic\s+(?P<return>[A-Za-z_$][A-Za-z0-9_$.<>?]*)\s+"
                            rf"{re.escape(method_name)}\s*\(",
                            signature,
                        )
                        return_type = (
                            str(return_match.group("return") or "").strip()
                            if return_match is not None
                            else ""
                        )
                        if (
                            len(params) != 1
                            or not cls._looks_like_configuration_method(
                                method_name,
                                params[0],
                                return_type,
                                builder_type,
                            )
                        ):
                            continue
                        setters.append({
                            "name": method_name,
                            "param": params[0],
                            "line": None,
                            "source_file": str(
                                cls._find_project_source_for_fqn(
                                    project_root,
                                    parent_fqn,
                                )
                                or ""
                            ),
                            "inherited_from": parent_fqn,
                        })
        deduped_setters: list[dict[str, Any]] = []
        seen_setters: set[tuple[str, str]] = set()
        for setter in setters:
            key = (
                str(setter.get("name") or "").strip(),
                str(setter.get("param") or "").strip(),
            )
            if not all(key) or key in seen_setters:
                continue
            seen_setters.add(key)
            deduped_setters.append(setter)
        recipe = {
            "type": simple,
            "builder_type": builder_type,
            "builder_params": builder_params,
            "builder_line": builder_line,
            "terminal_name": terminal_name,
            "build_line": build_line,
            "setters": deduped_setters[:20],
            "source_file": str(source_file),
        }
        cls._SOURCE_BUILDER_RECIPE_CACHE[cache_key] = recipe
        return recipe

    @classmethod
    def _rewrite_guarded_removed_call_builder_setup(
        cls,
        java_code: str,
        *,
        project_root: Path,
        target_fqn: str,
        mutation_feedback: dict[str, Any] | None,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Close one source-proven builder state needed by a removed call.

        This mutation-only prepatch follows an exact Java data-flow chain:
        callee guard getter -> getter return field/value -> inherited builder
        method writing that field -> target builder factory/terminal.  It never
        selects a method by semantic naming and leaves ambiguous chains alone.
        """

        if not java_code or not project_root or not target_fqn:
            return java_code, []
        objectives = [
            row
            for row in list(
                (mutation_feedback or {}).get("mutation_objectives") or []
            )
            if isinstance(row, dict)
        ]
        if len(objectives) != 1:
            return java_code, []
        facts = objectives[0].get("facts")
        if not isinstance(facts, dict):
            return java_code, []
        line_reachability_retry = bool(
            facts.get("mutation_line_reachability_retry")
        )
        if (
            str(facts.get("status") or "").strip().upper() != "NO_COVERAGE"
            and not line_reachability_retry
        ):
            return java_code, []
        root = Path(project_root)
        symbol_index = symbol_index or cls._build_symbol_index(root)

        def _method_blocks_for_fqn(
            fqn: str,
            method_name: str,
        ) -> list[dict[str, object]]:
            resolved = cls._project_source_type_body_for_fqn(root, fqn)
            if resolved is None:
                return []
            source_text, _body = resolved
            class_leaf = fqn.replace("$", ".").rsplit(".", 1)[-1]
            return [
                block
                for block in cls()._collect_method_blocks(
                    source_text,
                    class_name=class_leaf,
                )
                if str(block.get("name") or "") == method_name
                and len(
                    cls._signature_param_types(
                        str(block.get("signature") or "")
                    )
                ) == 0
            ]

        # A call made by the target can only resolve on its receiver hierarchy.
        # Restricting both callee and guard lookup to that hierarchy avoids
        # unrelated package-local wrappers with the same method name.
        candidate_fqns: list[str] = []
        hierarchy_seen: set[str] = set()
        current_fqn = target_fqn
        while current_fqn and current_fqn not in hierarchy_seen:
            hierarchy_seen.add(current_fqn)
            candidate_fqns.append(current_fqn)
            resolved = cls._project_source_type_body_for_fqn(root, current_fqn)
            if resolved is None:
                break
            current_source, _current_body = resolved
            current_leaf = current_fqn.replace("$", ".").rsplit(".", 1)[-1]
            declaration = re.search(
                rf"\b(?:class|interface)\s+{re.escape(current_leaf)}\b"
                rf"[^{{;]*?\bextends\s+"
                rf"(?P<parent>[A-Za-z_$][A-Za-z0-9_$.]*)",
                cls._strip_java_comments_and_strings(current_source),
            )
            if declaration is None:
                break
            parent_simple = str(declaration.group("parent") or "").rsplit(".", 1)[-1]
            parent_fqns = list(symbol_index.get(parent_simple) or [])
            if len(parent_fqns) != 1:
                break
            current_fqn = parent_fqns[0]

        callee = facts.get("removed_call_callee_evidence")
        declaration = (
            " ".join(str(callee.get("source_declaration") or "").split())
            if isinstance(callee, dict)
            else ""
        )
        if not declaration:
            normalized_mutator = re.sub(
                r"[^a-z0-9]+",
                "-",
                str(facts.get("mutator") or "").lower(),
            ).strip("-")
            if normalized_mutator not in {
                "voidmethodcallmutator",
                "remove-void-call",
            }:
                return java_code, []
            exact_source_line = " ".join(
                str(
                    facts.get("authoritative_source_line")
                    or facts.get("source_line")
                    or facts.get("program_fact")
                    or ""
                ).split()
            )
            call_match = re.search(
                r"(?<![\w$.])(?P<callee>[A-Za-z_$][A-Za-z0-9_$]*)"
                r"\s*\(\s*\)\s*;",
                exact_source_line,
            )
            if call_match is None:
                return java_code, []
            callee_name = str(call_match.group("callee") or "")
            callee_rows = [
                (fqn, block)
                for fqn in candidate_fqns
                for block in _method_blocks_for_fqn(fqn, callee_name)
            ]
            if len(callee_rows) != 1:
                return java_code, []
            declaration = " ".join(
                str(callee_rows[0][1].get("body") or "").split()
            )

        guard_match = re.search(
            r"\bif\s*\(\s*(?P<getter>[A-Za-z_$][A-Za-z0-9_$]*)"
            r"\s*\(\s*\)\s*\)\s*\{",
            declaration,
        )
        thrown = re.search(
            r"\bthrow\s+new\s+(?P<type>[A-Za-z_$][A-Za-z0-9_$.]*)\s*\(",
            declaration,
        )
        if guard_match is None or thrown is None:
            return java_code, []
        exception_simple = str(thrown.group("type") or "").rsplit(".", 1)[-1]
        if not re.search(
            rf"\bassertThrows\s*\(\s*(?:[A-Za-z_$][A-Za-z0-9_$.]*\.)?"
            rf"{re.escape(exception_simple)}\s*\.class\b",
            java_code,
        ):
            return java_code, []

        getter_name = str(guard_match.group("getter") or "")
        getter_rows: list[tuple[str, dict[str, object]]] = []
        for fqn in candidate_fqns:
            for block in _method_blocks_for_fqn(fqn, getter_name):
                getter_rows.append((fqn, block))
        if len(getter_rows) != 1:
            return java_code, []
        getter_owner, getter_block = getter_rows[0]
        getter_body = str(getter_block.get("body") or "")
        equality = re.search(
            r"\breturn\s+(?:(?:this\.)?(?P<field1>[A-Za-z_$][A-Za-z0-9_$]*)"
            r"\s*==\s*(?P<value1>[A-Za-z_$][A-Za-z0-9_$.]*)|"
            r"(?P<value2>[A-Za-z_$][A-Za-z0-9_$.]*)\s*==\s*"
            r"(?:this\.)?(?P<field2>[A-Za-z_$][A-Za-z0-9_$]*))\s*;",
            getter_body,
        )
        boolean_field = re.search(
            r"\breturn\s+(?:this\.)?(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)\s*;",
            getter_body,
        )
        if equality is not None:
            state_field = str(
                equality.group("field1") or equality.group("field2") or ""
            )
            required_value = str(
                equality.group("value1") or equality.group("value2") or ""
            )
        elif boolean_field is not None:
            state_field = str(boolean_field.group("field") or "")
            required_value = "true"
        else:
            return java_code, []
        if not state_field or not required_value:
            return java_code, []

        recipe = cls._source_builder_recipe_for_fqn(root, target_fqn)
        if not recipe:
            return java_code, []
        builder_type = str(recipe.get("builder_type") or "").strip()
        terminal = str(recipe.get("terminal_name") or "").strip()
        target_simple = target_fqn.rsplit(".", 1)[-1]
        if not builder_type or not terminal:
            return java_code, []
        target_source_file = cls._find_project_source_for_fqn(root, target_fqn)
        if target_source_file is None:
            return java_code, []
        try:
            target_source = target_source_file.read_text(
                encoding="utf-8",
                errors="ignore",
            )
        except OSError:
            return java_code, []
        builder_decl = re.search(
            rf"\bclass\s+{re.escape(builder_type)}\b[^{{;]*\bextends\s+"
            rf"(?P<parent>[A-Za-z_$][A-Za-z0-9_$.]*)",
            cls._strip_java_comments_and_strings(target_source),
        )
        if builder_decl is None:
            return java_code, []
        parent_simple = str(builder_decl.group("parent") or "").rsplit(".", 1)[-1]
        parent_fqns = list(symbol_index.get(parent_simple) or [])
        if len(parent_fqns) != 1:
            return java_code, []
        parent_fqn = parent_fqns[0]
        parent_resolved = cls._project_source_type_body_for_fqn(root, parent_fqn)
        if parent_resolved is None:
            return java_code, []
        parent_source, _parent_body = parent_resolved
        parent_leaf = parent_fqn.replace("$", ".").rsplit(".", 1)[-1]
        setter_rows: list[tuple[str, str]] = []
        for block in cls()._collect_method_blocks(
            parent_source,
            class_name=parent_leaf,
        ):
            signature = str(block.get("signature") or "")
            param_names = cls._source_method_param_names(signature)
            param_types = cls._signature_param_types(signature)
            if (
                str(block.get("access") or "") != "public"
                or len(param_names) != 1
                or len(param_types) != 1
            ):
                continue
            parameter = param_names[0]
            body = str(block.get("body") or "")
            if not re.search(
                rf"\bthis\s*\.\s*{re.escape(state_field)}\s*=\s*"
                rf"{re.escape(parameter)}\b",
                body,
            ):
                continue
            value_type = (
                required_value.rsplit(".", 1)[0].rsplit(".", 1)[-1]
                if "." in required_value
                else "boolean" if required_value in {"true", "false"}
                else ""
            )
            parameter_type = cls._simple_type_name(param_types[0])
            if value_type and parameter_type != value_type:
                continue
            setter_rows.append((str(block.get("name") or ""), parameter_type))
        setter_rows = list(dict.fromkeys(setter_rows))
        if len(setter_rows) != 1:
            return java_code, []
        setter_name, _setter_type = setter_rows[0]

        qualified_value = required_value
        if "." in required_value:
            value_owner, value_member = required_value.rsplit(".", 1)
            value_fqns = list(symbol_index.get(value_owner) or [])
            if len(value_fqns) != 1:
                return java_code, []
            qualified_value = f"{value_fqns[0]}.{value_member}"
        chain = re.compile(
            rf"\b{re.escape(target_simple)}\s*\.\s*builder\s*\(\s*\)"
            rf"(?P<middle>(?:\s*\.\s*[A-Za-z_$][A-Za-z0-9_$]*\s*"
            rf"\([^;]*?\))*)\s*\.\s*{re.escape(terminal)}\s*\(\s*\)"
        )
        matches = list(chain.finditer(java_code))
        if len(matches) == 1:
            match = matches[0]
            if re.search(rf"\.\s*{re.escape(setter_name)}\s*\(", match.group(0)):
                return java_code, [
                    "guarded-removed-call-builder-setup:"
                    f"{getter_owner}.{getter_name}->{parent_fqn}.{setter_name}"
                    f"({qualified_value})"
                ]
            patched_chain = re.sub(
                rf"\.\s*{re.escape(terminal)}\s*\(\s*\)\s*$",
                f".{setter_name}({qualified_value}).{terminal}()",
                match.group(0),
            )
            patched = (
                java_code[: match.start()]
                + patched_chain
                + java_code[match.end() :]
            )
        elif not matches:
            # The same source proof can safely replace one default receiver
            # construction.  This remains deliberately narrower than general
            # fixture synthesis: exactly one no-arg construction must exist,
            # and the replacement is the already-proven builder state path.
            constructor = re.compile(
                rf"\bnew\s+{re.escape(target_simple)}\s*\(\s*\)"
            )
            constructors = list(constructor.finditer(java_code))
            if len(constructors) != 1:
                return java_code, []
            match = constructors[0]
            patched_chain = (
                f"{target_simple}.builder().{setter_name}"
                f"({qualified_value}).{terminal}()"
            )
            patched = (
                java_code[: match.start()]
                + patched_chain
                + java_code[match.end() :]
            )
        else:
            return java_code, []
        return patched, [
            "guarded-removed-call-builder-setup:"
            f"{getter_owner}.{getter_name}->{parent_fqn}.{setter_name}"
            f"({qualified_value})"
        ]

    @classmethod
    def _source_builder_string_payload_expression_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
        *,
        string_expression: str,
    ) -> str:
        """Return a source-visible expression that builds ``fqn`` from a string.

        This is used only as a structural prepatch for generated builder chains
        whose missing method clearly carried a string payload.  It relies on a
        public builder method such as ``text(String)``, ``content(String)``, or
        ``value(String)`` in the project source; otherwise it returns empty.
        """
        recipe = cls._source_builder_recipe_for_fqn(project_root, fqn)
        if not recipe:
            return ""
        setters = [item for item in list(recipe.get("setters") or []) if isinstance(item, dict)]
        preferred = {"text": 0, "content": 1, "value": 2, "data": 3, "message": 4}
        candidates: list[tuple[int, str]] = []
        for setter in setters:
            name = str(setter.get("name") or "").strip()
            params = cls._split_top_level_args(str(setter.get("param") or ""))
            if len(params) != 1:
                continue
            param_type = cls._simple_type_name(" ".join(str(params[0] or "").split()[:-1]) or str(params[0] or ""))
            if param_type not in {"String", "CharSequence"}:
                continue
            rank = preferred.get(name.lower(), 10)
            candidates.append((rank, name))
        if not candidates:
            return ""
        candidates.sort(key=lambda item: (item[0], item[1]))
        setter_name = candidates[0][1]
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        terminal = str(recipe.get("terminal_name") or "build").strip() or "build"
        return f"{fqn if '.' in fqn else simple}.builder().{setter_name}({string_expression}).{terminal}()"

    @classmethod
    def _source_public_string_constructor_expression_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
        *,
        string_expression: str,
    ) -> str:
        """Return a source-proven public one-string constructor expression."""
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            return ""
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return ""
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        ctor_re = re.compile(
            rf"\bpublic\s+{re.escape(simple)}\s*\(([^)]*)\)",
            re.DOTALL,
        )
        for match in ctor_re.finditer(code):
            params = cls._split_top_level_args(str(match.group(1) or "").strip())
            if len(params) != 1:
                continue
            param = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", params[0]).strip()
            parts = param.split()
            param_type = cls._simple_type_name(" ".join(parts[:-1]) if len(parts) > 1 else param)
            if param_type in {"String", "CharSequence"}:
                return f"new {fqn}({string_expression})"
        return ""

    @classmethod
    def _source_string_payload_expression_for_expected_type(
        cls,
        project_root: Path,
        expected_type: str,
        *,
        string_expression: str,
        symbol_index: dict[str, list[str]] | None = None,
        preferred_package: str = "",
    ) -> str:
        """Build a source-backed value of ``expected_type`` from a string.

        The method is deliberately conservative: it supports direct String-like
        parameters and project source types/implementations with public builders
        that have one String payload setter.  It does not infer domain-specific
        conversion rules.
        """
        raw = str(expected_type or "").strip()
        if not raw:
            return ""
        raw = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", raw)
        raw = re.sub(r"\b(?:final|volatile|transient)\b\s*", "", raw).strip()
        simple = cls._simple_type_name(raw)
        if simple in {"String", "CharSequence", "Object"}:
            return str(string_expression or "").strip()
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(project_root)
        candidates = list(symbol_index.get(simple) or [])
        raw_base = raw.split("<", 1)[0].replace("[]", "").strip()
        fqn = ""
        if "." in raw_base and cls._find_project_source_for_fqn(project_root, raw_base):
            fqn = raw_base
        if not fqn:
            fqn = cls._resolve_best_fqn(
                simple,
                candidates=candidates,
                current_package=preferred_package,
                source_package=preferred_package,
            )
        if fqn:
            direct = cls._source_builder_string_payload_expression_for_fqn(
                project_root,
                fqn,
                string_expression=string_expression,
            )
            if direct:
                return direct
            direct = cls._source_public_string_constructor_expression_for_fqn(
                project_root,
                fqn,
                string_expression=string_expression,
            )
            if direct:
                return direct
        expected_simple = simple
        try:
            source_index = cls._build_source_file_index(cls._find_scan_root(project_root))
        except Exception:
            source_index = {}
        ranked_paths = list(source_index.items())
        expected_package = fqn.rsplit(".", 1)[0] if fqn and "." in fqn else ""
        scope_prefixes = cls._dedupe_ordered(
            [
                *cls._preferred_source_package_prefixes(expected_package),
                *cls._preferred_source_package_prefixes(preferred_package),
            ]
        )
        if scope_prefixes:
            ranked_paths = [
                item for item in ranked_paths
                if cls._fqn_in_preferred_source_scope(str(item[0] or ""), scope_prefixes)
            ]
        if preferred_package or expected_package:
            ranked_paths.sort(
                key=lambda item: (
                    0 if expected_package and str(item[0]).startswith(expected_package + ".") else 1,
                    0 if preferred_package and str(item[0]).startswith(preferred_package + ".") else 1,
                    item[0],
                )
            )
        impl_re = re.compile(
            rf"\b(?:public\s+)?(?:final\s+)?(?:class|record)\s+([A-Z][A-Za-z0-9_$]*)\b[^\{{;]*"
            rf"\b(?:implements|extends)\b[^\{{;]*\b{re.escape(expected_simple)}\b"
        )
        implementation_payloads: list[tuple[int, str, str]] = []
        setter_rank = {"text": 0, "value": 1, "data": 2, "message": 3, "content": 4}
        for impl_fqn, path in ranked_paths:
            try:
                text = path.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            stripped = cls._strip_java_comments_and_strings(text)
            match = impl_re.search(stripped)
            if not match:
                continue
            impl_simple = match.group(1)
            if re.search(rf"\babstract\s+class\s+{re.escape(impl_simple)}\b", stripped):
                continue
            expr = cls._source_builder_string_payload_expression_for_fqn(
                project_root,
                impl_fqn,
                string_expression=string_expression,
            )
            if not expr:
                expr = cls._source_public_string_constructor_expression_for_fqn(
                    project_root,
                    impl_fqn,
                    string_expression=string_expression,
                )
            if expr:
                setter_match = re.search(r"\.builder\s*\(\s*\)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(", expr)
                setter_name = str(setter_match.group(1) if setter_match else "")
                implementation_payloads.append((setter_rank.get(setter_name.lower(), 10), impl_fqn, expr))
        if implementation_payloads:
            implementation_payloads.sort(key=lambda item: (item[0], item[1]))
            return implementation_payloads[0][2]
        return ""

    @classmethod
    def _source_builder_required_fields_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
        *,
        recipe: dict[str, Any],
    ) -> list[str]:
        """Return builder fields directly guarded as non-null in ``build()``."""
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            return []
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return []
        # Keep string literals because checkNotNullParam names the guarded
        # builder field in its first string argument.
        code = source_text
        owner = fqn.rsplit(".", 1)[-1].split("$")[-1]
        terminal = str(recipe.get("terminal_name") or "build").strip() or "build"
        match = re.search(
            rf"\bpublic\s+{re.escape(owner)}\s+{re.escape(terminal)}\s*\(\s*\)\s*\{{",
            code,
        )
        if not match:
            return []
        open_brace = code.find("{", match.end() - 1)
        close_brace = cls._find_matching_brace(code, open_brace)
        if open_brace < 0 or close_brace <= open_brace:
            return []
        block = code[open_brace + 1:close_brace]
        fields: list[str] = []
        for required in re.finditer(
            r"(?:checkNotNullParam\s*\(\s*\"([A-Za-z_$][A-Za-z0-9_$]*)\"\s*,"
            r"|Objects\.requireNonNull\s*\(\s*([A-Za-z_$][A-Za-z0-9_$]*))",
            block,
        ):
            name = str(required.group(1) or required.group(2) or "").strip()
            if name and name not in fields:
                fields.append(name)
        for required in re.finditer(
            r"\b([A-Za-z_$][A-Za-z0-9_$]*)\s*==\s*null\s*\)\s*\{?"
            r"[^{};]{0,240}\bthrow\s+new\s+(?:IllegalArgumentException|NullPointerException)",
            block,
            re.DOTALL,
        ):
            name = str(required.group(1) or "").strip()
            if name and name not in fields:
                fields.append(name)
        visible_setters = {
            str(item.get("name") or "").strip()
            for item in list(recipe.get("setters") or [])
            if isinstance(item, dict) and str(item.get("name") or "").strip()
        }
        return [name for name in fields if name in visible_setters]

    @classmethod
    def _source_enum_constant_expression(
        cls,
        project_root: Path,
        raw_type: str,
        *,
        owner_fqn: str,
        symbol_index: dict[str, list[str]],
        preferred_package: str,
    ) -> str:
        simple = cls._simple_type_name(raw_type)
        if not simple:
            return ""

        def _first_constant(source_text: str, enum_name: str) -> str:
            code = cls._strip_java_comments_and_strings(source_text)
            match = re.search(rf"\benum\s+{re.escape(enum_name)}\b[^\{{]*\{{", code)
            if not match:
                return ""
            open_brace = code.find("{", match.end() - 1)
            close_brace = cls._find_matching_brace(code, open_brace)
            if open_brace < 0 or close_brace <= open_brace:
                return ""
            constants = code[open_brace + 1:close_brace].split(";", 1)[0]
            constant = re.search(r"\b([A-Z][A-Z0-9_]*)\b", constants)
            return str(constant.group(1) if constant else "")

        owner_source = cls._find_project_source_for_fqn(project_root, owner_fqn)
        if owner_source is not None:
            try:
                text = owner_source.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                text = ""
            constant = _first_constant(text, simple)
            if constant:
                return f"{owner_fqn}.{simple}.{constant}"
        enum_fqn = cls._resolve_best_fqn(
            simple,
            candidates=list(symbol_index.get(simple) or []),
            current_package=preferred_package,
            source_package=preferred_package,
        )
        if not enum_fqn:
            return ""
        enum_source = cls._find_project_source_for_fqn(project_root, enum_fqn)
        if enum_source is None:
            return ""
        try:
            text = enum_source.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return ""
        constant = _first_constant(text, simple)
        return f"{enum_fqn}.{constant}" if constant else ""

    @classmethod
    def _source_required_builder_value_expression(
        cls,
        project_root: Path,
        owner_fqn: str,
        param: str,
        *,
        symbol_index: dict[str, list[str]],
        preferred_package: str,
    ) -> str:
        cleaned = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", str(param or "")).strip()
        parts = cleaned.split()
        declared = " ".join(parts[:-1]) if len(parts) > 1 else cleaned
        declared = declared.replace("...", "[]").strip()
        simple = cls._simple_type_name(declared)
        literals = {
            "String": '"generated"',
            "CharSequence": '"generated"',
            "boolean": "true",
            "Boolean": "true",
            "byte": "(byte) 1",
            "Byte": "(byte) 1",
            "short": "(short) 1",
            "Short": "(short) 1",
            "int": "1",
            "Integer": "1",
            "long": "1L",
            "Long": "1L",
            "float": "1.0f",
            "Float": "1.0f",
            "double": "1.0d",
            "Double": "1.0d",
        }
        if simple in literals:
            return literals[simple]
        collection = re.search(
            r"\b(?:java\.util\.)?(?:List|Collection|Iterable|Set)\s*<\s*(.+)\s*>\s*$",
            declared,
        )
        if collection:
            element_declared = str(collection.group(1) or "").strip()
            element_simple = cls._simple_type_name(element_declared)
            owner_package = owner_fqn.rsplit(".", 1)[0] if "." in owner_fqn else preferred_package
            element_fqn = cls._resolve_best_fqn(
                element_simple,
                candidates=list(symbol_index.get(element_simple) or []),
                current_package=owner_package,
                source_package=owner_package,
            ) or element_declared.split("<", 1)[0].strip()
            element_expr = cls._source_string_payload_expression_for_expected_type(
                project_root,
                element_fqn,
                string_expression='"generated"',
                symbol_index=symbol_index,
                preferred_package=preferred_package,
            )
            if not element_expr:
                return ""
            generic_suffix = (
                element_declared[element_declared.find("<"):]
                if "<" in element_declared
                else ""
            )
            witness = element_fqn + generic_suffix
            factory = "singleton" if "Set" in declared else "singletonList"
            return f"java.util.Collections.<{witness}>{factory}({element_expr})"
        enum_expr = cls._source_enum_constant_expression(
            project_root,
            declared,
            owner_fqn=owner_fqn,
            symbol_index=symbol_index,
            preferred_package=preferred_package,
        )
        if enum_expr:
            return enum_expr
        return cls._source_string_payload_expression_for_expected_type(
            project_root,
            declared,
            string_expression='"generated"',
            symbol_index=symbol_index,
            preferred_package=preferred_package,
        )

    @classmethod
    def _rewrite_missing_required_builder_fields_from_source(
        cls,
        java_code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Fill source-guarded builder fields using only source-proven values."""
        if not java_code or not project_root or ".builder()" not in java_code:
            return java_code, []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        symbol_index = symbol_index or {}
        imports = cls._extract_source_import_map(java_code)
        package_match = cls._RE_PACKAGE_DECL.search(java_code)
        preferred_package = str(package_match.group(1) if package_match else "")
        replacements: list[tuple[int, str, list[str]]] = []
        for match in re.finditer(r"\b([A-Z][A-Za-z0-9_$]*)\s*\.\s*builder\s*\(\s*\)", java_code):
            simple = str(match.group(1) or "").strip()
            fqn = imports.get(simple) or cls._resolve_best_fqn(
                simple,
                candidates=list(symbol_index.get(simple) or []),
                current_package=preferred_package,
                source_package=preferred_package,
            )
            if not fqn:
                continue
            recipe = cls._source_builder_recipe_for_fqn(root, fqn)
            if not recipe:
                continue
            terminal = str(recipe.get("terminal_name") or "build").strip() or "build"
            cursor = match.end()
            calls: list[tuple[str, int]] = []
            terminal_start = -1
            while cursor < len(java_code):
                call = re.match(
                    r"\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(",
                    java_code[cursor:],
                )
                if not call:
                    break
                name = str(call.group(1) or "")
                dot_start = cursor + call.start()
                open_idx = cursor + call.end() - 1
                close_idx = cls._find_matching_paren(java_code, open_idx)
                if close_idx < 0:
                    break
                calls.append((name, dot_start))
                cursor = close_idx + 1
                if name == terminal:
                    terminal_start = dot_start
                    break
            if terminal_start < 0:
                continue
            existing = {name for name, _ in calls}
            required = cls._source_builder_required_fields_for_fqn(
                root,
                fqn,
                recipe=recipe,
            )
            missing = [name for name in required if name not in existing]
            if not missing:
                continue
            setters_by_name: dict[str, list[str]] = {}
            for setter in list(recipe.get("setters") or []):
                if not isinstance(setter, dict):
                    continue
                name = str(setter.get("name") or "").strip()
                param = str(setter.get("param") or "").strip()
                if name and param:
                    setters_by_name.setdefault(name, []).append(param)
            inserted: list[str] = []
            labels: list[str] = []
            for name in missing:
                params = setters_by_name.get(name, [])
                value = ""
                for param in params:
                    value = cls._source_required_builder_value_expression(
                        root,
                        fqn,
                        param,
                        symbol_index=symbol_index,
                        preferred_package=preferred_package,
                    )
                    if value:
                        break
                if not value:
                    continue
                inserted.append(f".{name}({value})")
                labels.append(f"{simple}.{name}:source-required-builder-field")
            if inserted:
                replacements.append((terminal_start, "".join(inserted), labels))
        if not replacements:
            return java_code, []
        patched = java_code
        applied: list[str] = []
        for offset, insertion, labels in sorted(replacements, key=lambda item: item[0], reverse=True):
            patched = patched[:offset] + insertion + patched[offset:]
            applied.extend(labels)
        return patched, sorted(set(applied))[:12]

    @classmethod
    def _source_type_assignable_to_expected(
        cls,
        project_root: Path,
        actual_type: str,
        expected_type: str,
        *,
        symbol_index: dict[str, list[str]] | None = None,
        preferred_package: str = "",
    ) -> bool:
        """Return true when source evidence proves ``actual`` fits ``expected``.

        This is intentionally shallow and source-backed. It handles the common
        generated-test case where a concrete builder expression such as
        ``TextBlock.builder().build()`` is passed to a setter declared as
        ``ContentBlock``.  If we cannot close the evidence chain, callers should
        not rewrite on this basis.
        """
        def _declared_type_part(value: str) -> str:
            item = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", str(value or "")).strip()
            item = re.sub(r"\b(?:final|volatile|transient)\b\s*", "", item).strip()
            item = item.replace("...", "[]")
            if " " in item:
                left, right = item.rsplit(" ", 1)
                if re.fullmatch(r"[a-zA-Z_$][A-Za-z0-9_$]*", right.strip()):
                    item = left.strip()
            return item

        actual_simple = cls._simple_type_name(_declared_type_part(str(actual_type or "")))
        expected_simple = cls._simple_type_name(_declared_type_part(str(expected_type or "")))
        if not actual_simple or not expected_simple:
            return False
        if actual_simple == expected_simple:
            return True
        if expected_simple in {"Object"}:
            return True
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(project_root)
        actual_fqn = cls._resolve_best_fqn(
            actual_simple,
            candidates=list((symbol_index or {}).get(actual_simple) or []),
            current_package=preferred_package,
            source_package=preferred_package,
        )
        expected_fqn = cls._resolve_best_fqn(
            expected_simple,
            candidates=list((symbol_index or {}).get(expected_simple) or []),
            current_package=preferred_package,
            source_package=preferred_package,
        )
        if not actual_fqn:
            return False
        source_file = cls._find_project_source_for_fqn(project_root, actual_fqn)
        if source_file is None:
            return False
        try:
            text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return False
        stripped = cls._strip_java_comments_and_strings(text)
        actual_leaf = actual_fqn.rsplit(".", 1)[-1].split("$")[-1]
        header_match = re.search(
            rf"\b(?:public\s+|protected\s+|private\s+)?(?:abstract\s+|final\s+|sealed\s+|non-sealed\s+)*"
            rf"(?:class|interface|record|enum)\s+{re.escape(actual_leaf)}\b(?P<header>[^\{{;]*)",
            stripped,
            re.DOTALL,
        )
        if not header_match:
            return False
        header = str(header_match.group("header") or "")
        expected_tokens = {expected_simple}
        if expected_fqn:
            expected_tokens.add(expected_fqn)
        for token in expected_tokens:
            if token and re.search(
                rf"\b(?:extends|implements|permits)\b[^\{{;]*\b{re.escape(token)}\b",
                header,
            ):
                return True
        return False

    @classmethod
    def _builder_expression_owner_simple(cls, arg_expr: str) -> tuple[str, bool]:
        """Return (builder owner simple name, has terminal build/get)."""
        expr = str(arg_expr or "").strip()
        match = re.match(
            r"(?P<owner>(?:[a-z_][A-Za-z0-9_$]*\.)*[A-Z][A-Za-z0-9_$]*)\s*\.\s*builder\s*\(\s*\)(?P<body>.*)$",
            expr,
            re.DOTALL,
        )
        if not match:
            return "", False
        owner = str(match.group("owner") or "").strip().rsplit(".", 1)[-1]
        has_terminal = bool(re.search(r"\.\s*(?:build|get)\s*\(\s*\)\s*$", expr))
        return owner, has_terminal

    @classmethod
    def _argument_source_assignable_to_param(
        cls,
        project_root: Path,
        arg_expr: str,
        param_text: str,
        *,
        symbol_index: dict[str, list[str]] | None = None,
        preferred_package: str = "",
    ) -> bool:
        """Return true when an argument expression already fits a source param."""
        expr = str(arg_expr or "").strip()
        param = str(param_text or "").strip()
        if not expr or not param:
            return False
        list_match = re.search(
            r"\b(?:java\.util\.)?(?:List|Collection|Iterable)\s*<\s*([A-Z][A-Za-z0-9_$.]*)\s*>",
            param,
        )
        if list_match:
            element_type = list_match.group(1)
            inner_expr = ""
            collection_match = re.search(
                r"(?:java\.util\.)?(?:Collections\.\s*singletonList|List\.\s*of)\s*\((?P<inner>.*)\)\s*$",
                expr,
                re.DOTALL,
            )
            typed_singleton_match = re.search(
                r"(?:java\.util\.)?Collections\s*\.\s*<\s*(?P<type>[A-Z][A-Za-z0-9_$.]*)\s*>\s*singletonList\s*\((?P<inner>.*)\)\s*$",
                expr,
                re.DOTALL,
            )
            if typed_singleton_match:
                typed = typed_singleton_match.group("type")
                if cls._source_type_assignable_to_expected(
                    project_root,
                    typed,
                    element_type,
                    symbol_index=symbol_index,
                    preferred_package=preferred_package,
                ):
                    return True
                inner_expr = str(typed_singleton_match.group("inner") or "").strip()
            elif collection_match:
                inner_expr = str(collection_match.group("inner") or "").strip()
            if inner_expr:
                owner, has_terminal = cls._builder_expression_owner_simple(inner_expr)
                if owner and has_terminal:
                    return cls._source_type_assignable_to_expected(
                        project_root,
                        owner,
                        element_type,
                        symbol_index=symbol_index,
                        preferred_package=preferred_package,
                    )
            return False
        raw_type = cls._simple_type_name(" ".join(param.split()[:-1]) or param)
        owner, has_terminal = cls._builder_expression_owner_simple(expr)
        if owner and has_terminal:
            return cls._source_type_assignable_to_expected(
                project_root,
                owner,
                raw_type,
                symbol_index=symbol_index,
                preferred_package=preferred_package,
            )
        new_match = re.match(r"new\s+(?P<owner>(?:[a-z_][A-Za-z0-9_$]*\.)*[A-Z][A-Za-z0-9_$]*)\s*\(", expr)
        if new_match:
            return cls._source_type_assignable_to_expected(
                project_root,
                str(new_match.group("owner") or "").rsplit(".", 1)[-1],
                raw_type,
                symbol_index=symbol_index,
                preferred_package=preferred_package,
            )
        return False

    @classmethod
    def _source_builder_payload_replacement_for_missing_call(
        cls,
        project_root: Path,
        owner_fqn: str,
        *,
        missing_method: str,
        arg_text: str,
        recipe: dict[str, Any],
        symbol_index: dict[str, list[str]] | None = None,
        preferred_package: str = "",
        local_variable_types: dict[str, str] | None = None,
    ) -> str:
        """Replace a missing fluent payload method with a compatible setter.

        Example shape, generalized:
        ``Value.builder().textPayload("x").build()`` may become
        ``Value.builder().payload(Collections.<Payload>singletonList(
        PayloadImpl.builder().text("x").build())).build()`` when project source
        proves the actual builder has ``payload(List<Payload>)`` and a concrete
        payload implementation has a String builder setter.
        """
        args = cls._split_top_level_args(str(arg_text or ""))
        if len(args) != 1 or not str(args[0]).strip():
            return ""
        arg_expr = str(args[0]).strip()
        missing_lower = str(missing_method or "").lower()
        setters = [item for item in list(recipe.get("setters") or []) if isinstance(item, dict)]
        ranked: list[tuple[int, dict[str, Any]]] = []
        for setter in setters:
            setter_name = str(setter.get("name") or "").strip()
            if not setter_name:
                continue
            setter_lower = setter_name.lower()
            if setter_lower not in missing_lower and missing_lower not in setter_lower:
                # Keep only semantically close payload-like names.
                if setter_lower not in {"content", "value", "payload", "data", "text", "message"}:
                    continue
            rank = 0 if setter_lower in missing_lower else 1
            if setter_lower in {"content", "value", "payload", "text"}:
                rank -= 1
            ranked.append((rank, setter))
        if not ranked:
            return ""
        ranked.sort(key=lambda item: (item[0], str(item[1].get("name") or "")))
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(project_root)
        for _rank, setter in ranked:
            setter_name = str(setter.get("name") or "").strip()
            param = str(setter.get("param") or "").strip()
            params = cls._split_top_level_args(param)
            param_text = str(params[0] if len(params) == 1 else param).strip()
            list_match = re.search(
                r"\b(?:java\.util\.)?(?:List|Collection|Iterable)\s*<\s*([A-Z][A-Za-z0-9_$.]*)\s*>",
                param_text,
            )
            if list_match:
                element_type = list_match.group(1)
                element_expr = cls._source_string_payload_expression_for_expected_type(
                    project_root,
                    element_type,
                    string_expression=arg_expr,
                    symbol_index=symbol_index,
                    preferred_package=preferred_package,
                )
                if not element_expr:
                    continue
                element_simple = cls._simple_type_name(element_type)
                element_fqn = cls._resolve_best_fqn(
                    element_simple,
                    candidates=list((symbol_index or {}).get(element_simple) or []),
                    current_package=preferred_package,
                    source_package=preferred_package,
                ) or element_type
                return f".{setter_name}(java.util.Collections.<{element_fqn}>singletonList({element_expr}))"
            raw_type = cls._simple_type_name(" ".join(param_text.split()[:-1]) or param_text)
            value_expr = cls._source_string_payload_expression_for_expected_type(
                project_root,
                raw_type,
                string_expression=arg_expr,
                symbol_index=symbol_index,
                preferred_package=preferred_package,
            )
            if value_expr:
                return f".{setter_name}({value_expr})"
        return ""

    @classmethod
    def _source_builder_payload_replacement_for_existing_call(
        cls,
        project_root: Path,
        *,
        setter_name: str,
        arg_text: str,
        recipe: dict[str, Any],
        symbol_index: dict[str, list[str]] | None = None,
        preferred_package: str = "",
        local_variable_types: dict[str, str] | None = None,
    ) -> str:
        """Rewrite existing builder setter calls whose argument shape is wrong.

        Example: ``ToolResultBlock.builder().output("x")`` when source declares
        ``output(ContentBlock)`` becomes ``output(TextBlock.builder().text("x").build())``.
        The rewrite fires for one argument when source proves the setter
        expects a payload type that can be built from a string-like value, or
        when the argument is a source-visible builder chain missing its terminal
        build/get call.
        """
        args = cls._split_top_level_args(str(arg_text or ""))
        if len(args) != 1:
            return ""
        arg_expr = str(args[0] or "").strip()
        if not arg_expr:
            return ""
        setters = [
            item for item in list(recipe.get("setters") or [])
            if isinstance(item, dict) and str(item.get("name") or "").strip() == setter_name
        ]
        if not setters:
            return ""
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(project_root)
        string_payload_expr = (
            arg_expr
            if re.fullmatch(r'"(?:\\.|[^"\\])*"', arg_expr)
            else f"String.valueOf({arg_expr})"
        )
        builder_arg_match = re.match(
            r"(?P<owner>(?:[a-z_][A-Za-z0-9_$]*\.)*[A-Z][A-Za-z0-9_$]*)\s*\.\s*builder\s*\(\s*\)(?P<body>.*)$",
            arg_expr,
            re.DOTALL,
        )
        for setter in setters:
            param = str(setter.get("param") or "").strip()
            params = cls._split_top_level_args(param)
            param_text = str(params[0] if len(params) == 1 else param).strip()
            if local_variable_types and re.fullmatch(r"[a-zA-Z_$][A-Za-z0-9_$]*", arg_expr):
                declared_type = str(local_variable_types.get(arg_expr) or "").strip()
                if declared_type and cls._source_type_assignable_to_expected(
                    project_root,
                    declared_type,
                    param_text,
                    symbol_index=symbol_index,
                    preferred_package=preferred_package,
                ):
                    return ""
            if cls._argument_source_assignable_to_param(
                project_root,
                arg_expr,
                param_text,
                symbol_index=symbol_index,
                preferred_package=preferred_package,
            ):
                return ""
        builder_arg_terminal_expr = ""
        builder_arg_owner_simple = ""
        if builder_arg_match and not re.search(r"\.\s*(?:build|get)\s*\(\s*\)\s*$", arg_expr):
            owner_simple = str(builder_arg_match.group("owner") or "").strip()
            builder_arg_owner_simple = owner_simple.rsplit(".", 1)[-1]
            owner_fqn = ""
            owner_candidates = list((symbol_index or {}).get(builder_arg_owner_simple) or [])
            if len(owner_candidates) == 1:
                owner_fqn = str(owner_candidates[0])
            elif owner_candidates:
                owner_fqn = cls._resolve_best_fqn(
                    builder_arg_owner_simple,
                    candidates=owner_candidates,
                    current_package=preferred_package,
                    source_package=preferred_package,
                ) or ""
            if owner_fqn:
                owner_recipe = cls._source_builder_recipe_for_fqn(project_root, owner_fqn)
                if owner_recipe:
                    terminal = str(owner_recipe.get("terminal_name") or "build").strip() or "build"
                    builder_arg_terminal_expr = f"{arg_expr}.{terminal}()"
        ranked: list[tuple[int, str]] = []
        for setter in setters:
            param = str(setter.get("param") or "").strip()
            params = cls._split_top_level_args(param)
            param_text = str(params[0] if len(params) == 1 else param).strip()
            simple_param = cls._simple_type_name(param_text.rsplit(" ", 1)[0] if " " in param_text else param_text)
            if simple_param in {"String", "CharSequence", "Object"}:
                continue
            list_match = re.search(
                r"\b(?:java\.util\.)?(?:List|Collection|Iterable)\s*<\s*([A-Z][A-Za-z0-9_$.]*)\s*>",
                param_text,
            )
            if list_match:
                element_type = list_match.group(1)
                element_expr = cls._source_string_payload_expression_for_expected_type(
                    project_root,
                    element_type,
                    string_expression=string_payload_expr,
                    symbol_index=symbol_index,
                    preferred_package=preferred_package,
                )
                if not element_expr:
                    continue
                element_simple = cls._simple_type_name(element_type)
                element_fqn = cls._resolve_best_fqn(
                    element_simple,
                    candidates=list((symbol_index or {}).get(element_simple) or []),
                    current_package=preferred_package,
                    source_package=preferred_package,
                ) or element_type
                ranked.append((
                    1,
                    f".{setter_name}(java.util.Collections.<{element_fqn}>singletonList({element_expr}))",
                ))
                continue
            raw_type = cls._simple_type_name(" ".join(param_text.split()[:-1]) or param_text)
            if builder_arg_terminal_expr:
                if cls._source_type_assignable_to_expected(
                    project_root,
                    builder_arg_owner_simple,
                    raw_type,
                    symbol_index=symbol_index,
                    preferred_package=preferred_package,
                ):
                    ranked.append((0, f".{setter_name}({builder_arg_terminal_expr})"))
                continue
            value_expr = cls._source_string_payload_expression_for_expected_type(
                project_root,
                raw_type,
                string_expression=string_payload_expr,
                symbol_index=symbol_index,
                preferred_package=preferred_package,
            )
            if value_expr and value_expr != arg_expr:
                ranked.append((0, f".{setter_name}({value_expr})"))
        if not ranked:
            return ""
        ranked.sort(key=lambda item: (item[0], item[1]))
        return ranked[0][1]

    @staticmethod
    def _rewrite_extra_closing_parens_in_fluent_lines(code: str) -> tuple[str, list[str]]:
        """Remove mechanically extra trailing ')' from fluent continuation lines.

        This is a narrow syntax cleanup for LLM builder chains such as
        ``.input(Map.of("k", "v")))`` or
        ``.output(TextBlock.builder().text("x").build()).build())``.  It only
        edits lines that start with a fluent ``.method(`` continuation and have
        more closing than opening parentheses on that same line.
        """
        text = str(code or "")
        if not text or "." not in text or ")" not in text:
            return text, []
        changed: list[str] = []
        out_lines: list[str] = []
        for line_no, raw in enumerate(text.splitlines(), 1):
            line = raw
            stripped = line.lstrip()
            if (
                stripped.startswith(".")
                and re.search(r"^\.\s*[A-Za-z_$][A-Za-z0-9_$]*\s*\(", stripped)
                and stripped.count(")") > stripped.count("(")
            ):
                while stripped.count(")") > stripped.count("("):
                    if re.search(r"\)\s*;\s*$", line):
                        newline = re.sub(r"\)\s*;\s*$", ";", line, count=1)
                    elif re.search(r"\)\s*$", line):
                        newline = re.sub(r"\)\s*$", "", line, count=1)
                    else:
                        break
                    if newline == line:
                        break
                    line = newline
                    stripped = line.lstrip()
                    changed.append(f"line{line_no}:remove-extra-fluent-close-paren")
            out_lines.append(line)
        if not changed:
            return text, []
        trailing_newline = "\n" if text.endswith("\n") else ""
        return "\n".join(out_lines) + trailing_newline, changed

    @classmethod
    def _source_builder_default_payload_call(
        cls,
        project_root: Path,
        owner_fqn: str,
        *,
        recipe: dict[str, Any],
        existing_calls: set[str],
        symbol_index: dict[str, list[str]] | None = None,
        preferred_package: str = "",
        string_expression: str = '"generated"',
    ) -> str:
        """Return a conservative non-null payload setter call for a builder chain.

        This is intentionally narrower than general fixture synthesis.  It is
        used for generated terminal/collaborator producer values such as
        ``Flux.just(Type.builder().id("x").build())`` where the source builder
        has an observable payload-like setter that the generated candidate did
        not call.  The inserted value must be source-constructible.
        """
        if not isinstance(recipe, dict):
            return ""
        existing = {str(name or "").strip() for name in set(existing_calls or set()) if str(name or "").strip()}
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(project_root)
        preferred_names = {"content": 0, "payload": 1, "data": 2, "value": 3, "message": 4}
        setters = [item for item in list(recipe.get("setters") or []) if isinstance(item, dict)]
        ranked: list[tuple[int, str, str]] = []
        for setter in setters:
            setter_name = str(setter.get("name") or "").strip()
            if not setter_name or setter_name in existing:
                continue
            setter_lower = setter_name.lower()
            if setter_lower not in preferred_names:
                continue
            param = str(setter.get("param") or "").strip()
            if not param:
                continue
            ranked.append((preferred_names[setter_lower], setter_name, param))
        ranked.sort(key=lambda item: (item[0], item[1]))
        for _rank, setter_name, param in ranked:
            params = cls._split_top_level_args(param)
            param_text = str(params[0] if len(params) == 1 else param).strip()
            list_match = re.search(
                r"\b(?:java\.util\.)?(?:List|Collection|Iterable)\s*<\s*([A-Z][A-Za-z0-9_$.]*)\s*>",
                param_text,
            )
            if list_match:
                element_type = list_match.group(1)
                element_expr = cls._source_string_payload_expression_for_expected_type(
                    project_root,
                    element_type,
                    string_expression=string_expression,
                    symbol_index=symbol_index,
                    preferred_package=preferred_package,
                )
                if not element_expr:
                    continue
                element_simple = cls._simple_type_name(element_type)
                element_fqn = cls._resolve_best_fqn(
                    element_simple,
                    candidates=list((symbol_index or {}).get(element_simple) or []),
                    current_package=preferred_package,
                    source_package=preferred_package,
                ) or element_type
                return f".{setter_name}(java.util.Collections.<{element_fqn}>singletonList({element_expr}))"
            varargs_match = re.search(r"\b([A-Z][A-Za-z0-9_$.]*)\s*\.\.\.", param_text)
            raw_type = ""
            if varargs_match:
                raw_type = varargs_match.group(1)
            else:
                raw_type = cls._simple_type_name(" ".join(param_text.split()[:-1]) or param_text)
            if raw_type in {"String", "CharSequence", "Object"}:
                continue
            value_expr = cls._source_string_payload_expression_for_expected_type(
                project_root,
                raw_type,
                string_expression=string_expression,
                symbol_index=symbol_index,
                preferred_package=preferred_package,
            )
            if value_expr:
                return f".{setter_name}({value_expr})"
        return ""

    @staticmethod
    def _builder_chain_in_terminal_producer_statement(statement: str) -> bool:
        text = str(statement or "")
        if not text:
            return False
        return bool(
            re.search(r"\b(?:thenReturn|doReturn|willReturn)\s*\(", text)
            or re.search(r"\b(?:Flux|Mono|Single|Maybe|Observable|CompletableFuture|Optional)\s*\.\s*(?:just|from|fromIterable|completedFuture|of)\s*\(", text)
        )

    @classmethod
    def _source_compatible_builder_replacement(
        cls,
        project_root: Path,
        fqn: str,
        *,
        args: list[str],
        constructor_params: list[str] | None = None,
    ) -> tuple[str, dict[str, Any]] | tuple[str, None]:
        """Build a conservative ``Type.builder()...build()`` replacement.

        The rewrite only fires when the builder path is public and the argument
        to setter mapping is unambiguous.  For a single argument we prefer a
        setter whose name matches the constructor parameter/field name; if
        there is only one one-arg setter, that is also source-backed enough for
        simple value DTOs.
        """
        recipe = cls._source_builder_recipe_for_fqn(project_root, fqn)
        if not recipe:
            return "", None
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        arg_values = [str(arg).strip() for arg in list(args or [])]
        arity = 0 if len(arg_values) == 1 and not arg_values[0] else len(arg_values)
        setters = [setter for setter in list(recipe.get("setters") or []) if isinstance(setter, dict)]
        terminal_name = str(recipe.get("terminal_name") or "build").strip() or "build"
        if arity == 0:
            return f"{simple}.builder().{terminal_name}()", {
                "type": simple,
                "builder": "builder()",
                "setters": [],
                "build": f"{terminal_name}()",
                "evidence": recipe,
            }
        if arity != 1:
            return "", None
        builder_type = str(recipe.get("builder_type") or "").strip()
        arg0 = arg_values[0] if arg_values else ""
        arg0_simple = re.fullmatch(r"[A-Za-z_$][A-Za-z0-9_$]*", arg0 or "")
        # Common source shape: a non-public constructor takes the owner builder
        # and build() performs extra collaborator/default wiring.  Generated
        # tests sometimes emit `new Type(builder)` even though the visible API
        # is `builder.build()`.  If source proves the builder terminal returns
        # the owner type, rewrite only simple builder-like variables to the
        # terminal call rather than rejecting the whole candidate before repair.
        if builder_type and arg0_simple and "builder" in arg0.lower():
            return f"{arg0}.{terminal_name}()", {
                "type": simple,
                "builder": builder_type,
                "setters": [],
                "build": f"{terminal_name}()",
                "evidence": recipe,
                "rewrite": "builder-arg-constructor-to-terminal",
            }
        wanted_names: set[str] = set()
        for param in list(constructor_params or []):
            cleaned = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", str(param or "")).strip()
            parts = cleaned.split()
            if len(parts) >= 2:
                wanted_names.add(parts[-1].strip())
                param_type = cls._simple_type_name(" ".join(parts[:-1]))
                if builder_type and param_type == builder_type and arg0_simple:
                    return f"{arg0}.{terminal_name}()", {
                        "type": simple,
                        "builder": builder_type,
                        "setters": [],
                        "build": f"{terminal_name}()",
                        "evidence": recipe,
                        "rewrite": "builder-param-constructor-to-terminal",
                    }
        one_arg_setters = [
            setter for setter in setters
            if len(cls._split_top_level_args(str(setter.get("param") or "").strip())) == 1
        ]
        chosen: dict[str, Any] | None = None
        if wanted_names:
            matches = [
                setter for setter in one_arg_setters
                if str(setter.get("name") or "").strip() in wanted_names
            ]
            if len(matches) == 1:
                chosen = matches[0]
        elif len(one_arg_setters) == 1:
            chosen = one_arg_setters[0]
        if chosen is None:
            return "", None
        setter_name = str(chosen.get("name") or "").strip()
        if not setter_name:
            return "", None
        replacement = f"{simple}.builder().{setter_name}({arg_values[0]}).{terminal_name}()"
        return replacement, {
            "type": simple,
            "builder": "builder()",
            "setters": [chosen],
            "build": f"{terminal_name}()",
            "evidence": recipe,
        }

    @classmethod
    def _project_source_static_return_types_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> dict[str, str] | None:
        cache_key = (str(project_root.resolve() if project_root.exists() else project_root), fqn)
        if cache_key in cls._SOURCE_STATIC_RETURNS_CACHE:
            return cls._SOURCE_STATIC_RETURNS_CACHE[cache_key]
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            cls._SOURCE_STATIC_RETURNS_CACHE[cache_key] = None
            return None
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            cls._SOURCE_STATIC_RETURNS_CACHE[cache_key] = None
            return None
        code = cls._strip_java_comments_and_strings(source_text)
        returns: dict[str, str] = {}
        static_re = re.compile(
            r"\b(?:public|protected|private)?\s+static\s+([\w.<>,?$ \[\]]+?)\s+"
            r"([A-Za-z_$][A-Za-z0-9_$]*)\s*\("
        )
        for match in static_re.finditer(code):
            return_type = match.group(1).strip()
            method = match.group(2).strip()
            simple = return_type.split("<", 1)[0].replace("[]", "").rsplit(".", 1)[-1]
            if simple and method:
                returns[method] = simple
        cls._SOURCE_STATIC_RETURNS_CACHE[cache_key] = returns or {}
        return returns

    @classmethod
    def _project_source_type_body_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> tuple[str, str] | None:
        """Return ``(source, direct type body)`` for a source-backed FQN.

        Nested source types share their outer type's Java file.  Resolving the
        declaration one lexical level at a time avoids accidentally mixing an
        outer class's methods with a nested builder's methods.
        """
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            return None
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return None
        code = cls._strip_java_comments_and_strings(source_text)
        package_match = cls._RE_PACKAGE_DECL.search(source_text)
        package = package_match.group(1) if package_match else ""
        normalized_fqn = str(fqn or "").replace("$", ".")
        relative = (
            normalized_fqn[len(package) + 1 :]
            if package and normalized_fqn.startswith(f"{package}.")
            else normalized_fqn
        )
        type_parts = [part for part in relative.split(".") if part]
        outer_simple = source_file.stem
        if outer_simple in type_parts:
            type_parts = type_parts[type_parts.index(outer_simple) :]
        elif type_parts:
            type_parts = [outer_simple, type_parts[-1]]
        else:
            type_parts = [outer_simple]

        scope = code
        for simple in type_parts:
            declaration = None
            for match in re.finditer(
                rf"\b(?:class|interface|record|enum)\s+{re.escape(simple)}\b[^\{{;]*\{{",
                scope,
                re.DOTALL,
            ):
                prefix = scope[: match.start()]
                depth = max(0, prefix.count("{") - prefix.count("}"))
                if depth == 0:
                    declaration = match
                    break
            if declaration is None:
                return None
            open_brace = scope.find("{", declaration.end() - 1)
            close_brace = cls._find_matching_brace(scope, open_brace)
            if open_brace < 0 or close_brace <= open_brace:
                return None
            scope = scope[open_brace + 1 : close_brace]
        return source_text, scope

    @classmethod
    def _project_source_direct_method_contracts_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> dict[str, list[dict[str, Any]]] | None:
        """Return direct source method arity/return contracts for one type."""
        resolved = cls._project_source_type_body_for_fqn(project_root, fqn)
        if resolved is None:
            return None
        _source_text, body = resolved
        method_re = re.compile(
            r"(?m)^\s*(?P<mods>(?:(?:public|protected|private|static|final|"
            r"abstract|default|synchronized|native|strictfp)\s+)*)"
            r"(?:<[^>\n]+>\s*)?"
            r"(?P<return>[A-Za-z_$][\w$.\s<>,?\[\]]*?)\s+"
            r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*\("
        )
        contracts: dict[str, list[dict[str, Any]]] = {}
        for match in method_re.finditer(body):
            prefix = body[: match.start()]
            if prefix.count("{") != prefix.count("}"):
                continue
            open_idx = body.find("(", match.end() - 1)
            close_idx = cls._find_matching_paren(body, open_idx)
            if open_idx < 0 or close_idx < 0:
                continue
            raw_params = body[open_idx + 1 : close_idx].strip()
            arity = 0 if not raw_params else len(cls._split_top_level_args(raw_params))
            modifiers = set(str(match.group("mods") or "").split())
            contracts.setdefault(match.group("name"), []).append(
                {
                    "arity": arity,
                    "varargs": "..." in raw_params,
                    "return_type": " ".join(match.group("return").split()),
                    "static": "static" in modifiers,
                }
            )
        return contracts

    @staticmethod
    def _source_method_contract_accepts_arity(
        contract: dict[str, Any],
        observed_arity: int,
    ) -> bool:
        """Match Java invocation arity, including expanded varargs calls."""

        declared_arity = int(contract.get("arity", -1))
        if declared_arity < 0:
            return False
        if bool(contract.get("varargs")):
            return observed_arity >= max(0, declared_arity - 1)
        return observed_arity == declared_arity

    @classmethod
    def _resolve_project_source_return_fqn(
        cls,
        project_root: Path,
        return_type: str,
        *,
        owner_fqn: str,
        symbol_index: dict[str, list[str]],
    ) -> str | None:
        """Resolve a method return type only when project source proves it."""
        raw = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", str(return_type or "")).strip()
        raw = re.sub(r"\b(?:final|volatile|transient)\s+", "", raw).strip()
        raw = raw.split("<", 1)[0].replace("[]", "").strip()
        if not raw or raw in {
            "boolean",
            "byte",
            "char",
            "double",
            "float",
            "int",
            "long",
            "short",
            "void",
        }:
            return None
        simple = raw.rsplit(".", 1)[-1]
        candidates = list(symbol_index.get(simple) or [])
        if len(candidates) == 1:
            candidate = candidates[0]
            if cls._project_source_type_body_for_fqn(project_root, candidate) is not None:
                return candidate

        owner_file = cls._find_project_source_for_fqn(project_root, owner_fqn)
        owner_source = ""
        if owner_file is not None:
            try:
                owner_source = owner_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                owner_source = ""
        imports = cls._extract_source_import_map(owner_source)
        imported = imports.get(simple)
        if imported and cls._project_source_type_body_for_fqn(project_root, imported) is not None:
            return imported

        package_match = cls._RE_PACKAGE_DECL.search(owner_source)
        package = package_match.group(1) if package_match else owner_fqn.rsplit(".", 1)[0]
        normalized_owner = owner_fqn.replace("$", ".")
        owner_parts = normalized_owner.split(".")
        trial_fqns: list[str] = []
        if "." in raw and raw[:1].islower():
            trial_fqns.append(raw)
        trial_fqns.append(f"{normalized_owner}.{simple}")
        if package:
            trial_fqns.append(f"{package}.{simple}")
        # A nested owner can return a sibling nested type.  Try each enclosing
        # source type from the innermost level outward.
        package_parts = package.split(".") if package else []
        for end in range(len(owner_parts), len(package_parts), -1):
            trial_fqns.append(".".join([*owner_parts[:end], simple]))
        for candidate in dict.fromkeys(trial_fqns):
            if cls._project_source_type_body_for_fqn(project_root, candidate) is not None:
                return candidate
        return None

    @classmethod
    def _classpath_unavailable_static_calls_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find static-looking calls to classpath types whose method is absent.

        The check is deliberately narrow: it only examines ``Type.method(...)``
        calls where ``Type`` resolves to a single indexed classpath FQN and
        that class was inspectable by ``javap``. This avoids rejecting dynamic,
        inherited, instance, or ambiguous calls on weak evidence.
        """
        if not code or not project_root:
            return []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        symbol_index = symbol_index or {}

        found: list[str] = []
        candidates = sorted({
            (match.group(1), match.group(2))
            for match in re.finditer(r"\b([A-Z][A-Za-z0-9_$]*)\s*\.\s*([a-zA-Z_$][A-Za-z0-9_$]*)\s*\(", code)
        })
        for owner, method in candidates[:32]:
            if owner in cls._JAVA_LANG_TYPES:
                continue
            fqns = list(symbol_index.get(owner) or [])
            if len(fqns) != 1:
                continue
            if cls._is_test_framework_fqn(fqns[0]):
                continue
            source_file = cls._find_project_source_for_fqn(root, fqns[0])
            if source_file is not None:
                continue
            methods = cls._classpath_methods_for_fqn(root, fqns[0])
            if methods is not None and methods and method not in methods:
                found.append(f"{owner}.{method}")
        return sorted(set(found))

    @classmethod
    def _declared_instance_unavailable_calls_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find ``declaredVar.missingMethod(...)`` when the declared type is inspectable."""
        if not code or not project_root:
            return []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        symbol_index = symbol_index or {}
        object_methods = {"equals", "hashCode", "toString", "getClass", "wait", "notify", "notifyAll"}
        declarations: dict[str, str] = {}
        decl_re = re.compile(
            r"(?<![\w$.<])(?:final\s+)?([A-Z][A-Za-z0-9_$.]*(?:<[^;=(){}]+>)?(?:\[\])?)\s+([a-z_$][A-Za-z0-9_$]*)\s*(?:=|;|,)"
        )
        for match in decl_re.finditer(code):
            raw_type = match.group(1).strip()
            var_name = match.group(2).strip()
            simple = raw_type.split("<", 1)[0].replace("[]", "").rsplit(".", 1)[-1]
            if simple and var_name:
                declarations.setdefault(var_name, simple)
            if len(declarations) >= 40:
                break
        mock_decl_re = re.compile(
            r"(?<![\w$.])(?:final\s+)?(?:var|[A-Z][A-Za-z0-9_$.]*(?:<[^;=(){}]+>)?)\s+"
            r"([a-z_$][A-Za-z0-9_$]*)\s*=\s*(?:Mockito\s*\.\s*)?mock\s*\(\s*"
            r"([A-Z][A-Za-z0-9_$.]*)\s*\.class\s*\)"
        )
        for match in mock_decl_re.finditer(code):
            var_name = match.group(1).strip()
            raw_type = match.group(2).strip()
            simple = raw_type.rsplit(".", 1)[-1]
            if var_name and simple:
                declarations[var_name] = simple
            if len(declarations) >= 60:
                break
        found: list[str] = []
        if declarations:
            for match in re.finditer(r"\b([a-z_$][A-Za-z0-9_$]*)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(", code):
                var_name, method = match.group(1), match.group(2)
                if method in object_methods:
                    continue
                simple = declarations.get(var_name)
                if not simple:
                    continue
                if cls._is_common_jdk_instance_method(simple, method):
                    continue
                fqns = list(symbol_index.get(simple) or [])
                common_fqn = cls._common_java_type_fqn(simple)
                if len(fqns) != 1 and not common_fqn:
                    continue
                fqn = fqns[0] if len(fqns) == 1 else common_fqn
                if not fqn:
                    continue
                methods = cls._known_methods_for_fqn(root, fqn)
                if methods is not None and methods and method not in methods:
                    found.append(f"{simple}.{method}")
        cast_call_re = re.compile(
            r"\(\s*\(?\s*([A-Z][A-Za-z0-9_$.]*(?:<[^;=(){}]+>)?)\s*\)\s*"
            r"[^;{}]{0,180}?\)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\("
        )
        for match in cast_call_re.finditer(code):
            raw_type, method = match.group(1).strip(), match.group(2).strip()
            if method in object_methods:
                continue
            simple = raw_type.split("<", 1)[0].rsplit(".", 1)[-1]
            if not simple:
                continue
            if cls._is_common_jdk_instance_method(simple, method):
                continue
            fqns = list(symbol_index.get(simple) or [])
            common_fqn = cls._common_java_type_fqn(simple)
            if len(fqns) != 1 and not common_fqn:
                continue
            fqn = fqns[0] if len(fqns) == 1 else common_fqn
            if not fqn:
                continue
            methods = cls._known_methods_for_fqn(root, fqn)
            if methods is not None and methods and method not in methods:
                found.append(f"{simple}.{method}")
        return sorted(set(found))

    @classmethod
    def _chained_instance_unavailable_calls_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Validate source-proven fluent calls starting from ``Type.factory()``.

        The analysis deliberately stops when a return type or inherited method
        is ambiguous.  It rejects only absent methods and wrong arities proven
        by the exact project-source receiver type.
        """
        if not code or not project_root:
            return []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return []
        found: list[str] = []
        chain_re = re.compile(
            r"\b([A-Z][A-Za-z0-9_$]*)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\("
        )
        for match in chain_re.finditer(code):
            owner, factory_method = match.group(1), match.group(2)
            owner_fqns = list(symbol_index.get(owner) or [])
            if len(owner_fqns) != 1:
                continue
            owner_fqn = owner_fqns[0]
            open_idx = code.find("(", match.end() - 1)
            close_idx = cls._find_matching_paren(code, open_idx)
            if open_idx < 0 or close_idx < 0:
                continue
            raw_args = code[open_idx + 1 : close_idx].strip()
            factory_arity = 0 if not raw_args else len(cls._split_top_level_args(raw_args))
            owner_contracts = cls._project_source_direct_method_contracts_for_fqn(
                root,
                owner_fqn,
            )
            factory_contracts = [
                item
                for item in list((owner_contracts or {}).get(factory_method) or [])
                if bool(item.get("static"))
            ]
            if not factory_contracts:
                continue
            matching_factories = [
                item
                for item in factory_contracts
                if cls._source_method_contract_accepts_arity(
                    item,
                    factory_arity,
                )
            ]
            if not matching_factories:
                expected = sorted({int(item.get("arity", -1)) for item in factory_contracts})
                found.append(
                    f"{owner}.{factory_method}:wrong-arity"
                    f"(observed={factory_arity},expected={expected})"
                )
                continue
            return_fqns = {
                cls._resolve_project_source_return_fqn(
                    root,
                    str(item.get("return_type") or ""),
                    owner_fqn=owner_fqn,
                    symbol_index=symbol_index,
                )
                for item in matching_factories
            }
            return_fqns.discard(None)
            if len(return_fqns) != 1:
                continue
            current_fqn = next(iter(return_fqns))
            cursor = close_idx + 1
            for _depth in range(8):
                chained = re.match(
                    r"\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(",
                    code[cursor:],
                )
                if chained is None:
                    break
                chained_method = chained.group(1)
                chained_open = cursor + chained.end() - 1
                chained_close = cls._find_matching_paren(code, chained_open)
                if chained_close < 0:
                    break
                chained_args = code[chained_open + 1 : chained_close].strip()
                chained_arity = (
                    0 if not chained_args else len(cls._split_top_level_args(chained_args))
                )
                current_simple = current_fqn.replace("$", ".").rsplit(".", 1)[-1]
                known_methods = cls._known_methods_for_fqn(root, current_fqn)
                if (
                    chained_method not in {"equals", "hashCode", "toString", "getClass"}
                    and known_methods is not None
                    and chained_method not in known_methods
                ):
                    found.append(f"{current_simple}.{chained_method}")
                    break
                direct_contracts = cls._project_source_direct_method_contracts_for_fqn(
                    root,
                    current_fqn,
                )
                method_contracts = list((direct_contracts or {}).get(chained_method) or [])
                if not method_contracts:
                    # The method may be inherited.  Its return contract is not
                    # exact enough to continue type propagation.
                    break
                matching_methods = [
                    item
                    for item in method_contracts
                    if cls._source_method_contract_accepts_arity(
                        item,
                        chained_arity,
                    )
                ]
                if not matching_methods:
                    expected = sorted(
                        {int(item.get("arity", -1)) for item in method_contracts}
                    )
                    found.append(
                        f"{current_simple}.{chained_method}:wrong-arity"
                        f"(observed={chained_arity},expected={expected})"
                    )
                    break
                next_fqns = {
                    cls._resolve_project_source_return_fqn(
                        root,
                        str(item.get("return_type") or ""),
                        owner_fqn=current_fqn,
                        symbol_index=symbol_index,
                    )
                    for item in matching_methods
                }
                next_fqns.discard(None)
                cursor = chained_close + 1
                if len(next_fqns) != 1:
                    break
                current_fqn = next(iter(next_fqns))
        return sorted(set(found))

    @classmethod
    def _source_unavailable_constructors_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find ``new Type(args)`` when project source exposes no visible matching constructor."""
        if not code or not project_root:
            return []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return []
        found: list[str] = []
        for match in re.finditer(r"\bnew\s+([A-Z][A-Za-z0-9_$]*)\s*\(", code):
            simple = match.group(1)
            fqns = list(symbol_index.get(simple) or [])
            if len(fqns) != 1:
                continue
            arities = cls._project_source_visible_constructor_arities_for_fqn(root, fqns[0])
            if arities is None:
                continue
            open_idx = code.find("(", match.start())
            close_idx = cls._find_matching_paren(code, open_idx)
            if close_idx == -1:
                continue
            args = cls._split_top_level_args(code[open_idx + 1 : close_idx].strip())
            arity = 0 if len(args) == 1 and not args[0].strip() else len(args)
            if arity not in arities:
                found.append(f"{simple}({arity} args)")
        return sorted(set(found))

    @classmethod
    def _unterminated_source_builder_chains_in_code(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> list[str]:
        """Find source-proven ``Type.builder()`` chains used without terminal build()."""
        if not code or not project_root:
            return []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return []
        found: list[str] = []
        builder_terminals: dict[str, str] = {}
        for simple, fqns in list(symbol_index.items()):
            if len(fqns) != 1 or not re.search(rf"\b{re.escape(simple)}\s*\.\s*builder\s*\(", code):
                continue
            recipe = cls._source_builder_recipe_for_fqn(root, fqns[0])
            if not recipe:
                continue
            builder_terminals[simple] = str(recipe.get("terminal_name") or "build").strip() or "build"

        for simple, terminal in sorted(builder_terminals.items()):
            # Assignment: Type value = Type.builder().x(...);  // missing .build()
            assign_re = re.compile(
                rf"\b{re.escape(simple)}\s+[A-Za-z_$][A-Za-z0-9_$]*\s*=\s*"
                rf"{re.escape(simple)}\s*\.\s*builder\s*\([^;]*;",
                re.DOTALL,
            )
            for match in assign_re.finditer(code):
                segment = match.group(0)
                if f".{terminal}(" not in segment:
                    found.append(f"{simple}.builder:missing-{terminal}")

            # Method argument: target(..., Type.builder().x(...), ...)
            # A full Java expression parser would be overkill; this narrow
            # source-backed check rejects only a chain statement that contains a
            # Type.builder() expression but no terminal build/get before the
            # statement ends.
            for match in re.finditer(
                rf"{re.escape(simple)}\s*\.\s*builder\s*\(",
                code,
            ):
                semi = code.find(";", match.end())
                if semi < 0:
                    continue
                segment = code[match.start():semi]
                if f".{terminal}(" not in segment:
                    found.append(f"{simple}.builder:missing-{terminal}")
        return sorted(set(found))

    @classmethod
    def _rewrite_unterminated_source_builder_assignments(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Append a source-proven builder terminal to ``Type x = Type.builder()...``.

        This only rewrites assignments whose declared type is the target type
        and whose RHS starts from that type's public static builder. The terminal
        method is read from source (`build()` or `get()`) and must return the
        target type.
        """
        if not code or not project_root or ".builder(" not in code:
            return code, []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return code, []
        replacements: list[tuple[int, int, str, str]] = []
        for match in re.finditer(
            r"\b(?P<type>[A-Z][A-Za-z0-9_$]*)\s+(?P<var>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
            r"(?P=type)\s*\.\s*builder\s*\(",
            code,
        ):
            simple = match.group("type")
            fqns = list(symbol_index.get(simple) or [])
            if len(fqns) != 1:
                continue
            recipe = cls._source_builder_recipe_for_fqn(root, fqns[0])
            if not recipe:
                continue
            terminal = str(recipe.get("terminal_name") or "build").strip() or "build"
            semi = code.find(";", match.end())
            if semi < 0:
                continue
            segment = code[match.start():semi]
            if f".{terminal}(" in segment:
                continue
            replacements.append((semi, semi, f".{terminal}()", f"{simple}.builder:append-{terminal}"))
        if not replacements:
            return code, []
        out: list[str] = []
        pos = 0
        applied: list[str] = []
        for start, end, replacement, label in replacements:
            if start < pos:
                continue
            out.append(code[pos:start])
            out.append(replacement)
            pos = end
            applied.append(label)
        out.append(code[pos:])
        return "".join(out), applied[:12]

    @classmethod
    def _rewrite_source_builder_constructor_calls(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Rewrite unavailable ``new Type(args)`` to source-visible builder chains.

        The rewrite is intentionally conservative: it only fires when project
        source proves the direct constructor arity is not public and the same
        source file exposes ``public static <BuilderType> builder()`` plus a
        chain method on that builder with the same single-argument arity and a
        terminal ``build()`` returning the requested type.
        """
        if not code or not project_root:
            return code, []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return code, []

        explicit_imports = cls._extract_source_import_map(code)
        replacements: list[tuple[int, int, str, str]] = []
        for match in re.finditer(r"\bnew\s+([A-Z][A-Za-z0-9_$]*)\s*\(", code):
            simple = match.group(1)
            imported_fqn = str(explicit_imports.get(simple) or "").strip()
            fqns = [imported_fqn] if imported_fqn else list(symbol_index.get(simple) or [])
            if len(fqns) != 1:
                continue
            source_file = cls._find_project_source_for_fqn(root, fqns[0])
            if source_file is None:
                continue
            try:
                source_text = source_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            source_clean = cls._strip_java_comments_and_strings(source_text)
            arities = cls._project_source_visible_constructor_arities_for_fqn(root, fqns[0])
            if arities is None:
                continue
            open_idx = code.find("(", match.start())
            close_idx = cls._find_matching_paren(code, open_idx)
            if close_idx == -1:
                continue
            args = cls._split_top_level_args(code[open_idx + 1 : close_idx].strip())
            arity = 0 if len(args) == 1 and not args[0].strip() else len(args)
            if arity in arities:
                continue
            constructor_details = cls._project_source_constructor_details_for_fqn(root, fqns[0]) or []
            matching_params: list[str] = []
            for detail in constructor_details:
                if int(detail.get("arity") or -1) == arity:
                    matching_params = [str(item) for item in list(detail.get("params") or [])]
                    break
            replacement, evidence = cls._source_compatible_builder_replacement(
                root,
                fqns[0],
                args=args,
                constructor_params=matching_params,
            )
            if not replacement or not evidence:
                continue
            replacements.append((match.start(), close_idx + 1, replacement, f"{simple}({arity} args)->builder"))

        if not replacements:
            return code, []
        rewritten_parts: list[str] = []
        pos = 0
        applied: list[str] = []
        for start, end, replacement, label in replacements:
            if start < pos:
                continue
            rewritten_parts.append(code[pos:start])
            rewritten_parts.append(replacement)
            pos = end
            applied.append(label)
        rewritten_parts.append(code[pos:])
        return "".join(rewritten_parts), applied

    @classmethod
    def _source_nested_builder_has_inaccessible_zero_arg_constructor(
        cls,
        source_code: str,
        *,
        builder_type: str = "Builder",
    ) -> bool:
        """Return true when source proves ``new Owner.Builder()`` is not usable.

        The check is intentionally narrow: it only treats an explicit private or
        protected zero-arg nested builder constructor as inaccessible.  A missing
        constructor or a public constructor is left alone because those can be
        valid construction paths in same-package tests.
        """
        code = cls._strip_java_comments_and_strings(source_code or "")
        builder = str(builder_type or "Builder").strip() or "Builder"
        class_match = re.search(
            rf"\b(?:public|protected|private|static|final|\s)*class\s+{re.escape(builder)}\b[^\{{;]*\{{",
            code,
        )
        if not class_match:
            return False
        open_brace = code.find("{", class_match.end() - 1)
        if open_brace < 0:
            return False
        close_brace = cls._find_matching_brace(code, open_brace)
        if close_brace < 0:
            return False
        body = code[open_brace + 1 : close_brace]
        ctor_re = re.compile(
            rf"(?m)^\s*(?P<access>private|protected)\s+{re.escape(builder)}\s*\((?P<params>[^)]*)\)"
        )
        for ctor in ctor_re.finditer(body):
            params = str(ctor.group("params") or "").strip()
            if not params:
                return True
        return False

    @classmethod
    def _rewrite_nested_builder_constructor_calls_to_owner_factory(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Rewrite ``new Owner.Builder()`` to source-proven ``Owner.builder()``.

        Generated tests often infer that a public nested ``Builder`` type can be
        directly constructed.  Many industrial builders deliberately make the
        nested constructor private and expose only ``Owner.builder()``.  This
        prepatch fires only when source proves that exact public factory exists
        and that the nested zero-arg Builder constructor is explicitly
        inaccessible.
        """
        if not code or not project_root or ".Builder" not in code:
            return code, []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return code, []

        explicit_imports = cls._extract_source_import_map(code)
        replacements: list[tuple[int, int, str, str]] = []
        pattern = re.compile(
            r"\bnew\s+"
            r"(?P<owner>(?:[a-z_][A-Za-z0-9_$]*\.)*[A-Z][A-Za-z0-9_$]*)"
            r"\s*\.\s*Builder\s*\("
        )
        for match in pattern.finditer(code):
            owner_expr = str(match.group("owner") or "").strip()
            owner_simple = owner_expr.rsplit(".", 1)[-1]
            if not owner_simple:
                continue
            imported_fqn = str(explicit_imports.get(owner_simple) or "").strip()
            if imported_fqn:
                fqns = [imported_fqn]
            else:
                fqns = list((symbol_index or {}).get(owner_simple) or [])
            if owner_expr != owner_simple and not imported_fqn:
                fqns = [fqn for fqn in fqns if fqn == owner_expr or fqn.endswith("." + owner_expr)]
            if len(fqns) != 1:
                continue
            recipe = cls._source_builder_recipe_for_fqn(root, fqns[0])
            if not recipe:
                continue
            builder_type = str(recipe.get("builder_type") or "Builder").strip() or "Builder"
            if builder_type != "Builder":
                continue
            if str(recipe.get("builder_params") or "").strip():
                continue
            source_file = cls._find_project_source_for_fqn(root, fqns[0])
            if source_file is None:
                continue
            try:
                source_text = source_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            if not cls._source_nested_builder_has_inaccessible_zero_arg_constructor(
                source_text,
                builder_type=builder_type,
            ):
                continue
            open_idx = code.find("(", match.start())
            close_idx = cls._find_matching_paren(code, open_idx)
            if close_idx == -1:
                continue
            args = cls._split_top_level_args(code[open_idx + 1 : close_idx].strip())
            arity = 0 if len(args) == 1 and not str(args[0]).strip() else len(args)
            if arity != 0:
                continue
            replacement = f"{owner_expr}.builder()"
            replacements.append(
                (match.start(), close_idx + 1, replacement, f"{owner_simple}.Builder()->{owner_simple}.builder()")
            )

        if not replacements:
            return code, []
        rewritten_parts: list[str] = []
        pos = 0
        applied: list[str] = []
        for start, end, replacement, label in replacements:
            if start < pos:
                continue
            rewritten_parts.append(code[pos:start])
            rewritten_parts.append(replacement)
            pos = end
            applied.append(label)
        rewritten_parts.append(code[pos:])
        return "".join(rewritten_parts), applied[:12]

    @classmethod
    def _remove_empty_returnless_lambda_registration_statements(
        cls,
        code: str,
        *,
        target_method: str = "",
    ) -> tuple[str, list[str]]:
        """Remove empty lambda hook/listener/callback registration statements.

        A frequent generated-test compile blocker is a setup line such as
        ``agent.addSystemHook(hook -> {});`` where the callback interface has a
        non-void return type.  The empty lambda cannot influence target state, so
        deleting the standalone registration is safer than inventing a return
        value.  This is intentionally limited to callback-registration-shaped
        method names and single-statement empty lambdas.
        """
        if not code or "->" not in code or "{}" not in code:
            return code, []
        target = str(target_method or "").strip()
        method_re = (
            r"(?P<method>(?:add|register|set|with)"
            r"[A-Za-z0-9_$]*(?:Hook|Hooks|Listener|Listeners|Callback|Callbacks|Handler|Handlers|Observer|Observers)"
            r"[A-Za-z0-9_$]*)"
        )
        stmt_re = re.compile(
            rf"(?m)^[ \t]*(?P<stmt>(?:[A-Za-z_$][A-Za-z0-9_$]*\s*\.\s*)?"
            rf"{method_re}\s*\([^;\n]*?->[ \t]*\{{[ \t]*\}}[^;\n]*\)\s*;\s*)$"
        )
        out_parts: list[str] = []
        pos = 0
        removed: list[str] = []
        for match in stmt_re.finditer(code):
            method = str(match.group("method") or "").strip()
            if not method or (target and method == target):
                continue
            out_parts.append(code[pos:match.start()])
            pos = match.end()
            removed.append(f"{method}:empty-returnless-lambda-registration")
        if not removed:
            return code, []
        out_parts.append(code[pos:])
        return "".join(out_parts), removed[:12]

    @classmethod
    def _source_visible_constructor_params_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> list[list[tuple[str, str]]]:
        """Return source-visible constructor params as (type, name) pairs."""
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            return []
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return []
        code = cls._strip_java_comments_and_strings(source_text)
        simple = fqn.rsplit(".", 1)[-1].split("$")[-1]
        constructors: list[list[tuple[str, str]]] = []

        def _parse_params(params_text: str) -> list[tuple[str, str]]:
            params: list[tuple[str, str]] = []
            for raw in cls._split_top_level_args(params_text.strip()):
                cleaned = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", raw).strip()
                cleaned = re.sub(r"\b(?:final|volatile|transient)\s+", "", cleaned).strip()
                parts = cleaned.split()
                if len(parts) < 2:
                    continue
                name = parts[-1].strip()
                typ = " ".join(parts[:-1]).strip()
                if re.fullmatch(r"[A-Za-z_$][A-Za-z0-9_$]*", name):
                    params.append((typ, name))
            return params

        record_match = re.search(
            rf"\bpublic\s+record\s+{re.escape(simple)}\s*\(([^)]*)\)",
            code,
            re.DOTALL,
        )
        if record_match:
            parsed = _parse_params(record_match.group(1))
            if parsed:
                constructors.append(parsed)
        for match in re.finditer(
            rf"(?m)^\s*(public|protected)\s+{re.escape(simple)}\s*\(([^)]*)\)",
            code,
        ):
            parsed = _parse_params(match.group(2))
            constructors.append(parsed)
        constructors.sort(key=len)
        deduped: list[list[tuple[str, str]]] = []
        seen: set[tuple[tuple[str, str], ...]] = set()
        for params in constructors:
            key = tuple(params)
            if key not in seen:
                seen.add(key)
                deduped.append(params)
        return deduped

    @classmethod
    def _rewrite_unavailable_builder_chains_to_constructors(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Rewrite ``Type.builder().x(v).build()`` when source has no builder but has constructors."""
        if not code or not project_root or ".builder()" not in code:
            return code, []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return code, []

        explicit_imports: set[str] = set()
        wildcard_imports: set[str] = set()
        for import_match in re.finditer(r"(?m)^\s*import\s+(static\s+)?([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$*]*)*)\s*;", code):
            if import_match.group(1):
                continue
            imported = import_match.group(2)
            if imported.endswith(".*"):
                wildcard_imports.add(imported[:-2])
            else:
                explicit_imports.add(imported)

        def _candidate_fqns_for_simple(simple_name: str) -> list[str]:
            candidates = list(symbol_index.get(simple_name) or [])
            if not candidates:
                return []
            imported_exact = [
                fqn for fqn in candidates
                if fqn in explicit_imports or fqn.replace("$", ".") in explicit_imports
            ]
            if imported_exact:
                return imported_exact
            imported_wildcard = [
                fqn for fqn in candidates
                if fqn.rsplit(".", 1)[0] in wildcard_imports
            ]
            if imported_wildcard:
                return imported_wildcard
            return candidates if len(candidates) == 1 else []

        replacements: list[tuple[int, int, str, str]] = []
        for match in re.finditer(r"\b([A-Z][A-Za-z0-9_$]*)\.builder\s*\(\s*\)", code):
            simple = match.group(1)
            fqns = _candidate_fqns_for_simple(simple)
            if len(fqns) != 1:
                continue
            source_file = cls._find_project_source_for_fqn(root, fqns[0])
            if source_file is None:
                continue
            try:
                source_text = source_file.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            source_clean = cls._strip_java_comments_and_strings(source_text)
            if re.search(r"\bpublic\s+static\s+[A-Z][A-Za-z0-9_$]*\s+builder\s*\(\s*\)", source_clean):
                continue
            cursor = match.end()
            calls: dict[str, str] = {}
            end = -1
            while cursor < len(code):
                while cursor < len(code) and code[cursor].isspace():
                    cursor += 1
                if cursor >= len(code) or code[cursor] != ".":
                    break
                name_match = re.match(r"\.([A-Za-z_$][A-Za-z0-9_$]*)\s*\(", code[cursor:])
                if not name_match:
                    break
                call_name = name_match.group(1)
                open_idx = cursor + name_match.group(0).rfind("(")
                close_idx = cls._find_matching_paren(code, open_idx)
                if close_idx < 0:
                    break
                args_text = code[open_idx + 1:close_idx].strip()
                if call_name == "build":
                    end = close_idx + 1
                    break
                args = cls._split_top_level_args(args_text)
                arity = 0 if len(args) == 1 and not args[0].strip() else len(args)
                if arity == 1:
                    calls[call_name] = args[0].strip()
                cursor = close_idx + 1
            if end < 0 or not calls:
                continue
            constructors = cls._source_visible_constructor_params_for_fqn(root, fqns[0])
            replacement = ""
            for params in constructors:
                if not params:
                    continue
                param_names = [name for _typ, name in params]
                if all(name in calls for name in param_names):
                    replacement = f"new {simple}(" + ", ".join(calls[name] for name in param_names) + ")"
                    break
            if not replacement:
                continue
            replacements.append((match.start(), end, replacement, f"{simple}.builder()->constructor"))
        if not replacements:
            return code, []
        parts: list[str] = []
        pos = 0
        applied: list[str] = []
        for start, end, replacement, label in replacements:
            if start < pos:
                continue
            parts.append(code[pos:start])
            parts.append(replacement)
            pos = end
            applied.append(label)
        parts.append(code[pos:])
        return "".join(parts), applied

    @classmethod
    def _source_builder_list_setter_element_types_for_fqn(
        cls,
        project_root: Path,
        fqn: str,
    ) -> dict[str, str]:
        source_file = cls._find_project_source_for_fqn(project_root, fqn)
        if source_file is None:
            return {}
        try:
            source_text = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return {}
        source = cls._strip_java_comments_and_strings(source_text)
        builder_match = re.search(
            r"\bpublic\s+static\s+(?P<builder>[A-Z][A-Za-z0-9_$]*)\s+builder\s*\(\s*\)\s*\{",
            source,
        )
        if not builder_match:
            return {}
        builder_type = builder_match.group("builder")
        class_match = re.search(
            rf"\b(?:public|protected|private)?\s*(?:static\s+)?(?:final\s+)?class\s+{re.escape(builder_type)}\b[^\{{]*\{{",
            source,
        )
        if not class_match:
            return {}
        open_brace = source.find("{", class_match.end() - 1)
        close_brace = cls._find_matching_brace(source, open_brace)
        if open_brace < 0 or close_brace < 0:
            return {}
        block = source[open_brace + 1:close_brace]
        setters: dict[str, str] = {}
        method_re = re.compile(
            rf"\bpublic\s+{re.escape(builder_type)}\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*\(([^)]*)\)",
            re.DOTALL,
        )
        for match in method_re.finditer(block):
            method_name = match.group(1)
            params = cls._split_top_level_args(match.group(2).strip())
            if len(params) != 1:
                continue
            param = re.sub(r"@\w+(?:\([^)]*\))?\s*", "", params[0]).strip()
            list_match = re.search(
                r"\b(?:java\.util\.)?List\s*<\s*([A-Za-z_$][A-Za-z0-9_$.]*)(?:\s*<[^>]+>)?\s*(?:\?)?\s*>",
                param,
            )
            if not list_match:
                continue
            elem = list_match.group(1).rsplit(".", 1)[-1].strip()
            if elem:
                setters[method_name] = elem
        return setters

    @classmethod
    def _rewrite_empty_list_builder_setters_from_source(
        cls,
        code: str,
        project_root: Path | str | None,
        *,
        symbol_index: dict[str, list[str]] | None = None,
    ) -> tuple[str, list[str]]:
        """Replace source-known builder ``List.of()`` setters with a one-element list."""
        if not code or not project_root or "List.of()" not in code or ".builder()" not in code:
            return code, []
        root = Path(project_root)
        if symbol_index is None:
            symbol_index = cls._build_symbol_index(root)
        if not symbol_index:
            return code, []
        imports = cls._extract_source_import_map(code)

        def _fqns_for(simple_name: str) -> list[str]:
            imported = imports.get(simple_name)
            if imported:
                return [imported]
            candidates = list(symbol_index.get(simple_name) or [])
            return candidates if len(candidates) == 1 else []

        def _sample_for(elem: str) -> str:
            if elem == "String":
                return '"value"'
            if elem in {"Integer", "int"}:
                return "1"
            if elem in {"Long", "long"}:
                return "1L"
            if elem in {"Boolean", "boolean"}:
                return "true"
            if elem in {"Double", "double"}:
                return "1.0d"
            if elem in {"Float", "float"}:
                return "1.0f"
            return f"Mockito.mock({elem}.class)"

        replacements: list[tuple[int, int, str, str]] = []
        for match in re.finditer(r"\b([A-Z][A-Za-z0-9_$]*)\.builder\s*\(\s*\)", code):
            simple = match.group(1)
            fqns = _fqns_for(simple)
            if len(fqns) != 1:
                continue
            setters = cls._source_builder_list_setter_element_types_for_fqn(root, fqns[0])
            if not setters:
                continue
            semi = code.find(";", match.end())
            if semi < 0:
                continue
            segment = code[match.start():semi]
            for method_name, elem in setters.items():
                call_re = re.compile(
                    rf"\.\s*{re.escape(method_name)}\s*\(\s*(?:java\.util\.)?List\.of\s*\(\s*\)\s*\)"
                )
                for call_match in call_re.finditer(segment):
                    start = match.start() + call_match.start()
                    end = match.start() + call_match.end()
                    replacement = f".{method_name}(List.of({_sample_for(elem)}))"
                    replacements.append((start, end, replacement, f"{simple}.{method_name}:empty-list->{elem}"))
        if not replacements:
            return code, []
        parts: list[str] = []
        pos = 0
        applied: list[str] = []
        for start, end, replacement, label in sorted(replacements, key=lambda item: item[0]):
            if start < pos:
                continue
            parts.append(code[pos:start])
            parts.append(replacement)
            pos = end
            applied.append(label)
        parts.append(code[pos:])
        return "".join(parts), applied

    @classmethod
    def _add_mockito_static_imports_for_unqualified_calls(cls, code: str) -> str:
        if not code:
            return code
        static_imports = {
            "mock": "static org.mockito.Mockito.mock",
            "when": "static org.mockito.Mockito.when",
            "verify": "static org.mockito.Mockito.verify",
            "times": "static org.mockito.Mockito.times",
            "any": "static org.mockito.ArgumentMatchers.any",
            "anyList": "static org.mockito.ArgumentMatchers.anyList",
            "anyString": "static org.mockito.ArgumentMatchers.anyString",
            "eq": "static org.mockito.ArgumentMatchers.eq",
            "isNull": "static org.mockito.ArgumentMatchers.isNull",
            "notNull": "static org.mockito.ArgumentMatchers.notNull",
        }
        needed: list[str] = []
        cleaned = cls._strip_java_comments_and_strings(code)
        for method, import_target in static_imports.items():
            if re.search(rf"(?<![.\w$]){re.escape(method)}\s*\(", cleaned):
                needed.append(import_target)
        if not needed:
            return code
        non_static, static_lines, _, _ = cls._parse_import_block(code)
        existing = set(static_lines)
        changed = False
        for import_target in needed:
            line = f"import {import_target};"
            if line not in existing:
                static_lines.append(line)
                existing.add(line)
                changed = True
        if not changed:
            return code
        return cls._rewrite_import_block(code, non_static, static_lines)

    @classmethod
    def _add_mockito_class_import_for_qualified_calls(cls, code: str) -> str:
        if not code:
            return code
        cleaned = cls._strip_java_comments_and_strings(code)
        if not re.search(r"(?<![\w$])Mockito\s*\.", cleaned):
            return code
        non_static, static_lines, _, _ = cls._parse_import_block(code)
        if "import org.mockito.Mockito;" in non_static or "import org.mockito.Mockito.*;" in non_static:
            return code
        non_static.append("import org.mockito.Mockito;")
        return cls._rewrite_import_block(code, non_static, static_lines)

    @classmethod
    def _add_reactor_stepverifier_import_for_unqualified_calls(cls, code: str) -> str:
        if not code:
            return code
        cleaned = cls._strip_java_comments_and_strings(code)
        if not re.search(r"(?<![\w$.])StepVerifier\s*\.", cleaned):
            return code
        non_static, static_lines, _, _ = cls._parse_import_block(code)
        if "import reactor.test.StepVerifier;" in non_static or "import reactor.test.*;" in non_static:
            return code
        non_static.append("import reactor.test.StepVerifier;")
        return cls._rewrite_import_block(code, non_static, static_lines)

    @classmethod
    def _add_reflect_method_import_for_unqualified_calls(cls, code: str) -> str:
        if not code:
            return code
        cleaned = cls._strip_java_comments_and_strings(code)
        if not re.search(r"(?<![\w$.])Method\s+[A-Za-z_$][A-Za-z0-9_$]*\s*=", cleaned):
            return code
        if "getDeclaredMethod(" not in cleaned and "getMethod(" not in cleaned:
            return code
        non_static, static_lines, _, _ = cls._parse_import_block(code)
        if "import java.lang.reflect.Method;" in non_static or "import java.lang.reflect.*;" in non_static:
            return code
        non_static.append("import java.lang.reflect.Method;")
        return cls._rewrite_import_block(code, non_static, static_lines)

    @classmethod
    def _rewrite_unavailable_factory_assignments_to_mocks(
        cls,
        java_code: str,
        unavailable_calls: list[str] | set[str] | tuple[str, ...],
        *,
        excluded_simple_types: set[str] | None = None,
    ) -> tuple[str, int]:
        """Replace unavailable collaborator factory assignments with mocks.

        This is intentionally narrow and source-agnostic: it only rewrites a
        single variable initializer whose RHS is one of the already-proven
        unavailable static calls. It does not rewrite receiver construction or
        chained calls, so state-entry behavior remains LLM/source driven.
        """
        if not java_code or not unavailable_calls:
            return java_code, 0
        unavailable = {str(call).strip() for call in unavailable_calls if str(call).strip()}
        if not unavailable:
            return java_code, 0
        excluded = {str(item).strip() for item in (excluded_simple_types or set()) if str(item).strip()}
        changed = 0

        def repl(match: re.Match[str]) -> str:
            nonlocal changed
            indent, modifier, type_name, var_name, owner, method = match.groups()
            if f"{owner}.{method}" not in unavailable:
                return match.group(0)
            # Avoid rewriting primitive/string/value fixtures into mocks.
            simple_type = type_name.rsplit(".", 1)[-1]
            if simple_type in excluded:
                return match.group(0)
            if simple_type in cls._JAVA_LANG_TYPES or simple_type in {
                "BigDecimal", "BigInteger", "LocalDate", "LocalDateTime", "Instant"
            }:
                return match.group(0)
            changed += 1
            return (
                f"{indent}{modifier or ''}{type_name} {var_name} = "
                f"org.mockito.Mockito.mock({type_name}.class);"
            )

        rewritten = re.sub(
            r"(?m)^(\s*)((?:final\s+)?)"
            r"([A-Z][A-Za-z0-9_$.]*(?:<[^;=]+>)?)\s+"
            r"([a-zA-Z_$][A-Za-z0-9_$]*)\s*=\s*"
            r"([A-Z][A-Za-z0-9_$]*)\s*\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\([^;]*\)\s*;",
            repl,
            java_code,
        )
        return rewritten, changed

    @classmethod
    def _constructor_param_types_from_source(cls, source_code: str, class_name: str | None) -> list[list[str]]:
        if not source_code or not class_name:
            return []
        code = cls._strip_java_comments_and_strings(source_code)
        contracts: list[list[str]] = []
        pattern = re.compile(
            rf"\b(?:public|protected|private)?\s*{re.escape(class_name)}\s*\(([^)]*)\)",
            re.MULTILINE,
        )
        for match in pattern.finditer(code):
            params = cls._signature_param_types(f"{class_name}({match.group(1)})")
            contracts.append(params)
        return contracts

    @staticmethod
    def _find_matching_paren(text: str, open_index: int) -> int:
        depth = 0
        i = open_index
        while i < len(text):
            ch = text[i]
            if ch in ('"', "'"):
                quote = ch
                i += 1
                while i < len(text):
                    if text[i] == "\\":
                        i += 2
                        continue
                    if text[i] == quote:
                        break
                    i += 1
            elif ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return -1

    @classmethod
    def _rewrite_unavailable_factory_constructor_args_to_mocks(
        cls,
        java_code: str,
        unavailable_calls: list[str] | set[str] | tuple[str, ...],
        *,
        source_code: str,
        class_name: str | None,
    ) -> tuple[str, int]:
        """Replace unavailable constructor arguments using source constructor types."""
        if not java_code or not unavailable_calls or not class_name:
            return java_code, 0
        unavailable = {str(call).strip() for call in unavailable_calls if str(call).strip()}
        contracts = cls._constructor_param_types_from_source(source_code, class_name)
        if not unavailable or not contracts:
            return java_code, 0

        call_patterns = [
            re.compile(rf"\b{re.escape(call.split('.', 1)[0])}\s*\.\s*{re.escape(call.split('.', 1)[1])}\s*\(")
            for call in unavailable
            if "." in call
        ]
        if not call_patterns:
            return java_code, 0

        out: list[str] = []
        changed = 0
        cursor = 0
        ctor_re = re.compile(rf"\bnew\s+{re.escape(class_name)}\s*\(")
        for match in ctor_re.finditer(java_code):
            open_idx = java_code.find("(", match.start())
            close_idx = cls._find_matching_paren(java_code, open_idx)
            if close_idx == -1:
                continue
            args_text = java_code[open_idx + 1 : close_idx]
            args = cls._split_top_level_args(args_text)
            matching_contract = next((contract for contract in contracts if len(contract) == len(args)), None)
            if not matching_contract:
                continue
            new_args = list(args)
            local_changed = 0
            for idx, arg in enumerate(args):
                if not any(pattern.search(arg) for pattern in call_patterns):
                    continue
                param_type = str(matching_contract[idx] or "").strip()
                simple_type = re.sub(r"<.*>", "", param_type).strip().rsplit(".", 1)[-1]
                if (
                    not simple_type
                    or simple_type in cls._JAVA_LANG_TYPES
                    or simple_type in {"byte", "short", "int", "long", "float", "double", "boolean", "char"}
                ):
                    continue
                new_args[idx] = f"org.mockito.Mockito.mock({simple_type}.class)"
                local_changed += 1
            if not local_changed:
                continue
            out.append(java_code[cursor : open_idx + 1])
            out.append(", ".join(new_args))
            cursor = close_idx
            changed += local_changed
        if not changed:
            return java_code, 0
        out.append(java_code[cursor:])
        return "".join(out), changed

    @staticmethod
    def _render_construction_first_rescue_lines(coverage_feedback: dict) -> list[str]:
        if not TATGEngineAdapter._feedback_has_source_backed_compile_blockers(coverage_feedback):
            return []
        try:
            line_cov = float(coverage_feedback.get("line_coverage") or 0.0)
        except (TypeError, ValueError):
            line_cov = 0.0
        try:
            branch_cov = float(coverage_feedback.get("branch_coverage") or 0.0)
        except (TypeError, ValueError):
            branch_cov = 0.0
        if line_cov >= 0.50 or branch_cov >= 0.50:
            return []
        return [
            "[Construction-First Rescue Mode]",
            "Target-method coverage is still low and source-backed compile blockers were observed. Include at least one minimal compiling target-hit path, then use remaining tests for source-grounded branch/state variation.",
            "- Choose one receiver construction route proven by callable/helper surface, observed construction recipes, or public owner/factory APIs.",
            "- Do not call APIs listed under Source-Backed Compile Blockers; do not invent helper methods to build internal resources.",
            "- Each new test must invoke the target method body at least once; vary exactly one public input/state axis per additional test.",
            "- In test_behavior, name the construction route and the one state/input axis being varied.",
        ]

    @staticmethod
    def _render_immediate_validation_failure_objectives(
        directional_feedback: object,
        *,
        max_items: int = 3,
    ) -> list[str]:
        if not isinstance(directional_feedback, dict):
            return []
        recent = [
            item for item in list(directional_feedback.get("recent_validation_failures") or [])
            if isinstance(item, dict)
        ][:max_items]
        constraints = [
            " ".join(str(rule or "").split())
            for rule in list(directional_feedback.get("direction_constraints") or [])[:2]
            if str(rule or "").strip()
        ]
        if not recent and not constraints:
            return []
        lines = [
            "Immediate validation failure objectives:",
            "Fix these observed construction/runtime failures before adding new coverage axes; do not repeat the same null/empty/smoke candidate shape.",
        ]
        for item in recent:
            bits: list[str] = []
            test_method = str(item.get("test_method") or "").strip()
            category = str(item.get("category") or item.get("reason") or "").strip()
            exception_type = str(item.get("exception_type") or "").strip()
            message = " ".join(str(item.get("message") or "").split())[:180]
            if test_method:
                bits.append(f"test={test_method}")
            if category:
                bits.append(f"category={category}")
            if exception_type:
                bits.append(f"exception={exception_type}")
            if message:
                bits.append(f"message={message}")
            signal = item.get("failure_signal") if isinstance(item.get("failure_signal"), dict) else {}
            builder_required = item.get("builder_required_field")
            if not isinstance(builder_required, dict):
                builder_required = signal.get("builder_required_field") if isinstance(signal.get("builder_required_field"), dict) else {}
            if isinstance(builder_required, dict) and builder_required:
                owner_type = str(builder_required.get("owner_type") or "").strip()
                field = str(builder_required.get("field") or "").strip()
                required_setup = TATGEngineAdapter._shorten_inline(
                    builder_required.get("required_setup"),
                    220,
                )
                fact = "builder_required_field="
                if owner_type:
                    fact += f"{owner_type}."
                fact += field or "non-null-field"
                if required_setup:
                    fact += f"; setup={required_setup}"
                bits.append(fact)
            observable_payload = item.get("observable_builder_payload")
            if not isinstance(observable_payload, dict):
                observable_payload = signal.get("observable_builder_payload") if isinstance(signal.get("observable_builder_payload"), dict) else {}
            if isinstance(observable_payload, dict) and observable_payload:
                owner_type = str(observable_payload.get("owner_type") or "").strip()
                getter = str(observable_payload.get("getter") or "").strip()
                field = str(observable_payload.get("field") or "").strip()
                required_setup = TATGEngineAdapter._shorten_inline(
                    observable_payload.get("required_setup"),
                    240,
                )
                payload_fact = "observable_builder_payload="
                if owner_type:
                    payload_fact += f"{owner_type}."
                payload_fact += getter or field or "non-null-observable"
                if field:
                    payload_fact += f"; field={field}"
                if required_setup:
                    payload_fact += f"; setup={required_setup}"
                bits.append(payload_fact)
            pre_target = item.get("pre_target_failure")
            statement = ""
            if isinstance(pre_target, dict):
                statement = " ".join(str(pre_target.get("statement") or "").split())[:180]
            if statement:
                bits.append(f"failed_statement={statement}")
            action = (
                "required_action=repair the exact source-visible input/collaborator/state setup that failed; "
                "only keep exception assertions when that exception type is actually observed from the target path"
            )
            if category in {
                "missing-required-initialization",
                "missing-required-terminal-initialization",
                "pre_target_builder_setup_blocker",
            }:
                action = (
                    "required_action=build one valid baseline with source_required_public_input_baseline plus exact "
                    "collaborator/terminal callback or result consumption before testing guard/exception variants"
                )
            if category == "invalid-public-input":
                action = (
                    "required_action=satisfy source_required_public_input_baseline first; reserve null/empty/malformed "
                    "inputs for a separate guard objective after one target-positive baseline exists"
                )
            if category == "mock-stub-misuse":
                action = (
                    "required_action=replace invalid Mockito.when(...) setup with a source-visible real object, fake/subclass, "
                    "or a stub on a variable proven to be Mockito.mock(...); do not stub final/private/non-public-parent methods"
                )
            if bits:
                lines.append("- " + "; ".join(bits) + "; " + action)
        for rule in constraints:
            lines.append("- observed_constraint=" + rule[:240])
        return lines

    @staticmethod
    def _select_feedback_obligations_for_render(coverage_feedback: dict, obligations: list[dict]) -> tuple[list[dict], int]:
        """Render a small, priority-ordered obligation slice.

        The full obligation set is still kept in feedback state.  This helper
        only controls prompt surface area so measured directions and
        source-backed blockers are not buried under many unrelated open paths.
        """
        if not obligations:
            return [], 0
        render_max = TATGEngineAdapter._env_int("TATG_RENDER_MAX_OBLIGATIONS", 6, minimum=1, maximum=32)
        if TATGEngineAdapter._feedback_has_source_backed_compile_blockers(coverage_feedback):
            render_max = min(render_max, TATGEngineAdapter._env_int("TATG_RENDER_MAX_BLOCKER_OBLIGATIONS", 4, minimum=1, maximum=16))
        directional = coverage_feedback.get("measured_directional_feedback") if isinstance(coverage_feedback, dict) else {}
        if not isinstance(directional, dict):
            directional = {}
        next_ids = [
            str(item).strip()
            for item in list(directional.get("next_required_obligation_ids") or [])
            if str(item).strip()
        ]
        open_ids = [
            str(item).strip()
            for item in list(directional.get("open_obligation_ids") or [])
            if str(item).strip()
        ]
        preferred_groups = [
            sorted(next_ids, key=TATGEngineAdapter._oid_sort_key),
            sorted([oid for oid in open_ids if oid not in set(next_ids)], key=TATGEngineAdapter._oid_sort_key),
        ]
        by_id = {
            str(item.get("id") or "").strip(): item
            for item in obligations
            if str(item.get("id") or "").strip()
        }
        next_rank = {oid: idx for idx, oid in enumerate(next_ids)}
        open_rank = {oid: idx for idx, oid in enumerate(open_ids)}

        def _obligation_priority(item: dict) -> tuple[int, int, int, int, int, int, tuple[int, str]]:
            oid = str(item.get("id") or "").strip()
            partial_count = len([a for a in list(item.get("partial_branch_source_lines") or []) if isinstance(a, dict)])
            missed_count = len([a for a in list(item.get("missed_source_lines") or []) if isinstance(a, dict)])
            state_plan = TATGEngineAdapter._merge_obligation_state_dependency_plan(item)
            state_score = sum(len(list(state_plan.get(key) or [])) for key in state_plan)
            setup_score = len([v for v in list(item.get("required_setup") or []) if str(v).strip()])
            lifecycle = TATGEngineAdapter._coverage_obligation_lifecycle_status(item)
            lifecycle_rank = {
                "active_uncovered": 0,
                "partial_progress": 0,
                "salvage_candidate_failed": 0,
                "blocked_compile": 1,
                "blocked_runtime_setup": 1,
                "satisfied": 3,
            }.get(lifecycle, 2)
            # Keep measured next/open directions first, then prefer obligations
            # that expose concrete uncovered anchors and state-entry evidence.
            group = 0 if oid in next_rank else (1 if oid in open_rank else 2)
            group_rank = next_rank.get(oid, open_rank.get(oid, 10**6))
            return (
                lifecycle_rank,
                group,
                -partial_count,
                -missed_count,
                -state_score,
                -setup_score,
                group_rank,
                TATGEngineAdapter._oid_sort_key(oid),
            )

        selected: list[dict] = []
        seen: set[str] = set()
        for group in preferred_groups:
            group_items = [by_id[oid] for oid in group if oid in by_id]
            for item in sorted(group_items, key=_obligation_priority):
                oid = str(item.get("id") or "").strip()
                if item and oid not in seen:
                    selected.append(item)
                    seen.add(oid)
                if len(selected) >= render_max:
                    return selected, len(obligations)
        for item in sorted(obligations, key=_obligation_priority):
            oid = str(item.get("id") or "").strip()
            if oid in seen:
                continue
            selected.append(item)
            if oid:
                seen.add(oid)
            if len(selected) >= render_max:
                break
        return selected, len(obligations)

    @staticmethod
    def _coverage_obligation_lifecycle_status(obligation: object) -> str:
        """Classify an obligation for feedback-round prompt ordering."""
        if not isinstance(obligation, dict):
            return "active_uncovered"
        satisfied = obligation.get("satisfied")
        reason = str(obligation.get("reason") or "").strip().lower()
        if satisfied is True:
            return "satisfied"
        if "compile" in reason or "type" in reason or "symbol" in reason:
            return "blocked_compile"
        if "runtime" in reason or "setup" in reason or "initialization" in reason:
            return "blocked_runtime_setup"
        try:
            closed = int(obligation.get("closed_anchor_gap_count") or 0)
            remaining = int(obligation.get("remaining_anchor_gap_count") or 0)
        except (TypeError, ValueError):
            closed = 0
            remaining = 0
        if remaining > 0 and closed > 0:
            return "partial_progress"
        return "active_uncovered"

    @staticmethod
    def _coverage_obligation_contract_payload(
        coverage_feedback: object,
    ) -> list[dict[str, object]]:
        """Return exact, bounded source contracts for generated O-id tests.

        Candidate validation previously retained only the O-id string.  A
        candidate that closed a different missed line could therefore look
        like useful progress for its selected obligation, and post-target
        repair was allowed to delete the assertion exposing the mismatch.
        Keep the exact source anchors and control path with the candidate so
        repair can preserve objective intent.  This is data projection only;
        it does not classify methods or infer domain-specific input rows.
        """

        if not isinstance(coverage_feedback, dict):
            return []
        contracts: list[dict[str, object]] = []
        for obligation in list(
            coverage_feedback.get("coverage_obligations") or []
        )[:24]:
            if not isinstance(obligation, dict):
                continue
            objective_id = str(obligation.get("id") or "").strip()
            if not objective_id.upper().startswith("O"):
                continue
            anchors: list[dict[str, object]] = []
            seen: set[tuple[int, str]] = set()
            for key in (
                "missed_source_lines",
                "partial_branch_source_lines",
            ):
                for raw in list(obligation.get(key) or [])[:12]:
                    if not isinstance(raw, dict):
                        continue
                    try:
                        line = int(raw.get("line") or 0)
                    except (TypeError, ValueError):
                        line = 0
                    code = str(raw.get("code") or "").strip()
                    identity = (line, code)
                    if line <= 0 or identity in seen:
                        continue
                    seen.add(identity)
                    anchors.append({
                        "line": line,
                        "code": code[:500],
                        "branch_gap": str(
                            raw.get("branch_gap") or ""
                        )[:300],
                        "control_path": [
                            {
                                "line": node.get("line"),
                                "statement": str(
                                    node.get("statement") or ""
                                )[:500],
                                "required_outcome": str(
                                    node.get("required_outcome") or ""
                                )[:160],
                            }
                            for node in list(
                                raw.get("control_path") or []
                            )[:8]
                            if isinstance(node, dict)
                        ],
                    })
            if not anchors:
                continue
            contracts.append({
                "objective_id": objective_id,
                "kind": str(obligation.get("category") or "")[:100],
                "scenario": str(
                    obligation.get("scenario") or ""
                )[:400],
                "target_call": str(
                    obligation.get("target_call") or ""
                )[:400],
                "anchors": anchors[:12],
                "proof_status": "source_and_live_coverage_required",
            })
        return contracts

    @staticmethod
    def _feedback_obligations_by_lifecycle(obligations: list[dict]) -> dict[str, list[dict]]:
        grouped: dict[str, list[dict]] = {
            "active_uncovered": [],
            "partial_progress": [],
            "blocked_compile": [],
            "blocked_runtime_setup": [],
            "satisfied": [],
        }
        for obligation in obligations:
            if not isinstance(obligation, dict):
                continue
            status = TATGEngineAdapter._coverage_obligation_lifecycle_status(obligation)
            grouped.setdefault(status, []).append(obligation)
        return grouped

    @staticmethod
    def _render_objective_anchor_lines_for_feedback(
        obligation: object,
        *,
        max_each: int | None = None,
        indent: str = "  ",
        include_state_dependency_plan: bool = True,
    ) -> list[str]:
        """Render source-grounded anchors without blind character truncation."""
        if not isinstance(obligation, dict):
            return []
        if max_each is None:
            max_each = TATGEngineAdapter._env_int(
                "TATG_RENDER_MAX_ACTIVE_OBJECTIVE_ANCHORS",
                32,
                minimum=1,
                maximum=128,
            )
        compact_state_recipe = TATGEngineAdapter._compact_state_recipe_for_obligation(obligation)
        lines: list[str] = []
        for label, key in (("missed", "missed_source_lines"), ("partial", "partial_branch_source_lines")):
            anchors = [item for item in list(obligation.get(key) or []) if isinstance(item, dict)]
            if not anchors:
                continue
            if len(anchors) > max_each:
                lines.append(f"{indent}anchors.{label}: showing {max_each}/{len(anchors)} source-grounded anchors")
            else:
                lines.append(f"{indent}anchors.{label}:")
            for anchor in anchors[:max_each]:
                line_no = anchor.get("line")
                code = TATGEngineAdapter._shorten_inline(
                    anchor.get("logical_statement") or anchor.get("branch_expression") or anchor.get("code"),
                    220,
                )
                if not line_no and not code:
                    continue
                entry = f"{indent}- L{line_no}: {code}" if line_no else f"{indent}- {code}"
                branch_gap = TATGEngineAdapter._shorten_inline(anchor.get("branch_gap"), 180)
                if branch_gap:
                    entry += f" [{branch_gap}]"
                lines.append(entry)
                control_path = [
                    node for node in list(anchor.get("control_path") or [])
                    if isinstance(node, dict) and str(node.get("statement") or "").strip()
                ]
                if control_path:
                    rendered_path = " -> ".join(
                        f"L{node.get('line')}: {TATGEngineAdapter._shorten_inline(node.get('statement'), 120)}"
                        for node in control_path[-4:]
                    )
                    lines.append(f"{indent}  required_control_path: {rendered_path}")
                branch_expression = TATGEngineAdapter._shorten_inline(anchor.get("branch_expression"), 180)
                if branch_expression and branch_expression != code:
                    lines.append(f"{indent}  branch_expression: {branch_expression}")
                if not compact_state_recipe:
                    for state_hint in [
                        TATGEngineAdapter._shorten_high_priority_hint(item)
                        for item in list(anchor.get("public_state_search_hints") or [])[:3]
                        if str(item).strip()
                    ]:
                        lines.append(f"{indent}  public_state_hint: {state_hint}")
                if include_state_dependency_plan:
                    for state_line in TATGEngineAdapter._render_state_dependency_plan(
                        anchor.get("state_dependency_plan"),
                        indent=f"{indent}  ",
                    ):
                        lines.append(state_line)
        return lines

    @staticmethod
    def _feedback_anchor_identity(label: str, anchor: object) -> str:
        """Return a stable identity for one source-grounded coverage anchor."""
        if not isinstance(anchor, dict):
            return ""
        control_path = [
            {
                "line": item.get("line"),
                "statement": re.sub(
                    r"\s+",
                    " ",
                    str(item.get("statement") or "").strip(),
                ),
            }
            for item in list(anchor.get("control_path") or [])
            if isinstance(item, dict)
        ]
        payload = {
            "label": str(label or ""),
            "line": anchor.get("line"),
            "statement": re.sub(
                r"\s+",
                " ",
                str(
                    anchor.get("logical_statement")
                    or anchor.get("branch_expression")
                    or anchor.get("code")
                    or ""
                ).strip(),
            ),
            "branch_gap": re.sub(
                r"\s+",
                " ",
                str(anchor.get("branch_gap") or "").strip(),
            ),
            "control_path": control_path,
        }
        if not payload["line"] and not payload["statement"]:
            return ""
        return json.dumps(payload, sort_keys=True, separators=(",", ":"))

    @classmethod
    def _render_active_uncovered_objectives_section(
        cls,
        coverage_feedback: dict,
        obligations: list[dict],
        *,
        method_is_private: bool = False,
        private_entry_points: list[dict[str, object]] | None = None,
    ) -> str:
        active = [
            item for item in obligations
            if not TATGEngineAdapter._is_quality_hint_obligation(item)
            and TATGEngineAdapter._coverage_obligation_lifecycle_status(item)
            in {"active_uncovered", "partial_progress", "blocked_compile", "blocked_runtime_setup"}
        ]
        if not active:
            return ""
        verified_private_entries = (
            cls._verified_private_entry_points(private_entry_points)
            if method_is_private
            else []
        )
        private_entry_signature = ""
        if verified_private_entries:
            selected_entry = verified_private_entries[0]
            private_entry_signature = str(
                selected_entry.get("signature")
                or selected_entry.get("method")
                or ""
            ).strip().rstrip("{").rstrip()
        lines = [
            "[Active Uncovered Objectives]",
            "These are the current live-run objectives that still need coverage or setup repair. Preserve every listed source line/branch fact; do not replace them with generic smoke tests.",
        ]
        anchor_records: dict[str, tuple[str, dict]] = {}
        anchor_owners: dict[str, set[str]] = {}
        state_plan_owners: dict[str, set[str]] = {}
        state_plans: dict[str, dict] = {}
        for obligation in active:
            oid = str(obligation.get("id") or "O?").strip() or "O?"
            seen_for_obligation: set[str] = set()
            for label, key in (
                ("missed", "missed_source_lines"),
                ("partial", "partial_branch_source_lines"),
            ):
                for anchor in [
                    item for item in list(obligation.get(key) or [])
                    if isinstance(item, dict)
                ]:
                    identity = TATGEngineAdapter._feedback_anchor_identity(label, anchor)
                    if not identity or identity in seen_for_obligation:
                        continue
                    seen_for_obligation.add(identity)
                    anchor_records.setdefault(identity, (label, anchor))
                    anchor_owners.setdefault(identity, set()).add(oid)
            plan = TATGEngineAdapter._merge_obligation_state_dependency_plan(obligation)
            if plan:
                plan_identity = json.dumps(plan, sort_keys=True, separators=(",", ":"))
                state_plans.setdefault(plan_identity, plan)
                state_plan_owners.setdefault(plan_identity, set()).add(oid)

        shared_anchor_keys = [
            identity
            for identity, owners in anchor_owners.items()
            if len(owners) > 1
        ][:12]
        shared_anchor_ids = {
            identity: f"A{index}"
            for index, identity in enumerate(shared_anchor_keys, start=1)
        }
        shared_plan_keys = [
            identity
            for identity, owners in state_plan_owners.items()
            if len(owners) > 1
        ][:6]
        shared_plan_ids = {
            identity: f"SP{index}"
            for index, identity in enumerate(shared_plan_keys, start=1)
        }
        if shared_plan_ids:
            lines.extend([
                "shared_source_validated_state_plans:",
                "  Reuse these exact plans by SP-id; an objective reference does not remove or weaken the plan.",
            ])
            for identity, plan_id in shared_plan_ids.items():
                owners = ",".join(sorted(state_plan_owners.get(identity) or set()))
                lines.append(f"  - {plan_id}; objectives={owners}")
                lines.extend(
                    TATGEngineAdapter._render_state_dependency_plan(
                        state_plans[identity],
                        indent="    ",
                    )
                )
        if shared_anchor_ids:
            lines.extend([
                "shared_source_anchors:",
                "  These identical source anchors apply to every referenced objective and are rendered once to avoid contradictory repetition.",
            ])
            for identity, anchor_id in shared_anchor_ids.items():
                label, anchor = anchor_records[identity]
                owners = ",".join(sorted(anchor_owners.get(identity) or set()))
                lines.append(f"  - {anchor_id} [{label}]; objectives={owners}")
                temp_obligation = {
                    f"{label}_source_lines": [anchor],
                }
                lines.extend(
                    TATGEngineAdapter._render_objective_anchor_lines_for_feedback(
                        temp_obligation,
                        max_each=1,
                        indent="    ",
                        include_state_dependency_plan=False,
                    )
                )
        for obligation in active:
            oid = str(obligation.get("id") or "O?").strip() or "O?"
            category = str(obligation.get("category") or "CoverageObligation").strip()
            status = TATGEngineAdapter._coverage_obligation_lifecycle_status(obligation)
            is_quality_hint = (
                obligation.get("counts_toward_satisfaction") is False
                or str(obligation.get("obligation_layer") or "").strip() == "quality_hint"
            )
            scenario = TATGEngineAdapter._compact_high_priority_hint(
                obligation.get("scenario") or "cover uncovered target behavior",
                480,
            ) or "cover uncovered target behavior"
            layer_suffix = "; layer=quality_hint" if is_quality_hint else ""
            lines.append(f"- {oid} [{category}] status={status}{layer_suffix}; goal={scenario}")
            demoted_reason = TATGEngineAdapter._shorten_inline(obligation.get("frontier_demoted_reason"), 160)
            if demoted_reason:
                lines.append(f"  demoted_reason: {demoted_reason}")
            reason = TATGEngineAdapter._shorten_inline(obligation.get("reason"), 160)
            if reason:
                lines.append(f"  reason: {reason}")
            anchor_count = obligation.get("anchor_count")
            closed = obligation.get("closed_anchor_gap_count")
            remaining = obligation.get("remaining_anchor_gap_count")
            if anchor_count is not None or closed is not None or remaining is not None:
                lines.append(f"  anchor_progress: closed={closed}/{anchor_count}; remaining={remaining}")
            program_fact = TATGEngineAdapter._shorten_high_priority_hint(
                obligation.get("program_fact"),
                600,
            )
            if program_fact:
                lines.append(f"  target_fact: {program_fact}")
            setup_items = TATGEngineAdapter._compact_high_priority_items(
                obligation.get("required_setup"),
                limit=520,
                max_items=5,
            )
            if setup_items:
                lines.append("  required_setup: " + "; ".join(setup_items))
            state_recipe = TATGEngineAdapter._compact_state_recipe_for_obligation(obligation)
            if state_recipe:
                lines.append(f"  state_recipe: {state_recipe}")
            state_plan = TATGEngineAdapter._merge_obligation_state_dependency_plan(obligation)
            state_plan_identity = (
                json.dumps(state_plan, sort_keys=True, separators=(",", ":"))
                if state_plan
                else ""
            )
            shared_plan_id = shared_plan_ids.get(state_plan_identity)
            if shared_plan_id:
                lines.append(f"  state_plan_ref: {shared_plan_id}")
            else:
                lines.extend(TATGEngineAdapter._render_state_dependency_plan(state_plan, indent="  "))
            target_call = TATGEngineAdapter._shorten_high_priority_hint(
                obligation.get("target_call") or "invoke the target method",
                480,
            )
            if private_entry_signature:
                target_call = (
                    "invoke the exact source-verified visible entry `"
                    + private_entry_signature
                    + "`; do not call the private target directly. Reason "
                    "backward from the listed target branch/source facts "
                    "through the supplied caller source to choose public "
                    "inputs or ordered calls; descriptor-level candidate "
                    "coverage must prove the private target was reached"
                )
            if target_call:
                lines.append(f"  target_call: {target_call}")
            oracle_items = TATGEngineAdapter._compact_high_priority_items(
                obligation.get("oracle"),
                limit=480,
                max_items=4,
            )
            if oracle_items:
                lines.append("  oracle: " + "; ".join(oracle_items))
            parser_rows = TATGEngineAdapter._parser_token_input_rows_for_obligation(obligation)
            if parser_rows:
                lines.append("  parser_token_input_rows:")
                for row in parser_rows:
                    lines.append(f"  - {row}")
            anchor_refs: list[str] = []
            local_obligation = dict(obligation)
            for label, key in (
                ("missed", "missed_source_lines"),
                ("partial", "partial_branch_source_lines"),
            ):
                local_anchors: list[dict] = []
                for anchor in [
                    item for item in list(obligation.get(key) or [])
                    if isinstance(item, dict)
                ]:
                    identity = TATGEngineAdapter._feedback_anchor_identity(label, anchor)
                    anchor_id = shared_anchor_ids.get(identity)
                    if anchor_id:
                        if anchor_id not in anchor_refs:
                            anchor_refs.append(anchor_id)
                    else:
                        local_anchors.append(anchor)
                local_obligation[key] = local_anchors
            if anchor_refs:
                lines.append("  anchor_refs: " + ", ".join(anchor_refs))
            lines.extend(
                TATGEngineAdapter._render_objective_anchor_lines_for_feedback(
                    local_obligation,
                    max_each=8,
                    include_state_dependency_plan=not bool(shared_plan_id),
                )
            )
            anti_dup = TATGEngineAdapter._shorten_inline(obligation.get("anti_duplication_key"), 180)
            if anti_dup:
                lines.append(f"  anti_duplication_key: {anti_dup}")
            if is_quality_hint:
                lines.append(
                    f"  candidate_hint: optional objective_id={oid} only if this hint supports a source-backed executable recipe; do not bind coverage_obligation_id to this quality hint."
                )
            else:
                lines.append(
                    f"  required_candidate: coverage_obligation_id={oid}; candidate_role targets this active status; @Test name contains {oid}."
                )
        return "\n".join(lines)

    @staticmethod
    def _is_quality_hint_obligation(obligation: object) -> bool:
        return (
            isinstance(obligation, dict)
            and (
                obligation.get("counts_toward_satisfaction") is False
                or str(obligation.get("obligation_layer") or "").strip() == "quality_hint"
            )
        )

    @classmethod
    def _filter_current_round_test_objectives(
        cls,
        test_objectives: list[dict] | None,
        *,
        binding_obligation_ids: set[str] | None = None,
        demoted_obligation_ids: set[str] | None = None,
        mutation_feedback_allowed: bool = False,
    ) -> list[dict]:
        """Keep only objectives that are allowed to bind this round.

        A demoted O-id may remain visible as an optional quality hint, but it
        must not be rendered as a current objective or accepted in required
        coverage_obligation_id binding.
        """
        binding_ids = {str(item).strip() for item in set(binding_obligation_ids or set()) if str(item).strip()}
        demoted_ids = {str(item).strip() for item in set(demoted_obligation_ids or set()) if str(item).strip()}
        filtered: list[dict] = []
        seen: set[str] = set()
        for item in list(test_objectives or []):
            if not isinstance(item, dict):
                continue
            oid = str(item.get("id") or item.get("objective_id") or item.get("mutation_objective_id") or "").strip()
            if cls._is_mutation_objective(item):
                if not mutation_feedback_allowed:
                    continue
            elif re.fullmatch(r"O\d+", oid or ""):
                if oid in demoted_ids:
                    continue
                if binding_ids and oid not in binding_ids:
                    continue
            key = oid or json.dumps(item, sort_keys=True, default=str)[:120]
            if key in seen:
                continue
            seen.add(key)
            filtered.append(item)
        return filtered

    @staticmethod
    def _render_demoted_optional_objective_hints_section(obligations: list[dict]) -> str:
        hints = [
            item for item in obligations
            if TATGEngineAdapter._is_quality_hint_obligation(item)
        ]
        if not hints:
            return ""
        lines = [
            "[Demoted Optional Objective Hints]",
            "These hints are advisory only because a more source-backed frontier/recipe is available. Do not bind coverage_obligation_id to these O-ids and do not let null/empty/shape variants replace the executable recipe.",
        ]
        for item in hints[:6]:
            oid = str(item.get("id") or "O?").strip() or "O?"
            category = str(item.get("category") or "CoverageObligation").strip()
            fact = TATGEngineAdapter._shorten_inline(
                item.get("program_fact") or item.get("scenario") or item.get("anti_duplication_key"),
                180,
            )
            reason = TATGEngineAdapter._shorten_inline(
                item.get("frontier_demoted_reason") or item.get("demoted_reason") or "quality_hint",
                140,
            )
            bits = [f"{oid} [{category}]", "optional_only=true", "coverage_obligation_id=forbidden"]
            if fact:
                bits.append(f"fact={fact}")
            if reason:
                bits.append(f"reason={reason}")
            lines.append("- " + "; ".join(bits))
        if len(hints) > 6:
            lines.append(f"- ... {len(hints) - 6} more optional hints omitted.")
        return "\n".join(lines)

    @staticmethod
    def _render_satisfied_objectives_summary_section(obligations: list[dict]) -> str:
        satisfied = [
            item for item in obligations
            if TATGEngineAdapter._coverage_obligation_lifecycle_status(item) == "satisfied"
        ]
        if not satisfied:
            return ""
        max_items = TATGEngineAdapter._env_int("TATG_RENDER_MAX_SATISFIED_OBJECTIVES", 8, minimum=1, maximum=64)
        lines = [
            "[Satisfied Objectives Summary]",
            "Already covered in this live feedback state; keep as anti-duplication/skeleton evidence and prioritize active uncovered objectives above.",
        ]
        for obligation in satisfied[:max_items]:
            oid = str(obligation.get("id") or "O?").strip() or "O?"
            category = str(obligation.get("category") or "CoverageObligation").strip()
            scenario = TATGEngineAdapter._shorten_inline(
                obligation.get("scenario") or obligation.get("program_fact"),
                180,
            )
            closed = obligation.get("closed_anchor_gap_count")
            anchor_count = obligation.get("anchor_count")
            anti_dup = TATGEngineAdapter._shorten_inline(obligation.get("anti_duplication_key"), 140)
            bits = [f"{oid} [{category}]"]
            if scenario:
                bits.append(f"covered={scenario}")
            if anchor_count is not None or closed is not None:
                bits.append(f"anchors_closed={closed}/{anchor_count}")
            if anti_dup:
                bits.append(f"anti_duplication_key={anti_dup}")
            lines.append("- " + "; ".join(bits))
        if len(satisfied) > max_items:
            lines.append(f"- ... {len(satisfied) - max_items} more satisfied objective(s) summarized, not expanded.")
        return "\n".join(lines)

    @staticmethod
    def _shorten_inline(text: object, limit: int = 220) -> str:
        value = re.sub(r"\s+", " ", str(text or "").strip())
        if limit <= 0 or len(value) <= limit:
            return value
        return value[: max(0, limit - 3)].rstrip() + "..."

    @staticmethod
    def _shorten_high_priority_hint(text: object, limit: int = 220) -> str:
        """Normalize one authoritative fact without clipping its meaning."""
        return re.sub(r"\s+", " ", str(text or "").strip())

    @staticmethod
    def _compact_high_priority_hint(text: object, limit: int = 220) -> str:
        """Return a complete-clause prefix for repeatable prompt-list items."""
        value = re.sub(r"\s+", " ", str(text or "").strip())
        if limit <= 0 or len(value) <= limit:
            return value
        # Keep only complete clauses. A clipped diagnostic/setup/oracle can
        # look authoritative while silently changing its meaning; retaining
        # the whole oversized fact instead makes every structural prompt grow.
        # If no complete clause fits, omit the field and let the section-level
        # audit account for the omitted item.
        clauses = [
            item.strip()
            for item in re.split(r"(?<=;)\s+|(?<=\.)\s+|\s+\|\s+", value)
            if item.strip()
        ]
        selected: list[str] = []
        total = 0
        for clause in clauses:
            projected = total + len(clause) + (1 if selected else 0)
            if projected > limit:
                break
            selected.append(clause)
            total = projected
        return " ".join(selected)

    @staticmethod
    def _compact_high_priority_items(
        items: object,
        *,
        limit: int,
        max_items: int,
    ) -> list[str]:
        """Keep only complete, non-empty high-priority prompt items."""
        compacted: list[str] = []
        for item in list(items or [])[:max_items]:
            if not str(item).strip():
                continue
            value = TATGEngineAdapter._compact_high_priority_hint(item, limit)
            if value:
                compacted.append(value)
        return compacted

    @staticmethod
    def _parser_token_input_rows_for_obligation(obligation: object) -> list[str]:
        """Render compact token/cursor rows when source anchors prove parser paths.

        This historical keyword mapper is opt-in for reproducibility only.
        Default TATG feedback uses the separately validated semantic branch
        analyzer so arbitrary method names and protocols receive the same
        treatment.
        """
        if not TATGEngineAdapter._legacy_name_heuristics_enabled():
            return []
        if not isinstance(obligation, dict):
            return []
        category = str(obligation.get("category") or "")
        anchors: list[dict[str, Any]] = []
        for key in ("missed_source_lines", "partial_branch_source_lines"):
            anchors.extend([item for item in list(obligation.get(key) or []) if isinstance(item, dict)])
        snippets: list[str] = []
        for anchor in anchors:
            snippets.append(str(anchor.get("logical_statement") or anchor.get("branch_expression") or anchor.get("code") or ""))
            for node in list(anchor.get("control_path") or []):
                if isinstance(node, dict):
                    snippets.append(str(node.get("statement") or ""))
        text = "\n".join(snippets)
        lower = text.lower()
        parser_markers = (
            "isescape",
            "isquote",
            "isdelimiter",
            "readendofline",
            "isendoffile",
            "readescape",
            "lookahead",
            "token.",
            "eof",
            "eorecord",
        )
        if "TokenPathMatrix" not in category and sum(1 for marker in parser_markers if marker in lower) < 3:
            return []
        rows: list[str] = [
            "token_cursor_precondition: if invoking a private parse/cursor helper directly, arrange the reader/cursor at the helper precondition proven by its public caller; prefer public caller sequence when available",
        ]
        if re.search(r"\bisEscape\s*\(|\breadEscape\s*\(|\bisEscapeDelimiter\s*\(", text):
            rows.append(
                "input_shape_row: escape path: put escape char before delimiter/quote and one malformed EOF-after-escape variant; assert content append or exact IOException"
            )
        if re.search(r"\bisQuoteChar\s*\(", text):
            rows.append(
                "input_shape_row: quote path: include doubled quote, closing quote followed by delimiter, closing quote followed by EOL/EOF, and closing quote followed by invalid non-whitespace"
            )
        if re.search(r"\bisDelimiter\s*\(", text):
            rows.append(
                "input_shape_row: delimiter path: after finishing token, place delimiter immediately after optional whitespace and assert TOKEN/result boundary"
            )
        if re.search(r"\breadEndOfLine\s*\(|EORECORD", text):
            rows.append(
                "input_shape_row: eol path: after finishing token, place CR/LF and assert EORECORD/result boundary"
            )
        if re.search(r"\bisEndOfFile\s*\(|EOF|END_OF_STREAM", text):
            rows.append(
                "input_shape_row: eof path: close token at EOF and also test EOF before close for exact exception"
            )
        return rows[:6]

    @staticmethod
    def _render_obligation_anchor_summary(obligation: object) -> list[str]:
        if not isinstance(obligation, dict):
            return []
        max_each = TATGEngineAdapter._env_int("TATG_RENDER_MAX_OBJECTIVE_ANCHORS", 2, minimum=1, maximum=6)
        compact_state_recipe = TATGEngineAdapter._compact_state_recipe_for_obligation(obligation)
        lines: list[str] = []
        for label, key in (("missed", "missed_source_lines"), ("partial", "partial_branch_source_lines")):
            rendered: list[str] = []
            for anchor in [
                item for item in list(obligation.get(key) or [])[:max_each]
                if isinstance(item, dict)
            ]:
                line_no = anchor.get("line")
                code = TATGEngineAdapter._shorten_inline(
                    anchor.get("logical_statement") or anchor.get("branch_expression") or anchor.get("code"),
                    150,
                )
                if not line_no or not code:
                    continue
                entry = f"L{line_no}: {code}"
                control_path = [
                    node for node in list(anchor.get("control_path") or [])
                    if isinstance(node, dict) and str(node.get("statement") or "").strip()
                ]
                if control_path:
                    rendered_path = " -> ".join(
                        f"L{node.get('line')}: {TATGEngineAdapter._shorten_inline(node.get('statement'), 90)}"
                        for node in control_path[-2:]
                    )
                    entry += f" [path: {rendered_path}]"
                branch_gap = TATGEngineAdapter._shorten_inline(anchor.get("branch_gap"), 120)
                if branch_gap:
                    entry += f" [{branch_gap}]"
                state_hints = [
                    TATGEngineAdapter._shorten_high_priority_hint(item)
                    for item in list(anchor.get("public_state_search_hints") or [])[:1]
                    if str(item).strip()
                ]
                if state_hints and not compact_state_recipe:
                    entry += " [state_hint: " + "; ".join(state_hints) + "]"
                hint = TATGEngineAdapter._shorten_inline(anchor.get("hint"), 120)
                if hint:
                    entry += f" -> {hint}"
                rendered.append(entry)
            if rendered:
                lines.append(f"  anchors.{label}: " + " | ".join(rendered))
        return lines

    @staticmethod
    def _merge_obligation_state_dependency_plan(obligation: object) -> dict:
        if not isinstance(obligation, dict):
            return {}
        merged: dict[str, list[str]] = {
            "target_state": [],
            "state_entry_sequence_candidates": [],
            "callback_outcome_partition": [],
            "oracle_observation_to_assert": [],
        }
        for key in ("partial_branch_source_lines", "missed_source_lines"):
            for anchor in [
                item for item in list(obligation.get(key) or [])
                if isinstance(item, dict) and isinstance(item.get("state_dependency_plan"), dict)
            ]:
                plan = anchor.get("state_dependency_plan") or {}
                for plan_key in merged:
                    for item in list(plan.get(plan_key) or []):
                        text = str(item).strip()
                        if text and text not in merged[plan_key]:
                            merged[plan_key].append(text)
        return {key: value for key, value in merged.items() if value}

    @staticmethod
    def _render_obligation_forbidden_summary(coverage_feedback: dict) -> str:
        directional = coverage_feedback.get("measured_directional_feedback") if isinstance(coverage_feedback, dict) else {}
        if not isinstance(directional, dict):
            return ""
        blockers = directional.get("source_backed_compile_blockers")
        if not isinstance(blockers, dict):
            return ""
        fragments: list[str] = []
        for item in [
            blocker for blocker in list(blockers.get("missing_known_type_methods") or [])[:4]
            if isinstance(blocker, dict)
        ]:
            owner = str(item.get("owner") or "").strip()
            method = str(item.get("method") or "").strip()
            if owner and method:
                fragments.append(f"{owner}.{method}(...)")
        nested = [
            str(item).strip()
            for item in list(blockers.get("missing_nested_types") or [])[:4]
            if str(item).strip()
        ]
        fragments.extend(nested)
        if not fragments:
            return ""
        return "do_not_use: " + ", ".join(fragments)

    @staticmethod
    def _render_unified_objective_template(coverage_feedback: dict, obligations: list[dict]) -> str:
        if not obligations:
            return ""
        lines = [
            "[Unified Objective Template]",
            "Use each O-id as one compact planning unit: objective -> state entry -> oracle/receipt -> promotion. Avoid retrying a passing smoke path unless it closes a listed anchor or target-method coverage gap.",
            "Every generated test for an O-id must set coverage_obligation_id to that id and include the id in the Java @Test method name.",
        ]
        forbidden = TATGEngineAdapter._render_obligation_forbidden_summary(coverage_feedback)
        for obligation in obligations:
            oid = str(obligation.get("id") or "O?").strip() or "O?"
            category = str(obligation.get("category") or "CoverageObligation").strip()
            scenario = TATGEngineAdapter._shorten_inline(
                obligation.get("scenario") or "cover uncovered target behavior",
                220,
            )
            lines.append(f"- {oid} [{category}] {scenario}")
            if "satisfied" in obligation or obligation.get("reason"):
                satisfied = obligation.get("satisfied")
                status = "open" if satisfied is False else ("satisfied" if satisfied is True else "quality-hint")
                reason = TATGEngineAdapter._shorten_inline(obligation.get("reason"), 120)
                anchor_count = obligation.get("anchor_count")
                closed_count = obligation.get("closed_anchor_gap_count")
                remaining_count = obligation.get("remaining_anchor_gap_count")
                status_line = f"  status: {status}"
                if reason:
                    status_line += f"; reason={reason}"
                if anchor_count is not None or closed_count is not None or remaining_count is not None:
                    status_line += f"; anchors closed={closed_count}/{anchor_count}, remaining={remaining_count}"
                lines.append(status_line)
            program_fact = TATGEngineAdapter._shorten_inline(
                obligation.get("program_fact") or "coverage-grounded target structure",
                240,
            )
            if program_fact:
                lines.append(f"  objective: {program_fact}")
            setup_items = [
                TATGEngineAdapter._shorten_inline(item, 140)
                for item in list(obligation.get("required_setup") or [])[:3]
                if str(item).strip()
            ]
            if setup_items:
                lines.append("  state_entry: " + "; ".join(setup_items))
            state_recipe = TATGEngineAdapter._compact_state_recipe_for_obligation(obligation)
            if state_recipe:
                lines.append(f"  state_recipe: {state_recipe}")
            state_plan = TATGEngineAdapter._merge_obligation_state_dependency_plan(obligation)
            for state_line in TATGEngineAdapter._render_state_dependency_plan(state_plan, indent="  "):
                lines.append(state_line)
            target_call = TATGEngineAdapter._shorten_inline(
                obligation.get("target_call") or "invoke the target method",
                180,
            )
            if target_call:
                lines.append(f"  target_call: {target_call}")
            oracle_items = [
                TATGEngineAdapter._shorten_inline(item, 140)
                for item in list(obligation.get("oracle") or [])[:3]
                if str(item).strip()
            ]
            if oracle_items:
                lines.append("  oracle: " + "; ".join(oracle_items))
            operators = [
                TATGEngineAdapter._shorten_inline(item, 80)
                for item in list(obligation.get("recipe_operators") or [])[:5]
                if str(item).strip()
            ]
            if operators:
                lines.append("  recipe_operators: " + ", ".join(operators))
            if forbidden:
                lines.append(f"  forbidden: {forbidden}")
            lines.extend(TATGEngineAdapter._render_obligation_anchor_summary(obligation))
            sandbox_obj = TATGEngineAdapter._shorten_inline(obligation.get("sandbox_objective"), 200)
            if sandbox_obj:
                lines.append(f"  promotion: {sandbox_obj}")
            else:
                lines.append("  promotion: close listed anchors or improve target-method line/branch coverage.")
            anti_dup = TATGEngineAdapter._shorten_inline(obligation.get("anti_duplication_key"), 160)
            if anti_dup:
                lines.append(f"  anti_duplication_key: {anti_dup}")
            lines.append(
                "  receipt: coverage_obligation_id="
                f"{oid}; @Test name contains {oid}; invoke target; assert exact result/exception/state; do not delete state-entry code during repair."
            )
        return "\n".join(lines)

    @staticmethod
    def _compact_static_entry_path_plan(callgraph_ctx: str, *, method_is_private: bool) -> str:
        text = str(callgraph_ctx or "").strip()
        if not text:
            return ""
        max_chars = TATGEngineAdapter._env_int("TATG_STATIC_ENTRY_PATH_MAX_CHARS", 6000, minimum=1500, maximum=60000)
        if len(text) <= max_chars:
            return text
        max_paths = TATGEngineAdapter._env_int("TATG_STATIC_ENTRY_PATH_MAX_PATHS", 6 if method_is_private else 3, minimum=1, maximum=32)
        lines = text.splitlines()
        kept: list[str] = []
        path_count = 0
        in_path = False
        path_line_count = 0
        for line in lines:
            stripped = line.strip()
            is_path_start = bool(re.match(r"^(?:[-*]\s*)?(?:Path|Entry path|Call path)\b", stripped, re.IGNORECASE))
            is_header = stripped.startswith("#") or stripped.endswith(":")
            if is_path_start:
                path_count += 1
                if path_count > max_paths:
                    in_path = False
                    continue
                in_path = True
                path_line_count = 0
                kept.append(line)
                continue
            if in_path:
                path_line_count += 1
                if path_line_count <= 5 and len("\n".join(kept)) < max_chars:
                    kept.append(line)
                continue
            keep_structural = (
                is_header
                or stripped.lower().startswith(("target", "root", "roots", "max depth"))
                or "constructor:" in stripped.lower()
                or "factory:" in stripped.lower()
            )
            if keep_structural and len("\n".join(kept)) < max_chars:
                kept.append(line)
            if len("\n".join(kept)) >= max_chars:
                break
        compacted = "\n".join(line for line in kept if line.strip()).strip()
        if not compacted:
            compacted = text[:max_chars].rstrip()
        if len(compacted) > max_chars:
            compacted = compacted[:max_chars].rstrip()
        compacted += (
            f"\n[Static Entry Path Plan truncated: original_chars={len(text)}, "
            f"shown_chars={len(compacted)}, shown_paths<={max_paths}.]"
        )
        return compacted

    @staticmethod
    def _truncate_section_text(
        text: str,
        max_chars: int,
        *,
        keep_tail: bool = False,
        force: bool = False,
    ) -> str:
        value = str(text or "")
        stripped_value = value.lstrip()
        protected_min_chars = 0
        if "[Mutation Objective Context]" in value:
            protected_min_chars = max(protected_min_chars, min(len(value), 14000))
        if "[Source-Backed Baseline Skeleton Obligation]" in value:
            protected_min_chars = max(protected_min_chars, min(len(value), 12000))
        if "[Deep Frontier First Candidate]" in value:
            protected_min_chars = max(protected_min_chars, min(len(value), 9000))
        if "[Source-Derived Frontier Candidate Sketches]" in value:
            protected_min_chars = max(protected_min_chars, min(len(value), 9000))
        if "[Source-Derived Construction Repair Map]" in value:
            protected_min_chars = max(protected_min_chars, min(len(value), 9000))
        if "[Coverage-Positive Failed Candidates To Salvage]" in value:
            protected_min_chars = max(protected_min_chars, min(len(value), 14000))
        if "[Active Uncovered Objectives]" in value or "[Current Live Failure Objectives]" in value:
            protected_min_chars = max(protected_min_chars, min(len(value), 12000))
        if stripped_value.startswith("[Current Round Test Objectives]"):
            protected_min_chars = max(protected_min_chars, min(len(value), 12000))
        # The section carrying the target method's OWN SOURCE was the one thing
        # not protected, while eight advisory/scaffolding sections were.  On the
        # full benchmark 45 of 168 targets (27%) had it truncated, losing a mean
        # 9405 chars; those targets averaged 0.3947 branch coverage against
        # 0.4921 for untruncated ones (correlation, not causation -- large
        # methods are both likelier to truncate and intrinsically harder).
        #
        # Truncation itself is sound: an over-long prompt buries the point.  The
        # priority was simply inverted -- the code under test should outrank a
        # construction-API listing.  This does NOT disable truncation, and the
        # A/B must watch total prompt length: if it balloons without a coverage
        # gain, the right fix is compressing the largest scaffolding section
        # ([Visible Type Construction APIs], 15% of the prompt) instead.
        if TATGEngineAdapter._env_flag("TATG_PROTECT_TARGET_SOURCE", default=False):
            if stripped_value.startswith("[Target Execution Receipt]"):
                protected_min_chars = max(protected_min_chars, min(len(value), 16000))
        if protected_min_chars:
            max_chars = max(max_chars, protected_min_chars)
            force = True
        try:
            threshold = int(os.getenv("TATG_SECTION_TRUNCATE_THRESHOLD_CHARS", "10000"))
        except ValueError:
            threshold = 10000
        try:
            shown_chars = int(os.getenv("TATG_SECTION_TRUNCATE_SHOWN_CHARS", "5000"))
        except ValueError:
            shown_chars = 5000
        if threshold > 0 and not force:
            if len(value) <= threshold:
                return value
            max_chars = max(1, shown_chars)
        if max_chars <= 0 or len(value) <= max_chars:
            return value
        marker = f"\n[section truncated: original_chars={len(value)}, shown_chars={max_chars}]\n"
        if keep_tail and max_chars > len(marker) + 400:
            head = max_chars * 2 // 3
            tail = max_chars - head - len(marker)
            return value[:head].rstrip() + marker + value[-tail:].lstrip()
        return value[: max(0, max_chars - len(marker))].rstrip() + marker

    @staticmethod
    def _split_top_level_item_blocks(section: str) -> tuple[list[str], list[list[str]]]:
        header: list[str] = []
        blocks: list[list[str]] = []
        current: list[str] = []
        for line in str(section or "").splitlines():
            if line.startswith("- "):
                if current:
                    blocks.append(current)
                current = [line]
                continue
            if current:
                current.append(line)
            else:
                header.append(line)
        if current:
            blocks.append(current)
        return header, blocks

    @staticmethod
    def _compact_complete_item_section(
        section: str,
        max_chars: int,
        *,
        allow_partial_first_item: bool = True,
    ) -> str:
        """Compact a priority feedback section only at top-level item boundaries."""
        value = str(section or "")
        if max_chars <= 0 or len(value) <= max_chars:
            return value
        header, blocks = TATGEngineAdapter._split_top_level_item_blocks(value)
        if not blocks:
            kept_lines: list[str] = []
            total = 0
            lines = value.splitlines()
            for line in lines:
                projected = total + len(line) + 1
                if kept_lines and projected > max_chars:
                    break
                kept_lines.append(line)
                total = projected
            omitted = max(0, len(lines) - len(kept_lines))
            if omitted:
                kept_lines.append(f"priority_section_lines_omitted: omitted_lines={omitted}")
            return "\n".join(kept_lines).strip()

        selected: list[str] = list(header)
        shown = 0
        min_complete_items = 4
        for block in blocks:
            rendered = "\n".join(block)
            candidate = "\n".join([*selected, rendered]).strip()
            if shown >= min_complete_items and len(candidate) > max_chars:
                continue
            if shown == 0 and len(candidate) > max_chars:
                if not allow_partial_first_item:
                    kept_block: list[str] = []
                    base_len = len("\n".join(selected).strip())
                    total = base_len + (1 if base_len else 0)
                    for line in block:
                        projected = total + len(line) + 1
                        if kept_block and projected > max_chars:
                            break
                        kept_block.append(line)
                        total = projected
                    if kept_block:
                        selected.extend(kept_block)
                        shown += 1
                    continue
                kept_block: list[str] = []
                base_len = len("\n".join(selected).strip())
                total = base_len + (1 if base_len else 0)
                for line in block:
                    projected = total + len(line) + 1
                    if kept_block and projected > max_chars:
                        break
                    kept_block.append(line)
                    total = projected
                omitted_lines = max(0, len(block) - len(kept_block))
                selected.extend(kept_block)
                if omitted_lines:
                    selected.append(
                        f"priority_objective_item_tail_omitted: omitted_lines={omitted_lines}"
                    )
                shown += 1
                continue
            selected.extend(block)
            shown += 1
        omitted = max(0, len(blocks) - shown)
        if omitted:
            selected.append(
                f"priority_objective_items_omitted: original_items={len(blocks)}, shown_items={shown}"
            )
        return "\n".join(selected).strip()

    @staticmethod
    def _compact_priority_item_section(section: str, max_chars: int) -> str:
        """Compact high-priority facts without cutting inside the first item."""
        return TATGEngineAdapter._compact_complete_item_section(
            section,
            max_chars,
            allow_partial_first_item=False,
        )

    @staticmethod
    def _is_complete_item_priority_section(section: str) -> bool:
        stripped = str(section or "").lstrip()
        return stripped.startswith((
            "[Source-Backed Baseline Skeleton Obligation]",
            "[Deep Frontier First Candidate]",
            "[Executable Baseline Schema]",
            "[Source-Derived Frontier Candidate Sketches]",
            "[Source-Derived Construction Repair Map]",
            "[Source-Derived Collaborator Callable Map]",
            "[Source-Backed Compile Blockers]",
            "[Source-Backed State And Predicate Strategy]",
            "[Executable Candidate Recipe]",
            "[Source-Derived Target State/Call Plan]",
            "[Observed Construction Recipes]",
            "[Validated Target-Reaching State Entries]",
            "[Verified Baseline/Entry Evidence]",
            "[Measured Directional Feedback]",
            "[Measured Pre-Target Call Scaffold]",
            "[Type-Guided Execution Recipes]",
            "[Source-Derived Visible State Sequence]",
            "[Delegated Callback Outcome Matrix]",
            "[Delegated State Realism]",
            "[Execution Capsule Skeleton]",
            "[Callback/Interface Signature Grounding]",
            "[Active Uncovered Objectives]",
            "[Current Live Failure Objectives]",
            "[Recent Validation Failures]",
            "[Coverage-Positive Failed Candidates To Salvage]",
            "[Current Round Test Objectives]",
            "[Mutation Objective Context]",
            "[Coverage-Repair Mode]",
        ))

    @staticmethod
    def _compact_prompt_section(section: str, cap: int, *, keep_tail: bool = False) -> str:
        if TATGEngineAdapter._is_complete_item_priority_section(section):
            return TATGEngineAdapter._compact_priority_item_section(section, cap)
        return TATGEngineAdapter._truncate_section_text(section, cap, keep_tail=keep_tail)

    @staticmethod
    def _extract_bracket_section(text: str, marker: str) -> str:
        start = text.find(marker)
        if start < 0:
            return ""
        tail = text[start + len(marker):]
        for next_match in re.finditer(r"\n\[(?P<label>[^\n\]]+)\]\n", tail):
            label = str(next_match.group("label") or "").strip().lower()
            if (
                label.startswith("section truncated:")
                or label.startswith("priority ")
                or label.startswith("coverage feedback ")
            ):
                continue
            end = start + len(marker) + next_match.start()
            return text[start:end].strip()
        return text[start:].strip()

    @staticmethod
    def _strip_embedded_section_headers(text: str, *markers: str) -> str:
        """Remove exact bracket section header lines from an embedded excerpt.

        Short retry notes sometimes include compact snippets from high-priority
        sections under a different local heading. Keeping the original bracket
        header inside that snippet makes prompt audit report a duplicate real
        section and can confuse ordering. Strip only exact header lines; keep
        all evidence/body lines intact.
        """
        marker_set = {str(marker or "").strip() for marker in markers if str(marker or "").strip()}
        if not marker_set:
            return str(text or "").strip()
        kept = [
            line
            for line in str(text or "").splitlines()
            if line.strip() not in marker_set
        ]
        return "\n".join(kept).strip()

    @staticmethod
    def _drop_embedded_bracket_section(text: str, marker: str) -> str:
        """Drop one complete embedded bracket section without clipping neighbors."""

        marker_text = str(marker or "").strip()
        if not marker_text:
            return str(text or "").strip()
        kept: list[str] = []
        skipping = False
        for line in str(text or "").splitlines():
            stripped = line.strip()
            if stripped == marker_text:
                skipping = True
                continue
            if skipping and re.fullmatch(r"\[[^\]\n]+\]", stripped):
                skipping = False
            if not skipping:
                kept.append(line)
        return "\n".join(kept).strip()

    @staticmethod
    def _high_priority_truncation_warnings(prompt_text: str) -> list[dict[str, object]]:
        text = str(prompt_text or "")
        warnings: list[dict[str, object]] = []
        high_priority_markers = [
            "[Source-Backed Baseline Skeleton Obligation]",
            "[Deep Frontier First Candidate]",
            "[Executable Baseline Schema]",
            "[Source-Derived Frontier Candidate Sketches]",
            "[Executable Candidate Recipe]",
            "[Active Uncovered Objectives]",
            "[Current Live Failure Objectives]",
            "[Recent Validation Failures]",
            "[Coverage-Positive Failed Candidates To Salvage]",
            "[Mutation Objective Context]",
            "[Source-Derived Construction Repair Map]",
            "[Source-Derived Collaborator Callable Map]",
            "[Source-Backed Compile Blockers]",
            "[Source-Backed State And Predicate Strategy]",
            "[Source-Derived Target State/Call Plan]",
            "[Observed Construction Recipes]",
            "[Validated Target-Reaching State Entries]",
            "[Verified Baseline/Entry Evidence]",
            "[Measured Directional Feedback]",
            "[Measured Pre-Target Call Scaffold]",
            "[Type-Guided Execution Recipes]",
            "[Source-Derived Visible State Sequence]",
            "[Delegated Callback Outcome Matrix]",
            "[Delegated State Realism]",
            "[Execution Capsule Skeleton]",
            "[Callback/Interface Signature Grounding]",
            "[Current Round Test Objectives]",
            "[Coverage-Repair Mode]",
        ]
        for marker in high_priority_markers:
            marker_re = r"^" + re.escape(marker) + r"\s*$"
            count = len(list(re.finditer(marker_re, text, re.MULTILINE)))
            if count > 1:
                warnings.append({"section": marker, "reason": "duplicate_section", "count": count})
            if count <= 0:
                continue
            section = TATGEngineAdapter._extract_bracket_section(text, marker)
            if "[section truncated:" in section:
                warnings.append({"section": marker, "reason": "internal_section_truncation"})
            body = section.replace(marker, "", 1).strip()
            if not body or body.startswith("---"):
                warnings.append({"section": marker, "reason": "empty_section"})
        return warnings

    @staticmethod
    def _baseline_skeleton_rendered_complete(prompt_text: str) -> bool | None:
        section = TATGEngineAdapter._extract_bracket_section(
            str(prompt_text or ""),
            "[Source-Backed Baseline Skeleton Obligation]",
        )
        if not section:
            return None
        if "[section truncated:" in section:
            return False
        normalized = re.sub(r"\(\s*\.\.\.\s*\)", "(ARGS)", section)
        normalized = re.sub(r"<\s*\.\.\.\s*>", "<T>", normalized)
        if re.search(r"\b(?:required_|source_|target_|oracle_|fact_)[A-Za-z0-9_:-]*[^;\n]*\.\.\.", normalized):
            return False
        if TATGEngineAdapter._high_priority_section_has_suspicious_tail(section):
            return False
        return True

    @staticmethod
    def _high_priority_section_has_suspicious_tail(section: str) -> bool:
        suspicious_suffixes = (
            " retur",
            " impleme",
            " implemen",
            " obse",
            " obser",
            " visib",
            " visible imple",
            " correspondin",
            " source-visib",
        )
        for raw in str(section or "").splitlines():
            line = raw.rstrip()
            if not line or line.endswith("[more]"):
                continue
            lowered = line.lower()
            if any(lowered.endswith(suffix) for suffix in suspicious_suffixes):
                return True
        return False

    @staticmethod
    def _high_priority_mid_field_clip(prompt_text: str) -> bool:
        text = str(prompt_text or "")
        for marker in (
            "[Source-Backed Baseline Skeleton Obligation]",
            "[Deep Frontier First Candidate]",
            "[Executable Baseline Schema]",
            "[Source-Derived Frontier Candidate Sketches]",
            "[Source-Derived Construction Repair Map]",
            "[Source-Derived Collaborator Callable Map]",
            "[Source-Backed Compile Blockers]",
            "[Source-Backed State And Predicate Strategy]",
            "[Executable Candidate Recipe]",
            "[Source-Derived Target State/Call Plan]",
            "[Observed Construction Recipes]",
            "[Validated Target-Reaching State Entries]",
            "[Verified Baseline/Entry Evidence]",
            "[Measured Directional Feedback]",
            "[Measured Pre-Target Call Scaffold]",
            "[Type-Guided Execution Recipes]",
            "[Source-Derived Visible State Sequence]",
            "[Delegated Callback Outcome Matrix]",
            "[Delegated State Realism]",
            "[Execution Capsule Skeleton]",
            "[Callback/Interface Signature Grounding]",
            "[Required Executable Path Objective]",
            "[Current Live Failure Objectives]",
            "[Recent Validation Failures]",
            "[Coverage-Positive Failed Candidates To Salvage]",
            "[Active Uncovered Objectives]",
            "[Measured Pre-Target Call Scaffold]",
            "[Mutation Objective Context]",
            "[Coverage-Repair Mode]",
        ):
            section = TATGEngineAdapter._extract_bracket_section(text, marker)
            if not section:
                continue
            if TATGEngineAdapter._high_priority_section_has_suspicious_tail(section):
                return True
            for line in section.splitlines():
                stripped = line.strip()
                if "..." not in stripped:
                    continue
                if stripped.startswith("[") or stripped.startswith("- ..."):
                    continue
                # Complete, backticked executable templates may intentionally
                # show an omitted builder/configuration segment, for example
                # ``builder()...configure required fields...build()``.  This is
                # a whole prompt fact rather than evidence of character-level
                # clipping, so remove only that tightly bounded template shape
                # before scanning for suspicious ellipses elsewhere.
                normalized = re.sub(
                    r"`[^`\n]*\([^`\n]*\)\.\.\.[^`\n]+\.\.\.[^`\n]*\([^`\n]*\)`",
                    lambda match: match.group(0).replace("...", "<omitted-step>"),
                    stripped,
                )
                normalized = re.sub(r"\(\s*\.\.\.\s*\)", "(ARGS)", normalized)
                normalized = re.sub(r"<\s*\.\.\.\s*>", "<T>", normalized)
                if re.search(r"[A-Za-z0-9_$]\.\.\.(?:[A-Za-z0-9_$]|;|,|\)|$)", normalized):
                    return True
        return False

    @staticmethod
    def _compact_coverage_feedback_section(section: str, max_chars: int) -> str:
        value = str(section or "")
        if max_chars <= 0 or len(value) <= max_chars:
            return value
        priority_markers = [
            "[Current Live Failure Objectives]",
            "[Recent Validation Failures]",
            "[Coverage-Positive Failed Candidates To Salvage]",
            "[Active Uncovered Objectives]",
            "[Measured Pre-Target Call Scaffold]",
            "[Mutation Objective Context]",
            "[Fused Coverage + Mutation Feedback]",
            "[Source-Backed Baseline Skeleton Obligation]",
            "[Deep Frontier First Candidate]",
            "[Executable Baseline Schema]",
            "[Source-Derived Frontier Candidate Sketches]",
            "[Source-Backed Compile Blockers]",
            "[Source-Backed State And Predicate Strategy]",
            "[Source-Derived Construction Repair Map]",
            "[Source-Derived Collaborator Callable Map]",
            "[Executable Candidate Recipe]",
            "[Construction-First Rescue Mode]",
            "[Verified Baseline/Entry Evidence]",
            "[Validated Target-Reaching State Entries]",
            "[Current Round Test Objectives]",
            "[Unified Objective Template]",
            "[Measured Directional Feedback]",
            "[Previous Validation Failure Feedback]",
            "[Coverage-Repair Mode]",
            "[Satisfied Objectives Summary]",
        ]
        priority_keywords = [
            "NO_COVERAGE",
            "SURVIVED",
            "MutationReachability",
            "MutationAssertion",
            "mutation score gap",
            "surviving mutant",
        ]

        def _drop_internal_section_truncation_markers(chunk_text: str) -> str:
            """Remove pre-truncated fragments before putting feedback up front.

            Some feedback details arrive already compacted with an internal
            ``[section truncated: ...]`` marker.  Re-emitting that marker inside
            high-priority feedback gives the model a half field as if it were
            evidence.  Drop the marker and the immediately preceding dangling
            line, then leave an explicit omission note.
            """
            lines = str(chunk_text or "").splitlines()
            kept: list[str] = []
            removed = 0
            for line in lines:
                if "[section truncated:" not in line:
                    kept.append(line)
                    continue
                removed += 1
                if kept:
                    prev = kept[-1].rstrip()
                    if (
                        not prev
                        or prev.endswith(("_", "=", ":", ";", ","))
                        or not re.search(r"[.!?)\]}]$", prev)
                    ):
                        kept.pop()
                continue
            if not removed:
                return str(chunk_text or "")
            note = (
                f"priority_section_precompacted_fragments_omitted: "
                f"section_truncation_markers={removed}"
            )
            if note not in kept:
                kept.append(note)
            return "\n".join(kept).strip()

        def _drop_already_kept_bracket_sections(tail_text: str, kept_text: str) -> str:
            cleaned = str(tail_text or "")
            for marker in priority_markers:
                if marker not in kept_text or marker not in cleaned:
                    continue
                start = cleaned.find(marker)
                if start < 0:
                    continue
                next_match = re.search(r"\n\[[^\n\]]+\]\n", cleaned[start + len(marker):])
                end = (
                    start + len(marker) + next_match.start()
                    if next_match
                    else len(cleaned)
                )
                cleaned = (cleaned[:start].rstrip() + "\n\n" + cleaned[end:].lstrip()).strip()
            return cleaned

        chunks: list[str] = []
        seen: set[str] = set()
        has_explicit_mutation_context = "[Mutation Objective Context]" in value
        priority_starts = [
            start for start in (value.find(marker) for marker in priority_markers)
            if start >= 0
        ]
        head_end = min(priority_starts) if priority_starts else len(value)
        head_value = value[:head_end].rstrip() if head_end > 0 else value
        head_chunk = ""
        if head_value:
            if priority_starts:
                first_line = head_value.splitlines()[0] if head_value.splitlines() else "[Coverage Feedback For This Generation Round]"
                head_chunk = f"{first_line}\n[coverage feedback intro omitted: original_chars={len(head_value)}]"
            else:
                head_chunk = TATGEngineAdapter._truncate_section_text(
                    head_value,
                    min(1800, max(800, max_chars // 5)),
                    keep_tail=False,
                    force=True,
                ).strip()
        used_ranges: list[tuple[int, int]] = [(0, head_end)]
        for marker in priority_markers:
            start = value.find(marker)
            if start < 0:
                continue
            chunk = TATGEngineAdapter._extract_bracket_section(value, marker)
            if not chunk or chunk in seen:
                continue
            seen.add(chunk)
            if marker == "[Coverage-Positive Failed Candidates To Salvage]":
                cap = 9000
            elif marker == "[Recent Validation Failures]":
                cap = 7000
            elif marker == "[Active Uncovered Objectives]":
                cap = 9000
            elif marker == "[Measured Pre-Target Call Scaffold]":
                cap = 3600
            elif marker == "[Unified Objective Template]":
                cap = 4200
            elif marker == "[Mutation Objective Context]":
                cap = 11000
            elif marker == "[Source-Derived Collaborator Callable Map]":
                cap = 5200
            elif marker == "[Executable Candidate Recipe]":
                cap = 4200
            elif marker == "[Executable Baseline Schema]":
                cap = 4200
            else:
                cap = 2200
            if marker == "[Mutation Objective Context]":
                cap = max(cap, min(len(chunk), 7600))
            else:
                cap = min(cap, max(1200, max_chars - 600))
            if marker in {
                "[Mutation Objective Context]",
                "[Fused Coverage + Mutation Feedback]",
                "[Coverage-Positive Failed Candidates To Salvage]",
                "[Active Uncovered Objectives]",
                "[Source-Backed Baseline Skeleton Obligation]",
                "[Deep Frontier First Candidate]",
                "[Executable Baseline Schema]",
                "[Source-Derived Frontier Candidate Sketches]",
                "[Source-Derived Construction Repair Map]",
                "[Source-Derived Collaborator Callable Map]",
                "[Executable Candidate Recipe]",
                "[Current Round Test Objectives]",
                "[Current Live Failure Objectives]",
                "[Recent Validation Failures]",
                "[Previous Validation Failure Feedback]",
                "[Coverage-Repair Mode]",
                "[Measured Directional Feedback]",
                "[Measured Pre-Target Call Scaffold]",
                "[Validated Target-Reaching State Entries]",
                "[Construction-First Rescue Mode]",
                "[Unified Objective Template]",
            }:
                compacted_chunk = TATGEngineAdapter._compact_priority_item_section(chunk, cap).strip()
                chunks.append(_drop_internal_section_truncation_markers(compacted_chunk))
            else:
                compacted_chunk = TATGEngineAdapter._compact_priority_item_section(chunk, cap).strip()
                chunks.append(_drop_internal_section_truncation_markers(compacted_chunk))
            used_ranges.append((start, start + len(chunk)))
        lowered = value.lower()
        if not has_explicit_mutation_context:
            for keyword in priority_keywords:
                start = lowered.find(keyword.lower())
                if start < 0:
                    continue
                begin = max(0, start - 900)
                end = min(len(value), start + 3200)
                chunk = value[begin:end].strip()
                if not chunk or chunk in seen:
                    continue
                seen.add(chunk)
                chunks.append(
                    TATGEngineAdapter._truncate_section_text(
                        "[Mutation Feedback Evidence Snippet]\n" + chunk,
                        4200,
                        keep_tail=False,
                        force=True,
                    ).strip()
                )
                used_ranges.append((begin, end))
        if head_chunk:
            projected = "\n\n".join([head_chunk, *chunks]).strip()
            if not chunks or len(projected) <= max_chars:
                chunks.insert(0, head_chunk)
            else:
                first_line = head_chunk.splitlines()[0] if head_chunk.splitlines() else "[Coverage Feedback For This Generation Round]"
                # Keep the outer section identity even when all embedded
                # priority chunks do not fit together. Later prompt-budget
                # passes can then use this section-aware compactor again
                # instead of raw-truncating a block that happens to begin
                # with [Recent Validation Failures].
                chunks.insert(0, first_line)
        # Coverage-guided retries are not executable when the O-id mapping is
        # entirely displaced by large failure/salvage blocks. Reserve the
        # first embedded slot for the complete-item-compacted active objective
        # section, while retaining the outer coverage-feedback header. Other
        # evidence remains in its existing relative order and is also rendered
        # separately by the generation prompt when available.
        active_idx = next(
            (
                idx
                for idx, chunk in enumerate(chunks)
                if str(chunk).lstrip().startswith("[Active Uncovered Objectives]")
            ),
            -1,
        )
        if active_idx >= 0:
            insertion_idx = (
                1
                if chunks
                and str(chunks[0]).lstrip().startswith(
                    "[Coverage Feedback For This Generation Round]"
                )
                else 0
            )
            if active_idx != insertion_idx:
                active_chunk = chunks.pop(active_idx)
                chunks.insert(insertion_idx, active_chunk)
        scaffold_idx = next(
            (
                idx
                for idx, chunk in enumerate(chunks)
                if str(chunk).lstrip().startswith(
                    "[Measured Pre-Target Call Scaffold]"
                )
            ),
            -1,
        )
        if scaffold_idx >= 0:
            active_idx = next(
                (
                    idx
                    for idx, chunk in enumerate(chunks)
                    if str(chunk).lstrip().startswith(
                        "[Active Uncovered Objectives]"
                    )
                ),
                -1,
            )
            insertion_idx = active_idx + 1 if active_idx >= 0 else (
                1
                if chunks
                and str(chunks[0]).lstrip().startswith(
                    "[Coverage Feedback For This Generation Round]"
                )
                else 0
            )
            if scaffold_idx != insertion_idx:
                scaffold_chunk = chunks.pop(scaffold_idx)
                if scaffold_idx < insertion_idx:
                    insertion_idx -= 1
                chunks.insert(insertion_idx, scaffold_chunk)
        joined = "\n\n".join(chunk for chunk in chunks if chunk)
        if len(joined) <= max_chars:
            tail_budget = max_chars - len(joined) - 80
            if tail_budget > 800:
                tail = value[-tail_budget:].strip()
                tail = _drop_already_kept_bracket_sections(tail, joined)
                if tail and tail not in joined:
                    joined = joined.rstrip() + "\n\n[Coverage Feedback Tail]\n" + tail
        if len(joined) <= max_chars:
            joined += f"\n[coverage feedback compacted: original_chars={len(value)}, shown_chars={len(joined)}]"
            return joined
        compacted_chunks: list[str] = []
        omitted_chunks = 0
        for chunk in chunks:
            projected = "\n\n".join([*compacted_chunks, chunk]).strip()
            if compacted_chunks and len(projected) > max_chars:
                if (
                    len(compacted_chunks) == 1
                    and compacted_chunks[0].startswith(
                        "[Coverage Feedback For This Generation Round]"
                    )
                ):
                    # The first embedded chunk is the highest-ranked concrete
                    # evidence block. Preserve it intact even when it alone
                    # exceeds the approximate section budget; subsequent
                    # prompt passes can omit lower-ranked whole chunks.
                    compacted_chunks.append(chunk)
                    continue
                omitted_chunks += 1
                continue
            compacted_chunks.append(chunk)
        joined = "\n\n".join(chunk for chunk in compacted_chunks if chunk).strip()
        if omitted_chunks:
            suffix = f"\n[coverage feedback chunks omitted: omitted_chunks={omitted_chunks}]"
            if len(joined) + len(suffix) <= max_chars + 400:
                joined += suffix
        return joined

    @staticmethod
    def _compact_user_prompt_to_budget(user_prompt: str) -> str:
        """Keep prompt surface near the model-effective range.

        The generator benefits from source-grounded context, but very large
        prompts bury the few constraints that matter in feedback rounds.  This
        compactor is section-aware: it preserves high-signal coverage/blocker
        evidence and trims verbose advisory/context sections first.
        """
        text = str(user_prompt or "")
        compaction_mode = os.getenv("TATG_PROMPT_COMPACTION_MODE", "").strip().lower()
        if compaction_mode in {"off", "none", "no_clip", "noclip"}:
            return text
        explicit_target_chars = "TATG_PROMPT_TARGET_CHARS" in os.environ
        target_chars = TATGEngineAdapter._env_int("TATG_PROMPT_TARGET_CHARS", 60000, minimum=16000, maximum=120000)
        high_signal_state_sections = (
            "[Execution Capsule Skeleton]",
            "[Callback/Interface Signature Grounding]",
            "[Source-Derived Target State/Call Plan]",
        )
        if not explicit_target_chars and any(marker in text for marker in high_signal_state_sections):
            target_chars = max(target_chars, 46000)
        if len(text) <= target_chars:
            return text
        sep = "\n\n---\n\n"
        sections = text.split(sep)
        if len(sections) <= 1:
            return TATGEngineAdapter._truncate_section_text(text, target_chars, keep_tail=True)

        protect_priority = compaction_mode in {"protect_priority", "priority", "priority_only"}
        priority_protected_prefixes = (
            "[Generation Control Receipt]",
            "[Mutation Feedback For Mutation Extra Round]",
            "[Source-Visible Mutation Entry Paths]",
            "[Mutation Reachability Recipe]",
            "[Mutation Objective Context]",
            "[Mutation Source Neighborhoods]",
            "[Required Executable Path Objective]",
            "[Source-Backed Baseline Skeleton Obligation]",
            "[Deep Frontier First Candidate]",
            "[Executable Baseline Schema]",
            "[Source-Derived Frontier Candidate Sketches]",
            "[Source-Derived Construction Repair Map]",
            "[Source-Derived Collaborator Callable Map]",
            "[Executable Candidate Recipe]",
            "[Source-Backed Compile Blockers]",
            "[Current Live Failure Objectives]",
            "[Coverage-Positive Failed Candidates To Salvage]",
            "[Active Uncovered Objectives]",
            "[Coverage Feedback For This Generation Round]",
            "[Current Round Test Objectives]",
            "[Measured Directional Feedback]",
            "[Measured Pre-Target Call Scaffold]",
        )

        def _priority_protected(section: str) -> bool:
            return protect_priority and section.lstrip().startswith(priority_protected_prefixes)

        def _max_for(section: str) -> tuple[int, bool]:
            if _priority_protected(section):
                return (len(section), False)
            stripped = section.lstrip()
            if stripped.startswith("[Coverage Feedback For This Generation Round]"):
                # This is the only section that names the branches still to be
                # covered.  Dropping chunks out of it was observed on exactly
                # the large-method rounds that needed it most, so it gets a
                # larger share of the budget than the advisory scaffolding.
                return (
                    TATGEngineAdapter._env_int("TATG_PROMPT_MAX_COVERAGE_FEEDBACK_CHARS", 24000, minimum=8000, maximum=60000),
                    True,
                )
            if stripped.startswith("[Mutation Feedback For Mutation Extra Round]"):
                return (14000, False)
            if stripped.startswith("[Source-Visible Mutation Entry Paths]"):
                return (5200, False)
            if stripped.startswith("[Mutation Reachability Recipe]"):
                return (6200, False)
            if stripped.startswith("[Mutation Objective Context]"):
                return (7600, False)
            if stripped.startswith("[Mutation Source Neighborhoods]"):
                return (5200, False)
            if stripped.startswith("[Generation Control Receipt]"):
                return (
                    TATGEngineAdapter._env_int("TATG_PROMPT_MAX_GENERATION_RECEIPT_CHARS", 6200, minimum=2600, maximum=16000),
                    False,
                )
            if stripped.startswith("[Required Executable Path Objective]"):
                return (5200, False)
            if stripped.startswith("[Source-Backed Baseline Skeleton Obligation]"):
                return (6200, False)
            if stripped.startswith("[Deep Frontier First Candidate]"):
                return (3200, False)
            if stripped.startswith("[Executable Baseline Schema]"):
                return (4600, False)
            if stripped.startswith("[Source-Derived Frontier Candidate Sketches]"):
                return (5200, False)
            if stripped.startswith("[Source-Derived Construction Repair Map]"):
                return (5600, False)
            if stripped.startswith("[Source-Derived Collaborator Callable Map]"):
                return (5200, False)
            if stripped.startswith("[Executable Candidate Recipe]"):
                return (4200, False)
            if stripped.startswith("[Source-Backed Compile Blockers]"):
                return (4300, False)
            if stripped.startswith("[Source-Derived Target State/Call Plan]"):
                return (3800, False)
            if stripped.startswith("[Observed Construction Recipes]"):
                return (5200, False)
            if stripped.startswith("[Current Round Test Objectives]"):
                return (4600, False)
            if stripped.startswith("[Active Uncovered Objectives]"):
                return (9000, False)
            if stripped.startswith("[Satisfied Objectives Summary]"):
                return (2600, False)
            if stripped.startswith("[Verified Baseline/Entry Evidence]"):
                return (3600, False)
            if stripped.startswith("[Overload-Specific Scenario Contract]"):
                return (2600, False)
            if stripped.startswith("Coverage-quality guidance:"):
                return (3600, False)
            if stripped.startswith("Dependency context for the class under test:"):
                return (4200, False)
            if stripped.startswith("Domain type field shapes"):
                return (2400, False)
            if stripped.startswith("Strict type contracts"):
                return (4200, False)
            if stripped.startswith("[Unified Objective Template]"):
                return (
                    TATGEngineAdapter._env_int("TATG_PROMPT_MAX_UNIFIED_OBJECTIVE_CHARS", 7000, minimum=2000, maximum=30000),
                    True,
                )
            if stripped.startswith("[Coverage Obligations For This Round]"):
                return (
                    TATGEngineAdapter._env_int("TATG_PROMPT_MAX_COVERAGE_OBLIGATION_CHARS", 7000, minimum=2000, maximum=30000),
                    True,
                )
            if stripped.startswith("[Measured Directional Feedback]"):
                return (4500, True)
            if stripped.startswith("[Measured Pre-Target Call Scaffold]"):
                return (3600, False)
            if stripped.startswith("[Static Entry Path Plan]"):
                return (
                    TATGEngineAdapter._env_int("TATG_PROMPT_MAX_STATIC_ENTRY_CHARS", 5000, minimum=1000, maximum=20000),
                    False,
                )
            if stripped.startswith("[CALLABLE SURFACE"):
                return (
                    TATGEngineAdapter._env_int("TATG_PROMPT_MAX_CALLABLE_SURFACE_CHARS", 9500, minimum=2500, maximum=30000),
                    False,
                )
            if stripped.startswith("Source code under test:"):
                return (
                    TATGEngineAdapter._env_int("TATG_PROMPT_MAX_SOURCE_SECTION_CHARS", 8000, minimum=3000, maximum=30000),
                    True,
                )
            if stripped.startswith("[Execution Capsule Skeleton]"):
                return (3200, False)
            if stripped.startswith("[Callback/Interface Signature Grounding]"):
                return (3200, False)
            if stripped.startswith("[Target Execution Receipt]"):
                return (4200, True)
            if stripped.startswith("[Type-Guided Execution Recipes]"):
                return (4500, False)
            if stripped.startswith("[Source-Derived Visible State Sequence]"):
                return (4500, False)
            if stripped.startswith("[Delegated Callback Outcome Matrix]"):
                return (4200, False)
            if stripped.startswith("[Delegated State Realism]"):
                return (3200, False)
            if stripped.startswith("[Classpath Symbol Grounding]") or stripped.startswith("[Visible Type Construction APIs]"):
                return (4500, False)
            if stripped.startswith("Existing test file") or stripped.startswith("[Existing Test Context]"):
                return (3500, True)
            if stripped.startswith("Requirements:"):
                return (5200, False)
            return (
                TATGEngineAdapter._env_int("TATG_PROMPT_MAX_MISC_SECTION_CHARS", 3600, minimum=800, maximum=16000),
                False,
            )

        compacted: list[str] = []
        for section in sections:
            max_chars, keep_tail = _max_for(section)
            if _priority_protected(section):
                compacted.append(section)
            elif section.lstrip().startswith("[Coverage Feedback For This Generation Round]"):
                compacted.append(TATGEngineAdapter._compact_coverage_feedback_section(section, max_chars))
            else:
                compacted.append(TATGEngineAdapter._compact_prompt_section(section, max_chars, keep_tail=keep_tail))
        joined = sep.join(compacted)
        if len(joined) <= target_chars:
            return joined

        # Second pass: preserve section order but trim low-priority sections
        # harder before touching coverage/source/receipt evidence.
        priority_caps = [
            ("[Static Entry Path Plan]", 4200, False),
            (
                "[Generation Control Receipt]",
                TATGEngineAdapter._env_int("TATG_PROMPT_MAX_GENERATION_RECEIPT_CHARS", 6200, minimum=2600, maximum=16000),
                False,
            ),
            ("[Required Executable Path Objective]", 4200, False),
            ("[Source-Backed Baseline Skeleton Obligation]", 5600, False),
            ("[Deep Frontier First Candidate]", 3200, False),
            ("[Executable Baseline Schema]", 4200, False),
            ("[Source-Derived Frontier Candidate Sketches]", 4600, False),
            ("[Source-Derived Construction Repair Map]", 4600, False),
            ("[Source-Derived Collaborator Callable Map]", 4200, False),
            ("[Executable Candidate Recipe]", 3800, False),
            ("[Source-Derived Target State/Call Plan]", 3000, False),
            ("[Source-Backed Compile Blockers]", 3200, False),
            ("[Observed Construction Recipes]", 3600, False),
            ("[Active Uncovered Objectives]", 7600, False),
            ("[Mutation Objective Context]", 6200, False),
            ("[Current Round Test Objectives]", 3400, False),
            ("[Satisfied Objectives Summary]", 2200, False),
            ("[Verified Baseline/Entry Evidence]", 3200, False),
            ("[Overload-Specific Scenario Contract]", 2200, False),
            ("Coverage-quality guidance:", 3000, False),
            ("Dependency context for the class under test:", 3200, False),
            ("Domain type field shapes", 2000, False),
            ("Strict type contracts", 3200, False),
            ("[CALLABLE SURFACE", 9000, False),
            ("[Classpath Symbol Grounding]", 5600, False),
            ("[Visible Type Construction APIs]", 5600, False),
            ("[Type-Guided Execution Recipes]", 3200, False),
            ("[Source-Derived Visible State Sequence]", 3200, False),
            ("[Delegated Callback Outcome Matrix]", 3200, False),
            ("[Delegated State Realism]", 2400, False),
            ("[Execution Capsule Skeleton]", 2200, False),
            ("[Callback/Interface Signature Grounding]", 2400, False),
            ("Requirements:", 3600, False),
            ("Existing test file", 2000, True),
            ("Source code under test:", 6500, True),
            ("[Coverage Feedback For This Generation Round]", 16000, True),
            ("[Unified Objective Template]", 5200, True),
            ("[Coverage Obligations For This Round]", 5200, True),
            ("[Target Execution Receipt]", 3200, True),
        ]
        current = compacted
        for prefix, cap, keep_tail in priority_caps:
            if len(sep.join(current)) <= target_chars:
                break
            next_sections: list[str] = []
            for section in current:
                stripped = section.lstrip()
                if _priority_protected(section):
                    next_sections.append(section)
                    continue
                if not stripped.startswith(prefix):
                    next_sections.append(section)
                    continue
                if stripped.startswith("[Coverage Feedback For This Generation Round]"):
                    next_sections.append(TATGEngineAdapter._compact_coverage_feedback_section(section, cap))
                else:
                    next_sections.append(
                        TATGEngineAdapter._compact_prompt_section(section, cap, keep_tail=keep_tail)
                    )
            current = next_sections
        joined = sep.join(current)
        if len(joined) <= target_chars:
            return joined

        # Last-resort compaction must remain section-aware.  Truncating the
        # whole joined prompt by head/tail can drop the middle coverage
        # feedback section, which is the highest-signal part of feedback
        # rounds.
        def _fallback_cap(section: str) -> tuple[int, bool]:
            stripped = section.lstrip()
            if stripped.startswith("[Coverage Feedback For This Generation Round]"):
                return (12000, True)
            if stripped.startswith("[Generation Control Receipt]"):
                return (
                    TATGEngineAdapter._env_int("TATG_PROMPT_MAX_GENERATION_RECEIPT_CHARS", 6200, minimum=2600, maximum=16000),
                    False,
                )
            if stripped.startswith("[Required Executable Path Objective]"):
                return (3000, False)
            if stripped.startswith("[Source-Backed Baseline Skeleton Obligation]"):
                return (5000, False)
            if stripped.startswith("[Deep Frontier First Candidate]"):
                return (3000, False)
            if stripped.startswith("[Executable Baseline Schema]"):
                return (3800, False)
            if stripped.startswith("[Source-Derived Frontier Candidate Sketches]"):
                return (4200, False)
            if stripped.startswith("[Source-Derived Construction Repair Map]"):
                return (4200, False)
            if stripped.startswith("[Source-Derived Collaborator Callable Map]"):
                return (3600, False)
            if stripped.startswith("[Executable Candidate Recipe]"):
                return (3200, False)
            if stripped.startswith("[Source-Derived Target State/Call Plan]"):
                return (2400, False)
            if stripped.startswith("[Source-Backed Compile Blockers]"):
                return (2400, False)
            if stripped.startswith("[Observed Construction Recipes]"):
                return (2600, False)
            if stripped.startswith("[Current Round Test Objectives]"):
                return (2600, False)
            if stripped.startswith("[Active Uncovered Objectives]"):
                return (7000, False)
            if stripped.startswith("[Satisfied Objectives Summary]"):
                return (1800, False)
            if stripped.startswith("[Verified Baseline/Entry Evidence]"):
                return (2600, False)
            if stripped.startswith("[Overload-Specific Scenario Contract]"):
                return (1600, False)
            if stripped.startswith("Coverage-quality guidance:"):
                return (2200, False)
            if stripped.startswith("Dependency context for the class under test:"):
                return (2600, False)
            if stripped.startswith("Domain type field shapes"):
                return (1600, False)
            if stripped.startswith("Strict type contracts"):
                return (2600, False)
            if stripped.startswith("[Target Execution Receipt]"):
                return (3200, True)
            if stripped.startswith("Requirements:"):
                return (2800, False)
            if stripped.startswith("[CALLABLE SURFACE"):
                return (9000, False)
            if stripped.startswith("[Classpath Symbol Grounding]") or stripped.startswith("[Visible Type Construction APIs]"):
                return (5600, False)
            if stripped.startswith("Source code under test:"):
                return (6500, True)
            if stripped.startswith("[Execution Capsule Skeleton]"):
                return (2200, False)
            if stripped.startswith("[Callback/Interface Signature Grounding]"):
                return (2400, False)
            if stripped.startswith("[Type-Guided Execution Recipes]"):
                return (2600, False)
            if stripped.startswith("[Static Entry Path Plan]"):
                return (2600, False)
            if stripped.startswith("[Source-Derived Visible State Sequence]"):
                return (2600, False)
            if stripped.startswith("[Delegated Callback Outcome Matrix]"):
                return (2600, False)
            if stripped.startswith("[Delegated State Realism]"):
                return (2000, False)
            if stripped.startswith("Existing test file") or stripped.startswith("[Existing Test Context]"):
                return (1200, True)
            return (900, False)

        rebuilt: list[str] = []
        for section in current:
            if _priority_protected(section):
                rebuilt.append(section)
                continue
            cap, keep_tail = _fallback_cap(section)
            if section.lstrip().startswith("[Coverage Feedback For This Generation Round]"):
                rebuilt.append(TATGEngineAdapter._compact_coverage_feedback_section(section, cap))
            else:
                rebuilt.append(TATGEngineAdapter._compact_prompt_section(section, cap, keep_tail=keep_tail))
        joined = sep.join(rebuilt)
        if len(joined) <= target_chars:
            return joined
        # Trim low-priority sections further, preserving coverage feedback,
        # target receipt, callable surface, and requirements before all else.
        essential_prefixes = (
            "[Coverage Feedback For This Generation Round]",
            "[Active Uncovered Objectives]",
            "[Generation Control Receipt]",
            "[Required Executable Path Objective]",
            "[Source-Backed Baseline Skeleton Obligation]",
            "[Deep Frontier First Candidate]",
            "[Executable Baseline Schema]",
            "[Source-Derived Frontier Candidate Sketches]",
            "[Source-Derived Construction Repair Map]",
            "[Source-Derived Collaborator Callable Map]",
            "[Executable Candidate Recipe]",
            "[Source-Derived Target State/Call Plan]",
            "[Source-Backed Compile Blockers]",
            "[Observed Construction Recipes]",
            "[Current Round Test Objectives]",
            "[Satisfied Objectives Summary]",
            "[Verified Baseline/Entry Evidence]",
            "[Overload-Specific Scenario Contract]",
            "Coverage-quality guidance:",
            "Dependency context for the class under test:",
            "Domain type field shapes",
            "Strict type contracts",
            "[Target Execution Receipt]",
            "Source code under test:",
            "[Execution Capsule Skeleton]",
            "[Callback/Interface Signature Grounding]",
            "[Type-Guided Execution Recipes]",
            "[Source-Derived Visible State Sequence]",
            "[Delegated Callback Outcome Matrix]",
            "[Delegated State Realism]",
            "[Static Entry Path Plan]",
            "[CALLABLE SURFACE",
            "[Classpath Symbol Grounding]",
            "[Visible Type Construction APIs]",
            "Requirements:",
        )
        current = rebuilt
        for cap in (650, 420, 260):
            if len(sep.join(current)) <= target_chars:
                break
            current = [
                section
                if _priority_protected(section) or section.lstrip().startswith(essential_prefixes)
                else TATGEngineAdapter._compact_prompt_section(section, cap, keep_tail=False)
                for section in current
            ]
        joined = sep.join(current)
        if len(joined) <= target_chars:
            return joined

        # Final fallback: continue trimming by section.  A whole-prompt middle
        # clip can remove the current objectives or receipt even though each
        # section header is more valuable than a few extra lines from any one
        # large section.
        final_caps = [
            ("[CALLABLE SURFACE", 6200, False),
            ("[Classpath Symbol Grounding]", 5200, False),
            ("[Visible Type Construction APIs]", 5200, False),
            ("Source code under test:", 4200, True),
            ("Requirements:", 2200, False),
            ("[Coverage Feedback For This Generation Round]", 16000, False),
            ("[Mutation Feedback For Mutation Extra Round]", 14000, False),
            ("[Source-Visible Mutation Entry Paths]", 5200, False),
            ("[Mutation Reachability Recipe]", 6200, False),
            ("[Mutation Objective Context]", 7600, False),
            ("[Mutation Source Neighborhoods]", 5200, False),
            ("[Active Uncovered Objectives]", 6200, False),
            ("[Unified Objective Template]", 3600, True),
            ("[Coverage Obligations For This Round]", 3600, True),
            ("[Target Execution Receipt]", 2200, True),
            ("[Required Executable Path Objective]", 2400, False),
            ("[Source-Backed Baseline Skeleton Obligation]", 4200, False),
            ("[Deep Frontier First Candidate]", 2800, False),
            ("[Executable Baseline Schema]", 3400, False),
            ("[Source-Derived Frontier Candidate Sketches]", 3600, False),
            ("[Source-Derived Construction Repair Map]", 3600, False),
            ("[Source-Derived Collaborator Callable Map]", 3200, False),
            ("[Executable Candidate Recipe]", 3000, False),
            ("[Type-Guided Execution Recipes]", 2200, False),
            ("[Source-Derived Visible State Sequence]", 2200, False),
            ("[Delegated Callback Outcome Matrix]", 2200, False),
            ("[Delegated State Realism]", 1600, False),
            ("[Execution Capsule Skeleton]", 1600, False),
            ("[Callback/Interface Signature Grounding]", 1600, False),
            ("[Observed Construction Recipes]", 1800, False),
            ("[Current Round Test Objectives]", 1800, False),
            ("[Satisfied Objectives Summary]", 1400, False),
            ("[Verified Baseline/Entry Evidence]", 1800, False),
            ("[Source-Derived Target State/Call Plan]", 1800, False),
            ("Coverage-quality guidance:", 1600, False),
            ("Dependency context for the class under test:", 2200, False),
            ("Domain type field shapes", 1200, False),
            ("Strict type contracts", 2200, False),
            ("[Static Entry Path Plan]", 2200, False),
        ]
        current = list(current)
        for prefix, cap, keep_tail in final_caps:
            if len(sep.join(current)) <= target_chars:
                break
            def _apply_final_cap(section: str) -> str:
                if _priority_protected(section):
                    return section
                stripped = section.lstrip()
                if not stripped.startswith(prefix):
                    return section
                if stripped.startswith("[Coverage Feedback For This Generation Round]"):
                    return TATGEngineAdapter._compact_coverage_feedback_section(section, cap)
                return TATGEngineAdapter._compact_prompt_section(section, cap, keep_tail=keep_tail)

            current = [
                _apply_final_cap(section)
                for section in current
            ]
        joined = sep.join(current)
        if len(joined) <= target_chars:
            return joined
        if not explicit_target_chars:
            # Default mode honors the module-level truncation contract: a
            # section is left intact until it exceeds the configured threshold,
            # then shown with the configured section budget.  Do not silently
            # crush every module to an equal tiny slice just to hit an
            # approximate global prompt size; that has repeatedly removed the
            # exact source/callable evidence needed by hard stateful targets.
            return joined

        per_section_budget = max(600, (target_chars - len(sep) * (len(current) - 1)) // max(1, len(current)))
        rebuilt_minimal = [
            TATGEngineAdapter._truncate_section_text(
                section,
                per_section_budget,
                keep_tail=False,
                force=True,
            )
            for section in current
        ]
        joined = sep.join(rebuilt_minimal)
        if len(joined) <= target_chars:
            return joined
        return joined[:target_chars].rstrip()

