            ("[Type-Guided Execution Recipes]", 10),
            ("[Satisfied Objectives Summary]", 10),
            ("[CALLABLE SURFACE", 11),
            ("[Source-Exact Receiver Construction Contract]", 11),
            ("[Observed Construction Recipes]", 11),
            ("[Classpath Symbol Grounding]", 11),
            ("[Visible Type Construction APIs]", 11),
            ("[Callback/Interface Signature Grounding]", 11),
            ("[Target Execution Receipt", 12),
            ("[Coverage Obligations For This Round]", 12),
            ("[Target Method Obligation]", 12),
            ("[Overload-Specific Scenario Contract]", 12),
            ("[Target Overload Binding]", 12),
